def _now() -> datetime:
    """Return the effective runtime clock, honoring test/benchmark override."""
    raw = os.environ.get("QUAID_NOW", "").strip()
    if raw:
        try:
            parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        except ValueError as exc:
            raise ValueError(f"Invalid QUAID_NOW={raw!r}") from exc
        if parsed.tzinfo is not None:
            return parsed.replace(tzinfo=None)
        return parsed
    return datetime.now()


def _now_iso() -> str:
    return _now().isoformat()


def _now_for(reference: datetime) -> datetime:
    current = _now()
    if reference.tzinfo:
        return current if current.tzinfo else current.replace(tzinfo=reference.tzinfo)
    return current.replace(tzinfo=None) if current.tzinfo else current


