def _identifier_key(value: str) -> str:
    normalized = unicodedata.normalize("NFKC", str(value or "")).casefold()
    return "".join(ch for ch in normalized if ch.isalnum())


def _has_non_ascii(value: str) -> bool:
    return any(ord(ch) > 127 for ch in str(value or ""))


def _unicode_casefold(value: str) -> str:
    return unicodedata.normalize("NFKC", str(value or "")).casefold()


def _has_compact_unicode_char(value: str) -> bool:
    for ch in str(value or ""):
        name = unicodedata.name(ch, "")
        if name.startswith(("CJK ", "HIRAGANA", "KATAKANA", "HANGUL")):
            return True
    return False


def _recall_query_term_min_len(term: str) -> int:
    if not term:
        return 4
    if str(term).isascii():
        return 4
    if _has_compact_unicode_char(term):
        return 2
    return 3


def _is_fts_fallback_high_signal_token(term: str) -> bool:
    clean = str(term or "").strip()
    if not clean:
        return False
    if clean[:1].isupper() and not clean.isupper():
        return True
    return _has_compact_unicode_char(clean) and len(clean) >= _recall_query_term_min_len(clean)

