def search(
    query: str,
    limit: int = 10,
    owner_id: Optional[str] = None,
    source_channel: Optional[str] = None,
    source_conversation_id: Optional[str] = None,
    source_author_id: Optional[str] = None,
    subject_entity_id: Optional[str] = None,
    participant_entity_ids: Optional[List[str]] = None,
) -> List[Dict[str, Any]]:
    """Datastore search interface for API/core callers."""
    if not query or not query.strip():
        return []

    def _participants(raw: Any) -> set[str]:
        if isinstance(raw, list):
            return {str(v).strip() for v in raw if str(v).strip()}
        if isinstance(raw, str):
            txt = raw.strip()
            if not txt:
                return set()
            try:
                parsed = json.loads(txt)
                if isinstance(parsed, list):
                    return {str(v).strip() for v in parsed if str(v).strip()}
            except Exception:
                pass
            return {p.strip() for p in txt.split(",") if p.strip()}
        return set()

    graph = get_graph()
    raw = graph.search_hybrid(query, limit=limit, owner_id=owner_id)
    out: List[Dict[str, Any]] = []
    source_channel_norm = str(source_channel or "").strip().lower() or None
    source_conversation_norm = str(source_conversation_id or "").strip() or None
    source_author_norm = str(source_author_id or "").strip() or None
    subject_entity_norm = str(subject_entity_id or "").strip() or None
    requested_participants = _participants(participant_entity_ids)
    for node, score in raw:
        attrs = node.attributes if isinstance(node.attributes, dict) else {}
        row_source_channel = str(attrs.get("source_channel") or "").strip().lower() or None
        row_source_conversation = (
            str(attrs.get("source_conversation_id") or attrs.get("conversation_id") or node.conversation_id or "").strip()
            or None
        )
        row_source_author = str(attrs.get("source_author_id") or "").strip() or None
        row_subject_entity = str(attrs.get("subject_entity_id") or "").strip() or None
        row_participants = _participants(attrs.get("participant_entity_ids"))

        if source_channel_norm and row_source_channel != source_channel_norm:
            continue
        if source_conversation_norm and row_source_conversation != source_conversation_norm:
            continue
        if source_author_norm and row_source_author != source_author_norm:
            continue
        if subject_entity_norm and row_subject_entity != subject_entity_norm:
            continue
        if requested_participants and requested_participants.isdisjoint(row_participants):
            continue

        out.append(
            {
                "id": node.id,
                "text": node.name,
                "category": node.type,
                "similarity": round(score, 4),
                "confidence": node.confidence,
                "owner_id": node.owner_id,
                "created_at": node.created_at,
                "source_channel": row_source_channel,
                "source_conversation_id": row_source_conversation,
                "source_author_id": row_source_author,
                "speaker_entity_id": str(attrs.get("speaker_entity_id") or node.speaker_entity_id or "").strip() or None,
                "subject_entity_id": row_subject_entity,
                "conversation_id": str(attrs.get("conversation_id") or node.conversation_id or "").strip() or None,
                "visibility_scope": str(attrs.get("visibility_scope") or node.visibility_scope or "source_shared").strip(),
                "sensitivity": str(attrs.get("sensitivity") or node.sensitivity or "normal").strip(),
                "provenance_confidence": attrs.get("provenance_confidence", node.provenance_confidence),
                "participant_entity_ids": sorted(row_participants) if row_participants else [],
            }
        )
    return out


# Janitor and normal product adapters can touch the same SQLite DB concurrently.
# Treat WAL write contention as transient, but keep a hard bound.
_DATASTORE_BUSY_RETRY_DELAYS_SECONDS = (0.1, 0.25, 0.5, 1.0, 2.0)
_DEFAULT_MEMORYDB_EMBED_TIMEOUT_S = 30.0


def _memorydb_embedding_timeout_s(default: float = _DEFAULT_MEMORYDB_EMBED_TIMEOUT_S) -> float:
    raw = str(os.environ.get("QUAID_MEMORYDB_EMBED_TIMEOUT_S", "") or "").strip()
    if not raw:
        return float(default)
    try:
        value = float(raw)
    except Exception:
        logger.warning(
            "Invalid QUAID_MEMORYDB_EMBED_TIMEOUT_S=%r; using %.1fs",
            raw,
            float(default),
        )
        return float(default)
    if value <= 0:
        return float(default)
    return value


def _is_sqlite_busy_or_locked(exc: BaseException) -> bool:
    if not isinstance(exc, sqlite3.OperationalError):
        return False

    code = getattr(exc, "sqlite_errorcode", None)
    if isinstance(code, int):
        base_code = code & 0xFF
        busy_code = getattr(sqlite3, "SQLITE_BUSY", None)
        locked_code = getattr(sqlite3, "SQLITE_LOCKED", None)
        if base_code in {busy_code, locked_code}:
            return True

    text = str(exc).lower()
    return (
        "database is locked" in text
        or "database table is locked" in text
    )


def register_lifecycle_routines(registry, result_factory) -> None:
    """Register memory datastore lifecycle maintenance routines."""

    def _run_datastore_cleanup(ctx):
        result = result_factory()
        graph = ctx.graph or get_graph()
        cleanup_queries = {
            "recall_log": "DELETE FROM recall_log WHERE created_at < datetime('now', '-90 days')",
            "dedup_log": "DELETE FROM dedup_log WHERE review_status != 'unreviewed' AND created_at < datetime('now', '-90 days')",
            "health_snapshots": "DELETE FROM health_snapshots WHERE created_at < datetime('now', '-180 days')",
            "embedding_cache": "DELETE FROM embedding_cache WHERE created_at < datetime('now', '-30 days')",
            "janitor_metadata": "DELETE FROM janitor_metadata WHERE updated_at < datetime('now', '-180 days')",
            "janitor_runs": "DELETE FROM janitor_runs WHERE completed_at < datetime('now', '-180 days')",
        }
        attempts = len(_DATASTORE_BUSY_RETRY_DELAYS_SECONDS) + 1
        try:
            for attempt in range(1, attempts + 1):
                cleanup_stats = {
                    "recall_log": 0,
                    "dedup_log": 0,
                    "embedding_cache": 0,
                    "health_snapshots": 0,
                    "janitor_metadata": 0,
                    "janitor_runs": 0,
                }
                try:
                    with graph._get_conn() as conn:
                        for table, sql in cleanup_queries.items():
                            if ctx.dry_run:
                                count_sql = sql.replace("DELETE FROM", "SELECT COUNT(*) FROM", 1)
                                row = conn.execute(count_sql).fetchone()
                                cleanup_stats[table] = row[0] if row else 0
                            else:
                                cur = conn.execute(sql)
                                cleanup_stats[table] = cur.rowcount
                    break
                except sqlite3.OperationalError as exc:
                    if not _is_sqlite_busy_or_locked(exc) or attempt >= attempts:
                        raise
                    delay = _DATASTORE_BUSY_RETRY_DELAYS_SECONDS[attempt - 1]
                    result.logs.append(
                        "Datastore cleanup database busy; "
                        f"retrying in {delay:.2f}s (attempt {attempt}/{attempts}): {exc}"
                    )
                    time.sleep(delay)

            total = sum(cleanup_stats.values())
            result.logs.append(f"{'Would remove' if ctx.dry_run else 'Removed'}: {total} rows total")
            for table, count in cleanup_stats.items():
                if count > 0:
                    result.logs.append(f"  {table}: {count}")
            result.data["cleanup"] = cleanup_stats
        except Exception as exc:
            result.errors.append(f"Cleanup error: {exc}")
        return result

    registry.register("datastore_cleanup", _run_datastore_cleanup)


def _ollama_healthy(timeout: float = 0.5, retry_timeout: float = 2.5) -> bool:
    """Fast-but-stable health check for the embedding provider.

    Hits /api/tags (the lightest endpoint). Healthy results stay cached for
    30s; unhealthy results are cached briefly so a transient slow response
    does not poison fail-hard recall for the next 30s.
    """
    # In test environments with mock embeddings, always report healthy
    # (search_hybrid handles mock embeddings internally)
    import os as _os
    if _os.environ.get("MOCK_EMBEDDINGS"):
        return True
    import time as _time
    now = _time.monotonic()
    # Cache: (timestamp, result)
    if hasattr(_ollama_healthy, "_cache"):
        cache = _ollama_healthy._cache
        if isinstance(cache, tuple) and len(cache) == 2:
            ts, result = cache
            ttl = 30 if result else 2
            if now - ts < ttl:
                return bool(result)

    def _probe(request_timeout: float) -> bool:
        try:
            url = get_ollama_url()
            req = urllib.request.Request(f"{url}/api/tags", method="GET")
            with urllib.request.urlopen(req, timeout=request_timeout) as resp:
                return resp.status == 200
        except Exception:
            return False

    healthy = _probe(timeout)
    if not healthy and retry_timeout > timeout:
        healthy = _probe(retry_timeout)

    _ollama_healthy._cache = (now, healthy)
    return healthy


def _is_fail_hard_mode() -> bool:
    """Return whether embedding failures should raise instead of degrading."""
    # Test and mock environments intentionally run without embeddings.
    if os.environ.get("PYTEST_CURRENT_TEST") or os.environ.get("MOCK_EMBEDDINGS"):
        return False

    try:
        from lib.fail_policy import is_fail_hard_enabled
        return bool(is_fail_hard_enabled())
    except Exception:
        return True


def _resolve_auto_inject_graph_depth() -> int:
    """Return platform-wide graph depth for fast auto-inject recall."""
    default_depth = 2
    try:
        retrieval_cfg = _get_retrieval_lightweight_config()
        raw_depth = getattr(retrieval_cfg, "auto_inject_graph_depth", default_depth)
        if raw_depth is None:
            return default_depth
        return max(0, int(raw_depth))
    except Exception:
        if _is_fail_hard_mode():
            raise
        return default_depth


def route_query(query: str, timeout_ms: Optional[int] = None, max_retries: Optional[int] = None) -> str:
    """HyDE (Hypothetical Document Embedding) — generate a hypothetical answer
    to the query, then use that for semantic search. The embedding of an answer
    is closer to stored facts in vector space than keywords or the raw question.

    Falls back to original query if LLM unavailable or fails.
    """
    # Skip routing for very short queries (proper nouns, single words)
    if len(query) < 15:
        return query

    prompt = f'Rephrase this question as a declarative statement about someone\'s personal life. Do NOT invent specific names, dates, or places. Keep it general.\n\nQuestion: "{query}"\n\nStatement:'

    if timeout_ms is None:
        try:
            from config import get_config

            cfg_hyde_timeout = getattr(get_config().retrieval, "hyde_timeout_ms", 15000)
            timeout_ms = int(15000 if cfg_hyde_timeout is None else cfg_hyde_timeout)
        except Exception:
            timeout_ms = 15000

    try:
        cfg_timeout_ms = 15000
        cfg_max_retries = 1
        try:
            from config import get_config
            retrieval_cfg = get_config().retrieval
            cfg_timeout = getattr(retrieval_cfg, "hyde_timeout_ms", 15000)
            cfg_timeout_ms = int(15000 if cfg_timeout is None else cfg_timeout)
            cfg_retries = getattr(retrieval_cfg, "hyde_max_retries", 1)
            cfg_max_retries = int(1 if cfg_retries is None else cfg_retries)
        except Exception:
            cfg_timeout_ms = 15000
            cfg_max_retries = 1
        effective_timeout_ms = max(1000, int(timeout_ms if timeout_ms is not None else cfg_timeout_ms))
        effective_max_retries = max(0, int(max_retries if max_retries is not None else cfg_max_retries))

        from lib.llm_clients import call_fast_reasoning
        result, _ = call_fast_reasoning(
            prompt=prompt,
            max_tokens=50,
            timeout=effective_timeout_ms / 1000,
            system_prompt="You rephrase questions as declarative statements. Respond with only the statement, no explanation.",
            max_retries=effective_max_retries,
        )
        if result:
            result = result.strip().strip('"\'')
            if len(result) > 5 and len(result) < 500:
                return result
    except Exception as e:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "HyDE routing failed while fail-hard mode is enabled "
                f"(timeout_ms={effective_timeout_ms}, max_retries={effective_max_retries}, cause={type(e).__name__}: {e})"
            ) from e

    return query


def _compute_retrieval_difficulty(result: dict) -> float:
    """Compute how hard this memory was to retrieve (Bjork: desirable difficulty).

    Signals:
    - raw similarity score (lower = harder to find via embedding)
    - multi_pass (found only on second pass = harder)
    - via_relation / hop_depth (found via graph traversal = harder)

    Returns difficulty in [0.0, 1.0].
    """
    difficulty = 0.0

    # Similarity-based: continuous function — all retrievals contribute some difficulty,
    # but low-similarity retrievals contribute proportionally more
    sim = result.get("similarity", 0.8)
    difficulty += 0.4 * (1.0 - sim)  # sim=1.0→0.0, sim=0.8→0.08, sim=0.5→0.20

    # Multi-pass: found only on confidence-gated second pass
    if result.get("_multi_pass"):
        difficulty += 0.3

    # Graph traversal: found via edges, not direct search
    hop_depth = result.get("hop_depth", 0)
    if hop_depth > 0:
        difficulty += min(0.3, 0.15 * hop_depth)  # +0.15 per hop, max +0.3

    return min(difficulty, 1.0)


def _compute_composite_score(
    node: Node,
    search_score: float,
    config_retrieval=None,
    intent: str = "GENERAL",
    prefer_fresh: bool = False,
    target_date: str = "",
    temporal_dimension: Any = None,
) -> float:
    """Compute composite score mixing search relevance, recency, and frequency.

    Weights: search_relevance=0.60, recency=0.20, frequency=0.15
    Recency: 1.0 for accessed today, decays to 0.0 over 90 days.
    Frequency: log-scaled access_count, capped at 1.0.
    """
    import math

    boost_recent = True
    boost_frequent = True
    w_relevance = 0.60
    w_recency = 0.20
    w_frequency = 0.15
    recency_days = 90
    if config_retrieval:
        boost_recent = bool(getattr(config_retrieval, "boost_recent", boost_recent))
        boost_frequent = bool(getattr(config_retrieval, "boost_frequent", boost_frequent))
        w_relevance = getattr(config_retrieval, 'composite_relevance_weight', 0.60)
        w_recency = getattr(config_retrieval, 'composite_recency_weight', 0.20)
        w_frequency = getattr(config_retrieval, 'composite_frequency_weight', 0.15)
        recency_days = getattr(config_retrieval, 'recency_decay_days', 90)

    # Temporal-current queries should favor freshness over legacy popularity.
    if prefer_fresh:
        w_relevance = min(w_relevance, 0.50)
        w_recency = max(w_recency, 0.35)
        w_frequency = min(w_frequency, 0.10)

    # Base search relevance (already 0-1 from quality_score)
    relevance = min(search_score, 1.0)

    # Recency signal
    recency = 0.0
    if boost_recent and node.accessed_at:
        try:
            last_access = datetime.fromisoformat(node.accessed_at.replace('Z', '+00:00'))
            days_ago = (_now_for(last_access) - last_access).days
            recency = max(0.0, 1.0 - days_ago / max(1, recency_days))
        except (ValueError, TypeError):
            pass

    # Frequency signal (log-scaled, access_count 1->0.0, 10->0.59, 50->1.0)
    frequency = 0.0
    if boost_frequent and node.access_count > 0:
        frequency = min(1.0, math.log1p(node.access_count) / math.log1p(50))

    # Confirmation bonus (independently confirmed facts are more reliable)
    confirmation_bonus = 0.0
    if node.confirmation_count > 0:
        confirmation_bonus = min(0.05, node.confirmation_count * 0.01)

    # Temporal validity penalty
    temporal_penalty = 0.0
    if node.valid_until:
        try:
            until = datetime.fromisoformat(node.valid_until.replace('Z', '+00:00'))
            current = _now_for(until)
            if until < current:
                # Expired fact — penalize based on how long ago it expired
                days_expired = (current - until).days
                temporal_penalty = min(0.3, days_expired * 0.01)  # Up to -0.3
        except (ValueError, TypeError):
            pass
    if node.valid_from:
        try:
            vfrom = datetime.fromisoformat(node.valid_from.replace('Z', '+00:00'))
            current = _now_for(vfrom)
            if vfrom > current:
                temporal_penalty = 0.5  # Future fact — heavy penalty
        except (ValueError, TypeError):
            pass

    # WHEN intent temporal boost: facts with temporal data are more relevant
    temporal_data_bonus = 0.0
    if intent == "WHEN":
        if node.valid_from or node.valid_until or node.created_at:
            temporal_data_bonus = 0.05  # Small bonus for having temporal metadata
        if node.valid_from and node.valid_until:
            temporal_data_bonus = 0.10  # Larger bonus for fully-bounded temporal range

    # Confidence boost (small signal: 0.9 confidence -> +0.045, 0.5 -> +0.025)
    confidence_bonus = node.confidence * 0.05

    # Knowledge type adjustments
    if node.knowledge_type == "belief":
        confidence_bonus *= 0.7  # Beliefs are less authoritative than facts
    elif node.knowledge_type == "preference":
        # Preferences don't decay as fast but are worth less in general recall
        confidence_bonus *= 0.9

    # Storage strength bonus (deeply encoded facts are slightly more reliable)
    storage_bonus = min(0.03, node.storage_strength * 0.003)

    # Weighted composite (weights from config)
    if boost_recent and boost_frequent:
        composite = w_relevance * relevance + w_recency * recency + w_frequency * frequency + confidence_bonus + confirmation_bonus + temporal_data_bonus + storage_bonus
    elif boost_recent:
        composite = (w_relevance + w_frequency) * relevance + (w_recency + 0.05) * recency + confidence_bonus + confirmation_bonus + temporal_data_bonus + storage_bonus
    elif boost_frequent:
        composite = (w_relevance + w_recency) * relevance + w_frequency * frequency + confidence_bonus + confirmation_bonus + temporal_data_bonus + storage_bonus
    else:
        composite = relevance + confidence_bonus + confirmation_bonus + temporal_data_bonus + storage_bonus

    # Apply temporal validity penalty
    if prefer_fresh and temporal_penalty > 0.0:
        temporal_penalty = min(0.6, temporal_penalty * 1.5)
    composite = max(0.0, composite - temporal_penalty)
    composite = max(
        0.0,
        composite + _asof_temporal_score_delta(
            node,
            target_date,
            temporal_dimension=temporal_dimension,
        ),
    )

    return min(composite, 1.0)


def _apply_mmr(results: List[tuple], graph, limit: int, mmr_lambda: float = 0.7) -> List[tuple]:
    """Apply Maximal Marginal Relevance to diversify results.

    MMR(d) = lambda * sim(q, d) - (1-lambda) * max(sim(d, d_i) for d_i in selected)
    Uses embedding cosine similarity between result nodes.
    """
    if len(results) <= 1:
        return results
    if limit <= 1:
        return results[:1]
    if len(results) <= limit:
        # Nothing needs to be pruned, so skip the expensive pairwise
        # diversification loop and preserve score order.
        return results

    selected = [results[0]]  # Always keep the top result
    candidates = list(results[1:])

    while candidates and len(selected) < limit:
        best_mmr = -1.0
        best_idx = 0

        for i, (node, score) in enumerate(candidates):
            # Relevance component
            relevance = score

            # Diversity component: max similarity to any already-selected result
            max_sim_to_selected = 0.0
            if node.embedding:
                for sel_node, _ in selected:
                    if sel_node.embedding:
                        sim = graph.cosine_similarity(node.embedding, sel_node.embedding)
                        max_sim_to_selected = max(max_sim_to_selected, sim)

            mmr = mmr_lambda * relevance - (1 - mmr_lambda) * max_sim_to_selected
            if mmr > best_mmr:
                best_mmr = mmr
                best_idx = i

        selected.append(candidates.pop(best_idx))

    return selected


def _resolve_mmr_settings(
    config_retrieval: Any,
    *,
    limit: int,
    default_candidate_cap: int,
) -> Tuple[float, int]:
    """Resolve MMR config while treating only missing/None values as defaults."""
    try:
        safe_limit = max(1, int(limit or 1))
    except (TypeError, ValueError):
        safe_limit = 1
    try:
        candidate_cap = max(safe_limit, int(default_candidate_cap))
    except (TypeError, ValueError):
        candidate_cap = max(safe_limit, 12)

    mmr_lambda = 0.7
    if config_retrieval is None:
        return mmr_lambda, candidate_cap

    try:
        raw_lambda = getattr(config_retrieval, "mmr_lambda", None)
        if raw_lambda is not None:
            mmr_lambda = float(raw_lambda)
    except (TypeError, ValueError):
        mmr_lambda = 0.7

    try:
        raw_candidate_cap = getattr(config_retrieval, "mmr_candidate_cap", None)
        if raw_candidate_cap is not None:
            candidate_cap = max(safe_limit, int(raw_candidate_cap))
    except (TypeError, ValueError):
        pass

    return mmr_lambda, candidate_cap


def _fast_term_rescue_score(
    *,
    overlap: int,
    query_term_count: int,
    rank: float,
    min_similarity: float,
    best_existing_score: float,
    best_existing_overlap: int,
) -> float:
    """Score deterministic fast-inject lexical rescues.

    A row that covers every distinctive query term is a direct lexical fit. In
    hook preinject, that direct fit must not stay below hotter vector rows that
    only cover part of the query surface.
    """
    overlap_ratio = overlap / max(1, query_term_count)
    rescue_score = min(
        0.98,
        max(
            float(min_similarity or 0.0),
            0.58 + (overlap_ratio * 0.28) + max(0.0, (3.0 - float(rank or 0.0)) * 0.015),
        ),
    )
    if (
        query_term_count >= 2
        and overlap >= query_term_count
        and best_existing_overlap < query_term_count
    ):
        rescue_score = max(rescue_score, min(0.99, max(0.96, best_existing_score + 0.02)))
    return min(rescue_score, 0.99)


_FAST_LEXICAL_PREFLIGHT_MAX_BUDGET_MS = 30000


def _fast_lexical_preflight_enabled(timeout_ms: Optional[int]) -> bool:
    """Enable DB-local preflight within the normal hook-inject recall budget."""
    if timeout_ms is None:
        try:
            timeout_ms = int(_get_configured_injection_timeout_ms(3000) or 3000)
        except Exception:
            if _is_fail_hard_mode():
                raise
            timeout_ms = 3000
    try:
        return int(timeout_ms) <= _FAST_LEXICAL_PREFLIGHT_MAX_BUDGET_MS
    except (TypeError, ValueError):
        return False


def _fast_lexical_preflight_results(
    graph: "MemoryGraph",
    query: str,
    *,
    limit: int,
    min_similarity: float,
    owner_id: Optional[str],
) -> List[Tuple["Node", float]]:
    """Return strong DB-local lexical hits for the hook-inject fast path.

    Pre-inject recall has a tight wall-clock budget. When existing FTS/LIKE
    evidence directly covers the query surface, prefer that first-order DB path
    instead of starting an embedding/provider call that may exceed the hook
    timeout. Weak lexical matches still fall through to the normal hybrid path.
    """
    query_terms = _extract_distinctive_query_terms(query, limit=8)
    if len(query_terms) < 2:
        return []
    min_overlap = 1 if len(query_terms) <= 2 else 2
    search_limit = max(limit * 3, 24)

    hits: List[Tuple[Node, float]] = []
    seen: Set[str] = set()

    def _append_hits(raw_hits: List[Tuple[Node, float]]) -> None:
        for node, rank in raw_hits or []:
            node_id = str(getattr(node, "id", "") or "").strip()
            if not node_id or node_id in seen:
                continue
            seen.add(node_id)
            hits.append((node, float(rank or 1.0)))

    _append_hits(graph.search_fts(query, limit=search_limit, owner_id=owner_id))
    _append_hits(
        _search_nodes_by_query_terms(
            graph,
            query_terms,
            limit=search_limit,
            owner_id=owner_id,
        )
    )
    if not hits:
        return []

    scored: List[Tuple[Node, float, int, str]] = []
    best_overlap = 0
    for node, rank in hits:
        node_type = str(getattr(node, "type", "") or "").strip().lower()
        if node_type in {"person", "place", "organization", "entity"}:
            continue
        overlap = _query_term_overlap({"text": _node_searchable_text(node)}, query_terms)
        best_overlap = max(best_overlap, overlap)
        if overlap < min_overlap:
            continue
        overlap_ratio = overlap / max(1, len(query_terms))
        quality = min(
            0.99,
            max(
                float(min_similarity or 0.0),
                0.58 + (overlap_ratio * 0.34) + max(0.0, (4.0 - float(rank or 1.0)) * 0.012),
            ),
        )
        scored.append((node, quality, overlap, str(getattr(node, "created_at", "") or "")))

    if best_overlap < min_overlap or (best_overlap / max(1, len(query_terms))) < 0.67:
        return []
    scored.sort(key=lambda item: (item[2], item[1], item[3]), reverse=True)
    return [(node, quality) for node, quality, _overlap, _created in scored[: max(limit * 2, limit)]]


_ASSISTANT_PROVENANCE_SOURCE_TYPES = {"assistant", "subagent", "tool"}


def _node_source_type(node: Node) -> str:
    attrs = getattr(node, "attributes", None)
    if isinstance(attrs, dict):
        return str(attrs.get("source_type") or "").strip().lower()
    return str(getattr(node, "source_type", "") or "").strip().lower()


def _prefer_user_provenance_for_full_fit_rows(
    results: List[tuple],
    query: str,
    *,
    intent: str = "GENERAL",
) -> List[tuple]:
    """Keep assistant recollections below direct user evidence on normal queries."""
    if len(results) <= 1:
        return results
    analysis = _derive_query_requirements(
        query,
        intent=intent,
        include_relation_keywords=False,
    )
    if "assistant_source" in set(analysis.get("requirements") or []):
        return results
    query_terms = list(analysis.get("query_terms") or [])
    if len(query_terms) < 2:
        return results

    indexed: List[Tuple[Node, float, int, str]] = []
    for node, score in results:
        overlap = _query_term_overlap({"text": _node_searchable_text(node)}, query_terms)
        indexed.append((node, float(score), overlap, _node_source_type(node)))

    full_fit_count = len(query_terms)
    direct_full_scores = [
        score
        for _node, score, overlap, source_type in indexed
        if overlap >= full_fit_count and source_type not in _ASSISTANT_PROVENANCE_SOURCE_TYPES
    ]
    if not direct_full_scores:
        return results

    direct_full_ceiling = max(direct_full_scores)
    adjusted: List[tuple] = []
    touched = False
    for node, score, overlap, source_type in indexed:
        adjusted_score = score
        if overlap >= full_fit_count and source_type in _ASSISTANT_PROVENANCE_SOURCE_TYPES:
            adjusted_score = min(score, max(0.0, direct_full_ceiling - 0.01))
            touched = touched or adjusted_score != score
        adjusted.append((node, adjusted_score))
    if touched:
        adjusted.sort(key=lambda item: float(item[1]), reverse=True)
    return adjusted


# ==========================================================================
# Intent-Aware Query Classification
# ==========================================================================

def classify_intent(query: str) -> Tuple[str, Dict[str, float]]:
    """Return the neutral intent.

    Semantic intent routing belongs to the planner/fanout layer. This helper keeps
    the legacy API shape without applying English-only lexical classifiers in the
    deliberate recall path.
    """
    return "GENERAL", {}


def _expand_low_signal_query(query: str, intent: str) -> str:
    """Return the original query; semantic expansion belongs to planner fanout."""
    return (query or "").strip()


def _get_fusion_weights(intent: Optional[str] = None) -> Tuple[float, float]:
    """Return (vector_weight, fts_weight) based on query intent.

    Entity-heavy queries boost FTS for exact name matching.
    Preference/semantic queries boost vector for meaning matching.
    """
    if intent in ("WHO", "WHERE", "RELATION"):
        return (0.5, 0.5)  # Entity queries — boost FTS (exact name match)
    elif intent == "WHEN":
        return (0.4, 0.6)  # Temporal — strong FTS boost (date strings)
    elif intent == "PREFERENCE":
        return (0.8, 0.2)  # Preferences — semantic meaning matters more
    elif intent == "WHY":
        return (0.8, 0.2)  # Causal — heavily semantic (causal relations are meaning-based)
    elif intent == "PROJECT":
        return (0.6, 0.4)  # Project queries — moderate FTS boost for tech terms
    else:
        return (0.7, 0.3)  # Default unchanged


def _resolve_reranker_timeout_ms(
    config_retrieval=None,
    overall_timeout_ms: Optional[int] = None,
) -> int:
    reranker_timeout_ms = _RERANKER_DEFAULT_TIMEOUT_MS
    if config_retrieval:
        try:
            reranker_timeout_ms = int(
                getattr(config_retrieval, "reranker_timeout_ms", reranker_timeout_ms)
                or reranker_timeout_ms
            )
        except Exception:
            reranker_timeout_ms = _RERANKER_DEFAULT_TIMEOUT_MS
    reranker_timeout_ms = max(_RERANKER_MIN_TIMEOUT_MS, reranker_timeout_ms)

    if overall_timeout_ms is not None:
        try:
            overall_budget_ms = int(overall_timeout_ms)
        except (TypeError, ValueError):
            overall_budget_ms = 0
        if overall_budget_ms > reranker_timeout_ms:
            budget_timeout_ms = int(overall_budget_ms * _RERANKER_BUDGET_TIMEOUT_FRACTION)
            budget_timeout_ms = min(_RERANKER_BUDGET_TIMEOUT_CAP_MS, budget_timeout_ms)
            reranker_timeout_ms = max(reranker_timeout_ms, budget_timeout_ms)

    return reranker_timeout_ms


def _rerank_with_cross_encoder(
    query: str,
    results: List[tuple],
    config_retrieval=None,
    overall_timeout_ms: Optional[int] = None,
) -> List[tuple]:
    """Rerank results using an LLM for relevance judgments.

    Always uses a single fast-reasoning LLM call path (provider selected by adapter).

    Falls back to original ranking if the model is unavailable.
    """
    if not results:
        return results

    instruction = "Given a personal memory query, determine if this memory is relevant to the query"
    top_k = 20

    if config_retrieval:
        instruction = getattr(config_retrieval, 'reranker_instruction', instruction)
        top_k = getattr(config_retrieval, 'reranker_top_k', top_k)

    # Only rerank top-K candidates
    to_rerank = results[:top_k]
    rest = results[top_k:]

    reranked = _rerank_via_llm(
        query,
        to_rerank,
        instruction,
        config_retrieval,
        overall_timeout_ms=overall_timeout_ms,
    )

    # Sort reranked by blended score
    reranked.sort(key=lambda x: x[1], reverse=True)
    return reranked + rest


def _rerank_via_llm(
    query: str,
    candidates: List[tuple],
    instruction: str,
    config_retrieval=None,
    overall_timeout_ms: Optional[int] = None,
) -> List[tuple]:
    """Batch rerank via fast-reasoning LLM call — single call for all candidates."""
    from lib.llm_clients import call_fast_reasoning
    start_monotonic = time.monotonic()

    # Hard wall timeout: reranker must not block the user path. An explicit
    # recall budget may widen the reranker slice, but failHard still raises
    # if the widened deadline is exceeded.
    reranker_timeout_ms = _resolve_reranker_timeout_ms(
        config_retrieval,
        overall_timeout_ms=overall_timeout_ms,
    )
    timeout_seconds = max(1, int((reranker_timeout_ms + 999) // 1000))

    # Build numbered candidate list
    lines = []
    for i, (node, _score) in enumerate(candidates):
        lines.append(f"{i+1}. {node.name}")
    candidate_text = "\n".join(lines)

    prompt = (
        f"{instruction}\n\n"
        f"Query: {query}\n\n"
        f"Documents:\n{candidate_text}\n\n"
        f"Rate each document's relevance to the query on a scale of 0-5:\n"
        f"0=irrelevant, 1=tangential, 2=somewhat relevant, 3=relevant, 4=highly relevant, 5=perfect match\n"
        f"Format: one per line, e.g.:\n1. 4\n2. 0\n3. 5\n"
        f"Respond ONLY with the numbered list."
    )

    try:
        response, _duration = call_fast_reasoning(
            prompt, max_tokens=200, timeout=timeout_seconds,
            system_prompt="You are a relevance judge. Respond ONLY with a numbered list of 0-5 scores."
        )

        elapsed_ms = int((time.monotonic() - start_monotonic) * 1000)
        if elapsed_ms > reranker_timeout_ms:
            if _is_fail_hard_mode():
                raise RuntimeError(
                    "Recall reranker exceeded its timeout while failHard is enabled "
                    f"(elapsed_ms={elapsed_ms}, timeout_ms={reranker_timeout_ms})"
                )
            logger.info(
                "[memory][reranker] slow response (%sms > %sms limit); returning original ranking",
                elapsed_ms,
                reranker_timeout_ms,
            )
            return [(node, score) for node, score in candidates]

        if not response:
            if _is_fail_hard_mode():
                raise RuntimeError("Recall reranker returned no response while failHard is enabled")
            return [(node, score) for node, score in candidates]

        # Parse responses: "1. 4\n2. 0\n..."
        verdicts = {}
        for line in response.strip().split("\n"):
            line = line.strip()
            if not line:
                continue
            # Try graded score first (0-5)
            m = re.match(r'(\d+)[.\s:)]+\s*(\d+)', line)
            if m:
                verdicts[int(m.group(1))] = min(int(m.group(2)), 5)
                continue
        reranked = []
        inhibited_ids = []  # Track nodes that scored poorly for storage_strength decay
        for i, (node, score) in enumerate(candidates):
            grade = verdicts.get(i + 1)
            if grade is None:
                reranked.append((node, score))
            else:
                rerank_score = min(grade, 5) / 5.0  # Normalize to [0, 1]
                _blend = 0.5
                if config_retrieval:
                    try:
                        _blend = float(getattr(config_retrieval, 'reranker_blend', 0.5))
                    except (TypeError, ValueError):
                        _blend = 0.5
                _blend = max(0.0, min(1.0, _blend))
                blended = _blend * rerank_score + (1 - _blend) * score
                reranked.append((node, blended))
                # Competitive inhibition: only inhibit when the item looked relevant
                # (high original score) but the reranker judged it irrelevant.
                # This avoids eroding valid facts that just weren't relevant to THIS query.
                if grade <= 1 and score >= 0.65:
                    inhibited_ids.append(node.id)

        # Apply competitive inhibition — small decrement for losing candidates
        if inhibited_ids:
            try:
                graph = get_graph()
                with graph._get_conn() as conn:
                    for nid in inhibited_ids:
                        conn.execute(
                            "UPDATE nodes SET storage_strength = MAX(storage_strength - 0.02, 0.0) WHERE id = ?",
                            (nid,)
                        )
            except Exception:
                pass  # Inhibition is best-effort

        return reranked
    except Exception as exc:
        elapsed_ms = int((time.monotonic() - start_monotonic) * 1000)
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Recall reranker failed while failHard is enabled "
                f"(elapsed_ms={elapsed_ms}, timeout_ms={reranker_timeout_ms}, cause={type(exc).__name__}: {exc})"
            ) from exc
        if elapsed_ms >= reranker_timeout_ms:
            logger.info(
                "[memory][reranker] slow response (%sms, limit=%sms); returning original ranking",
                elapsed_ms,
                reranker_timeout_ms,
            )
        else:
            logger.debug("[memory][reranker] exception: %s; returning original ranking", str(exc))
        return [(node, score) for node, score in candidates]


def _log_recall(graph, query: str, owner_id: Optional[str], intent: str,
                results_count: int, avg_similarity: float, top_similarity: float,
                multi_pass_triggered: bool, fts_fallback_used: bool,
                reranker_used: bool, reranker_changes: int,
                reranker_top1_changed: int, reranker_avg_displacement: float,
                graph_discoveries: int, latency_ms: int):
    """Log recall metrics to recall_log table (best-effort, never raises)."""
    try:
        with graph._get_conn() as conn:
            conn.execute("""
                INSERT INTO recall_log
                    (query, owner_id, intent, results_count, avg_similarity, top_similarity,
                     multi_pass_triggered, fts_fallback_used, reranker_used, reranker_changes,
                     reranker_top1_changed, reranker_avg_displacement,
                     graph_discoveries, latency_ms)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (query, owner_id, intent, results_count,
                  round(avg_similarity, 4), round(top_similarity, 4),
                  1 if multi_pass_triggered else 0,
                  1 if fts_fallback_used else 0,
                  1 if reranker_used else 0,
                  reranker_changes, reranker_top1_changed,
                  round(reranker_avg_displacement, 3) if reranker_avg_displacement else None,
                  graph_discoveries, latency_ms))
    except Exception:
        pass  # Observability logging is strictly best-effort


def _contract_error(message: str) -> RuntimeError:
    return RuntimeError(f"Recall contract validation failed: {message}")


def _recall_telemetry_enabled() -> bool:
    """Enable verbose recall telemetry via opt-in env flag."""
    raw = str(os.getenv("QUAID_RECALL_TELEMETRY", "") or "").strip().lower()
    return raw in {"1", "true", "yes", "on", "debug"}


def _sample_recall_rows(rows: List[Dict[str, Any]], limit: int = 5) -> List[Dict[str, Any]]:
    """Return a compact sample of recall rows for telemetry."""
    sample: List[Dict[str, Any]] = []
    for row in rows[: max(0, limit)]:
        if not isinstance(row, dict):
            continue
        sample.append({
            "id": row.get("id"),
            "category": row.get("category"),
            "similarity": row.get("similarity"),
            "source_type": row.get("source_type"),
            "project": row.get("project"),
            "text_preview": str(row.get("text") or "")[:120],
        })
    return sample


def _sample_candidate_tuples(
    rows: List[Tuple["Node", float]],
    *,
    debug_info: Optional[Dict[str, Dict[str, Any]]] = None,
    limit: int = 8,
    threshold: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """Return a compact sample of internal candidate tuples for telemetry."""
    sample: List[Dict[str, Any]] = []
    for node, score in rows[: max(0, limit)]:
        attrs = node.attributes if isinstance(node.attributes, dict) else {}
        item = {
            "id": node.id,
            "category": node.type.lower(),
            "score": round(float(score), 4),
            "source_type": attrs.get("source_type"),
            "project": attrs.get("project"),
            "text_preview": str(node.name or "")[:120],
        }
        dbg = (debug_info or {}).get(node.id)
        if isinstance(dbg, dict):
            item["raw_quality_score"] = dbg.get("raw_quality_score")
            item["composite_score"] = dbg.get("composite_score")
        if threshold is not None:
            item["passes_threshold"] = bool(float(score) >= float(threshold))
        sample.append(item)
    return sample


def _append_recall_telemetry_trace(payload: Dict[str, Any]) -> None:
    """Write a per-call recall telemetry event to the workspace logs."""
    now = _now()
    if now.tzinfo is None:
        now = now.replace(tzinfo=timezone.utc)
    else:
        now = now.astimezone(timezone.utc)
    try:
        path = get_logs_dir() / "recall-telemetry.jsonl"
        path.parent.mkdir(parents=True, exist_ok=True)
        event = {
            "ts": now.isoformat(),
            **dict(payload or {}),
        }
        with path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(event, ensure_ascii=False) + "\n")
    except Exception:
        logger.exception("Failed writing recall telemetry trace")


def _validate_recall_result_rows(rows: Any) -> List[Dict[str, Any]]:
    """Validate/normalize recall rows before returning them to callers."""
    if rows is None:
        return []
    if not isinstance(rows, list):
        raise _contract_error(f"results must be a list, got {type(rows).__name__}")

    normalized: List[Dict[str, Any]] = []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise _contract_error(f"result[{index}] must be an object, got {type(row).__name__}")
        text = row.get("text")
        category = row.get("category")
        similarity = row.get("similarity")
        if not isinstance(text, str) or not text.strip():
            raise _contract_error(f"result[{index}].text must be a non-empty string")
        if not isinstance(category, str) or not category.strip():
            raise _contract_error(f"result[{index}].category must be a non-empty string")
        try:
            similarity_value = float(similarity)
        except (TypeError, ValueError) as exc:
            raise _contract_error(f"result[{index}].similarity must be numeric") from exc

        item = dict(row)
        item["text"] = text
        item["category"] = category
        item["similarity"] = round(similarity_value, 3)
        normalized.append(item)
    return normalized


def _normalize_doc_chunk_contract(chunk: Any, index: int = 0) -> Dict[str, Any]:
    """Normalize a docs chunk into the runtime recall contract."""
    if not isinstance(chunk, dict):
        raise _contract_error(f"docs.chunks[{index}] must be an object, got {type(chunk).__name__}")

    content = chunk.get("content")
    source = chunk.get("source")
    section_header = chunk.get("section_header")
    similarity = chunk.get("similarity")

    # Backward-compatible repair for older/internal keys.
    if content is None and isinstance(chunk.get("text"), str):
        content = chunk.get("text")
    if section_header is None and isinstance(chunk.get("title"), str):
        section_header = chunk.get("title")
    if similarity is None and chunk.get("score") is not None:
        similarity = chunk.get("score")

    if not isinstance(content, str) or not content.strip():
        raise _contract_error(f"docs.chunks[{index}].content must be a non-empty string")
    if not isinstance(source, str) or not source.strip():
        raise _contract_error(f"docs.chunks[{index}].source must be a non-empty string")
    if section_header is not None and not isinstance(section_header, str):
        raise _contract_error(f"docs.chunks[{index}].section_header must be a string or null")
    try:
        similarity_value = float(similarity)
    except (TypeError, ValueError) as exc:
        raise _contract_error(f"docs.chunks[{index}].similarity must be numeric") from exc

    chunk_index = chunk.get("chunk_index")
    if chunk_index is not None:
        try:
            chunk_index = int(chunk_index)
        except (TypeError, ValueError) as exc:
            raise _contract_error(f"docs.chunks[{index}].chunk_index must be an integer or null") from exc

    project = chunk.get("project")
    if project is not None and not isinstance(project, str):
        raise _contract_error(f"docs.chunks[{index}].project must be a string or null")
    source_date = chunk.get("source_date")
    if source_date is not None:
        source_date = _date_part(source_date)
        if not source_date:
            raise _contract_error(f"docs.chunks[{index}].source_date must be an ISO date or null")

    return {
        "content": content,
        "source": source,
        "section_header": section_header or None,
        "similarity": round(similarity_value, 3),
        "chunk_index": chunk_index,
        "project": project or None,
        "source_date": source_date or None,
    }


def _validate_docs_bundle(bundle: Any) -> Dict[str, Any]:
    """Validate/normalize docs payload returned by unified recall."""
    if bundle is None:
        return {"chunks": [], "project": None, "project_md": None, "telemetry": None}
    if not isinstance(bundle, dict):
        raise _contract_error(f"docs payload must be an object, got {type(bundle).__name__}")

    chunks = bundle.get("chunks", [])
    if chunks is None:
        chunks = []
    if not isinstance(chunks, list):
        raise _contract_error("docs.chunks must be a list")

    project = bundle.get("project")
    project_md = bundle.get("project_md")
    telemetry = bundle.get("telemetry")
    if project is not None and not isinstance(project, str):
        raise _contract_error("docs.project must be a string or null")
    if project_md is not None and not isinstance(project_md, str):
        raise _contract_error("docs.project_md must be a string or null")
    if telemetry is not None and not isinstance(telemetry, dict):
        raise _contract_error("docs.telemetry must be an object or null")

    return {
        "chunks": [_normalize_doc_chunk_contract(chunk, index=i) for i, chunk in enumerate(chunks)],
        "project": project or None,
        "project_md": project_md,
        "telemetry": telemetry if isinstance(telemetry, dict) else None,
    }


def _normalize_source_chunk_output_token_limit(max_chunk_tokens: Optional[int]) -> int:
    try:
        value = int(max_chunk_tokens) if max_chunk_tokens is not None else 512
    except (TypeError, ValueError):
        value = 512
    return max(1, min(value, 4000))


def _normalize_source_chunk_total_token_limit(max_total_chunk_tokens: Optional[int]) -> int:
    try:
        value = int(max_total_chunk_tokens) if max_total_chunk_tokens is not None else 2048
    except (TypeError, ValueError):
        value = 2048
    return max(1, min(value, 16000))


def _truncate_source_chunk_output_text(text: str, *, max_chunk_tokens: int) -> Tuple[str, bool, int]:
    clean = str(text or "")
    token_count = int(_lib_estimate_tokens(clean))
    if token_count <= max_chunk_tokens:
        return clean, False, token_count

    lo = 0
    hi = len(clean)
    best = ""
    best_tokens = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        candidate = clean[:mid].rstrip()
        candidate_tokens = int(_lib_estimate_tokens(candidate))
        if candidate_tokens <= max_chunk_tokens:
            best = candidate
            best_tokens = candidate_tokens
            lo = mid + 1
        else:
            hi = mid - 1
    return best, True, best_tokens


def _source_chunk_recall_payload(chunk: Dict[str, Any], *, max_chunk_tokens: int) -> Dict[str, Any]:
    text, truncated, output_tokens = _truncate_source_chunk_output_text(
        str(chunk.get("text") or ""),
        max_chunk_tokens=max_chunk_tokens,
    )
    return {
        "chunk_id": chunk.get("chunk_id"),
        "text": text,
        "truncated": bool(truncated),
        "output_token_count": int(output_tokens),
        "token_count": int(chunk.get("token_count") or 0),
        "source_id": chunk.get("source_id"),
        "session_id": chunk.get("session_id"),
        "chunk_index": chunk.get("chunk_index"),
        "chunk_kind": chunk.get("chunk_kind"),
        "parent_chunk_id": chunk.get("parent_chunk_id"),
        "next_chunk_id": chunk.get("next_chunk_id"),
        "message_id": chunk.get("message_id"),
        "message_pair_id": chunk.get("message_pair_id"),
        "microchunk_id": chunk.get("microchunk_id"),
        "content_hash": chunk.get("content_hash"),
        "source_channel": chunk.get("source_channel"),
        "source_conversation_id": chunk.get("source_conversation_id"),
        "conversation_id": chunk.get("conversation_id"),
        "source_author_id": chunk.get("source_author_id"),
        "source_type": chunk.get("source_type"),
        "privacy": chunk.get("privacy"),
        "visibility_scope": chunk.get("visibility_scope"),
        "sensitivity": chunk.get("sensitivity"),
        "domains": chunk.get("domains"),
        "project": chunk.get("project"),
        "source_date": chunk.get("source_date"),
        "created_at": chunk.get("created_at"),
    }


def _attach_source_chunks_to_recall_rows(
    rows: Any,
    *,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
) -> Tuple[Any, Dict[str, Any]]:
    """Attach bounded source chunk evidence to already-selected recall rows."""
    if rows is None:
        normalized_rows: List[Any] = []
    elif isinstance(rows, list):
        normalized_rows = [dict(row) if isinstance(row, dict) else row for row in rows]
    else:
        normalized_rows = rows
    token_limit = _normalize_source_chunk_output_token_limit(max_chunk_tokens)
    total_token_limit = _normalize_source_chunk_total_token_limit(max_total_chunk_tokens)
    summary = {
        "requested": True,
        "attached": 0,
        "missing": 0,
        "omitted": 0,
        "linked_rows": 0,
        "max_chunk_tokens": token_limit,
        "max_total_chunk_tokens": total_token_limit,
        "output_token_count": 0,
        "failed": False,
    }
    if not isinstance(normalized_rows, list) or not normalized_rows:
        return normalized_rows, summary

    row_ids = [
        str(row.get("id") or "").strip()
        for row in normalized_rows
        if isinstance(row, dict) and str(row.get("id") or "").strip()
    ]
    try:
        graph = get_graph()
        id_to_link: Dict[str, Tuple[Optional[str], Optional[str]]] = {}
        chunk_owner_pairs: set[Tuple[str, str]] = set()
        with graph._get_conn() as conn:
            if row_ids:
                placeholders = ",".join("?" for _ in row_ids)
                for db_row in conn.execute(
                    f"SELECT id, source_chunk_id, owner_id FROM nodes WHERE id IN ({placeholders})",
                    row_ids,
                ).fetchall():
                    chunk_id = str(db_row["source_chunk_id"] or "").strip() or None
                    owner = str(db_row["owner_id"] or "").strip() or None
                    id_to_link[str(db_row["id"])] = (chunk_id, owner)
                    if chunk_id and owner:
                        chunk_owner_pairs.add((chunk_id, owner))
            for row in normalized_rows:
                if not isinstance(row, dict):
                    continue
                row_source_type = str(row.get("source_type") or row.get("category") or "").strip().lower()
                row_chunk_id = str(row.get("source_chunk_id") or "").strip()
                if not row_chunk_id and row_source_type in {"source_chunk", "session_chunk"}:
                    row_chunk_id = str(row.get("chunk_id") or row.get("session_chunk_id") or "").strip()
                if not row_chunk_id:
                    row_chunk_id = str(row.get("session_window_center_chunk_id") or "").strip()
                row_owner = str(row.get("owner_id") or "").strip()
                if row_chunk_id and row_owner:
                    chunk_owner_pairs.add((row_chunk_id, row_owner))
            chunks_by_key: Dict[Tuple[str, str], Dict[str, Any]] = {}
            chunk_existing_owners: Dict[str, set[str]] = {}
            if chunk_owner_pairs:
                graph._ensure_source_chunks_table(conn)
                sorted_pairs = sorted(chunk_owner_pairs)
                clauses = " OR ".join("(chunk_id = ? AND owner_id = ?)" for _ in sorted_pairs)
                params = [value for pair in sorted_pairs for value in pair]
                for db_row in conn.execute(
                    f"SELECT * FROM source_chunks WHERE {clauses}",
                    params,
                ).fetchall():
                    chunk = graph._row_to_source_chunk(db_row)
                    chunk_id = str(chunk.get("chunk_id") or "").strip()
                    chunk_owner = str(chunk.get("owner_id") or "").strip()
                    if chunk_id and chunk_owner:
                        chunks_by_key[(chunk_id, chunk_owner)] = chunk
                chunk_ids = sorted({chunk_id for chunk_id, _owner in sorted_pairs if chunk_id})
                if chunk_ids:
                    placeholders = ",".join("?" for _ in chunk_ids)
                    for db_row in conn.execute(
                        f"SELECT chunk_id, owner_id FROM source_chunks WHERE chunk_id IN ({placeholders})",
                        chunk_ids,
                    ).fetchall():
                        chunk_id = str(db_row["chunk_id"] or "").strip()
                        chunk_owner = str(db_row["owner_id"] or "").strip()
                        if chunk_id and chunk_owner:
                            chunk_existing_owners.setdefault(chunk_id, set()).add(chunk_owner)
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError("Failed to attach source chunks to recall results") from exc
        logger.warning(
            "[recall] include_chunks failed while reading source chunks: %s",
            exc,
            exc_info=True,
        )
        summary["failed"] = True
        return normalized_rows, summary

    for row in normalized_rows:
        if not isinstance(row, dict):
            continue
        row_id = str(row.get("id") or "").strip()
        source_type = str(row.get("source_type") or row.get("category") or "").strip().lower()
        chunk_id = str(row.get("source_chunk_id") or "").strip() or None
        if not chunk_id and source_type in {"source_chunk", "session_chunk"}:
            chunk_id = str(row.get("chunk_id") or row.get("session_chunk_id") or "").strip() or None
        if not chunk_id:
            chunk_id = str(row.get("session_window_center_chunk_id") or "").strip() or None
        row_owner = str(row.get("owner_id") or "").strip() or None
        if not chunk_id and row_id:
            chunk_id, linked_owner = id_to_link.get(row_id, (None, None))
            row_owner = row_owner or linked_owner
        if not chunk_id:
            continue
        summary["linked_rows"] += 1
        row["source_chunk_id"] = chunk_id
        if not row_owner:
            summary["missing"] += 1
            row["source_chunk_missing"] = True
            if _is_fail_hard_mode():
                raise RuntimeError(
                    f"Recall result source chunk owner missing: result={row_id} chunk={chunk_id}"
                )
            logger.warning(
                "[recall] include_chunks owner missing for result %s chunk %s",
                row_id,
                chunk_id,
            )
            continue
        chunk = chunks_by_key.get((chunk_id, row_owner))
        if not chunk:
            existing_owners = chunk_existing_owners.get(chunk_id, set())
            if row_owner and existing_owners and row_owner not in existing_owners:
                summary["missing"] += 1
                row["source_chunk_missing"] = True
                if _is_fail_hard_mode():
                    raise RuntimeError(
                        f"Recall result source chunk owner mismatch: result={row_id} chunk={chunk_id}"
                    )
                logger.warning(
                    "[recall] include_chunks owner mismatch for result %s chunk %s",
                    row_id,
                    chunk_id,
                )
                continue
            summary["missing"] += 1
            row["source_chunk_missing"] = True
            if _is_fail_hard_mode():
                raise RuntimeError(f"Recall result references missing source chunk: {chunk_id}")
            logger.warning("[recall] include_chunks missing source chunk %s for result %s", chunk_id, row_id)
            continue
        chunk_owner = str(chunk.get("owner_id") or "").strip() or None
        if chunk_owner != row_owner:
            summary["missing"] += 1
            row["source_chunk_missing"] = True
            if _is_fail_hard_mode():
                raise RuntimeError(
                    f"Recall result source chunk owner mismatch: result={row_id} chunk={chunk_id}"
                )
            logger.warning(
                "[recall] include_chunks owner mismatch for result %s chunk %s",
                row_id,
                chunk_id,
            )
            continue
        remaining_tokens = total_token_limit - int(summary.get("output_token_count") or 0)
        if remaining_tokens <= 0:
            summary["omitted"] += 1
            row["source_chunk_omitted"] = True
            continue
        row_token_limit = min(token_limit, remaining_tokens)
        source_chunk = _source_chunk_recall_payload(chunk, max_chunk_tokens=row_token_limit)
        row["source_chunk"] = source_chunk
        summary["output_token_count"] = int(summary.get("output_token_count") or 0) + int(
            source_chunk.get("output_token_count") or 0
        )
        summary["attached"] += 1
    return normalized_rows, summary


def _prioritize_attached_source_chunk_rows(rows: Any) -> Any:
    """For include_chunks output, make attached first-order evidence visible first."""
    if not isinstance(rows, list) or len(rows) <= 1:
        return rows
    attached: List[Any] = []
    other: List[Any] = []
    for row in rows:
        if isinstance(row, dict) and isinstance(row.get("source_chunk"), dict):
            attached.append(row)
        else:
            other.append(row)
    if not attached or not other:
        return rows
    return [*attached, *other]


_DEFAULT_RECALL_RAW_PROVENANCE_FIELDS = {
    # Raw datastore/source linkage is opt-in evidence metadata. Default recall
    # output should keep readable context fields, not internal row ids.
    "chunk_id",
    "microchunk_id",
    "next_chunk_id",
    "parent_chunk_id",
    "session_chunk_id",
    "session_window_center_chunk_id",
    "session_window_center_microchunk_id",
    "session_window_chunk_ids",
    "source_chunk_id",
    "source_chunk_ids",
    "source_id",
    "source_provenance_type",
}


_SESSION_CHUNK_NAVIGATION_FIELDS = {"chunk_id", "session_chunk_id"}


def _is_session_chunk_output_row(row: Dict[str, Any]) -> bool:
    source_type = str(row.get("source_type") or "").strip().lower()
    via = str(row.get("via") or "").strip().lower()
    return source_type == "session_chunk" or via == "session_chunks"


def _should_suppress_default_session_chunk_rows(
    meta: Optional[Dict[str, Any]],
    *,
    suppress_session_chunk_rows: bool,
    respect_auto_include_meta: bool = True,
) -> bool:
    # CLI default store plans pass the flag; API/programmatic recall uses persisted auto-include metadata.
    if suppress_session_chunk_rows:
        return True
    if not respect_auto_include_meta:
        return False
    if not isinstance(meta, dict):
        return False
    return bool(meta.get("session_chunks_auto_included"))


def _sanitize_default_recall_output_row(row: Dict[str, Any]) -> Dict[str, Any]:
    sanitized = dict(row)
    preserve_session_chunk_navigation = _is_session_chunk_output_row(row)
    for field in _DEFAULT_RECALL_RAW_PROVENANCE_FIELDS:
        if preserve_session_chunk_navigation and field in _SESSION_CHUNK_NAVIGATION_FIELDS:
            continue
        sanitized.pop(field, None)
    if preserve_session_chunk_navigation:
        chunk_id = str(row.get("chunk_id") or row.get("session_chunk_id") or "").strip()
        if chunk_id:
            sanitized.setdefault("chunk_id", chunk_id)
            sanitized.setdefault("session_chunk_id", chunk_id)
    return sanitized


def _prepare_recall_output_rows(
    rows: Any,
    meta: Optional[Dict[str, Any]],
    *,
    include_chunks: bool = False,
    preserve_source_chunk_ids: bool = False,
    suppress_session_chunk_rows: bool = False,
    respect_auto_session_chunk_meta: bool = True,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
) -> Tuple[Any, Optional[Dict[str, Any]]]:
    if not include_chunks:
        if not isinstance(rows, list):
            return rows, meta
        output_rows: List[Any] = []
        suppress_default_session_chunks = _should_suppress_default_session_chunk_rows(
            meta,
            suppress_session_chunk_rows=suppress_session_chunk_rows,
            respect_auto_include_meta=respect_auto_session_chunk_meta,
        )
        for row in rows:
            if not isinstance(row, dict) or preserve_source_chunk_ids:
                output_rows.append(row)
                continue
            if suppress_default_session_chunks and _is_session_chunk_output_row(row):
                continue
            output_rows.append(_sanitize_default_recall_output_row(row))
        return output_rows, meta
    output_rows, source_chunk_meta = _attach_source_chunks_to_recall_rows(
        rows,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )
    if int(source_chunk_meta.get("attached") or 0) > 0:
        output_rows = _prioritize_attached_source_chunk_rows(output_rows)
    output_meta = dict(meta or {})
    output_meta["session_chunks"] = source_chunk_meta
    output_meta["source_chunks"] = source_chunk_meta
    return output_rows, output_meta


def _resolve_cli_recall_owner(options: Dict[str, Any]) -> str:
    """Resolve CLI recall owner aliases before falling back to the configured default."""
    owner = str((options or {}).get("owner_id") or (options or {}).get("owner") or "").strip()
    if owner:
        return owner
    return str(_get_memory_config().users.default_owner)


def _return_validated_recall(
    rows: Any,
    meta: Optional[Dict[str, Any]],
    return_meta: bool,
    *,
    include_chunks: bool = False,
    preserve_source_chunk_ids: bool = False,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
) -> Any:
    rows, meta = _prepare_recall_output_rows(
        rows,
        meta,
        include_chunks=include_chunks,
        preserve_source_chunk_ids=preserve_source_chunk_ids,
        suppress_session_chunk_rows=(
            isinstance(meta, dict) and bool(meta.get("session_chunks_auto_included"))
        ),
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )
    validated_rows = _validate_recall_result_rows(rows)
    if isinstance(meta, dict):
        _attach_recall_meta(validated_rows, meta)
    return (validated_rows, meta) if return_meta else validated_rows


def _build_recall_json_payload(
    results: Any,
    *,
    meta: Optional[Dict[str, Any]] = None,
    docs: Optional[Dict[str, Any]] = None,
    graph_payload: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Build a machine-readable recall payload with a strict top-level contract."""
    validated_results = _validate_recall_result_rows(results)
    payload: Dict[str, Any] = {
        "contract": "quaid.recall.v1",
        "results": _strip_recall_transport_meta_from_output_rows(validated_results),
    }
    if isinstance(meta, dict):
        payload["meta"] = meta
    if docs is not None:
        payload["docs"] = _validate_docs_bundle(docs)
    if graph_payload:
        payload["direct_results"] = list(payload["results"])
        for key in ("graph_results", "entities_found", "source_breakdown"):
            if key in graph_payload:
                payload[key] = graph_payload[key]
    return payload


def _resolve_recall_store_request(cfg: Dict[str, Any]) -> Tuple[List[str], Dict[str, Any]]:
    """Resolve recall store config with stable default semantics.

    Omitted stores should preserve the standard deliberate memory recall path.
    Graph-aware recall must be explicitly requested.
    """
    stores_cfg = cfg.get("stores")
    if stores_cfg is None:
        return ["vector"], {}
    if isinstance(stores_cfg, list):
        return stores_cfg, {}
    return list(stores_cfg.keys()), stores_cfg


def _normalize_store_plan(stores: Optional[List[str]]) -> List[str]:
    allowed = {"vector", "graph", "docs", "session_chunks"}
    out: List[str] = []
    for store in list(stores or []):
        name = str(store or "").strip().lower()
        if name == "source_chunks":
            name = "session_chunks"
        if name in allowed and name not in out:
            out.append(name)
    return out or ["vector"]


def _planner_store_plan(stores: Optional[List[str]]) -> List[str]:
    """Normalize planner-selected stores and keep vector as the base lane."""
    out = _normalize_store_plan(stores)
    if "vector" not in out and ("docs" in out or "graph" in out):
        out.insert(0, "vector")
    return out


def _should_run_recall_store_plan(store_names: Optional[List[str]], *, use_fast: bool) -> bool:
    """Use the store-plan runner for fast, mixed, or non-vector explicit stores."""
    normalized = _normalize_store_plan(store_names)
    return bool(use_fast) or len(normalized) > 1 or any(store != "vector" for store in normalized)


def _session_chunks_explicitly_requested(stores_explicit: bool, store_names: List[str]) -> bool:
    return bool(stores_explicit and "session_chunks" in _normalize_store_plan(store_names))


def _infer_edge_entity_type(name: str, relation: str, is_subject: bool) -> str:
    rel_lower = str(relation or "").lower().replace("-", "_")
    relation_object_types = {
        "works_at": "Organization", "employed_by": "Organization",
        "trains_at": "Organization",
        "member_of": "Organization", "founded": "Organization",
        "lives_in": "Place", "lives_at": "Place", "located_in": "Place",
        "born_in": "Place", "moved_to": "Place", "visited": "Place",
        "has_pet": "Pet", "owns_pet": "Pet",
        "has_feature": "Feature", "uses_tool": "Tool",
        "works_on": "Project", "contributes_to": "Project",
        "manages": "Project",
    }
    relation_subject_types = {
        "subsidiary_of": "Organization", "part_of": "Organization",
        "feature_of": "Project", "component_of": "Project",
        "works_at": "Person", "employed_by": "Person",
        "trains_at": "Person",
        "lives_in": "Person", "lives_at": "Person", "visited": "Person", "moved_to": "Person",
        "has_pet": "Person", "owns_pet": "Person", "owns": "Person",
        "works_on": "Person", "contributes_to": "Person", "manages": "Person",
        "wants_to_visit": "Person",
    }
    person_relations = {
        "parent_of", "child_of", "sibling_of", "spouse_of", "partner_of",
        "friend_of", "colleague_of", "family_of", "related_to", "neighbor_of", "knows",
        "aunt_of", "uncle_of", "cousin_of", "grandparent_of",
        "has_manager", "managed_by", "mentored_by", "mentors",
        "married_to", "dating", "roommate_of", "has_employee",
    }

    if is_subject and rel_lower in relation_subject_types:
        return relation_subject_types[rel_lower]
    if not is_subject and rel_lower in relation_object_types:
        return relation_object_types[rel_lower]
    if rel_lower in person_relations:
        return "Person"
    return "Fact"


def _store_meta_result_count(meta: Optional[Dict[str, Any]]) -> int:
    if not isinstance(meta, dict):
        return 0
    counts = meta.get("counts")
    if isinstance(counts, dict):
        for key in ("final_results", "diverse_results", "post_threshold_candidates", "initial_candidates"):
            value = counts.get(key)
            if isinstance(value, (int, float)):
                return max(0, int(value))
    return 0


def _harmonize_store_plan_meta(
    meta: Optional[Dict[str, Any]],
    *,
    final_rows: List[Dict[str, Any]],
    store_runs: List[Dict[str, Any]],
) -> Dict[str, Any]:
    out = dict(meta or {})
    final_count = len(final_rows)
    counts = dict(out.get("counts") or {})
    if final_count > 0:
        for key in ("initial_candidates", "post_threshold_candidates", "diverse_results", "final_results"):
            current = counts.get(key)
            current_i = int(current) if isinstance(current, (int, float)) else 0
            if current_i < final_count:
                counts[key] = final_count
        graph_discoveries = sum(
            int(run.get("graph_discovery_count") or 0)
            for run in store_runs
            if str(run.get("store") or "") == "graph"
        )
        final_graph_rows = _count_graph_discovery_rows(final_rows)
        graph_discoveries = max(graph_discoveries, final_graph_rows)
        if graph_discoveries:
            current_graph = counts.get("graph_discoveries")
            current_graph_i = int(current_graph) if isinstance(current_graph, (int, float)) else 0
            counts["graph_discoveries"] = max(current_graph_i, graph_discoveries)
        out["counts"] = counts
        if str(out.get("stop_reason") or "") == "no_initial_results":
            out["stop_reason"] = "store_plan_results"
        bailout_counts = dict(out.get("bailout_counts") or {})
        if isinstance(bailout_counts.get("no_initial_results"), (int, float)):
            bailout_counts["no_initial_results"] = 0
            out["bailout_counts"] = bailout_counts
    elif store_runs and "stop_reason" not in out:
        out["stop_reason"] = "no_initial_results"
    return out


def _docs_bundle_to_rows(bundle: Optional[Dict[str, Any]], limit: int) -> List[Dict[str, Any]]:
    docs = _validate_docs_bundle(bundle)
    out: List[Dict[str, Any]] = []
    # Keep docs payloads bounded so a single docs-heavy recall cannot flood
    # answer context with tens of thousands of chars.
    # Config keys: retrieval.docs_per_chunk_char_cap, retrieval.docs_total_char_budget
    try:
        from config import get_config as _gc
        _r = getattr(_gc(), "retrieval", None)
        per_chunk_char_cap = int(getattr(_r, "docs_per_chunk_char_cap", 900) or 900)
        total_char_budget = int(getattr(_r, "docs_total_char_budget", 9000) or 9000)
    except Exception:
        per_chunk_char_cap = 900
        total_char_budget = 9000
    consumed_chars = 0
    for chunk in docs["chunks"][:limit]:
        text = " ".join(str(chunk.get("content") or "").split()).strip()
        if not text:
            continue
        if len(text) > per_chunk_char_cap:
            text = text[: per_chunk_char_cap - 1].rstrip() + "…"
        if consumed_chars + len(text) > total_char_budget:
            remaining = total_char_budget - consumed_chars
            if remaining <= 160:
                break
            text = text[: remaining - 1].rstrip() + "…"
        source = str(chunk.get("source") or "").strip()
        section = str(chunk.get("section_header") or "").strip()
        project = str(chunk.get("project") or "").strip() or None
        source_date = _date_part(chunk.get("source_date"))
        prefix = f"[docs] {source}"
        if section:
            prefix += f" > {section}"
        out.append({
            "text": f"{prefix}: {text}",
            "similarity": float(chunk.get("similarity") or 0.0),
            "category": "docs",
            "source_type": "docs",
            "project": project,
            "source": source or None,
            "section_header": section or None,
            "source_date": source_date or None,
        })
        consumed_chars += len(text)
        if consumed_chars >= total_char_budget:
            break

    # If scoped docs recall missed entirely but discovered plausible matches in
    # unlinked projects, emit a compact row so the agent can ask the user to
    # link explicitly before filesystem fallback.
    if not out:
        telemetry = docs.get("telemetry") if isinstance(docs.get("telemetry"), dict) else {}
        scope_hint = telemetry.get("scope_hint") if isinstance(telemetry, dict) else None
        if isinstance(scope_hint, dict) and str(scope_hint.get("type") or "") == "unlinked_project_candidates":
            candidates = scope_hint.get("candidates")
            if isinstance(candidates, list):
                names = []
                for item in candidates:
                    if not isinstance(item, dict):
                        continue
                    project = str(item.get("project") or "").strip()
                    if not project:
                        continue
                    path = str(item.get("path") or "").strip()
                    names.append(f"{project} ({path})" if path else project)
                if names:
                    out.append(
                        {
                            "text": (
                                "[docs] scoped miss: likely matches may exist in unlinked project(s): "
                                f"{', '.join(names)}. For read-only lookups or one-fact questions, "
                                "answer from scoped recall or direct file read without linking. "
                                "Link only when the user explicitly asks to link the project or requests "
                                "durable work such as edits, API/tool use, or starting development."
                            ),
                            "similarity": 0.0,
                            "category": "docs_scope_hint",
                            "source_type": "docs",
                        }
                    )
    return out


def _build_docs_only_recall_json_payload(doc_results: Dict[str, Any], *, limit: int) -> Dict[str, Any]:
    """Build JSON for docs-only recall with docs hits visible as top-level rows."""
    return _build_recall_json_payload(
        _docs_bundle_to_rows(doc_results, limit=limit),
        docs=doc_results,
    )


_CLI_VECTOR_RECALL_KWARGS = frozenset({
    "limit",
    "owner_id",
    "min_similarity",
    "current_session_id",
    "compaction_time",
    "date_from",
    "date_to",
    "temporal_dimension",
    "debug",
    "domain",
    "domain_boost",
    "project",
    "timeout_ms",
    "include_chunks",
    "max_chunk_tokens",
    "max_total_chunk_tokens",
    "use_multi_pass",
    "use_reranker",
    "max_turns",
    "use_routing",
    "planner_profile",
    "planned_queries",
    "planner_meta",
})


def _should_broker_cli_vector_recall(
    *,
    stores_explicit: bool,
    store_names: List[str],
    archive: Any = False,
    session_id: Optional[str] = None,
) -> bool:
    """Return true only for the M5 explicit vector-only activation slice."""
    if not stores_explicit or archive or session_id:
        return False
    normalized = [str(store or "").strip().lower().replace("-", "_") for store in list(store_names or [])]
    return normalized == ["vector"]


def _build_cli_vector_recall_kwargs(
    *,
    limit: int,
    owner: str,
    min_similarity: Any,
    current_session_id: Optional[str],
    compaction_time: Optional[str],
    date_from: Optional[str],
    date_to: Optional[str],
    temporal_dimension: Optional[str],
    use_debug: bool,
    domain_filter: Dict[str, Any],
    domain_boost: Any,
    project: Optional[str],
    timeout_ms: Optional[int],
    include_chunks: bool,
    max_chunk_tokens: Optional[int],
    max_total_chunk_tokens: Optional[int],
    use_fast: bool,
    planner_profile: str,
    planned_queries: Optional[List[str]],
    planned_meta: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    """Build the exact recall kwargs used by the existing vector-only CLI path."""
    recall_kwargs: Dict[str, Any] = dict(
        limit=limit,
        owner_id=owner,
        min_similarity=min_similarity,
        current_session_id=current_session_id,
        compaction_time=compaction_time,
        date_from=date_from,
        date_to=date_to,
        temporal_dimension=temporal_dimension,
        debug=use_debug,
        domain=domain_filter,
        domain_boost=domain_boost,
        project=project,
        timeout_ms=timeout_ms,
        include_chunks=include_chunks,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )
    if use_fast:
        recall_kwargs["use_multi_pass"] = False
        recall_kwargs["use_reranker"] = False
        recall_kwargs["max_turns"] = 1
        recall_kwargs["use_routing"] = False
    recall_kwargs["planner_profile"] = planner_profile
    if planned_queries is not None and not use_fast:
        recall_kwargs["planned_queries"] = planned_queries
        recall_kwargs["planner_meta"] = planned_meta
    return recall_kwargs


def _resolve_cli_recall_owner(options: Dict[str, Any]) -> str:
    """Resolve CLI recall owner aliases before falling back to the configured default."""
    owner = str((options or {}).get("owner_id") or (options or {}).get("owner") or "").strip()
    if owner:
        return owner
    return str(_get_memory_config().users.default_owner)


def _validate_cli_vector_recall_kwargs(value: Any) -> Dict[str, Any]:
    if not isinstance(value, dict):
        raise _contract_error("vector request options.recall_kwargs must be an object")
    unknown = sorted(set(value) - _CLI_VECTOR_RECALL_KWARGS)
    if unknown:
        raise _contract_error(f"vector request options.recall_kwargs has unsupported keys: {unknown}")
    return dict(value)


_MEMORY_VECTOR_REQUEST_SELECTORS = frozenset({"vector", "vector_basic", "vector_technical"})


def _run_cli_vector_recall_request(query: str, options: Dict[str, Any], *, selector: str = "vector") -> Dict[str, Any]:
    """Execute vector-backed recall through the broker request handler."""
    recall_kwargs = _validate_cli_vector_recall_kwargs((options or {}).get("recall_kwargs"))
    rows, meta = recall(query, return_meta=True, **recall_kwargs)
    return {
        "status": "ok",
        "selector": selector,
        "store": "vector",
        "results": _validate_recall_result_rows(rows),
        "meta": dict(meta or {}),
    }


def _handle_cli_vector_recall_request(event: Dict[str, Any]) -> Dict[str, Any]:
    payload = event.get("payload") if isinstance(event, dict) else None
    if not isinstance(payload, dict):
        raise _contract_error("vector request event payload must be an object")
    selector = str(payload.get("selector") or "").strip().lower().replace("-", "_")
    store = str(payload.get("store") or "").strip().lower().replace("-", "_")
    if selector not in _MEMORY_VECTOR_REQUEST_SELECTORS or store != "vector":
        return {
            "status": "nacked",
            "error": "M6 memory recall handler only supports selector vector/vector_basic/vector_technical with store vector",
            "selector": selector,
            "store": store,
        }
    query = str(payload.get("query") or "").strip()
    if not query:
        raise _contract_error("vector request payload.query is required")
    options = payload.get("options")
    if options is None:
        options = {}
    if not isinstance(options, dict):
        raise _contract_error("vector request payload.options must be an object")
    return _run_cli_vector_recall_request(query, dict(options), selector=selector)


def _register_cli_vector_recall_request_handler() -> None:
    from core.contracts.recall import RECALL_MEMORY_REQUEST
    from core.runtime.events import register_request_handler

    register_request_handler(
        RECALL_MEMORY_REQUEST,
        _handle_cli_vector_recall_request,
        datastore_id="memorydb",
        force=True,
    )


def _validate_cli_vector_broker_response(response: Any) -> Dict[str, Any]:
    if not isinstance(response, dict):
        raise _contract_error(f"vector broker response must be an object, got {type(response).__name__}")
    if str(response.get("status") or "") != "ok":
        response_error = response.get("error")
        responses_for_error = response.get("responses")
        if not response_error and isinstance(responses_for_error, list) and len(responses_for_error) == 1:
            handler_for_error = responses_for_error[0]
            if isinstance(handler_for_error, dict):
                result_for_error = handler_for_error.get("result")
                response_error = handler_for_error.get("error")
                if not response_error and isinstance(result_for_error, dict):
                    response_error = result_for_error.get("error")
        raise _contract_error(str(response_error or "vector broker request failed"))
    responses = response.get("responses")
    if not isinstance(responses, list) or len(responses) != 1:
        raise _contract_error("vector broker response must contain exactly one handler response")
    handler_response = responses[0]
    if not isinstance(handler_response, dict):
        raise _contract_error("vector broker handler response must be an object")
    if str(handler_response.get("datastore_id") or "") != "memorydb":
        raise _contract_error("vector broker handler must be memorydb")
    if str(handler_response.get("status") or "") not in {"ok", "acked"}:
        result_payload = handler_response.get("result")
        result_error = result_payload.get("error") if isinstance(result_payload, dict) else None
        raise _contract_error(str(handler_response.get("error") or result_error or "vector broker handler failed"))
    result = handler_response.get("result")
    if not isinstance(result, dict):
        raise _contract_error("vector broker handler result must be an object")
    if "results" not in result:
        raise _contract_error("vector broker handler result.results must be a list")
    rows = _validate_recall_result_rows(result.get("results"))
    meta = result.get("meta")
    if meta is not None and not isinstance(meta, dict):
        raise _contract_error("vector broker handler result.meta must be an object or null")
    return {
        "selector": str(result.get("selector") or ""),
        "store": str(result.get("store") or ""),
        "results": rows,
        "meta": dict(meta or {}),
    }


def _request_cli_vector_recall_via_broker(
    query: str,
    recall_kwargs: Dict[str, Any],
    *,
    selector: str = "vector",
    store: str = "vector",
    register_handler: bool = True,
) -> Dict[str, Any]:
    from core.contracts.recall import (
        RECALL_MEMORY_REQUEST,
        build_recall_request_payload,
        resolve_recall_request_routes,
    )
    from core.runtime.events import request_broker_event

    if register_handler:
        _register_cli_vector_recall_request_handler()
    route = resolve_recall_request_routes([selector])[0]
    if route.event_type != RECALL_MEMORY_REQUEST:
        raise _contract_error(f"selector {selector!r} does not route to memory recall")
    payload = build_recall_request_payload(
        query=query,
        route=route,
        limit=int(recall_kwargs.get("limit") or 1),
        options={"recall_kwargs": dict(recall_kwargs or {})},
    )
    payload["store"] = str(store or "").strip().lower().replace("-", "_")
    response = request_broker_event(
        RECALL_MEMORY_REQUEST,
        payload,
        source="memory_graph.recall_memory_request",
        provenance={
            "replacement": "datastore.memorydb.memory_graph.recall vector-backed direct branch",
        },
    )
    return _validate_cli_vector_broker_response(response)


def _build_cli_memory_recall_request_kwargs(options: Dict[str, Any]) -> Dict[str, Any]:
    """Build recall kwargs for internal vector-backed broker requests."""
    use_fast = bool(options.get("fast"))
    return _build_cli_vector_recall_kwargs(
        limit=int(options.get("limit") or 1),
        owner=_resolve_cli_recall_owner(options),
        min_similarity=options.get("min_similarity", 0.60),
        current_session_id=options.get("current_session_id"),
        compaction_time=options.get("compaction_time"),
        date_from=options.get("date_from"),
        date_to=options.get("date_to"),
        temporal_dimension=options.get("temporal_dimension"),
        use_debug=bool(options.get("debug")),
        domain_filter=options.get("domain_filter") if isinstance(options.get("domain_filter"), dict) else {"all": True},
        domain_boost=options.get("domain_boost", []),
        project=options.get("project") if isinstance(options.get("project"), str) else None,
        timeout_ms=options.get("timeout_ms") if isinstance(options.get("timeout_ms"), int) else None,
        include_chunks=False,
        max_chunk_tokens=None,
        max_total_chunk_tokens=None,
        use_fast=use_fast,
        planner_profile="fast" if use_fast else "full",
        planned_queries=None,
        planned_meta=None,
    )


def _run_cli_vector_recall_branch(
    query: str,
    recall_kwargs: Dict[str, Any],
    *,
    use_json: bool,
    stores_explicit: bool,
    store_names: List[str],
    archive: Any = False,
    session_id: Optional[str] = None,
) -> Tuple[Optional[Dict[str, Any]], Optional[List[Dict[str, Any]]]]:
    use_vector_broker = _should_broker_cli_vector_recall(
        stores_explicit=stores_explicit,
        store_names=store_names,
        archive=archive,
        session_id=session_id,
    )
    if use_json:
        if use_vector_broker:
            vector_response = _request_cli_vector_recall_via_broker(query, recall_kwargs)
            results = vector_response["results"]
            meta = vector_response["meta"]
        else:
            # M5: non-vector-only CLI paths keep their existing direct path until
            # their own broker activation slices.
            results, meta = recall(query, return_meta=True, **recall_kwargs)
        return _build_recall_json_payload(results, meta=meta), None

    if use_vector_broker:
        vector_response = _request_cli_vector_recall_via_broker(query, recall_kwargs)
        text_memory_results = vector_response["results"]
    else:
        # M5: non-vector-only CLI paths keep their existing direct path until
        # their own broker activation slices.
        text_memory_results = recall(query, **recall_kwargs)
    return None, text_memory_results


def _build_cli_docs_recall_options(
    cfg: Dict[str, Any],
    store_opts: Dict[str, Any],
    *,
    limit: int,
    want_memory: bool,
    date_from: Optional[str],
    date_to: Optional[str],
) -> Dict[str, Any]:
    """Preserve the existing CLI docs-only recall knobs at the broker boundary."""
    docs_opts = store_opts.get("docs", {}) if isinstance(store_opts, dict) else {}
    doc_project = docs_opts.get("project", cfg.get("project"))
    doc_limit = docs_opts.get("limit", limit if not want_memory else 3)
    docs_fanout_max = int(cfg.get("docs_fanout_max", 8))
    if not want_memory:
        doc_limit = min(int(doc_limit), docs_fanout_max)
    doc_filters = docs_opts.get("docs", cfg.get("docs"))
    if isinstance(doc_filters, str):
        doc_filters = [d.strip() for d in doc_filters.split(",") if d.strip()]
    doc_min_similarity = docs_opts.get("min_similarity", cfg.get("min_similarity", 0.30))
    if not want_memory:
        docs_floor = float(cfg.get("docs_only_min_similarity_floor", 0.35))
        doc_min_similarity = max(float(doc_min_similarity), docs_floor)
    bounded_limit = max(1, min(doc_limit, docs_fanout_max))
    return {
        "project": doc_project if doc_project else None,
        "docs": doc_filters,
        "limit": bounded_limit,
        "min_similarity": doc_min_similarity,
        "docs_only": not want_memory,
        "fallback_min_similarity": float(cfg.get("min_similarity", 0.20)),
        "date_from": date_from,
        "date_to": date_to,
    }


def _run_cli_docs_recall_request(query: str, options: Dict[str, Any]) -> Dict[str, Any]:
    """Execute the docs recall request handler using the old CLI search semantics."""
    from datastore.docsdb.rag import DocsRAG as _DocsRAG

    selector = str(options.get("selector") or "docs").strip().lower().replace("-", "_")
    if selector not in {"docs", "project"}:
        raise _contract_error("docs request selector must be docs or project")
    bounded_limit = max(1, int(options.get("limit") or 1))
    project = options.get("project") if options.get("project") else None
    doc_filters = options.get("docs")
    doc_min_similarity = options.get("min_similarity", 0.30)
    date_from = options.get("date_from")
    date_to = options.get("date_to")
    rag = _DocsRAG()
    doc_results = _search_docs_bundle_compat(
        rag,
        query=query,
        limit=bounded_limit,
        min_similarity=doc_min_similarity,
        project=project,
        docs=doc_filters,
        date_from=date_from,
        date_to=date_to,
    )
    if bool(options.get("docs_only")) and not _validate_docs_bundle(doc_results).get("chunks"):
        doc_results = _search_docs_bundle_compat(
            rag,
            query=query,
            limit=bounded_limit,
            min_similarity=float(options.get("fallback_min_similarity", 0.20)),
            project=project,
            docs=doc_filters,
            date_from=date_from,
            date_to=date_to,
        )
    docs = _validate_docs_bundle(doc_results)
    return {
        "status": "ok",
        "selector": selector,
        "store": "docs",
        "docs": docs,
        "limit": bounded_limit,
        "meta": {
            "query": query,
            "requested_project": project,
            "resolved_project": docs.get("project"),
            "chunk_count": len(docs.get("chunks", []) or []),
            "project_md_attached": bool(docs.get("project_md")),
        },
    }


def _handle_cli_docs_recall_request(event: Dict[str, Any]) -> Dict[str, Any]:
    payload = event.get("payload") if isinstance(event, dict) else None
    if not isinstance(payload, dict):
        raise _contract_error("docs request event payload must be an object")
    if str(payload.get("store") or "") != "docs":
        raise _contract_error("docs request payload.store must be docs")
    selector = str(payload.get("selector") or "docs").strip().lower().replace("-", "_")
    if selector not in {"docs", "project"}:
        raise _contract_error("docs request payload.selector must be docs or project")
    query = str(payload.get("query") or "").strip()
    if not query:
        raise _contract_error("docs request payload.query is required")
    options = payload.get("options")
    if options is None:
        options = {}
    if not isinstance(options, dict):
        raise _contract_error("docs request payload.options must be an object")
    request_options = dict(options)
    request_options["limit"] = int(payload.get("limit") or request_options.get("limit") or 1)
    request_options["selector"] = selector
    return _run_cli_docs_recall_request(query, request_options)


def _register_cli_docs_recall_request_handler() -> None:
    from core.contracts.recall import RECALL_DOCS_REQUEST
    from core.runtime.events import register_request_handler

    register_request_handler(
        RECALL_DOCS_REQUEST,
        _handle_cli_docs_recall_request,
        datastore_id="docsdb",
        force=True,
    )


def _validate_cli_docs_broker_response(response: Any) -> Dict[str, Any]:
    if not isinstance(response, dict):
        raise _contract_error(f"docs broker response must be an object, got {type(response).__name__}")
    if str(response.get("status") or "") != "ok":
        raise _contract_error(str(response.get("error") or "docs broker request failed"))
    responses = response.get("responses")
    if not isinstance(responses, list) or len(responses) != 1:
        raise _contract_error("docs broker response must contain exactly one handler response")
    handler_response = responses[0]
    if not isinstance(handler_response, dict):
        raise _contract_error("docs broker handler response must be an object")
    if str(handler_response.get("datastore_id") or "") != "docsdb":
        raise _contract_error("docs broker handler must be docsdb")
    if str(handler_response.get("status") or "") not in {"ok", "acked"}:
        raise _contract_error(str(handler_response.get("error") or "docs broker handler failed"))
    result = handler_response.get("result")
    if not isinstance(result, dict):
        raise _contract_error("docs broker handler result must be an object")
    selector = str(result.get("selector") or "docs").strip().lower().replace("-", "_")
    if selector not in {"docs", "project"}:
        raise _contract_error("docs broker handler result.selector must be docs or project")
    if result.get("store") is not None and str(result.get("store") or "") != "docs":
        raise _contract_error("docs broker handler result.store must be docs")
    if not isinstance(result.get("docs"), dict):
        raise _contract_error("docs broker handler result.docs must be an object")
    docs = _validate_docs_bundle(result.get("docs"))
    try:
        limit = int(result.get("limit"))
    except (TypeError, ValueError) as exc:
        raise _contract_error("docs broker handler result.limit must be an integer") from exc
    if limit <= 0:
        raise _contract_error("docs broker handler result.limit must be positive")
    meta = result.get("meta")
    if meta is not None and not isinstance(meta, dict):
        raise _contract_error("docs broker handler result.meta must be an object or null")
    return {
        "selector": selector,
        "store": "docs",
        "docs": docs,
        "limit": limit,
        "meta": dict(meta or {}),
    }


def _request_cli_docs_recall_via_broker(
    query: str,
    options: Dict[str, Any],
    *,
    register_handler: bool = True,
) -> Dict[str, Any]:
    from core.contracts.recall import (
        RECALL_DOCS_REQUEST,
        build_recall_request_payload,
        resolve_recall_request_routes,
    )
    from core.runtime.events import request_broker_event

    if register_handler:
        _register_cli_docs_recall_request_handler()
    selector = str(options.get("selector") or "docs").strip().lower().replace("-", "_")
    route = resolve_recall_request_routes([selector])[0]
    if route.event_type != RECALL_DOCS_REQUEST or route.handler_store != "docs":
        raise _contract_error("docs broker selector must route to docs")
    payload = build_recall_request_payload(
        query=query,
        route=route,
        limit=int(options.get("limit") or 1),
        options=options,
    )
    response = request_broker_event(
        RECALL_DOCS_REQUEST,
        payload,
        source="memory_graph.cli.recall",
        provenance={
            "replacement": "datastore.memorydb.memory_graph.recall docs-only direct branch",
        },
    )
    return _validate_cli_docs_broker_response(response)


def _merge_docs_bundles(existing: Optional[Dict[str, Any]], incoming: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    if not incoming:
        return existing
    if not existing:
        return _validate_docs_bundle(incoming)

    base = _validate_docs_bundle(existing)
    nxt = _validate_docs_bundle(incoming)
    seen = set()
    merged_chunks: List[Dict[str, Any]] = []
    for chunk in list(base["chunks"]) + list(nxt["chunks"]):
        key = (
            chunk.get("source"),
            chunk.get("section_header"),
            chunk.get("content"),
        )
        if key in seen:
            continue
        seen.add(key)
        merged_chunks.append(chunk)
    merged_chunks.sort(key=lambda item: float(item.get("similarity") or 0.0), reverse=True)
    return {
        "chunks": merged_chunks,
        "project": base.get("project") or nxt.get("project"),
        "project_md": base.get("project_md") or nxt.get("project_md"),
        "telemetry": nxt.get("telemetry") or base.get("telemetry"),
    }


_VECTOR_STORE_EXPLICIT_KWARGS = frozenset({
    "candidate_pool",
    "min_similarity",
    "use_routing",
    "use_aliases",
    "use_intent",
    "use_multi_pass",
    "use_reranker",
    "low_signal_retry",
    "max_turns",
    "planner_profile",
    "include_graph_traversal",
    "include_co_session",
    "include_mmr",
    "include_lexical_anchor_shaping",
    "lexical_anchor_planner_mode",
    "use_lightweight_config",
    "track_access",
    "return_meta",
    "planned_queries",
    "planner_meta",
})


def _vector_store_recall(
    query: str,
    *,
    limit: int,
    min_similarity: Optional[float],
    planner_profile: str,
    planned_queries: Optional[List[str]],
    planner_meta: Optional[Dict[str, Any]],
    fast_mode: bool,
    common_kwargs: Dict[str, Any],
) -> Tuple[List[Dict[str, Any]], Dict[str, Any], Optional[Dict[str, Any]]]:
    vector_kwargs = dict(common_kwargs or {})
    vector_kwargs = {
        key: value
        for key, value in vector_kwargs.items()
        if key not in _VECTOR_STORE_EXPLICIT_KWARGS
    }
    vector_kwargs["relative_temporal_freshness"] = bool(
        vector_kwargs.get("relative_temporal_freshness")
        or (isinstance(planner_meta, dict) and planner_meta.get("freshness_preferred") is True)
    )
    lexical_anchor_planner_mode = _seed_recall_lexical_anchor_planner_mode(
        query,
        fast_mode=fast_mode,
        date_from=vector_kwargs.get("date_from"),
        date_to=vector_kwargs.get("date_to"),
        graph_seed=False,
    )
    inner_planner_meta = dict(planner_meta or {})
    if "planned_stores" in inner_planner_meta:
        inner_planned_stores = [
            store
            for store in _planner_store_plan(inner_planner_meta.get("planned_stores") or ["vector"])
            if store in {"vector", "docs"}
        ]
        inner_planner_meta["planned_stores"] = inner_planned_stores or ["vector"]
    inner_planner_meta["suppress_session_chunks_auto_include"] = True
    inner_planner_meta["suppress_graph_auto_include"] = True
    results, meta = recall(
        query=query,
        limit=limit,
        min_similarity=min_similarity,
        use_routing=not fast_mode,
        use_aliases=not fast_mode,
        use_intent=True,
        use_multi_pass=not fast_mode,
        use_reranker=not fast_mode,
        low_signal_retry=not fast_mode,
        max_turns=1 if fast_mode else 3,
        planner_profile=planner_profile,
        include_graph_traversal=False,
        include_co_session=False if fast_mode else True,
        include_mmr=False if fast_mode else True,
        include_lexical_anchor_shaping=True,
        lexical_anchor_planner_mode=lexical_anchor_planner_mode,
        use_lightweight_config=fast_mode,
        track_access=not fast_mode,
        return_meta=True,
        preserve_source_chunk_ids=True,
        planned_queries=planned_queries,
        planner_meta=inner_planner_meta,
        **vector_kwargs,
    )
    return results, dict(meta or {}), None


def _callable_accepts_kwarg(fn: Any, name: str) -> bool:
    try:
        params = inspect.signature(fn).parameters
    except (TypeError, ValueError):
        return True
    return name in params or any(param.kind == inspect.Parameter.VAR_KEYWORD for param in params.values())


def _seed_recall_lexical_anchor_planner_mode(
    query: str,
    *,
    fast_mode: bool,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    graph_seed: bool = False,
) -> str:
    if fast_mode:
        return "deterministic"

    explicit_anchor_terms = _extract_explicit_query_anchor_terms(query, limit=4)
    if not explicit_anchor_terms:
        return "llm"

    if date_from or date_to:
        return "deterministic"

    if graph_seed:
        lowered = str(query or "").lower()
        if len(explicit_anchor_terms) >= 2:
            return "deterministic"
        if _NAMED_ENTITY_ACTIVITY_QUERY_RE.search(lowered):
            return "deterministic"

    return "llm"


def _filter_supported_kwargs(fn: Any, kwargs: Dict[str, Any]) -> Dict[str, Any]:
    try:
        params = inspect.signature(fn).parameters
    except (TypeError, ValueError):
        return dict(kwargs)
    if any(param.kind == inspect.Parameter.VAR_KEYWORD for param in params.values()):
        return dict(kwargs)
    return {key: value for key, value in kwargs.items() if key in params}


_RECALL_JSON_PLANNER_MAX_TOKENS = 768
_LEXICAL_ANCHOR_JSON_PLANNER_MAX_TOKENS = 512


_DOCS_PROJECT_LOG_LINE_DATE_RE = re.compile(
    r"^\s*-\s*(?:\[(20\d{2}-\d{2}-\d{2})(?:[T\s][^\]]*)?\]|(20\d{2}-\d{2}-\d{2})\b)"
)


def _docs_project_log_line_date(line: str) -> Optional[str]:
    match = _DOCS_PROJECT_LOG_LINE_DATE_RE.match(str(line or ""))
    if not match:
        return None
    return match.group(1) or match.group(2)


def _docs_project_log_query_terms(query: str) -> List[str]:
    """Language-neutral query terms for legacy PROJECT.log date filtering."""
    out: List[str] = []
    for raw in re.findall(r"[\w./-]+", str(query or "").lower()):
        term = raw.strip().strip("/.")
        min_len = 2 if _has_compact_unicode_char(term) else 3
        if len(term) < min_len or re.fullmatch(r"20\d{2}-\d{2}-\d{2}", term) or term in out:
            continue
        out.append(term)
    return out


def _docs_project_log_line_score(line: str, query_terms: List[str]) -> int:
    lower_line = str(line or "").lower()
    score = 0
    for term in query_terms or []:
        score += min(lower_line.count(str(term or "").lower()), 3)
    return score


def _filter_docs_project_log_content_by_date(
    content: str,
    *,
    date_from: Optional[str],
    date_to: Optional[str],
    query_terms: List[str],
) -> Optional[Tuple[str, str, int]]:
    """Return filtered PROJECT.log content plus latest date and best query score."""
    kept: List[Tuple[str, int, int, str]] = []
    for index, line in enumerate(str(content or "").splitlines()):
        line_date = _docs_project_log_line_date(line)
        if not line_date:
            continue
        if date_from and line_date < date_from:
            continue
        if date_to and line_date > date_to:
            continue
        line_score = _docs_project_log_line_score(line, query_terms)
        kept.append((line_date, index, line_score, line))
    if not kept:
        return None
    if date_to:
        kept.sort(key=lambda item: (item[0], item[2], -item[1]), reverse=True)
    latest = max(line_date for line_date, _, _, _ in kept)
    best_score = max(line_score for _, _, line_score, _ in kept)
    return "\n".join(line for _, _, _, line in kept), latest, best_score


def _docs_source_matches_filters(source_file: str, docs: Optional[List[str]]) -> bool:
    filters = [str(item or "").strip().lower() for item in (docs or []) if str(item or "").strip()]
    if not filters:
        return True
    source_lower = str(source_file or "").lower()
    basename = Path(source_lower).name
    return any(item in source_lower or item == basename for item in filters)


def _docs_source_matches_project(rag: Any, source_file: str, project: Optional[str]) -> bool:
    if not project:
        return True

    def _project_key(value: Any) -> str:
        return unicodedata.normalize("NFKC", str(value or "").strip()).casefold()

    inferred_project: Optional[str] = None
    infer_project = getattr(rag, "infer_project_for_source", None)
    if callable(infer_project):
        try:
            inferred = str(infer_project(source_file) or "").strip()
            if inferred:
                inferred_project = inferred
        except Exception as exc:
            logger.debug("_project_matches_source: failed to infer project for %s: %s", source_file, exc)
    project_token = _project_key(project)
    if not project_token:
        return True
    normalized = _project_key(str(source_file or "").replace("\\", "/"))
    path_match = (
        f"/{project_token}/" in normalized
        or normalized.startswith(f"{project_token}/")
        or normalized.endswith(f"/{project_token}/project.log")
        or normalized == f"{project_token}/project.log"
    )
    if path_match:
        return True
    return inferred_project is not None and _project_key(inferred_project) == project_token


def _docs_infer_project_for_source(rag: Any, source_file: str) -> Optional[str]:
    infer_project = getattr(rag, "infer_project_for_source", None)
    if not callable(infer_project):
        return None
    try:
        inferred = infer_project(source_file)
    except Exception:
        return None
    return str(inferred) if inferred else None


def _legacy_search_dated_project_logs(
    rag: Any,
    *,
    query: str,
    limit: int,
    project: Optional[str],
    docs: Optional[List[str]],
    date_from: Optional[str],
    date_to: Optional[str],
) -> List[Dict[str, Any]]:
    """Strict date-bounded PROJECT.log search for older DocsRAG surfaces."""
    db_path = getattr(rag, "db_path", None)
    if not db_path:
        raise RuntimeError(
            f"Date-bounded docs recall requires DocsRAG date support or db_path; got {type(rag).__name__}"
        )
    query_terms = _docs_project_log_query_terms(query)
    chunks: List[Dict[str, Any]] = []
    with _lib_get_connection(Path(db_path)) as conn:
        try:
            rows = conn.execute(
                """
                SELECT source_file, chunk_index, content, section_header
                FROM doc_chunks
                WHERE source_file LIKE ?
                """,
                ("%PROJECT.log",),
            ).fetchall()
        except sqlite3.OperationalError as exc:
            raise RuntimeError("Date-bounded docs recall requires indexed PROJECT.log chunks") from exc

    for row in rows:
        source_file = str(row["source_file"] or "")
        if Path(source_file).name != "PROJECT.log":
            continue
        if not _docs_source_matches_filters(source_file, docs):
            continue
        if not _docs_source_matches_project(rag, source_file, project):
            continue
        filtered = _filter_docs_project_log_content_by_date(
            str(row["content"] or ""),
            date_from=date_from,
            date_to=date_to,
            query_terms=query_terms,
        )
        if not filtered:
            continue
        content, latest_date, best_score = filtered
        score = 0.35 + min(best_score, 4) * 0.08
        if date_to and latest_date == date_to:
            score += 0.35
        chunks.append({
            "content": content,
            "source": source_file,
            "section_header": row["section_header"],
            "similarity": min(1.0, score),
            "_rank_score": score,
            "chunk_index": row["chunk_index"],
            "project": project or _docs_infer_project_for_source(rag, source_file),
            "source_date": latest_date,
        })
    chunks.sort(
        key=lambda item: float(item.get("_rank_score") or item.get("similarity") or 0.0),
        reverse=True,
    )
    limited = chunks[: max(1, int(limit or 1))]
    for chunk in limited:
        chunk.pop("_rank_score", None)
    return limited


def _filter_docs_chunks_by_date_bounds(
    chunks: Optional[List[Dict[str, Any]]],
    *,
    query: str,
    date_from: Optional[str],
    date_to: Optional[str],
) -> List[Dict[str, Any]]:
    """Strictly enforce date bounds on PROJECT.log chunks; preserve other docs evidence."""
    if not date_from and not date_to:
        return list(chunks or [])
    query_terms = _docs_project_log_query_terms(query)
    bounded: List[Dict[str, Any]] = []
    for raw in chunks or []:
        if not isinstance(raw, dict):
            continue
        source = str(raw.get("source") or raw.get("source_file") or "")
        if Path(source).name != "PROJECT.log":
            bounded.append(dict(raw))
            continue
        filtered = _filter_docs_project_log_content_by_date(
            str(raw.get("content") or ""),
            date_from=date_from,
            date_to=date_to,
            query_terms=query_terms,
        )
        if not filtered:
            continue
        content, latest_date, _best_score = filtered
        chunk = dict(raw)
        chunk["content"] = content
        chunk["source"] = source
        chunk["source_date"] = latest_date
        bounded.append(chunk)
    return bounded


def _with_strict_date_bounded_docs_bundle(
    rag: Any,
    *,
    query: str,
    bundle: Dict[str, Any],
    limit: int,
    project: Optional[str],
    docs: Optional[List[str]],
    date_from: Optional[str],
    date_to: Optional[str],
) -> Dict[str, Any]:
    """Apply memory-style post-merge date enforcement to docs bundles."""
    if not date_from and not date_to:
        return bundle

    raw_chunks = bundle.get("chunks") if isinstance(bundle, dict) else []
    bounded_chunks = _filter_docs_chunks_by_date_bounds(
        raw_chunks if isinstance(raw_chunks, list) else [],
        query=query,
        date_from=date_from,
        date_to=date_to,
    )
    if not bounded_chunks:
        try:
            bounded_chunks = _legacy_search_dated_project_logs(
                rag,
                query=query,
                limit=limit,
                project=project,
                docs=docs,
                date_from=date_from,
                date_to=date_to,
            )
        except RuntimeError as exc:
            if _is_fail_hard_mode():
                raise
            logger.warning("Date-bounded docs PROJECT.log fallback failed: %s", exc)
            bounded_chunks = []

    inferred_project = (project or bundle.get("project")) if isinstance(bundle, dict) else project
    infer_project = getattr(rag, "infer_project_from_chunks", None)
    if not inferred_project and callable(infer_project):
        inferred_project = infer_project(bounded_chunks)

    bounded_bundle = dict(bundle) if isinstance(bundle, dict) else {}
    bounded_bundle["chunks"] = bounded_chunks[: max(1, int(limit or 1))]
    bounded_bundle["project"] = inferred_project
    bounded_bundle["project_md"] = None
    telemetry = dict(bounded_bundle.get("telemetry") or {})
    telemetry.update({
        "query": query,
        "requested_project": project,
        "resolved_project": inferred_project,
        "requested_docs": list(docs or []),
        "chunk_count": len(bounded_bundle["chunks"]),
        "project_md_attached": False,
        "date_from": date_from,
        "date_to": date_to,
    })
    bounded_bundle["telemetry"] = telemetry
    return bounded_bundle


def _search_docs_bundle_compat(
    rag: Any,
    *,
    query: str,
    limit: int,
    min_similarity: float = 0.3,
    project: Optional[str] = None,
    docs: Optional[List[str]] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
) -> Dict[str, Any]:
    """Call DocsRAG bundle search while preserving strict date-bounded semantics."""
    date_from = _normalize_recall_date_bound(date_from)
    date_to = _normalize_recall_date_bound(date_to)
    bundle_kwargs = {
        "query": query,
        "limit": limit,
        "min_similarity": min_similarity,
        "project": project,
        "docs": docs,
        "date_from": date_from,
        "date_to": date_to,
    }
    has_date_bounds = bool(date_from or date_to)
    bundle_fn = getattr(rag, "search_docs_bundle")
    bundle_accepts_dates = (
        _callable_accepts_kwarg(bundle_fn, "date_from")
        and _callable_accepts_kwarg(bundle_fn, "date_to")
    )
    if not has_date_bounds or bundle_accepts_dates:
        bundle = bundle_fn(**_filter_supported_kwargs(bundle_fn, bundle_kwargs))
        return _with_strict_date_bounded_docs_bundle(
            rag,
            query=query,
            bundle=bundle,
            limit=limit,
            project=project,
            docs=docs,
            date_from=date_from,
            date_to=date_to,
        )

    search_fn = getattr(rag, "search_docs", None)
    if not callable(search_fn):
        chunks = _legacy_search_dated_project_logs(
            rag,
            query=query,
            limit=limit,
            project=project,
            docs=docs,
            date_from=date_from,
            date_to=date_to,
        )
        return _build_date_bounded_docs_bundle(
            rag,
            query=query,
            limit=limit,
            chunks=chunks,
            project=project,
            docs=docs,
            date_from=date_from,
            date_to=date_to,
        )
    if not (
        _callable_accepts_kwarg(search_fn, "date_from")
        and _callable_accepts_kwarg(search_fn, "date_to")
    ):
        chunks = _legacy_search_dated_project_logs(
            rag,
            query=query,
            limit=limit,
            project=project,
            docs=docs,
            date_from=date_from,
            date_to=date_to,
        )
        return _build_date_bounded_docs_bundle(
            rag,
            query=query,
            limit=limit,
            chunks=chunks,
            project=project,
            docs=docs,
            date_from=date_from,
            date_to=date_to,
        )

    chunks = search_fn(**_filter_supported_kwargs(search_fn, bundle_kwargs))
    return _build_date_bounded_docs_bundle(
        rag,
        query=query,
        limit=limit,
        chunks=chunks,
        project=project,
        docs=docs,
        date_from=date_from,
        date_to=date_to,
    )


def _build_date_bounded_docs_bundle(
    rag: Any,
    *,
    query: str,
    limit: int,
    chunks: Optional[List[Dict[str, Any]]],
    project: Optional[str],
    docs: Optional[List[str]],
    date_from: Optional[str],
    date_to: Optional[str],
) -> Dict[str, Any]:
    infer_project = getattr(rag, "infer_project_from_chunks", None)
    inferred_project = project
    if not inferred_project and callable(infer_project):
        inferred_project = infer_project(chunks)
    bundle: Dict[str, Any] = {
        "chunks": chunks or [],
        "project": inferred_project,
        "project_md": None,
    }
    telemetry = {
        "query": query,
        "requested_project": project,
        "resolved_project": inferred_project,
        "requested_docs": list(docs or []),
        "chunk_count": len(chunks or []),
        "project_md_attached": False,
        "date_from": date_from,
        "date_to": date_to,
    }
    bundle["telemetry"] = telemetry
    # Legacy searches already date-filter PROJECT.log rows; this final pass keeps
    # the date-bound invariant stable if callers merge or preserve docs rows later.
    return _with_strict_date_bounded_docs_bundle(
        rag,
        query=query,
        bundle=bundle,
        limit=limit,
        project=project,
        docs=docs,
        date_from=date_from,
        date_to=date_to,
    )


def _docs_store_recall(
    query: str,
    *,
    limit: int,
    project: Optional[str],
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any], Optional[Dict[str, Any]]]:
    started = time.monotonic()
    from datastore.docsdb.rag import DocsRAG as _DocsRAG

    rag = _DocsRAG()
    bundle = _search_docs_bundle_compat(
        rag,
        query=query,
        limit=limit,
        project=project,
        date_from=date_from,
        date_to=date_to,
    )
    rows = _docs_bundle_to_rows(bundle, limit=limit)
    elapsed_ms = round((time.monotonic() - started) * 1000)
    meta = {
        "selected_path": "docs_bundle",
        "phases_ms": {"total_ms": elapsed_ms},
        "counts": {"final_results": len(rows)},
    }
    if isinstance(bundle, dict) and isinstance(bundle.get("telemetry"), dict):
        meta["docs_telemetry"] = bundle.get("telemetry")
    return rows, meta, bundle


def _source_chunk_query_terms(query: str, *, limit: int = 10) -> List[str]:
    terms: List[str] = []
    seen: set[str] = set()
    for raw in list(_extract_explicit_query_anchor_terms(query, limit=limit)) + list(
        _extract_distinctive_query_terms(query, limit=limit)
    ):
        term = " ".join(str(raw or "").split()).strip().lower()
        if not term or term in seen:
            continue
        seen.add(term)
        terms.append(term)
        if len(terms) >= limit:
            break
    return terms


_QUOTED_ITEM_RE = re.compile(r"[\"“”]([^\"“”]{2,120})[\"“”]")


def _query_requests_temporal_answer(query: str) -> bool:
    """Return true when a query has enough structure to benefit from dated source headers."""
    return bool(_source_chunk_query_terms(query, limit=3))


def _quoted_item_mentions(text: str, *, limit: int = 8) -> List[str]:
    mentions: List[str] = []
    seen: set[str] = set()
    for match in _QUOTED_ITEM_RE.finditer(str(text or "")):
        item = " ".join(str(match.group(1) or "").split()).strip()
        key = item.lower()
        if not item or key in seen:
            continue
        if not re.search(r"[\w]", item, flags=re.UNICODE):
            continue
        seen.add(key)
        mentions.append(item)
        if len(mentions) >= limit:
            break
    return mentions


def _quoted_item_keys(text: str, *, limit: int = 8) -> List[str]:
    return [mention.lower() for mention in _quoted_item_mentions(text, limit=limit)]


def _repeated_quoted_item_keys(text: str, *, limit: int = 8) -> List[str]:
    counts: Dict[str, int] = {}
    for match in _QUOTED_ITEM_RE.finditer(str(text or "")):
        item = " ".join(str(match.group(1) or "").split()).strip()
        key = item.lower()
        if not item or not re.search(r"[\w]", item, flags=re.UNICODE):
            continue
        counts[key] = counts.get(key, 0) + 1
    keys = [key for key, count in counts.items() if count >= 2]
    return keys[: max(0, int(limit or 0))]


def _shared_quoted_item_score(scoring_text: str, terms: List[str], anchors: List[str]) -> float:
    """Score first-order transcript windows that repeat a quoted item near anchors."""
    text = str(scoring_text or "")
    repeated_keys = _repeated_quoted_item_keys(text)
    if len(anchors or []) < 2 or not repeated_keys:
        return 0.0
    anchor_hits = sum(
        1 for anchor in anchors
        if anchor and _text_contains_anchor_term_fuzzy(text, anchor)
    )
    if anchor_hits < 2:
        return 0.0
    return 0.995


def _query_term_variants(term: str) -> List[str]:
    clean = " ".join(str(term or "").split()).strip().lower()
    if not clean:
        return []
    return [clean]


def _text_matches_query_term(text: str, term: str) -> bool:
    return any(_text_contains_anchor_term_fuzzy(text, variant) for variant in _query_term_variants(term))


def _text_matches_query_term_exact(text: str, term: str) -> bool:
    return any(_text_contains_anchor_term(text, variant) for variant in _query_term_variants(term))


def _source_chunk_context_scope_key(chunk: Dict[str, Any]) -> str:
    for key in ("source_id", "session_id", "source_conversation_id", "conversation_id"):
        value = str((chunk or {}).get(key) or "").strip()
        if value:
            source_date = _date_part((chunk or {}).get("source_date"))
            if source_date:
                return f"{key}:{value}|source_date:{source_date}"
            return f"{key}:{value}"
    return ""


def _source_chunk_adjacent_scoring_text(
    chunk: Dict[str, Any],
    chunks_by_scope_index: Dict[Tuple[str, int], Dict[str, Any]],
    *,
    radius: int = _SESSION_CHUNK_SCORING_WINDOW_RADIUS,
    before: Optional[int] = None,
    after: Optional[int] = None,
) -> str:
    text = str((chunk or {}).get("text") or "").strip()
    scope_key = _source_chunk_context_scope_key(chunk)
    if not scope_key:
        return text
    try:
        center_index = int((chunk or {}).get("chunk_index"))
    except (TypeError, ValueError):
        return text
    parts: List[str] = []
    before_count = max(0, int(radius if before is None else before or 0))
    after_count = max(0, int(radius if after is None else after or 0))
    for offset in range(-before_count, after_count + 1):
        neighbor = chunks_by_scope_index.get((scope_key, center_index + offset))
        neighbor_text = str((neighbor or {}).get("text") or "").strip()
        if neighbor_text:
            parts.append(neighbor_text)
    return "\n".join(parts) if parts else text


def _source_chunk_store_recall(
    query: str,
    *,
    owner_id: Optional[str],
    limit: int,
    domain: Optional[Dict[str, bool]],
    project: Optional[str],
    current_session_id: Optional[str] = None,
    source_channel: Optional[str] = None,
    source_conversation_id: Optional[str] = None,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
    timeout_ms: Optional[int] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any], Optional[Dict[str, Any]]]:
    """Opt-in session chunk recall lane for exact transcript context."""
    started = time.monotonic()
    token_limit = _normalize_source_chunk_output_token_limit(max_chunk_tokens)
    total_token_limit = _normalize_source_chunk_total_token_limit(max_total_chunk_tokens)
    terms = _source_chunk_query_terms(query, limit=10)
    meta: Dict[str, Any] = {
        "selected_path": "session_chunk_store",
        "query_terms_count": len(terms),
        "max_chunk_tokens": token_limit,
        "max_total_chunk_tokens": total_token_limit,
        "counts": {"final_results": 0},
        "session_chunk_telemetry": {
            "owner_scoped": bool(str(owner_id or "").strip()),
            "omitted": 0,
            "output_token_count": 0,
            "semantic_candidate_count": 0,
            "lexical_candidate_count": 0,
        },
    }
    if not str(owner_id or "").strip():
        if _is_fail_hard_mode():
            raise RuntimeError("session_chunks recall requires owner_id")
        logger.warning("[recall] session_chunks store requested without owner_id; returning no chunks")
        meta["stop_reason"] = "missing_owner"
        meta["phases_ms"] = {"total_ms": round((time.monotonic() - started) * 1000)}
        return [], meta, None

    graph = get_graph()
    clauses = ["owner_id = ?"]
    params: List[Any] = [str(owner_id).strip()]
    normalized_project = _normalize_project_tag(project)
    if normalized_project:
        clauses.append("project = ?")
        params.append(normalized_project)
    if current_session_id:
        clauses.append("session_id = ?")
        params.append(str(current_session_id))
    if source_conversation_id:
        clauses.append("source_conversation_id = ?")
        params.append(str(source_conversation_id))
    if source_channel:
        clauses.append("source_channel = ?")
        params.append(str(source_channel))

    requested_domain_filter = (
        isinstance(domain, dict)
        and any(
            bool(v) and _normalize_domain_tag(k) and _normalize_domain_tag(k) != "all"
            for k, v in domain.items()
        )
    )
    active_domains = _active_domains_for_filter(graph) if requested_domain_filter else set()
    include_all_domains, included_domains = _normalize_domain_filter(domain, active_domains)

    try:
        with graph._get_conn() as conn:
            graph._ensure_source_chunks_table(conn)
            rows = conn.execute(
                f"""
                SELECT *
                FROM source_chunks
                WHERE {" AND ".join(clauses)}
                ORDER BY created_at DESC, chunk_index ASC, chunk_id ASC
                LIMIT ?
                """,
                [*params, max(limit * 128, _SESSION_CHUNK_RECALL_CANDIDATE_FLOOR)],
            ).fetchall()
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError("session_chunks recall failed while reading chunks") from exc
        logger.warning("[recall] session_chunks store failed; returning no chunks: %s", exc, exc_info=True)
        meta["failed"] = True
        meta["phases_ms"] = {"total_ms": round((time.monotonic() - started) * 1000)}
        return [], meta, None

    scoped_chunks: List[Tuple[Any, Dict[str, Any]]] = []
    chunks_by_scope_index: Dict[Tuple[str, int], Dict[str, Any]] = {}
    for row in rows:
        chunk = graph._row_to_source_chunk(row)
        chunk_domains = set(_normalize_domains(chunk.get("domains")))
        if not include_all_domains and included_domains and not chunk_domains.intersection(included_domains):
            continue
        scoped_chunks.append((row, chunk))
        scope_key = _source_chunk_context_scope_key(chunk)
        try:
            chunk_index = int(chunk.get("chunk_index"))
        except (TypeError, ValueError):
            continue
        if scope_key:
            chunks_by_scope_index.setdefault((scope_key, chunk_index), chunk)

    lexical_probe_count = 0
    for _row, chunk in scoped_chunks:
        scoring_text = _source_chunk_adjacent_scoring_text(chunk, chunks_by_scope_index)
        if any(_text_matches_query_term(scoring_text, term) for term in terms):
            lexical_probe_count += 1
            if lexical_probe_count >= max(1, int(limit or 1)):
                break

    query_embedding: Optional[List[float]] = None
    embedding_timeout_s: Optional[float] = None
    if timeout_ms is not None:
        try:
            embedding_timeout_s = max(0.5, min(10.0, float(timeout_ms) / 1000.0 * 0.2))
        except (TypeError, ValueError):
            embedding_timeout_s = None
    try:
        query_embedding = graph.get_embedding(query, timeout_s=embedding_timeout_s)
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError("session_chunks recall failed while embedding query") from exc
        logger.warning("[recall] session_chunks embedding unavailable; using lexical search only: %s", exc)

    vec_distance_by_chunk_id: Dict[str, float] = {}
    ann_backfilled_count = 0
    if query_embedding and _lib_has_vec():
        try:
            with graph._get_conn() as conn:
                ann_backfilled_count = graph._backfill_source_chunk_vec_index(conn)
                packed_query = graph._pack_embedding(query_embedding)
                vec_rows = conn.execute(
                    f"""
                    SELECT sc.chunk_id, knn.distance
                    FROM (
                        SELECT chunk_id, distance
                        FROM vec_source_chunks
                        WHERE embedding MATCH ? AND k = ?
                    ) knn
                    JOIN source_chunks sc ON sc.chunk_id = knn.chunk_id
                    WHERE {" AND ".join(clauses)}
                    ORDER BY knn.distance
                    """,
                    [
                        packed_query,
                        max(limit * 128, _SESSION_CHUNK_RECALL_CANDIDATE_FLOOR),
                        *params,
                    ],
                ).fetchall()
            for vec_row in vec_rows:
                chunk_id = str(vec_row["chunk_id"] or "").strip()
                if not chunk_id:
                    continue
                try:
                    vec_distance_by_chunk_id[chunk_id] = float(vec_row["distance"])
                except (TypeError, ValueError):
                    continue
        except Exception as exc:
            if _is_fail_hard_mode():
                raise RuntimeError("session_chunks recall failed while querying chunk vector index") from exc
            logger.warning("[recall] session_chunks ANN index unavailable; using stored chunk embeddings: %s", exc)

    candidates: List[Tuple[Tuple[float, str], Dict[str, Any]]] = []
    lexical_candidate_count = 0
    semantic_candidate_count = 0
    adjacent_scoring_contexts = 0
    temporal_answer_query = _query_requests_temporal_answer(query)
    shared_source_query = _is_multi_entity_shared_source_query(query)
    shared_source_anchors = _shared_source_anchor_terms(query, limit=6) if shared_source_query else []
    for row, chunk in scoped_chunks:
        text = str(chunk.get("text") or "")
        if temporal_answer_query:
            scoring_text = _source_chunk_adjacent_scoring_text(
                chunk,
                chunks_by_scope_index,
                before=2,
                after=4,
            )
        elif shared_source_query:
            scoring_text = _source_chunk_adjacent_scoring_text(
                chunk,
                chunks_by_scope_index,
                before=2,
                after=2,
            )
        else:
            scoring_text = _source_chunk_adjacent_scoring_text(chunk, chunks_by_scope_index)
        if scoring_text != text:
            adjacent_scoring_contexts += 1
        overlap = sum(1 for term in terms if _text_matches_query_term(scoring_text, term))
        lexical_score = 0.0
        if overlap > 0:
            exact_bonus = 0.05 if " ".join(str(query or "").lower().split()) in scoring_text.lower() else 0.0
            lexical_score = min(0.99, 0.35 + (0.55 * (overlap / max(1, len(terms)))) + exact_bonus)
            lexical_candidate_count += 1
        semantic_score = 0.0
        ann_distance = vec_distance_by_chunk_id.get(str(chunk.get("chunk_id") or "").strip())
        if ann_distance is not None:
            semantic_score = max(0.0, min(0.99, 1.0 - float(ann_distance)))
        elif query_embedding and row["embedding"]:
            try:
                semantic_score = max(0.0, min(0.99, graph.cosine_similarity(query_embedding, graph._unpack_embedding(row["embedding"]))))
            except Exception as exc:
                if _is_fail_hard_mode():
                    raise RuntimeError("session_chunks recall failed while scoring chunk embedding") from exc
                logger.warning("[recall] session_chunks embedding score failed for %s: %s", chunk.get("chunk_id"), exc)
                semantic_score = 0.0
        if semantic_score >= 0.60:
            semantic_candidate_count += 1
        score = max(lexical_score, semantic_score)
        shared_quoted_item_score = 0.0
        if shared_source_query:
            shared_quoted_item_score = _shared_quoted_item_score(
                scoring_text,
                terms,
                shared_source_anchors,
            )
            score = max(score, shared_quoted_item_score)
        if lexical_score <= 0 and semantic_score < 0.60:
            if shared_quoted_item_score <= 0:
                continue
        match_modes = []
        if lexical_score > 0:
            match_modes.append("lexical")
        if semantic_score >= 0.60:
            match_modes.append("semantic")
        if shared_quoted_item_score > 0:
            match_modes.append("shared_quoted_item")
        chunk["match_modes"] = match_modes
        chunk["lexical_score"] = round(float(lexical_score), 3)
        chunk["semantic_score"] = round(float(semantic_score), 3)
        if shared_quoted_item_score > 0:
            chunk["shared_quoted_item_score"] = round(float(shared_quoted_item_score), 3)
            chunk["shared_quoted_item_keys"] = _repeated_quoted_item_keys(scoring_text)
        chunk["session_scoring_context_overlap"] = int(overlap)
        chunk["session_scoring_context_radius"] = int(_SESSION_CHUNK_SCORING_WINDOW_RADIUS)
        if scoring_text != text:
            chunk["session_scoring_context_text"] = scoring_text
            if temporal_answer_query:
                chunk["session_temporal_context_text"] = scoring_text
            if shared_quoted_item_score > 0:
                chunk["session_shared_item_context_text"] = scoring_text
        candidates.append(((score, str(chunk.get("created_at") or "")), chunk))
    candidates.sort(key=lambda item: item[0], reverse=True)

    out: List[Dict[str, Any]] = []
    consumed_tokens = 0
    omitted = 0
    shared_item_output_counts: Dict[str, int] = {}
    for (score, _created), chunk in candidates:
        if len(out) >= max(1, int(limit or 1)):
            omitted += 1
            continue
        shared_item_keys = [
            str(key or "").strip().lower()
            for key in list(chunk.get("shared_quoted_item_keys") or [])
            if str(key or "").strip()
        ]
        if shared_item_keys and all(shared_item_output_counts.get(key, 0) >= 2 for key in shared_item_keys):
            omitted += 1
            continue
        remaining = total_token_limit - consumed_tokens
        if remaining <= 0:
            omitted += 1
            continue
        payload = _source_chunk_recall_payload(
            chunk,
            max_chunk_tokens=min(token_limit, remaining),
        )
        output_tokens = int(payload.get("output_token_count") or 0)
        consumed_tokens += output_tokens
        chunk_id = str(payload.get("chunk_id") or "").strip()
        source_label = str(payload.get("session_id") or payload.get("source_id") or "session").strip()
        prefix = f"[session_chunk] {source_label}"
        if payload.get("chunk_index") is not None:
            prefix += f"#{payload.get('chunk_index')}"
        row_text = payload.get("text")
        if temporal_answer_query:
            row_text = chunk.get("session_temporal_context_text") or row_text
        if chunk.get("shared_quoted_item_score"):
            row_text = chunk.get("session_shared_item_context_text") or row_text
        payload_text = str(row_text or "")
        source_date = _date_part(payload.get("source_date"))
        if source_date and f"source_date: {source_date}" not in str(payload_text):
            payload_text = f"source_date: {source_date}\n{payload_text}"
        out.append({
            "id": chunk_id,
            "text": f"{prefix}: {payload_text}",
            "category": "session_chunk",
            "source_type": "session_chunk",
            "source_provenance_type": payload.get("source_type"),
            "via": "session_chunks",
            "similarity": round(float(score), 3),
            "chunk_id": chunk_id,
            "source_chunk_id": chunk_id,
            "session_chunk_id": chunk_id,
            "session_id": payload.get("session_id"),
            "source_id": payload.get("source_id"),
            "chunk_index": payload.get("chunk_index"),
            "chunk_kind": payload.get("chunk_kind"),
            "parent_chunk_id": payload.get("parent_chunk_id"),
            "next_chunk_id": payload.get("next_chunk_id"),
            "message_id": payload.get("message_id"),
            "message_pair_id": payload.get("message_pair_id"),
            "microchunk_id": payload.get("microchunk_id"),
            "content_hash": payload.get("content_hash"),
            "owner_id": chunk.get("owner_id"),
            "domains": _normalize_domains(payload.get("domains")),
            "project": payload.get("project"),
            "privacy": payload.get("privacy"),
            "source_channel": payload.get("source_channel"),
            "source_conversation_id": payload.get("source_conversation_id"),
            "conversation_id": payload.get("conversation_id"),
            "source_author_id": payload.get("source_author_id"),
            "token_count": payload.get("token_count"),
            "output_token_count": output_tokens,
            "truncated": payload.get("truncated"),
            "created_at": payload.get("created_at"),
            "source_date": payload.get("source_date"),
            "match_modes": list(chunk.get("match_modes") or []),
            "lexical_score": chunk.get("lexical_score"),
            "semantic_score": chunk.get("semantic_score"),
            "shared_quoted_item_score": chunk.get("shared_quoted_item_score"),
            "shared_quoted_item_keys": list(chunk.get("shared_quoted_item_keys") or []),
            "session_scoring_context_overlap": chunk.get("session_scoring_context_overlap"),
            "session_scoring_context_radius": chunk.get("session_scoring_context_radius"),
            "session_scoring_context_text": chunk.get("session_scoring_context_text"),
            "session_temporal_context_attached": bool(temporal_answer_query and chunk.get("session_temporal_context_text")),
            "session_shared_item_context_attached": bool(chunk.get("session_shared_item_context_text")),
        })
        for key in shared_item_keys:
            shared_item_output_counts[key] = shared_item_output_counts.get(key, 0) + 1
    meta["counts"] = {"final_results": len(out)}
    meta["session_chunk_telemetry"] = {
        **dict(meta.get("session_chunk_telemetry") or {}),
        "candidate_count": len(candidates),
        "omitted": omitted,
        "output_token_count": consumed_tokens,
        "domain_filter_applied": not include_all_domains,
        "semantic_candidate_count": semantic_candidate_count,
        "lexical_candidate_count": lexical_candidate_count,
        "adjacent_scoring_contexts": adjacent_scoring_contexts,
        "lexical_probe_count": lexical_probe_count,
        "embedding_timeout_s": embedding_timeout_s,
        "semantic_embedding_used": bool(query_embedding),
        "ann_index_used": bool(vec_distance_by_chunk_id),
        "ann_candidate_count": len(vec_distance_by_chunk_id),
        "ann_index_backfilled": ann_backfilled_count,
    }
    meta["source_chunk_telemetry"] = dict(meta["session_chunk_telemetry"])
    meta["phases_ms"] = {"total_ms": round((time.monotonic() - started) * 1000)}
    return _validate_recall_result_rows(out), meta, None


def _owner_has_session_chunks(owner_id: Optional[str]) -> bool:
    owner = str(owner_id or "").strip()
    if not owner:
        return False
    graph = get_graph()
    try:
        with graph._get_conn() as conn:
            graph._ensure_source_chunks_table(conn)
            row = conn.execute(
                "SELECT 1 FROM source_chunks WHERE owner_id = ? LIMIT 1",
                (owner,),
            ).fetchone()
            return row is not None
    except Exception:
        if _is_fail_hard_mode():
            raise
        return False


def _session_chunk_expansion_counts(value: Any, default: int) -> int:
    try:
        return max(0, min(int(value), 4))
    except (TypeError, ValueError):
        return default


def _sessiondb_bridge_expand_microchunk(
    microchunk_id: str,
    *,
    owner_id: str,
    before: int,
    after: int,
) -> Optional[Dict[str, Any]]:
    mid = str(microchunk_id or "").strip()
    owner = str(owner_id or "").strip()
    if not mid or not owner:
        return None
    from core.services.session_memory_bridge import get_session_memory_bridge

    return get_session_memory_bridge().expand_microchunk(
        mid,
        owner_id=owner,
        before=before,
        after=after,
    )


def _compact_session_source_header(source_header: str, source_date: str = "") -> str:
    header = str(source_header or "").strip()
    if not header:
        return ""
    first_line = next((line.strip() for line in header.splitlines() if line.strip()), "")
    if not first_line:
        return ""
    if len(first_line) > 240:
        first_line = first_line[:237].rstrip() + "..."
    date_value = _date_part(source_date)
    if date_value and date_value not in first_line:
        return f"source_date: {date_value}; {first_line}"
    return first_line


_SESSION_SOURCE_WINDOW_HEADER_REQUIRED_KEYS = (
    "session_id",
    "source_date",
    "pair_id",
    "microchunk_id",
    "header_id",
)


def _session_source_window_header_id(session_id: Optional[str], source_date: Any) -> str:
    sid = str(session_id or "").strip()
    date_value = _date_part(source_date)
    return f"{sid}:{date_value}" if sid and date_value else ""


def _validate_session_source_window_header(raw: Any) -> Dict[str, str]:
    if not isinstance(raw, dict):
        raise ValueError("source_window_header must be a dict")
    out: Dict[str, str] = {}
    for key in _SESSION_SOURCE_WINDOW_HEADER_REQUIRED_KEYS:
        value = raw.get(key)
        if not isinstance(value, str):
            raise ValueError(f"source_window_header.{key} must be a non-empty string")
        cleaned = value.strip()
        if not cleaned:
            raise ValueError(f"source_window_header.{key} must be a non-empty string")
        out[key] = cleaned
    source_date = _date_part(out["source_date"])
    if not source_date:
        raise ValueError("source_window_header.source_date must be an ISO date string")
    out["source_date"] = source_date
    expected_header_id = _session_source_window_header_id(out["session_id"], source_date)
    if out["header_id"] != expected_header_id:
        raise ValueError("source_window_header.header_id must be session_id:source_date")
    return out


def _session_window_source_date_header_row(
    *,
    source_date: Any,
    session_id: Optional[str] = None,
    pair_id: Optional[str] = None,
    microchunk_id: Optional[str] = None,
    header_id: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    date_value = _date_part(source_date)
    if not date_value:
        return None
    header_text = f"source_date: {date_value}"
    stable_header_id = str(header_id or "").strip() or _session_source_window_header_id(session_id, date_value)
    return {
        "chunk_id": f"{microchunk_id or pair_id or session_id or 'session'}:source_header",
        "header_id": stable_header_id or None,
        "text": header_text,
        "token_count": int(_lib_estimate_tokens(header_text)),
        "source_id": session_id,
        "session_id": session_id,
        "chunk_index": "context",
        "chunk_kind": "session_source_header",
        "message_pair_id": pair_id,
        "microchunk_id": microchunk_id,
        "created_at": None,
        "source_date": date_value,
        "source_type": "session_chunk",
        "session_source_header": True,
    }


def _session_window_source_date_header_from_metadata(expanded: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if "source_window_header" not in expanded:
        return None
    try:
        header = _validate_session_source_window_header(expanded.get("source_window_header"))
    except Exception as exc:
        if _is_fail_hard_mode():
            raise
        logger.warning("Ignoring malformed SessionDB source_window_header metadata: %s", exc, exc_info=True)
        return None
    return _session_window_source_date_header_row(
        source_date=header["source_date"],
        session_id=header["session_id"],
        pair_id=header["pair_id"],
        microchunk_id=header["microchunk_id"],
        header_id=header["header_id"],
    )


def _ensure_session_window_source_date_header(
    window: List[Dict[str, Any]],
    *,
    source_date: Any,
    session_id: Optional[str] = None,
    pair_id: Optional[str] = None,
    microchunk_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    date_value = _date_part(source_date)
    if not date_value or not window:
        return window
    if any(isinstance(item, dict) and item.get("session_source_header") for item in window):
        return window
    header_row = _session_window_source_date_header_row(
        source_date=date_value,
        session_id=session_id,
        pair_id=pair_id,
        microchunk_id=microchunk_id,
    )
    return [header_row, *window] if header_row else window


def _sessiondb_bridge_expansion_window(expanded: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not isinstance(expanded, dict):
        return []
    window: List[Dict[str, Any]] = []
    source_window_header = _session_window_source_date_header_from_metadata(expanded)
    if source_window_header is not None:
        window.append(source_window_header)
    source_header = str(expanded.get("source_header") or "").strip()
    if source_header and source_window_header is None:
        micro = expanded.get("microchunk") if isinstance(expanded.get("microchunk"), dict) else {}
        source_date = _date_part(expanded.get("source_date"))
        header_text = _compact_session_source_header(source_header, source_date)
        window.append({
            "chunk_id": f"{micro.get('microchunk_id') or 'session'}:source_header",
            "header_id": _session_source_window_header_id(micro.get("session_id"), source_date) or None,
            "text": header_text,
            "token_count": int(_lib_estimate_tokens(header_text)),
            "source_id": micro.get("session_id"),
            "session_id": micro.get("session_id"),
            "chunk_index": "context",
            "chunk_kind": "session_source_header",
            "message_pair_id": micro.get("pair_id"),
            "microchunk_id": micro.get("microchunk_id"),
            "created_at": None,
            "source_date": source_date or None,
            "source_type": "session_chunk",
            "session_source_header": True,
        })
    for item in list(expanded.get("microchunk_window") or []):
        if not isinstance(item, dict):
            continue
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        window.append({
            "chunk_id": item.get("memory_chunk_id") or item.get("microchunk_id"),
            "text": text,
            "token_count": int(item.get("token_count") or _lib_estimate_tokens(text)),
            "source_id": item.get("session_id"),
            "session_id": item.get("session_id"),
            "chunk_index": item.get("microchunk_index"),
            "chunk_kind": "session_microchunk",
            "parent_chunk_id": item.get("chunk_id"),
            "message_pair_id": item.get("pair_id"),
            "microchunk_id": item.get("microchunk_id"),
            "created_at": item.get("created_at"),
            "source_date": _date_part(item.get("source_date")) or None,
            "source_type": "session_chunk",
        })
    if window:
        return window
    micro = expanded.get("microchunk")
    if isinstance(micro, dict):
        text = str(micro.get("text") or "").strip()
        if text:
            window.append({
                "chunk_id": micro.get("memory_chunk_id") or micro.get("microchunk_id"),
                "text": text,
                "token_count": int(micro.get("token_count") or _lib_estimate_tokens(text)),
                "source_id": micro.get("session_id"),
                "session_id": micro.get("session_id"),
                "chunk_index": micro.get("microchunk_index"),
                "chunk_kind": "session_microchunk",
                "parent_chunk_id": micro.get("chunk_id"),
                "message_pair_id": micro.get("pair_id"),
                "microchunk_id": micro.get("microchunk_id"),
                "created_at": micro.get("created_at"),
                "source_date": _date_part(micro.get("source_date")) or None,
                "source_type": "session_chunk",
            })
            return window
    for item in list(expanded.get("window") or []):
        if not isinstance(item, dict):
            continue
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        window.append({
            "chunk_id": item.get("pair_id") or item.get("microchunk_id"),
            "text": text,
            "token_count": int(_lib_estimate_tokens(text)),
            "source_id": item.get("session_id"),
            "session_id": item.get("session_id"),
            "chunk_index": item.get("pair_index"),
            "chunk_kind": "session_pair",
            "message_pair_id": item.get("pair_id"),
            "microchunk_id": item.get("microchunk_id"),
            "created_at": item.get("created_at"),
            "source_date": _date_part(item.get("source_date")) or None,
            "source_type": "session_chunk",
        })
    if window:
        return window
    return []


def _session_window_item_overlap(item: Dict[str, Any], query_terms: List[str]) -> int:
    if not query_terms:
        return 0
    tokens = {
        token.strip(".,;:!?\"'“”¿¡")
        for token in re.findall(r"\w+", str(item.get("text") or "").lower(), flags=re.UNICODE)
    }
    tokens.discard("")
    if not tokens:
        return 0
    return sum(1 for term in query_terms if term and term in tokens)


def _session_window_item_anchor_overlap(item: Dict[str, Any], query_terms: List[str]) -> int:
    if not query_terms or not isinstance(item, dict):
        return 0
    text = str(item.get("text") or "")
    if not text:
        return 0
    tokens = [
        token.strip(".,;:!?\"'“”¿¡").lower()
        for token in re.findall(r"[\w][\w._-]*", text.lower(), flags=re.UNICODE)
    ]
    return sum(
        1
        for term in query_terms
        if _text_contains_anchor_term_fuzzy(text, term)
        or (
            len(str(term or "")) >= 5
            and any(token.startswith(str(term or "").lower()) for token in tokens)
        )
    )


def _session_window_item_id(item: Dict[str, Any]) -> str:
    if not isinstance(item, dict):
        return ""
    if item.get("session_source_header"):
        header_id = str(item.get("header_id") or "").strip()
        if header_id:
            return header_id
    for key in ("chunk_id", "memory_chunk_id", "microchunk_id", "message_pair_id", "message_id"):
        value = str(item.get(key) or "").strip()
        if value:
            return value
    return ""


def _session_stream_support_window(
    *,
    center_chunk: Optional[Dict[str, Any]],
    owner_id: str,
    query_terms: List[str],
    excluded_ids: Set[str],
) -> List[Dict[str, Any]]:
    """Find a compact earlier same-stream support window for selected source evidence."""
    if not isinstance(center_chunk, dict) or len(query_terms or []) < 2:
        return []
    try:
        center_index = int(center_chunk.get("chunk_index"))
    except (TypeError, ValueError):
        return []
    owner = str(owner_id or "").strip()
    if not owner:
        return []
    scope_clauses = ["owner_id = ?", "chunk_index < ?"]
    params: List[Any] = [owner, center_index]
    for key in ("source_id", "source_conversation_id", "conversation_id", "session_id"):
        value = str(center_chunk.get(key) or "").strip()
        if value:
            scope_clauses.append(f"{key} = ?")
            params.append(value)
            break
    else:
        return []
    try:
        graph = get_graph()
        with graph._get_conn() as conn:
            graph._ensure_source_chunks_table(conn)
            rows = conn.execute(
                f"""
                SELECT *
                FROM source_chunks
                WHERE {" AND ".join(scope_clauses)}
                ORDER BY chunk_index DESC, created_at DESC
                LIMIT 2048
                """,
                params,
            ).fetchall()
    except Exception:
        if _is_fail_hard_mode():
            raise
        logger.warning("session support window lookup failed", exc_info=True)
        return []

    chunks: List[Dict[str, Any]] = []
    graph = get_graph()
    for row in rows:
        chunk = graph._row_to_source_chunk(row)
        chunk_id = _session_window_item_id(chunk)
        if chunk_id and chunk_id in excluded_ids:
            continue
        chunks.append(chunk)
    term_counts: Dict[str, int] = {}
    normalized_terms = [str(term or "").lower() for term in query_terms if str(term or "").strip()]
    for term in normalized_terms:
        count = 0
        for chunk in chunks:
            if _session_window_item_anchor_overlap(chunk, [term]) > 0:
                count += 1
        if count:
            term_counts[term] = count

    scored: List[Tuple[float, int, int, Dict[str, Any]]] = []
    for chunk in chunks:
        matched_terms = [
            term
            for term in normalized_terms
            if _session_window_item_anchor_overlap(chunk, [term]) > 0
        ]
        overlap = len(matched_terms)
        if overlap < 1:
            continue
        rare_score = sum(
            len(term) / max(1, term_counts.get(term, 1))
            for term in matched_terms
        )
        if overlap < 2 and rare_score < 5.0:
            continue
        try:
            index = int(chunk.get("chunk_index") or 0)
        except (TypeError, ValueError):
            index = 0
        scored.append((rare_score, overlap, index, chunk))
    if not scored:
        return []
    scored.sort(reverse=True, key=lambda item: (item[0], item[1], item[2]))
    support_center = scored[0][3]
    support_id = str(support_center.get("chunk_id") or "").strip()
    if not support_id:
        return []
    try:
        support = get_graph().get_source_chunk(
            support_id,
            owner_id=owner,
            before=1,
            after=2,
            fail_hard=_is_fail_hard_mode(),
        )
    except Exception:
        if _is_fail_hard_mode():
            raise
        logger.warning("session support window expansion failed for %s", support_id, exc_info=True)
        return []
    window = []
    for item in list((support or {}).get("window") or [support_center]):
        if not isinstance(item, dict):
            continue
        item_id = _session_window_item_id(item)
        if item_id and item_id in excluded_ids:
            continue
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        window.append(item)
    return window[:3]


def _extract_query_temporal_anchor_terms(query: str, *, limit: int = 8) -> List[str]:
    text = str(query or "").lower()
    if not text:
        return []
    anchors: List[str] = []
    seen = set()
    for year_match in re.finditer(r"(?<!\d)(?:19|20)\d{2}(?!\d)", text):
        before_tokens = re.findall(r"\w+", text[:year_match.start()], flags=re.UNICODE)[-2:]
        after_tokens = re.findall(r"\w+", text[year_match.end():], flags=re.UNICODE)[:1]
        for token in [*before_tokens, year_match.group(0), *after_tokens]:
            token = token.strip(".,;:!?\"'“”¿¡")
            if len(token) < 3 or token in seen:
                continue
            seen.add(token)
            anchors.append(token)
            if len(anchors) >= limit:
                return anchors
    return anchors


def _first_order_session_query_coverage_score(
    row: Dict[str, Any],
    query_terms: List[str],
    temporal_terms: List[str],
) -> int:
    if not isinstance(row, dict):
        return 0
    source_type = str(row.get("source_type") or row.get("category") or "").strip().lower()
    if source_type != "session_chunk":
        return 0
    text = str(row.get("session_scoring_context_text") or row.get("text") or "").lower()
    if not text:
        return 0
    base = sum(1 for term in query_terms if _text_contains_anchor_term_fuzzy(text, term))
    temporal = sum(1 for term in temporal_terms if _text_contains_anchor_term_fuzzy(text, term))
    return base + (2 * temporal)


def _prioritize_first_order_session_query_coverage(
    query: str,
    rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    if not rows:
        return rows
    query_terms = _extract_vocabulary_free_query_terms(query, limit=16)
    temporal_terms = _extract_query_temporal_anchor_terms(query, limit=8)
    if not query_terms and not temporal_terms:
        return rows
    scored = [
        (
            idx,
            row,
            _first_order_session_query_coverage_score(row, query_terms, temporal_terms),
        )
        for idx, row in enumerate(rows)
    ]
    if max((score for _idx, _row, score in scored), default=0) < 3:
        return rows
    adjusted: List[Tuple[int, Dict[str, Any], int]] = []
    for idx, row, score in scored:
        if isinstance(row, dict) and score >= 3:
            promoted = dict(row)
            try:
                current_score = float(promoted.get("similarity") or promoted.get("score") or 0.0)
            except (TypeError, ValueError):
                current_score = 0.0
            coverage_floor = min(0.99, 0.90 + (0.015 * min(score, 6)))
            if coverage_floor > current_score:
                promoted["similarity"] = coverage_floor
                promoted["score"] = coverage_floor
                promoted["first_order_query_coverage_promoted"] = True
                promoted["first_order_query_coverage_score"] = score
            row = promoted
        adjusted.append((idx, row, score))
    sorted_rows = sorted(
        adjusted,
        key=lambda item: (
            item[2],
            float((item[1] or {}).get("similarity") or 0.0) if isinstance(item[1], dict) else 0.0,
            -item[0],
        ),
        reverse=True,
    )
    return [row for _idx, row, _score in sorted_rows]


def _prioritize_source_dated_session_rows_for_temporal_answers(
    query: str,
    rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    if not rows or not _query_requests_temporal_answer(query):
        return rows
    query_terms = _extract_vocabulary_free_query_terms(query, limit=16)
    if not query_terms:
        return rows
    temporal_terms = _extract_query_temporal_anchor_terms(query, limit=8)
    scored: List[Tuple[int, float, int, Dict[str, Any]]] = []
    trailing: List[Tuple[int, Dict[str, Any]]] = []
    for idx, row in enumerate(rows):
        if not isinstance(row, dict):
            trailing.append((idx, row))
            continue
        if not _is_first_order_session_source_row(row) or not _date_part(row.get("source_date")):
            trailing.append((idx, row))
            continue
        score = _first_order_session_query_coverage_score(row, query_terms, temporal_terms)
        if score < 3:
            trailing.append((idx, row))
            continue
        promoted = dict(row)
        try:
            current_score = float(promoted.get("similarity") or promoted.get("score") or 0.0)
        except (TypeError, ValueError):
            current_score = 0.0
        floor = min(0.995, 0.94 + (0.01 * min(score, 5)))
        if floor > current_score:
            promoted["similarity"] = floor
            promoted["score"] = floor
        promoted["temporal_source_dated_session_promoted"] = True
        promoted["temporal_source_dated_session_score"] = score
        scored.append((score, float(promoted.get("similarity") or 0.0), -idx, promoted))
    if not scored:
        return rows
    scored.sort(key=lambda item: item[:3], reverse=True)
    ordered_promoted = [row for _score, _confidence, _negative_idx, row in scored]
    promoted_ids = {_recall_row_identity(row) for row in ordered_promoted}
    ordered_trailing = [
        row for _idx, row in sorted(trailing, key=lambda item: item[0])
        if not isinstance(row, dict) or _recall_row_identity(row) not in promoted_ids
    ]
    return [*ordered_promoted, *ordered_trailing]


def _select_session_window_items_for_budget(
    window: List[Dict[str, Any]],
    *,
    available_tokens: int,
    query_terms: Optional[List[str]] = None,
) -> List[Dict[str, Any]]:
    """Keep dense first-order evidence instead of truncating every microchunk."""
    if not window:
        return []
    budget = max(1, int(available_tokens or 0))
    item_tokens = [
        max(1, int(_lib_estimate_tokens(str(item.get("text") or ""))))
        if isinstance(item, dict)
        else 1
        for item in window
    ]
    if sum(item_tokens) <= budget:
        return window
    terms = list(query_terms or [])
    header_indexes: List[int] = []
    required_indexes: List[int] = []
    for idx, item in enumerate(window):
        if not isinstance(item, dict):
            continue
        if item.get("session_source_header"):
            header_indexes.append(idx)
        if item.get("session_window_required"):
            required_indexes.append(idx)

    scored: List[Tuple[int, int, int]] = []
    for idx, item in enumerate(window):
        if not isinstance(item, dict):
            continue
        overlap = _session_window_item_overlap(item, terms)
        if overlap <= 0:
            continue
        token_count = item_tokens[idx] if idx < len(item_tokens) else 1
        scored.append((overlap, -token_count, idx))
    scored.sort(reverse=True)

    selected: set[int] = set()
    running = 0
    for idx in required_indexes:
        token_count = item_tokens[idx] if idx < len(item_tokens) else 1
        if selected and running + token_count > budget:
            continue
        selected.add(idx)
        running += token_count

    def add_index_if_budget_allows(idx: int) -> None:
        nonlocal running
        if idx in selected:
            return
        token_count = item_tokens[idx] if idx < len(item_tokens) else 1
        if selected and running + token_count > budget:
            return
        selected.add(idx)
        running += token_count

    if required_indexes:
        # Required provenance already anchors the source turn; spend the next
        # tokens on query-relevant dialogue before lower-signal date headers.
        for _overlap, _negative_tokens, idx in scored:
            add_index_if_budget_allows(idx)
        for idx in header_indexes:
            add_index_if_budget_allows(idx)
    else:
        for idx in header_indexes:
            add_index_if_budget_allows(idx)
        for _overlap, _negative_tokens, idx in scored:
            add_index_if_budget_allows(idx)

    if not selected:
        # Fallback to the highest-ranked contiguous prefix when no term signal
        # exists; this preserves previous behavior without fragmenting text.
        running = 0
        for idx in range(len(window)):
            token_count = item_tokens[idx] if idx < len(item_tokens) else 1
            if selected and running + token_count > budget:
                break
            selected.add(idx)
        running += token_count
    if not selected:
        return [window[0]]
    return [window[idx] for idx in sorted(selected)]


def _expand_selected_session_chunk_rows(
    rows: List[Dict[str, Any]],
    *,
    owner_id: Optional[str],
    max_chunk_tokens: Optional[int],
    max_total_chunk_tokens: Optional[int] = None,
    before: Optional[int] = None,
    after: Optional[int] = None,
    query: Optional[str] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    if not rows:
        return rows, {"expanded": 0, "window_chunk_count": 0}
    cfg = _get_retrieval_lightweight_config()
    before_count = _session_chunk_expansion_counts(
        before if before is not None else getattr(cfg, "session_chunk_window_before", getattr(cfg, "sessionChunkWindowBefore", 2)),
        2,
    )
    after_count = _session_chunk_expansion_counts(
        after if after is not None else getattr(cfg, "session_chunk_window_after", getattr(cfg, "sessionChunkWindowAfter", 2)),
        2,
    )
    if _query_requests_temporal_answer(str(query or "")):
        before_count = max(before_count, 2)
        after_count = max(after_count, 4)
    if before_count <= 0 and after_count <= 0:
        return rows, {"expanded": 0, "window_chunk_count": 0}
    owner_key = str(owner_id or "").strip()
    if not owner_key:
        return rows, {"expanded": 0, "window_chunk_count": 0, "skipped_reason": "missing_owner"}
    per_chunk_limit = min(_normalize_source_chunk_output_token_limit(max_chunk_tokens), 384)
    total_token_limit = _normalize_source_chunk_total_token_limit(max_total_chunk_tokens)
    query_terms = _extract_vocabulary_free_query_terms(str(query or ""), limit=12)
    row_token_counts = [
        _session_chunk_row_output_tokens(row)
        if isinstance(row, dict)
        and (
            str(row.get("source_type") or row.get("category") or "").strip().lower() in {"session_chunk", "source_chunk"}
            or str(row.get("source_chunk_id") or row.get("microchunk_id") or "").strip()
            or bool(row.get("source_chunk_ids"))
        )
        else 0
        for row in rows
    ]
    expandable_row_count = sum(1 for count in row_token_counts if count > 0)
    per_expandable_row_limit = (
        max(1, total_token_limit // max(1, expandable_row_count))
        if expandable_row_count > 1
        else total_token_limit
    )
    used_tokens = sum(row_token_counts)
    expanded_rows: List[Dict[str, Any]] = []
    expanded_count = 0
    window_chunk_count = 0
    omitted_for_budget = 0
    support_window_count = 0
    for row_index, row in enumerate(rows):
        if not isinstance(row, dict):
            expanded_rows.append(row)
            continue
        if row.get("session_window_expanded"):
            expanded_rows.append(row)
            continue
        source_type = str(row.get("source_type") or row.get("category") or "").strip().lower()
        chunk_id = str(row.get("chunk_id") or row.get("session_chunk_id") or row.get("source_chunk_id") or "").strip()
        microchunk_id = str(row.get("microchunk_id") or "").strip()
        source_chunk_ids = [
            str(value or "").strip()
            for value in (row.get("source_chunk_ids") or [])
            if str(value or "").strip()
        ]
        can_expand = source_type in {"session_chunk", "source_chunk"} or bool(chunk_id or microchunk_id or source_chunk_ids)
        if not can_expand:
            expanded_rows.append(row)
            continue
        try:
            chunk = None
            row_owner_key = owner_key
            if chunk_id:
                chunk = get_graph().get_source_chunk(
                    chunk_id,
                    owner_id=owner_key if source_type in {"session_chunk", "source_chunk"} else None,
                    fail_hard=_is_fail_hard_mode(),
                )
                if isinstance(chunk, dict):
                    row_owner_key = str(chunk.get("owner_id") or "").strip() or owner_key
                if not microchunk_id and isinstance(chunk, dict):
                    microchunk_id = str(chunk.get("microchunk_id") or "").strip()
            window: List[Dict[str, Any]] = []
            expansion_source = "memorydb_projection"
            if source_chunk_ids and not chunk_id and not microchunk_id:
                expansion_source = "graph_cluster_source_chunks"
                seen_window_ids: set[str] = set()
                collected_source_windows: List[List[Dict[str, Any]]] = []
                for source_chunk_id in source_chunk_ids[:_GRAPH_CLUSTER_SOURCE_CHUNK_LIMIT]:
                    source_chunk = get_graph().get_source_chunk(
                        source_chunk_id,
                        # Graph-cluster provenance points at the source chunk
                        # that produced the selected graph fact. Its stored
                        # owner is authoritative; benchmark/import owners can
                        # differ from the recall caller owner.
                        fail_hard=_is_fail_hard_mode(),
                    )
                    if not isinstance(source_chunk, dict):
                        continue
                    source_owner_key = str(source_chunk.get("owner_id") or "").strip() or owner_key
                    source_microchunk_id = str(source_chunk.get("microchunk_id") or "").strip()
                    source_window: List[Dict[str, Any]] = []
                    if source_microchunk_id:
                        expanded = _sessiondb_bridge_expand_microchunk(
                            source_microchunk_id,
                            owner_id=source_owner_key,
                            before=min(before_count, _GRAPH_CLUSTER_SOURCE_WINDOW_RADIUS),
                            after=min(after_count, _GRAPH_CLUSTER_SOURCE_WINDOW_RADIUS),
                        )
                        source_window = _sessiondb_bridge_expansion_window(expanded)
                        source_window = _ensure_session_window_source_date_header(
                            source_window,
                            source_date=source_chunk.get("source_date"),
                            session_id=str(source_chunk.get("session_id") or "").strip() or None,
                            pair_id=str(source_chunk.get("message_pair_id") or "").strip() or None,
                            microchunk_id=source_microchunk_id or None,
                        )
                        center_item = next(
                            (
                                item for item in source_window
                                if isinstance(item, dict)
                                and not item.get("session_source_header")
                                and str(item.get("microchunk_id") or "").strip() == source_microchunk_id
                            ),
                            None,
                        )
                        if center_item is not None:
                            # The selected provenance chunk is the reason this
                            # graph cluster is expanding; keep it even when the
                            # surrounding source window is budget-trimmed.
                            center_item["session_window_required"] = True
                    if not source_window:
                        expanded_chunk = get_graph().get_source_chunk(
                            source_chunk_id,
                            before=min(before_count, _GRAPH_CLUSTER_SOURCE_WINDOW_RADIUS),
                            after=min(after_count, _GRAPH_CLUSTER_SOURCE_WINDOW_RADIUS),
                            fail_hard=_is_fail_hard_mode(),
                        )
                        source_window = list((expanded_chunk or {}).get("window") or [source_chunk])
                        center_item = next(
                            (
                                item for item in source_window
                                if isinstance(item, dict)
                                and str(item.get("chunk_id") or "").strip() == source_chunk_id
                            ),
                            None,
                        )
                        if center_item is not None:
                            # The selected provenance chunk is the reason this
                            # graph cluster is expanding; keep it even when the
                            # surrounding source window is budget-trimmed.
                            center_item["session_window_required"] = True
                    if source_window:
                        collected_source_windows.append(source_window)

                def append_source_window_item(item: Dict[str, Any]) -> bool:
                    if not isinstance(item, dict):
                        return False
                    item_id = _session_window_item_id(item)
                    if item_id and item_id in seen_window_ids:
                        return False
                    if item_id:
                        seen_window_ids.add(item_id)
                    window.append(item)
                    return len(window) >= _GRAPH_CLUSTER_SOURCE_WINDOW_ITEM_LIMIT

                for source_window in collected_source_windows:
                    priority_items = [
                        item for item in source_window
                        if isinstance(item, dict) and item.get("session_source_header")
                    ][:1]
                    priority_items.extend([
                        item for item in source_window
                        if isinstance(item, dict) and item.get("session_window_required")
                    ][:1])
                    for item in priority_items:
                        if append_source_window_item(item):
                            break
                    if len(window) >= _GRAPH_CLUSTER_SOURCE_WINDOW_ITEM_LIMIT:
                        break
                if len(window) < _GRAPH_CLUSTER_SOURCE_WINDOW_ITEM_LIMIT:
                    candidate_items: List[Tuple[int, int, int, int, Dict[str, Any]]] = []
                    for source_index, source_window in enumerate(collected_source_windows):
                        required_positions = [
                            idx for idx, item in enumerate(source_window)
                            if isinstance(item, dict) and item.get("session_window_required")
                        ]
                        for item_index, item in enumerate(source_window):
                            if (
                                isinstance(item, dict)
                                and (item.get("session_source_header") or item.get("session_window_required"))
                            ):
                                continue
                            if not isinstance(item, dict):
                                continue
                            distance = min(
                                (abs(item_index - required_index) for required_index in required_positions),
                                default=item_index,
                            )
                            candidate_items.append((
                                _session_window_item_overlap(item, query_terms),
                                -distance,
                                -source_index,
                                -item_index,
                                item,
                            ))
                    candidate_items.sort(key=lambda item: item[:4], reverse=True)
                    for _overlap, _negative_distance, _negative_source_index, _negative_item_index, item in candidate_items:
                        if append_source_window_item(item):
                            break
            elif microchunk_id:
                expanded = _sessiondb_bridge_expand_microchunk(
                    microchunk_id,
                    owner_id=row_owner_key,
                    before=before_count,
                    after=after_count,
                )
                window = _sessiondb_bridge_expansion_window(expanded)
                if isinstance(chunk, dict):
                    window = _ensure_session_window_source_date_header(
                        window,
                        source_date=chunk.get("source_date"),
                        session_id=str(chunk.get("session_id") or "").strip() or None,
                        pair_id=str(chunk.get("message_pair_id") or "").strip() or None,
                        microchunk_id=microchunk_id or None,
                    )
                if window:
                    expansion_source = "sessiondb_bridge"
                    center_item = next(
                        (
                            item for item in window
                            if isinstance(item, dict)
                            and not item.get("session_source_header")
                            and str(item.get("microchunk_id") or "").strip() == microchunk_id
                        ),
                        None,
                    )
                    if center_item is not None:
                        center_item["session_window_required"] = True
            if not window and chunk_id:
                chunk = get_graph().get_source_chunk(
                    chunk_id,
                    owner_id=owner_key,
                    before=before_count,
                    after=after_count,
                    fail_hard=_is_fail_hard_mode(),
                )
                window = list((chunk or {}).get("window") or [])
        except Exception as exc:
            if _is_fail_hard_mode():
                raise
            logger.warning("session chunk expansion failed for %s: %s", chunk_id, exc, exc_info=True)
            expanded_rows.append(row)
            continue
        if not window or (
            len(window) <= 1
            and not microchunk_id
            and expansion_source != "graph_cluster_source_chunks"
        ):
            expanded_rows.append(row)
            continue
        excluded_ids = {
            _session_window_item_id(item)
            for item in window
            if isinstance(item, dict) and _session_window_item_id(item)
        }
        support_window = _session_stream_support_window(
            center_chunk=chunk if isinstance(chunk, dict) else None,
            owner_id=owner_key,
            query_terms=query_terms,
            excluded_ids=excluded_ids,
        )
        if support_window:
            window_header_dates = {
                value
                for value in (
                    _date_part(item.get("source_date"))
                    for item in window
                    if isinstance(item, dict) and item.get("session_source_header")
                )
                if value
            }
            if window_header_dates:
                # Do not attach support from a different dated transcript turn
                # under the center window's header; that mislabels relative-time
                # phrases like "last week" with the wrong conversation date.
                support_window = [
                    item
                    for item in support_window
                    if isinstance(item, dict)
                    and _date_part(item.get("source_date") or item.get("created_at")) in window_header_dates
                ]
            if support_window:
                window = [*window, *support_window]
                support_window_count += 1
        baseline_tokens = row_token_counts[row_index] if row_index < len(row_token_counts) else 0
        available_tokens = total_token_limit - max(0, used_tokens - baseline_tokens)
        if available_tokens < len(window):
            omitted_for_budget += 1
            expanded_rows.append(row)
            continue
        original_text = str(row.get("text") or "").strip()
        include_original = (
            source_type not in {"session_chunk", "source_chunk"}
            or bool(row.get("session_temporal_context_attached"))
        ) and bool(original_text)
        original_tokens = int(_lib_estimate_tokens(original_text)) if include_original else 0
        available_window_tokens = max(0, min(available_tokens, per_expandable_row_limit) - original_tokens)
        if available_window_tokens < len(window):
            omitted_for_budget += 1
            expanded_rows.append(row)
            continue
        selected_window = _select_session_window_items_for_budget(
            window,
            available_tokens=available_window_tokens,
            query_terms=query_terms,
        )
        header_dates = [
            _date_part(item.get("source_date"))
            for item in window
            if isinstance(item, dict) and item.get("session_source_header")
        ]
        window_source_date = next((value for value in header_dates if value), None)
        selected_window_tokens = sum(
            int(_lib_estimate_tokens(str(item.get("text") or "")))
            for item in selected_window
            if isinstance(item, dict)
        )
        window_chunk_limit = max(1, min(per_chunk_limit, available_window_tokens // max(1, len(selected_window))))
        parts: List[str] = []
        chunk_ids: List[str] = []
        output_tokens = original_tokens
        for item in selected_window:
            if not isinstance(item, dict):
                continue
            item_token_limit = min(
                per_chunk_limit,
                max(
                    window_chunk_limit,
                    int(_lib_estimate_tokens(str(item.get("text") or "")))
                    if selected_window_tokens <= available_window_tokens
                    else window_chunk_limit,
                ),
            )
            payload = _source_chunk_recall_payload(
                item,
                max_chunk_tokens=item_token_limit,
            )
            label = str(payload.get("session_id") or payload.get("source_id") or "session").strip()
            index = payload.get("chunk_index")
            suffix = f"#{index}" if index is not None else ""
            item_source_date = _date_part(payload.get("source_date") or item.get("source_date")) or window_source_date
            payload_text = str(payload.get("text") or "")
            parts.append(f"[session_chunk] {label}{suffix}: {payload_text}")
            chunk_ids.append(str(payload.get("chunk_id") or "").strip())
            output_tokens += int(_lib_estimate_tokens(payload_text))
        if not parts:
            expanded_rows.append(row)
            continue
        expanded = dict(row)
        if include_original:
            if expansion_source == "graph_cluster_source_chunks":
                # For synthetic graph clusters, lead with first-order evidence;
                # the sanitized cluster remains as backup context below it.
                expanded["text"] = "\n".join([*parts, f"[memory] {original_text}"])
            else:
                expanded["text"] = "\n".join([f"[memory] {original_text}", *parts])
        else:
            expanded["text"] = "\n".join(parts)
        if header_dates:
            expanded["source_date"] = window_source_date
            expanded["session_source_header"] = True
        expanded["session_window_expanded"] = True
        expanded["session_window_expansion_source"] = expansion_source
        expanded["session_window_center_chunk_id"] = chunk_id
        if microchunk_id:
            expanded["session_window_center_microchunk_id"] = microchunk_id
        expanded["session_window_chunk_ids"] = [item for item in chunk_ids if item]
        expanded["session_window_size"] = len(expanded["session_window_chunk_ids"])
        expanded["output_token_count"] = output_tokens
        expanded_rows.append(expanded)
        used_tokens = max(0, used_tokens - baseline_tokens) + output_tokens
        if row_index < len(row_token_counts):
            row_token_counts[row_index] = output_tokens
        expanded_count += 1
        window_chunk_count += len(expanded["session_window_chunk_ids"])
    return expanded_rows, {
        "expanded": expanded_count,
        "window_chunk_count": window_chunk_count,
        "before": before_count,
        "after": after_count,
        "max_total_chunk_tokens": total_token_limit,
        "output_token_count": used_tokens,
        "omitted_for_budget": omitted_for_budget,
        "support_windows": support_window_count,
    }


def _expand_final_recall_source_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    owner_id: Optional[str],
    max_chunk_tokens: Optional[int],
    max_total_chunk_tokens: Optional[int],
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Attach first-order source windows for selected compact memory rows."""
    if not rows:
        return rows, {"expanded": 0, "window_chunk_count": 0}
    has_source_projection = any(
        isinstance(row, dict)
        and not row.get("session_window_expanded")
        and (
            str(row.get("source_chunk_id") or row.get("microchunk_id") or "").strip()
            or bool(row.get("source_chunk_ids"))
        )
        for row in rows
    )
    if not has_source_projection:
        return rows, {"expanded": 0, "window_chunk_count": 0}
    return _expand_selected_session_chunk_rows(
        rows,
        owner_id=owner_id,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
        query=query,
    )


def _session_chunk_row_output_tokens(row: Dict[str, Any]) -> int:
    try:
        value = int(row.get("output_token_count"))
    except (TypeError, ValueError):
        value = int(_lib_estimate_tokens(str(row.get("text") or "")))
    return max(0, value)


def _graph_store_recall(
    query: str,
    *,
    owner_id: Optional[str],
    limit: int,
    min_similarity: Optional[float],
    domain: Optional[Dict[str, bool]],
    domain_boost: Optional[Any],
    project: Optional[str],
    date_from: Optional[str],
    date_to: Optional[str],
    temporal_dimension: Optional[str] = None,
    depth: int,
    timeout_ms: Optional[int] = None,
    fast_mode: bool = False,
    candidate_pool: Optional[List[Dict[str, Any]]] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any], Optional[Dict[str, Any]]]:
    payload = graph_aware_recall(
        query,
        owner_id=owner_id,
        limit=limit,
        min_similarity=min_similarity if min_similarity is not None else 0.60,
        graph_depth=depth,
        domain=domain,
        domain_boost=domain_boost,
        project=project,
        date_from=date_from,
        date_to=date_to,
        temporal_dimension=temporal_dimension,
        timeout_ms=timeout_ms,
        fast_mode=fast_mode,
        candidate_pool=candidate_pool,
    )
    combined = list(payload.get("direct_results", [])) + list(payload.get("graph_results", []))
    relation_chain_groups = _relation_chain_groups_for_query(query)
    relation_chain_query = (
        len(relation_chain_groups) >= 2
        and _has_relation_chain_structure(query)
    )
    if relation_chain_query and combined:
        _boost_relation_chain_row_scores(combined, relation_chain_groups, query=query)
    try:
        graph = get_graph()
        _, anchor_expansions = _expand_high_confidence_entity_anchors(
            graph,
            query,
            combined,
            expansion_mode="cheap",
            max_anchor_count=2,
            expansion_limit_per_anchor=1,
            allow_graph_rows=True,
        )
        if anchor_expansions:
            combined.extend(anchor_expansions)
            if relation_chain_query:
                _boost_relation_chain_row_scores(combined, relation_chain_groups, query=query)
    except Exception as exc:
        logger.warning("graph store recall anchor expansion failed: %s", exc)
        if _is_fail_hard_mode():
            raise RuntimeError("graph store recall anchor expansion failed") from exc
    if date_from or date_to:
        combined = _filter_recall_rows_by_date_bounds(
            combined,
            date_from=date_from,
            date_to=date_to,
            temporal_dimension=temporal_dimension,
        )
    combined = _enforce_recall_rows_temporal_axis_validity(
        combined,
        temporal_dimension=temporal_dimension,
    )
    meta = dict(payload.get("meta") or {})
    counts = dict(meta.get("counts") or {})
    counts["graph_discoveries"] = _count_graph_discovery_rows(combined)
    meta["counts"] = counts
    return (
        _validate_recall_result_rows(combined),
        meta,
        None,
    )


def _validate_recall_store_registry(registry: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    for store in ("vector", "docs", "graph", "session_chunks"):
        spec = registry.get(store)
        if not isinstance(spec, dict):
            raise RuntimeError(f"recall store registry missing store '{store}'")
        for contract in ("recall", "recall_fast"):
            if not callable(spec.get(contract)):
                raise RuntimeError(f"recall store '{store}' missing required contract '{contract}'")
    return registry


def _get_recall_store_registry() -> Dict[str, Dict[str, Any]]:
    registry: Dict[str, Dict[str, Any]] = {
        "vector": {
            "recall": _vector_store_recall,
            "recall_fast": _vector_store_recall,
        },
        "docs": {
            "recall": _docs_store_recall,
            "recall_fast": _docs_store_recall,
        },
        "graph": {
            "recall": _graph_store_recall,
            "recall_fast": _graph_store_recall,
        },
        "session_chunks": {
            "recall": _source_chunk_store_recall,
            "recall_fast": _source_chunk_store_recall,
        },
    }
    return _validate_recall_store_registry(registry)


def _is_timeout_like_exception(exc: Exception) -> bool:
    if isinstance(exc, TimeoutError):
        return True
    detail = str(exc or "").lower()
    return (
        "timed out" in detail
        or "timeout" in detail
        or "deadline exhausted" in detail
        or "futures unfinished" in detail
    )


def _recall_store_plan_timeout_s(timeout_ms: Optional[int], *, fast_mode: bool) -> float:
    if timeout_ms is not None:
        try:
            return max(0.5, float(timeout_ms) / 1000.0)
        except (TypeError, ValueError):
            pass
    if fast_mode:
        try:
            raw = _get_configured_injection_timeout_ms(3000)
            return max(0.5, float(raw or 3000) / 1000.0)
        except Exception:
            if _is_fail_hard_mode():
                raise
            return 3.0
    return 30.0


def _resolve_cli_recall_fast_timeout_ms(timeout_ms: Optional[int]) -> int:
    if timeout_ms is None:
        return _CLI_RECALL_FAST_DEFAULT_TIMEOUT_MS
    return int(timeout_ms)


def _handle_recall_branch_exception(
    *,
    parent_query: str,
    branch_query: str,
    branch_index: int,
    turn: int,
    exc: Exception,
) -> Dict[str, Any]:
    timeout_like = _is_timeout_like_exception(exc)
    fail_hard = _is_fail_hard_mode()
    _trace_m15(
        "memory_graph.recall.branch_error",
        query=parent_query,
        branch_query=branch_query,
        branch_index=branch_index,
        turn=turn,
        timeout_like=timeout_like,
        fail_hard=fail_hard,
        error_type=type(exc).__name__,
        error=str(exc),
    )
    if fail_hard or not timeout_like:
        raise exc
    logger.warning(
        "recall branch %d on turn %d timed out; continuing with completed branches: %s",
        branch_index,
        turn,
        exc,
    )
    return {
        "query": branch_query,
        "counts": {
            "initial_candidates": 0,
            "post_threshold_candidates": 0,
            "diverse_results": 0,
            "final_results": 0,
        },
        "phases_ms": {
            "total_ms": 0,
        },
        "flags": {
            "timed_out": True,
        },
        "error_type": type(exc).__name__,
        "error": str(exc)[:240],
        "timed_out": True,
        "stop_reason": "branch_timeout",
    }


def _run_recall_branch_callables(
    callables: List[Any],
    *,
    max_workers: int,
    pool_name: str,
    timeout_seconds: Optional[float],
) -> Tuple[List[Any], float]:
    started = time.monotonic()
    try:
        batches = run_callables(
            callables,
            max_workers=max_workers,
            pool_name=pool_name,
            timeout_seconds=timeout_seconds,
            return_exceptions=True,
        )
    except Exception as exc:
        batches = [exc for _ in callables]
    wall_ms = (time.monotonic() - started) * 1000
    return batches, wall_ms


def _run_recall_store_plan(
    query: str,
    *,
    stores: List[str],
    limit: int,
    owner_id: Optional[str],
    min_similarity: Optional[float],
    planner_profile: str,
    planned_queries: Optional[List[str]],
    planner_meta: Optional[Dict[str, Any]],
    fast_mode: bool,
    graph_depth: int = 1,
    common_kwargs: Optional[Dict[str, Any]] = None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any], Optional[Dict[str, Any]]]:
    normalized_stores = _normalize_store_plan(stores)
    registry = _validate_recall_store_registry(_get_recall_store_registry())
    handler_name = "recall_fast" if fast_mode else "recall"
    kwargs = dict(common_kwargs or {})
    planned_project = (planner_meta or {}).get("planned_project") or kwargs.get("project")
    relation_chain_groups_for_plan = _relation_chain_groups_for_query(query)
    relation_chain_query_for_plan = (
        len(relation_chain_groups_for_plan) >= 2
        and _has_relation_chain_structure(query)
    )
    if relation_chain_query_for_plan:
        try:
            graph_depth = max(int(graph_depth or 1), len(relation_chain_groups_for_plan))
        except (TypeError, ValueError):
            graph_depth = len(relation_chain_groups_for_plan)
    if relation_chain_query_for_plan and "graph" in normalized_stores:
        # Graph-aware relation-chain recall already performs a vector-only seed
        # pass internally. Running a parallel top-level vector lane duplicates
        # embedding work and can starve the tight search-hybrid pool under
        # failHard, so make graph the coordinating store for these chains.
        normalized_stores = [store for store in normalized_stores if store != "vector"]
        if not normalized_stores:
            normalized_stores = ["graph"]

    callables = []
    for store in normalized_stores:
        handler = registry[store][handler_name]
        if store == "vector":
            callables.append(lambda store=store, handler=handler: (
                store,
                handler(
                    query,
                    limit=limit,
                    min_similarity=min_similarity,
                    planner_profile=planner_profile,
                    planned_queries=planned_queries,
                    planner_meta=planner_meta,
                    fast_mode=fast_mode,
                    common_kwargs={**kwargs, "project": planned_project, "owner_id": owner_id},
                ),
            ))
        elif store == "docs":
            callables.append(lambda store=store, handler=handler: (
                store,
                handler(
                    query,
                    limit=max(1, min(limit, 6 if fast_mode else 8)),
                    project=planned_project,
                    date_from=kwargs.get("date_from"),
                    date_to=kwargs.get("date_to"),
                ),
            ))
        elif store == "graph":
            graph_candidate_pool = kwargs.get("candidate_pool")
            if (
                graph_candidate_pool is None
                and "vector" in normalized_stores
                and not relation_chain_query_for_plan
            ):
                # The vector lane is already running in this store plan. Graph
                # recall should traverse explicit/entity anchors instead of
                # recursively paying for another full base recall inside the
                # same plan. Relation-chain queries are the exception: graph
                # needs its own seed facts when owner anchoring is incomplete.
                graph_candidate_pool = []
            callables.append(lambda store=store, handler=handler, graph_candidate_pool=graph_candidate_pool: (
                store,
                handler(
                    query,
                    owner_id=owner_id,
                    limit=max(1, min(limit, 8 if fast_mode else limit)),
                    min_similarity=min_similarity,
                    domain=kwargs.get("domain"),
                    domain_boost=kwargs.get("domain_boost"),
                    project=planned_project,
                    date_from=kwargs.get("date_from"),
                    date_to=kwargs.get("date_to"),
                    temporal_dimension=kwargs.get("temporal_dimension"),
                    depth=graph_depth,
                    timeout_ms=kwargs.get("timeout_ms"),
                    fast_mode=fast_mode,
                    candidate_pool=graph_candidate_pool,
                ),
            ))
        elif store == "session_chunks":
            callables.append(lambda store=store, handler=handler: (
                store,
                handler(
                    query,
                    owner_id=owner_id,
                    limit=max(1, min(limit, 6 if fast_mode else 8)),
                    domain=kwargs.get("domain"),
                    project=planned_project,
                    current_session_id=kwargs.get("current_session_id"),
                    source_channel=kwargs.get("source_channel"),
                    source_conversation_id=kwargs.get("source_conversation_id"),
                    max_chunk_tokens=kwargs.get("max_chunk_tokens"),
                    max_total_chunk_tokens=kwargs.get("max_total_chunk_tokens"),
                    timeout_ms=kwargs.get("timeout_ms"),
                ),
            ))

    started = time.monotonic()
    store_plan_timeout_s = _recall_store_plan_timeout_s(kwargs.get("timeout_ms"), fast_mode=fast_mode)
    outputs = run_callables(
        callables,
        max_workers=min(len(callables), 3),
        pool_name="recall_stores",
        timeout_seconds=store_plan_timeout_s,
        return_exceptions=True,
    )
    wall_ms = round((time.monotonic() - started) * 1000)

    merged_batches: List[List[Dict[str, Any]]] = []
    docs_rows: List[Dict[str, Any]] = []
    docs_bundle: Optional[Dict[str, Any]] = None
    store_runs: List[Dict[str, Any]] = []
    serial_ms = 0
    base_meta: Optional[Dict[str, Any]] = None
    vector_meta: Optional[Dict[str, Any]] = None
    store_meta_entries: List[Tuple[str, Dict[str, Any]]] = []
    rrf_named_batches: List[Tuple[str, List[Dict[str, Any]]]] = []
    for idx, output in enumerate(outputs):
        store_name = normalized_stores[idx] if idx < len(normalized_stores) else "unknown"
        if isinstance(output, Exception):
            timeout_like = _is_timeout_like_exception(output)
            fail_hard = _is_fail_hard_mode()
            store_runs.append({
                "store": store_name,
                "result_count": 0,
                "total_ms": None,
                "selected_path": None,
                "error_type": type(output).__name__,
                "error": str(output)[:240],
                "timed_out": timeout_like,
            })
            _trace_m15(
                "memory_graph.recall_store_plan.store_error",
                query=query,
                store=store_name,
                timeout_like=timeout_like,
                fail_hard=fail_hard,
                error_type=type(output).__name__,
                error=str(output),
            )
            if fail_hard or not timeout_like:
                raise RuntimeError(
                    f"Recall store '{store_name}' failed while failHard is enabled "
                    f"(planned_stores={normalized_stores}, timeout_like={timeout_like}, "
                    f"cause={type(output).__name__}: {output})"
                ) from output
            logger.warning(
                "recall store '%s' timed out; continuing with completed stores: %s",
                store_name,
                output,
            )
            continue
        store, payload = output
        rows, meta, bundle = payload
        rows = _validate_recall_result_rows(rows)
        if kwargs.get("date_from") or kwargs.get("date_to"):
            rows = _filter_recall_rows_by_date_bounds(
                rows,
                date_from=kwargs.get("date_from"),
                date_to=kwargs.get("date_to"),
                temporal_dimension=kwargs.get("temporal_dimension"),
                keep_undated=_keep_undated_rows_for_temporal_dimension(
                    kwargs.get("temporal_dimension"),
                ),
            )
        if store == "session_chunks":
            rows = _prioritize_first_order_session_query_coverage(query, rows)
        if store == "docs" and rows:
            docs_rows.extend(rows)
        meta = dict(meta or {})
        store_meta_entries.append((store, meta))
        rrf_named_batches.append((store, list(rows)))
        if rows:
            merged_batches.append(rows)
        if bundle:
            docs_bundle = _merge_docs_bundles(docs_bundle, bundle)
        phases = meta.get("phases_ms") or {}
        total_ms = phases.get("total_ms")
        if isinstance(total_ms, (int, float)):
            serial_ms += int(total_ms)
        if base_meta is None and store == "vector":
            base_meta = meta
        if store == "vector":
            vector_meta = meta
        store_run = {
            "store": store,
            "result_count": len(rows),
            "total_ms": int(total_ms) if isinstance(total_ms, (int, float)) else None,
            "selected_path": meta.get("selected_path"),
        }
        if store == "graph":
            source_breakdown = meta.get("source_breakdown")
            if isinstance(source_breakdown, dict):
                graph_count = source_breakdown.get("graph_count")
                if isinstance(graph_count, (int, float)):
                    store_run["graph_count"] = max(0, int(graph_count))
            counts = meta.get("counts")
            if isinstance(counts, dict):
                graph_discovery_count = counts.get("graph_discoveries")
                if isinstance(graph_discovery_count, (int, float)):
                    store_run["graph_discovery_count"] = max(0, int(graph_discovery_count))
        store_runs.append(store_run)

    # Keep a wider merged candidate window before post-merge rank refinement.
    # In mixed vector+graph recall, exact entity/relationship rows can occupy
    # the first limit-sized window even when a graph-attached fact is already
    # present just below it. If we truncate to `limit` here, later deliberate
    # prioritizers never see that fact row.
    merge_limit = max(limit, limit * 2 if fast_mode else limit)
    if not fast_mode and len(normalized_stores) > 1:
        merge_limit = max(merge_limit, limit * 2)
    relation_chain_groups = relation_chain_groups_for_plan
    relation_chain_query = relation_chain_query_for_plan
    materialized_row_count = sum(
        len(batch)
        for batch in merged_batches
        if isinstance(batch, list)
    )
    candidate_merge_limit = merge_limit
    if relation_chain_query and materialized_row_count > merge_limit:
        candidate_merge_limit = materialized_row_count
    rrf_branch_weights = _store_plan_rrf_branch_weights(
        normalized_stores,
        planner_meta=planner_meta,
        common_kwargs=common_kwargs,
    )
    rrf_shadow_meta = _shadow_rrf_recall_store_plan(
        rrf_named_batches,
        limit=merge_limit,
        branch_weights=rrf_branch_weights,
    )
    rrf_fusion_meta: Dict[str, Any] = {"enabled": False}
    rrf_fused_rows: Optional[List[Dict[str, Any]]] = None
    if _should_apply_rrf_store_plan_fusion(normalized_stores):
        rrf_fused_rows, rrf_fusion_meta = _active_rrf_recall_store_plan(
            rrf_named_batches,
            normalized_stores=normalized_stores,
            limit=candidate_merge_limit,
            branch_weights=rrf_branch_weights,
        )
    merged = (
        rrf_fused_rows
        if rrf_fused_rows is not None
        else _merge_recall_batches(merged_batches, limit=candidate_merge_limit)
    )
    if relation_chain_query and merged:
        _boost_relation_chain_row_scores(merged, relation_chain_groups, query=query)
        merged.sort(
            key=lambda row: _relation_chain_sort_key(row, relation_chain_groups, query=query),
            reverse=True,
        )
        merged = merged[:merge_limit]
    merged = _prioritize_date_relation_callback_rows(query, merged)
    merged = _prioritize_named_entity_activity_anchor_rows(query, merged)
    merged = _prioritize_first_order_session_query_coverage(query, merged)
    if fast_mode:
        merged = _prioritize_fast_anchor_direct_rows(query, merged)
    else:
        merged = _prioritize_deliberate_confident_direct_anchor_rows(query, merged)
    store_plan_facet_rescue_rows: List[Dict[str, Any]] = []
    store_plan_facet_rescue_meta: Dict[str, Any] = {
        "applied": False,
        "candidate_count": 0,
        "anchor_terms": [],
        "facet_terms": [],
        "error": None,
    }
    if normalized_stores == ["session_chunks"]:
        store_plan_facet_rescue_meta["skipped_reason"] = "session_chunks_only"
    else:
        store_plan_facet_rescue_rows, store_plan_facet_rescue_meta = _recover_explicit_entity_facet_rows(
            query,
            merged,
            owner_id=owner_id,
            limit=limit,
            intent=None,
            domain=kwargs.get("domain"),
            include_unscoped=(kwargs.get("include_unscoped", True) is not False),
        )
    if store_plan_facet_rescue_rows:
        merged = _merge_recall_batches(
            [merged, store_plan_facet_rescue_rows],
            limit=max(candidate_merge_limit, len(merged) + len(store_plan_facet_rescue_rows)),
        )
    if kwargs.get("date_from") or kwargs.get("date_to"):
        merged = _filter_recall_rows_by_date_bounds(
            merged,
            date_from=kwargs.get("date_from"),
            date_to=kwargs.get("date_to"),
            temporal_dimension=kwargs.get("temporal_dimension"),
            keep_undated=_keep_undated_rows_for_temporal_dimension(
                kwargs.get("temporal_dimension"),
            ),
        )
    final_rows = (
        _select_final_recall_rows_with_facet_rescue(
            query,
            merged,
            limit=limit,
            intent=None,
        )
        if store_plan_facet_rescue_rows
        else merged[:limit]
    )
    final_rows, store_plan_preserved_meta = _preserve_strong_store_plan_rows(
        final_rows,
        rrf_named_batches,
        limit=limit,
    )
    final_rows, preserved_shared_quoted_item_rows = _preserve_shared_quoted_item_rows(
        query,
        final_rows,
        rrf_named_batches,
        limit=limit,
    )
    final_rows, preserved_source_dated_fact_rows = _preserve_source_dated_session_rows_for_selected_facts(
        query,
        final_rows,
        rrf_named_batches,
        limit=limit,
    )
    final_rows, preserved_docs_rows = _preserve_requested_docs_rows(
        final_rows,
        docs_rows,
        limit=limit,
        date_to=kwargs.get("date_to"),
    )
    final_rows, assistant_session_suppression_meta = _suppress_assistant_session_rows_when_strong_evidence_exists(
        query,
        final_rows,
        merged,
        limit=limit,
    )
    final_rows, preserved_graph_relation_summary_rows = _preserve_compact_graph_relation_summary_row(
        query,
        final_rows,
        rrf_named_batches,
        limit=limit,
    )
    final_rows, preserved_graph_cluster_rows = _preserve_graph_fact_cluster_row(
        final_rows,
        merged,
        limit=limit,
    )
    final_rows = _prioritize_compact_graph_relation_rows(
        query,
        final_rows,
        limit=limit,
    )
    final_rows = _prioritize_graph_fact_cluster_rows(
        query,
        final_rows,
        limit=limit,
    )
    final_rows, graph_cluster_interpretation_meta = _interpret_selected_graph_fact_cluster_rows(
        query,
        final_rows,
        fast_mode=fast_mode,
    )
    if kwargs.get("date_from") or kwargs.get("date_to"):
        final_rows = _filter_recall_rows_by_date_bounds(
            final_rows,
            date_from=kwargs.get("date_from"),
            date_to=kwargs.get("date_to"),
            temporal_dimension=kwargs.get("temporal_dimension"),
            keep_undated=_keep_undated_rows_for_temporal_dimension(
                kwargs.get("temporal_dimension"),
            ),
        )
    final_rows = _enforce_recall_rows_temporal_axis_validity(
        final_rows,
        temporal_dimension=kwargs.get("temporal_dimension"),
    )
    final_rows, session_chunk_cap_meta = _cap_mixed_session_chunk_results(
        final_rows,
        merged,
        limit=limit,
    )
    final_rows, query_echo_session_meta = _defer_query_echo_session_rows(
        query,
        final_rows,
        merged,
        limit=limit,
    )
    final_rows, session_conflict_meta = _suppress_weaker_synthetic_temporal_conflicts_after_session_source(
        query,
        final_rows,
    )
    final_rows, session_window_meta = _expand_selected_session_chunk_rows(
        final_rows,
        owner_id=owner_id,
        max_chunk_tokens=kwargs.get("max_chunk_tokens"),
        max_total_chunk_tokens=kwargs.get("max_total_chunk_tokens"),
        before=kwargs.get("session_chunk_window_before"),
        after=kwargs.get("session_chunk_window_after"),
        query=query,
    )
    final_rows = _prioritize_first_order_session_query_coverage(query, final_rows)
    final_rows = _prioritize_source_dated_session_rows_for_temporal_answers(query, final_rows)
    if not fast_mode:
        final_rows = _prioritize_deliberate_confident_direct_anchor_rows(query, final_rows)
    final_rows = _prioritize_high_signal_facet_rescue_rows(query, final_rows)
    final_rows = _prioritize_compact_graph_relation_rows(
        query,
        final_rows,
        limit=limit,
    )
    if kwargs.get("date_from") or kwargs.get("date_to"):
        final_rows = _filter_recall_rows_by_date_bounds(
            final_rows,
            date_from=kwargs.get("date_from"),
            date_to=kwargs.get("date_to"),
            temporal_dimension=kwargs.get("temporal_dimension"),
            keep_undated=_keep_undated_rows_for_temporal_dimension(
                kwargs.get("temporal_dimension"),
            ),
        )
    final_rows = _enforce_recall_rows_temporal_axis_validity(
        final_rows,
        temporal_dimension=kwargs.get("temporal_dimension"),
    )
    final_rows, exact_docs_text_dedup_meta = _dedupe_exact_docs_text_recall_rows(
        final_rows,
        merged,
        limit=limit,
    )
    if rrf_fusion_meta.get("enabled"):
        rrf_shadow_meta = dict(rrf_shadow_meta)
        rrf_shadow_meta["comparison_suppressed_reason"] = "active_rrf_fusion"
    else:
        rrf_shadow_meta = _annotate_rrf_shadow_comparison(
            rrf_shadow_meta,
            final_rows,
            limit=limit,
        )
    if _store_meta_result_count(base_meta) <= 0:
        for _, candidate_meta in store_meta_entries:
            if _store_meta_result_count(candidate_meta) > 0:
                base_meta = candidate_meta
                break
    if base_meta is None and store_meta_entries:
        base_meta = store_meta_entries[0][1]
    meta = _harmonize_store_plan_meta(base_meta, final_rows=final_rows, store_runs=store_runs)
    meta.setdefault("mode", "fast" if fast_mode else "deliberate")
    meta.setdefault("query", query)
    meta["selected_path"] = "store_plan" if len(normalized_stores) > 1 or normalized_stores != ["vector"] else meta.get("selected_path", "vector")
    meta["planned_stores"] = normalized_stores
    meta["planned_project"] = planned_project
    if isinstance(planner_meta, dict) and planner_meta.get("session_chunks_auto_included"):
        meta["session_chunks_auto_included"] = True
    meta["store_runs"] = store_runs
    if rrf_fusion_meta.get("enabled") or rrf_fusion_meta.get("failed"):
        meta["rrf_fusion"] = rrf_fusion_meta
    if rrf_shadow_meta.get("enabled") or rrf_shadow_meta.get("failed"):
        meta["rrf_shadow"] = rrf_shadow_meta
    if store_plan_preserved_meta.get("preserved"):
        meta["store_plan_preserved_branch_tops"] = store_plan_preserved_meta
    for store_name, store_meta in store_meta_entries:
        if store_name != "session_chunks":
            continue
        session_chunk_telemetry = store_meta.get("session_chunk_telemetry") or store_meta.get("source_chunk_telemetry")
        if isinstance(session_chunk_telemetry, dict):
            meta["session_chunk_telemetry"] = dict(session_chunk_telemetry)
            meta["source_chunk_telemetry"] = dict(session_chunk_telemetry)
    if preserved_docs_rows:
        meta["preserved_docs_rows"] = preserved_docs_rows
    if assistant_session_suppression_meta.get("applied"):
        meta["assistant_session_suppression"] = assistant_session_suppression_meta
    if preserved_shared_quoted_item_rows.get("preserved"):
        meta["preserved_shared_quoted_item_rows"] = preserved_shared_quoted_item_rows
    if preserved_source_dated_fact_rows.get("preserved"):
        meta["preserved_source_dated_fact_rows"] = preserved_source_dated_fact_rows
    if preserved_graph_relation_summary_rows:
        meta["preserved_graph_relation_summary_rows"] = preserved_graph_relation_summary_rows
    if preserved_graph_cluster_rows:
        meta["preserved_graph_cluster_rows"] = preserved_graph_cluster_rows
    if session_conflict_meta.get("suppressed"):
        meta["session_source_conflict_suppression"] = session_conflict_meta
    if exact_docs_text_dedup_meta.get("deduped"):
        meta["exact_docs_text_dedup"] = exact_docs_text_dedup_meta
    if query_echo_session_meta.get("applied"):
        meta["query_echo_session_deferral"] = query_echo_session_meta
    if session_chunk_cap_meta.get("applied"):
        meta["session_chunk_result_cap"] = session_chunk_cap_meta
    if store_plan_facet_rescue_meta.get("applied") or store_plan_facet_rescue_meta.get("error"):
        meta["facet_rescue"] = store_plan_facet_rescue_meta
    if graph_cluster_interpretation_meta.get("enabled"):
        meta["graph_cluster_interpretation"] = graph_cluster_interpretation_meta
    if session_window_meta.get("expanded") or session_window_meta.get("omitted_for_budget"):
        meta["session_window_expansion"] = session_window_meta
    # Preserve lexical planner diagnostics from vector recall even when the
    # merged/base metadata row was sourced from another store lane.
    if isinstance(vector_meta, dict):
        vector_lexical = vector_meta.get("lexical_anchor")
        if isinstance(vector_lexical, dict):
            meta["lexical_anchor"] = dict(vector_lexical)
        if isinstance(vector_meta.get("turn_details"), list) and vector_meta.get("turn_details"):
            vector_first = vector_meta["turn_details"][0]
            if isinstance(vector_first, dict):
                vector_diag = vector_first.get("diagnostics")
                if isinstance(vector_diag, dict):
                    lexical_diag = vector_diag.get("lexical_anchor")
                    if isinstance(lexical_diag, dict):
                        turn_details = meta.get("turn_details")
                        if not isinstance(turn_details, list) or not turn_details:
                            turn_details = [{"turn": 1}]
                            meta["turn_details"] = turn_details
                        first_turn = turn_details[0]
                        if isinstance(first_turn, dict):
                            diagnostics = first_turn.get("diagnostics")
                            if not isinstance(diagnostics, dict):
                                diagnostics = {}
                                first_turn["diagnostics"] = diagnostics
                            diagnostics["lexical_anchor"] = dict(lexical_diag)
    phases = dict(meta.get("phases_ms") or {})
    phases["store_plan_wall_ms"] = wall_ms
    phases["store_plan_serial_ms"] = serial_ms
    phases["total_ms"] = wall_ms
    meta["phases_ms"] = phases
    store_plan_gate_intent = "GENERAL"
    try:
        store_plan_gate_intent, _ = classify_intent(query)
    except Exception:
        store_plan_gate_intent = "GENERAL"
    store_plan_include_relation_keywords = not fast_mode
    store_plan_gate_eval = _evaluate_quality_gate_readiness(
        query,
        final_rows,
        intent=store_plan_gate_intent,
        limit=limit,
        include_relation_keywords=store_plan_include_relation_keywords,
    )
    quality_gate = dict(meta.get("quality_gate") or {})
    quality_gate["evaluation"] = store_plan_gate_eval
    quality_gate["result_count"] = len(final_rows)
    meta["quality_gate"] = quality_gate
    meta["memory_quality"] = _summarize_memory_quality(
        query,
        final_rows,
        gate_eval=store_plan_gate_eval,
        intent=store_plan_gate_intent,
        limit=limit,
        include_relation_keywords=store_plan_include_relation_keywords,
    )
    if not meta.get("turn_details"):
        meta["turn_details"] = [{
            "turn": 1,
            "planner": dict(planner_meta or {
                "query": query,
                "queries_count": len(list(planned_queries or [query])),
                "planned_stores": normalized_stores,
                "planned_project": planned_project,
            }),
            "store_runs": list(store_runs),
        }]
    elif isinstance(meta.get("turn_details"), list) and meta["turn_details"]:
        first = meta["turn_details"][0]
        if isinstance(first, dict):
            planner = first.get("planner")
            if not isinstance(planner, dict):
                planner = dict(planner_meta or {})
                first["planner"] = planner
            planner["planned_stores"] = normalized_stores
            planner["planned_project"] = planned_project
            first["store_runs"] = list(store_runs)
    return final_rows, meta, docs_bundle


def _print_docs_bundle(bundle: Dict[str, Any]) -> None:
    """Render docs recall results in the same shape as standalone docs search."""
    docs = _validate_docs_bundle(bundle)
    chunks = docs["chunks"]
    project_md = docs.get("project_md")
    scope_hint = None
    if isinstance(docs.get("telemetry"), dict):
        candidate_hint = docs["telemetry"].get("scope_hint")
        if isinstance(candidate_hint, dict):
            scope_hint = candidate_hint
    workspace_prefix = ""
    try:
        workspace_prefix = str(get_workspace_dir()) + "/"
    except Exception:
        workspace_prefix = ""

    if chunks:
        print("\n=== Documentation ===")
        for i, chunk in enumerate(chunks, 1):
            source_short = chunk["source"]
            if workspace_prefix and source_short.startswith(workspace_prefix):
                source_short = source_short.replace(workspace_prefix, "~/", 1)
            header = chunk.get("section_header") or ""
            header_str = f" > {header}" if header else ""
            print(f"{i}. {source_short}{header_str} (similarity: {chunk['similarity']})")
            for line in chunk["content"].splitlines():
                print(f"   {line}")
            print()
    if project_md:
        print("\n=== PROJECT.md ===")
        print(project_md[:1000])
        if len(project_md) > 1000:
            print("  ... (truncated)")
    if not chunks and isinstance(scope_hint, dict) and str(scope_hint.get("type") or "") == "unlinked_project_candidates":
        candidates = scope_hint.get("candidates")
        names: List[str] = []
        if isinstance(candidates, list):
            names = [
                str(item.get("project") or "").strip()
                for item in candidates
                if isinstance(item, dict) and str(item.get("project") or "").strip()
            ]
        if names:
            print("\n=== Documentation Scope Hint ===")
            print("No docs hits were found inside linked projects.")
            print(f"Likely unlinked project candidates: {', '.join(names)}")
            print(
                "For read-only lookups or one-fact questions, answer from scoped recall or direct file read "
                "without linking. Link only when the user explicitly asks to link the project or requests "
                "durable work such as edits, API/tool use, or starting development."
            )


def _normalize_domain_tag(value: Optional[str]) -> Optional[str]:
    """Normalize domain labels for registry and memory attributes."""
    return _normalize_domain_id(value)


def _registered_domains() -> Dict[str, str]:
    """Deprecated fallback map; runtime domain allowlist is DB-owned."""
    return {}


def _normalize_domains(values: Any) -> List[str]:
    """Normalize domains from input into a deduplicated list."""
    if values is None:
        return []
    if isinstance(values, str):
        values = [values]
    if not isinstance(values, list):
        return []
    seen = set()
    out: List[str] = []
    for value in values:
        norm = _normalize_domain_tag(value)
        if not norm or norm in seen:
            continue
        seen.add(norm)
        out.append(norm)
    return out


def _sanitize_domains_for_project(values: Any, project: Optional[str]) -> List[str]:
    """Drop a redundant project slug from domains when project metadata is explicit."""
    out = _normalize_domains(values)
    project_domain = _normalize_domain_tag(project)
    if not project_domain:
        return out
    return [domain for domain in out if domain != project_domain]


def _domains_from_attrs(attrs: Any) -> List[str]:
    """Read normalized domains from attrs."""
    if not isinstance(attrs, dict):
        return []
    return _normalize_domains(attrs.get("domains"))


def _active_domains_for_filter(graph: Optional["MemoryGraph"] = None) -> set[str]:
    """Resolve active domains from DB only."""
    if graph is not None:
        with graph._get_conn() as conn:
            _ensure_domain_registry_tables(conn)
            active = set(_read_active_domain_map(conn).keys())
            if not active:
                active = set(_bootstrap_default_domain_map(conn).keys())
            if active:
                return active
    return set()


def _normalize_domain_filter(value: Any, allowed_domains: Optional[set[str]] = None) -> Tuple[bool, set[str]]:
    """Normalize recall domain filter map.

    Returns:
      (include_all, included_domains)
    """
    if not isinstance(value, dict):
        return True, set()
    requested = {
        _normalize_domain_tag(k)
        for k, v in value.items()
        if bool(v) and _normalize_domain_tag(k) and _normalize_domain_tag(k) != "all"
    }
    registered = set(allowed_domains) if allowed_domains is not None else set(_registered_domains().keys())
    include = {d for d in requested if d in registered}
    # Fail open for unknown-only inputs so callers from older prompt/schema
    # variants do not hard-fail recall.
    if requested and not include:
        include_all = bool(value.get("all", True))
        return include_all, set()

    if include:
        return False, include
    include_all = bool(value.get("all", True))
    return include_all, set()


def _normalize_domain_boost(
    value: Any,
    allowed_domains: Optional[set[str]] = None,
    default_factor: float = 1.3,
) -> Dict[str, float]:
    """Normalize optional domain boost input to {domain_id: multiplier}.

    Accepted forms:
      - list[str]: ["technical", "project"] -> each gets default_factor
      - dict[str, number|bool|None]: {"technical": 1.5, "project": true}
        bool True / None values use default_factor
    """
    out: Dict[str, float] = {}
    if value is None:
        return out

    if isinstance(value, dict):
        items = value.items()
    else:
        if isinstance(value, str):
            value = [value]
        if not isinstance(value, list):
            return out
        items = [(raw, None) for raw in value]

    for raw_key, raw_factor in items:
        domain_id = _normalize_domain_tag(raw_key)
        if not domain_id:
            continue
        factor = default_factor
        if raw_factor is False:
            continue
        if raw_factor not in (None, True):
            try:
                parsed = float(raw_factor)
                if parsed <= 0:
                    continue
                factor = parsed
            except (TypeError, ValueError):
                pass
        factor = max(1.0, min(factor, 2.0))
        out[domain_id] = factor

    if allowed_domains is not None and allowed_domains:
        out = {k: v for k, v in out.items() if k in allowed_domains}
    return out


def _normalize_project_tag(value: Optional[str]) -> Optional[str]:
    """Normalize project label."""
    if value is None:
        return None
    raw = unicodedata.normalize("NFKC", str(value)).strip().casefold()
    if not raw:
        return None
    chars = [
        ch if ch in "._/-" or ch.isalnum() or unicodedata.category(ch).startswith("M") else "-"
        for ch in raw
    ]
    norm = re.sub(r"-{2,}", "-", "".join(chars)).strip("-")
    return norm[:64] if norm else None


def _recall_once(
    query: str,
    limit: int = 5,
    privacy: Optional[List[str]] = None,
    owner_id: Optional[str] = None,
    min_similarity: Optional[float] = None,
    use_routing: bool = True,
    use_aliases: bool = True,
    use_intent: bool = True,
    use_multi_pass: bool = True,
    use_reranker: Optional[bool] = None,
    current_session_id: Optional[str] = None,
    compaction_time: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    source_channel: Optional[str] = None,
    source_conversation_id: Optional[str] = None,
    source_author_id: Optional[str] = None,
    actor_id: Optional[str] = None,
    subject_entity_id: Optional[str] = None,
    viewer_entity_id: Optional[str] = None,
    participant_entity_ids: Optional[List[str]] = None,
    include_unscoped: bool = True,
    debug: bool = False,
    domain: Optional[Dict[str, bool]] = None,
    domain_boost: Optional[Any] = None,
    project: Optional[str] = None,
    include_graph_traversal: bool = True,
    include_co_session: bool = True,
    include_mmr: bool = True,
    include_lexical_anchor_shaping: bool = True,
    lexical_anchor_planner_mode: str = "llm",
    lexical_anchor_timeout_ms: Optional[int] = None,
    use_lightweight_config: bool = False,
    track_access: bool = True,
    relative_temporal_freshness: bool = False,
    temporal_dimension: Optional[str] = None,
    low_signal_retry: bool = True,
    timeout_ms: Optional[int] = None,
    include_chunks: bool = False,
    preserve_source_chunk_ids: bool = False,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
    return_meta: bool = False,
) -> Any:
    """
    Recall memories matching a query.
    Returns list of dicts with text, category, similarity.

    Uses RRF-fused hybrid search, composite scoring (relevance + recency +
    frequency), and MMR diversity to return high-quality, diverse results.

    Args:
        query: Search query
        limit: Max results to return
        privacy: Privacy levels to search
        owner_id: Filter by owner (includes shared/public if set)
        min_similarity: Minimum similarity threshold (None = read from config retrieval.minSimilarity)
        use_routing: Whether to apply HyDE query expansion via LLM before search
        use_aliases: Whether to resolve entity aliases (e.g., Mom -> a known person node)
        use_intent: Whether to classify query intent for fusion weight tuning
        use_multi_pass: Whether to attempt a second-pass broader search on low-quality results
        use_reranker: Override config reranker_enabled (None = use config)
        date_from: Only return memories on or after this date (YYYY-MM-DD)
        date_to: Only return memories on or before this date (YYYY-MM-DD). When
            supplied without date_from, recall treats the bound as an as-of view
            and prefers newer eligible dated rows after filtering.
        temporal_dimension: Date axis for filters: auto, occurred, mentioned, or record.
        domain: Optional domain filter map (default {"all": true})
        project: Optional project label filter
    """
    if not query or not query.strip():
        return []
    date_from = _normalize_recall_date_bound(date_from)
    date_to = _normalize_recall_date_bound(date_to)
    temporal_dimension = _normalize_recall_temporal_dimension(temporal_dimension)

    import time as _time
    _recall_start = _time.monotonic()
    search_timeout_s: Optional[float] = None
    if timeout_ms is not None:
        try:
            search_timeout_s = max(0.5, float(timeout_ms) / 1000.0)
        except (TypeError, ValueError):
            search_timeout_s = None
    _fts_fallback_used = False
    _multi_pass_triggered = False
    _multi_pass_ids = set()  # Track which node IDs came from second pass (for Bjork difficulty)
    _reranker_changes = 0
    _reranker_top1_changed = 0
    _reranker_avg_displacement = 0.0
    _graph_discoveries = 0
    _co_session_added = 0
    _lexical_rescue_added = 0
    _lexical_rescue_boosted = 0
    _phase_ms: Dict[str, int] = {
        "alias_resolution_ms": 0,
        "intent_classification_ms": 0,
        "ollama_health_ms": 0,
        "hyde_ms": 0,
        "lexical_anchor_planner_ms": 0,
        "search_hybrid_ms": 0,
        "fts_fallback_ms": 0,
        "raw_fts_ms": 0,
        "scoring_ms": 0,
        "reranker_ms": 0,
        "multi_pass_ms": 0,
        "mmr_ms": 0,
        "co_session_ms": 0,
        "graph_traversal_ms": 0,
        "filtering_ms": 0,
        "access_update_ms": 0,
        "total_ms": 0,
    }

    config_retrieval = None
    try:
        if use_lightweight_config:
            config_retrieval = _get_retrieval_lightweight_config()
        else:
            from config import get_config
            config_retrieval = get_config().retrieval
        if min_similarity is None:
            min_similarity = getattr(config_retrieval, "min_similarity", 0.60)
    except Exception as exc:
        logger.warning("recall_once config load failed; using default: %s", exc)
        if _is_fail_hard_mode():
            raise RuntimeError("recall_once config load failed") from exc
        if min_similarity is None:
            min_similarity = 0.60
    if privacy is None:
        privacy = ["private", "shared", "public"]
    elif isinstance(privacy, str):
        privacy = [privacy]
    if use_lightweight_config:
        graph = MemoryGraph(db_path=_get_db_path_lightweight(), initialize=False)
    else:
        graph = get_graph()
    requested_domain_filter = (
        isinstance(domain, dict)
        and any(
            bool(v) and _normalize_domain_tag(k) and _normalize_domain_tag(k) != "all"
            for k, v in domain.items()
        )
    )
    active_domains = _active_domains_for_filter(graph) if (requested_domain_filter or domain_boost) else set()
    include_all_domains, included_domains = _normalize_domain_filter(
        domain,
        active_domains,
    )
    boosted_domains = _normalize_domain_boost(domain_boost, active_domains, default_factor=1.3)
    boosted_node_factors: Dict[str, float] = {}
    if boosted_domains:
        try:
            with graph._get_conn() as conn:
                placeholders = ",".join("?" for _ in boosted_domains)
                rows = conn.execute(
                    f"SELECT node_id, domain FROM node_domains WHERE domain IN ({placeholders})",
                    list(boosted_domains.keys()),
                ).fetchall()
            for row in rows:
                node_id = str(row[0])
                domain_id = _normalize_domain_tag(row[1])
                if not node_id or not domain_id:
                    continue
                factor = boosted_domains.get(domain_id)
                if factor is None:
                    continue
                prior = boosted_node_factors.get(node_id, 1.0)
                if factor > prior:
                    boosted_node_factors[node_id] = factor
        except Exception as exc:
            logger.warning("domain boost index lookup failed; skipping boost: %s", exc)
            if _is_fail_hard_mode():
                raise
            boosted_node_factors = {}
    requested_project = _normalize_project_tag(project)

    # Strip gateway metadata from query (e.g. "[Telegram User id:...] actual message")
    clean_query = query
    meta_match = re.search(r'\]\s*([^\[].+)$', query, re.DOTALL)
    if meta_match and len(meta_match.group(1).strip()) >= 3:
        clean_query = meta_match.group(1).strip()

    # Resolve entity aliases in query
    _phase_t0 = _time.monotonic()
    if use_aliases:
        clean_query = graph.resolve_alias(clean_query, owner_id=owner_id)
    _phase_ms["alias_resolution_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Classify query intent BEFORE search — used for fusion weights and type boosting
    _phase_t0 = _time.monotonic()
    if use_intent:
        intent, type_boosts = classify_intent(clean_query)
    else:
        intent = "GENERAL"
        type_boosts = {}
    _phase_ms["intent_classification_ms"] = round((_time.monotonic() - _phase_t0) * 1000)
    target_date = _query_target_date(clean_query)
    prefer_fresh = bool(relative_temporal_freshness) and not target_date

    # Search with buffer for composite scoring + MMR selection
    search_limit = limit * 3
    if date_from or date_to:
        # Date bounds are applied after hybrid search because event/source
        # dates live on heterogeneous row types, not in the ANN/FTS indexes.
        # Pull a wider bounded pool so in-range facts are not starved by
        # high-scoring out-of-window or source-chunk candidates.
        search_limit = max(search_limit, min(max(limit * 12, 60), 160))
    search_query = clean_query
    results: List[Tuple[Node, float]] = []
    _fast_lexical_preflight_used = False
    planner_mode = str(lexical_anchor_planner_mode or "llm").strip().lower()
    if (
        use_lightweight_config
        and planner_mode == "deterministic"
        and _fast_lexical_preflight_enabled(timeout_ms)
    ):
        _phase_t0 = _time.monotonic()
        results = _fast_lexical_preflight_results(
            graph,
            clean_query,
            limit=search_limit,
            min_similarity=float(min_similarity or 0.0),
            owner_id=owner_id,
        )
        _phase_ms["fts_fallback_ms"] = round((_time.monotonic() - _phase_t0) * 1000)
        if results:
            _fast_lexical_preflight_used = True
            _fts_fallback_used = True

    # Fast Ollama health check — skip semantic search entirely if Ollama is down
    # Saves ~30s of embedding timeout waits when Ollama is unreachable. Strong
    # fast lexical preflight rows intentionally avoid provider calls altogether.
    _ollama_up = True
    if not results:
        _phase_t0 = _time.monotonic()
        _ollama_up = _ollama_healthy()
        _phase_ms["ollama_health_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    if results:
        search_query = clean_query
    elif _ollama_up:
        # Route query through LLM (HyDE) — only when embeddings will be used
        cfg_use_hyde = True
        try:
            cfg_use_hyde = bool(get_config().retrieval.use_hyde)
        except Exception:
            cfg_use_hyde = True
        _use_hyde = bool(use_routing) and cfg_use_hyde
        if not _HAS_LLM_CLIENTS:
            _use_hyde = False
        _phase_t0 = _time.monotonic()
        search_query = route_query(clean_query) if _use_hyde else clean_query
        _phase_ms["hyde_ms"] = round((_time.monotonic() - _phase_t0) * 1000)
        _phase_t0 = _time.monotonic()
        results = graph.search_hybrid(
            search_query,
            limit=search_limit,
            privacy=privacy,
            owner_id=owner_id,
            current_session_id=current_session_id,
            compaction_time=compaction_time,
            intent=intent,
            timeout_seconds=search_timeout_s,
        )
        _phase_ms["search_hybrid_ms"] = round((_time.monotonic() - _phase_t0) * 1000)
    else:
        search_query = clean_query  # No HyDE when embeddings unavailable
        import logging
        msg = "Ollama unreachable — recall falling back to FTS-only"
        logging.getLogger(__name__).warning(msg)
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Embedding provider unavailable during recall. "
                "Fail-hard mode is ON (retrieval.fail_hard=true), "
                "so degraded FTS-only fallback is blocked. "
                "Set retrieval.fail_hard=false to allow fallback, "
                "but this is not recommended because it masks infrastructure faults."
            )
        results = []  # Skip semantic search, go straight to FTS fallback
        _fts_fallback_used = True

    # FTS fallback: if hybrid search returned nothing (Ollama may be down),
    # fall back to keyword-only search so recall isn't completely broken
    if not results:
        _phase_t0 = _time.monotonic()
        fts_fallback = graph.search_fts(clean_query, limit=search_limit, owner_id=owner_id)
        for node, fts_rank in fts_fallback:
            # Estimate quality score from rank position
            quality = max(0.5, 1.0 - fts_rank * 0.02)
            results.append((node, quality))
        if fts_fallback:
            _fts_fallback_used = True
        _phase_ms["fts_fallback_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Also run FTS on the raw query (before routing) to catch proper nouns
    # that route_query may have dropped or transformed
    elif use_routing and search_query != clean_query:
        _phase_t0 = _time.monotonic()
        raw_fts = graph.search_fts(clean_query, limit=limit, owner_id=owner_id)
        result_ids = {node.id for node, _ in results}
        for node, fts_rank in raw_fts:
            if node.id not in result_ids:
                quality = max(0.5, 1.0 - fts_rank * 0.02)
                results.append((node, quality))
                result_ids.add(node.id)
        _phase_ms["raw_fts_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    lexical_anchor_meta: Dict[str, Any] = {
        "used_llm": False,
        "bailout_reason": "lexical_anchor_shaping_disabled",
        "elapsed_ms": 0,
        "timeout_ms": 0,
        "anchor_count": 0,
        "source": "disabled",
    }
    query_anchor_terms: List[str] = []
    allow_anchor_miss_penalty = bool(include_lexical_anchor_shaping)
    if include_lexical_anchor_shaping:
        planner_timeout_ms = _LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS
        planner_max_retries = _LEXICAL_ANCHOR_DEFAULT_MAX_RETRIES
        if lexical_anchor_timeout_ms is not None:
            try:
                planner_timeout_ms = max(200, int(lexical_anchor_timeout_ms))
            except Exception:
                planner_timeout_ms = _LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS
        else:
            try:
                planner_timeout_ms = int(
                    getattr(config_retrieval, "lexical_anchor_timeout_ms", _LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS)
                    or _LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS
                )
            except Exception:
                planner_timeout_ms = _LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS
        planner_max_retries = _resolve_lexical_anchor_max_retries(config_retrieval)
        planner_anchor_limit = _resolve_lexical_anchor_limit(clean_query, config_retrieval)
        planner_mode = str(lexical_anchor_planner_mode or "llm").strip().lower()
        if planner_mode not in {"llm", "deterministic"}:
            planner_mode = "llm"
        if planner_mode == "deterministic":
            explicit_anchor_set = {
                term.lower()
                for term in _extract_explicit_query_anchor_terms(clean_query, limit=24)
                if term
            }
            explicit_terms: List[str] = []
            explicit_seen: set[str] = set()
            for candidate in _extract_explicit_query_anchor_terms(clean_query, limit=24):
                norm = " ".join(str(candidate or "").split()).strip().strip(".,;:!?\"'").lower()
                if not norm or norm in explicit_seen:
                    continue
                if norm in _QUERY_STOPWORDS:
                    continue
                explicit_seen.add(norm)
                explicit_terms.append(norm)
                if len(explicit_terms) >= planner_anchor_limit:
                    break

            seeded_terms: List[str] = []
            seeded_seen: set[str] = set()
            if explicit_terms:
                seeded_terms = explicit_terms[:planner_anchor_limit]
            else:
                # Deterministic fast-path shaping is intentionally conservative:
                # only add distinctive lexical terms when no explicit entities are
                # available, and filter out broad question nouns that often
                # increase false-attribution noise in preinject.
                strict_noise = {
                    "agent", "api", "app", "around", "city", "detail", "details",
                    "did", "does", "family", "find", "goal", "handle", "kind",
                    "label", "labels", "level", "live", "presentation", "project",
                    "school", "secret", "suggested", "target", "thing",
                    "type", "what", "which", "who", "whose", "why", "where", "when",
                }
                for candidate in _extract_distinctive_query_terms(clean_query, limit=24):
                    norm = " ".join(str(candidate or "").split()).strip().strip(".,;:!?\"'").lower()
                    if not norm or norm in seeded_seen:
                        continue
                    if len(norm) < 5:
                        continue
                    if norm in _QUERY_STOPWORDS or norm in strict_noise:
                        continue
                    pieces = re.findall(r"[\w][\w._'-]*", norm, flags=re.UNICODE)
                    normalized_pieces = [
                        re.sub(r"(?:['’]s)$", "", piece.lower())
                        for piece in pieces
                    ]
                    if pieces and all(
                        (
                            piece in _QUERY_STOPWORDS
                            or piece in strict_noise
                            or len(piece) < 3
                        )
                        for piece in normalized_pieces
                    ):
                        continue
                    seeded_seen.add(norm)
                    seeded_terms.append(norm)
                    if len(seeded_terms) >= planner_anchor_limit:
                        break
            query_anchor_terms = seeded_terms[:planner_anchor_limit]
            has_explicit_anchor_match = any(
                term.lower() in explicit_anchor_set for term in query_anchor_terms
            )
            # Deterministic fast-path shaping can still boost explicit anchors, but
            # when no explicit anchor exists it must not demote misses. This keeps
            # sparse/non-English fast queries from falling below lexical-off behavior.
            allow_anchor_miss_penalty = has_explicit_anchor_match
            lexical_anchor_meta = {
                "used_llm": False,
                "bailout_reason": None,
                "elapsed_ms": 0,
                "timeout_ms": 0,
                "anchor_count": len(query_anchor_terms),
                "limit": planner_anchor_limit,
                "anchors": list(query_anchor_terms),
                "source": "deterministic",
                "miss_penalty_enabled": allow_anchor_miss_penalty,
            }
        else:
            planner_timeout_s = _lexical_anchor_planner_timeout_s(
                planner_timeout_ms,
                fast_context=use_lightweight_config,
                timeout_ms=timeout_ms,
            )
            query_anchor_terms, lexical_anchor_meta = _plan_query_anchor_terms(
                clean_query,
                limit=planner_anchor_limit,
                timeout_s=planner_timeout_s,
                timeout_cap_s=(planner_timeout_ms / 1000.0),
                max_retries=planner_max_retries,
            )
            allow_anchor_miss_penalty = bool(query_anchor_terms)
            lexical_anchor_meta["miss_penalty_enabled"] = allow_anchor_miss_penalty
        _phase_ms["lexical_anchor_planner_ms"] = int(lexical_anchor_meta.get("elapsed_ms") or 0)
        logger.info(
            "RECALL_LEXICAL_ANCHOR_PLANNER elapsed_ms=%s used_llm=%s anchor_count=%s limit=%s bailout_reason=%s source=%s miss_penalty_enabled=%s anchors=%s",
            lexical_anchor_meta.get("elapsed_ms"),
            lexical_anchor_meta.get("used_llm"),
            lexical_anchor_meta.get("anchor_count"),
            lexical_anchor_meta.get("limit"),
            lexical_anchor_meta.get("bailout_reason"),
            lexical_anchor_meta.get("source"),
            lexical_anchor_meta.get("miss_penalty_enabled"),
            lexical_anchor_meta.get("anchors"),
        )

    # Apply composite scoring (search relevance + recency + frequency + intent boost)
    _phase_t0 = _time.monotonic()
    scored_results = []
    debug_info = {} if debug else None
    for node, quality_score in results:
        _attrs = node.attributes if isinstance(node.attributes, dict) else {}
        composite = _compute_composite_score(
            node,
            quality_score,
            config_retrieval,
            intent=intent,
            prefer_fresh=prefer_fresh,
            target_date=target_date,
            temporal_dimension=temporal_dimension,
        )
        # Apply intent-based type boost
        type_boost_applied = 1.0
        if type_boosts and node.type in type_boosts:
            type_boost_applied = type_boosts[node.type]
            composite = min(composite * type_boost_applied, 1.0)
        if boosted_node_factors:
            boost_factor = boosted_node_factors.get(node.id)
            if boost_factor:
                composite = min(composite * boost_factor, 1.0)
        composite = min(
            composite * _compute_query_fit_multiplier(
                clean_query,
                node,
                _attrs,
                intent=intent,
                include_anchor_terms=include_lexical_anchor_shaping,
                query_anchor_terms=query_anchor_terms,
                allow_anchor_miss_penalty=allow_anchor_miss_penalty,
                include_relation_keywords=not use_lightweight_config,
            ),
            1.0,
        )
        scored_results.append((node, composite))

        if debug:
            debug_info[node.id] = {
                "raw_quality_score": round(quality_score, 4),
                "composite_score": round(composite, 4),
                "intent": intent,
                "type_boost": type_boost_applied,
                "node_type": node.type,
                "confidence": node.confidence,
                "access_count": node.access_count,
                "confirmation_count": node.confirmation_count,
                "valid_from": node.valid_from,
                "valid_until": node.valid_until,
            }
    _phase_ms["scoring_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Cross-encoder reranking (if enabled)
    reranker_enabled = False
    if config_retrieval:
        reranker_enabled = getattr(config_retrieval, 'reranker_enabled', False)
    if use_reranker is not None:
        reranker_enabled = use_reranker
    if reranker_enabled:
        _phase_t0 = _time.monotonic()
        try:
            _pre_rerank_order = [node.id for node, _ in scored_results[:20]]
            scored_results = _rerank_with_cross_encoder(
                clean_query,
                scored_results,
                config_retrieval,
                overall_timeout_ms=timeout_ms,
            )
            _post_rerank_order = [node.id for node, _ in sorted(scored_results[:20], key=lambda x: x[1], reverse=True)]
            _reranker_changes = sum(1 for i, nid in enumerate(_pre_rerank_order)
                                    if i < len(_post_rerank_order) and _post_rerank_order[i] != nid)
            # Enhanced reranker delta tracking
            if _pre_rerank_order and _post_rerank_order:
                _reranker_top1_changed = 1 if _pre_rerank_order[0] != _post_rerank_order[0] else 0
                # Compute average absolute rank displacement
                post_index_map = {nid: i for i, nid in enumerate(_post_rerank_order)}
                displacements = []
                for pre_i, nid in enumerate(_pre_rerank_order):
                    if nid in post_index_map:
                        displacements.append(abs(pre_i - post_index_map[nid]))
                if displacements:
                    _reranker_avg_displacement = sum(displacements) / len(displacements)
        except Exception as exc:
            if _is_fail_hard_mode():
                raise RuntimeError(
                    "Recall reranker failed during recall while failHard is enabled"
                ) from exc
            logger.debug("Recall reranker failed during recall; using original scoring", exc_info=True)
        _phase_ms["reranker_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Sort by composite score before thresholding so telemetry can see near-misses.
    scored_results.sort(key=lambda x: x[1], reverse=True)
    _pre_threshold_scored_results = list(scored_results)
    _threshold_rejected_results = [
        (node, score) for node, score in _pre_threshold_scored_results
        if score < min_similarity
    ]

    # Filter by composite score threshold
    scored_results = [
        (node, score) for node, score in _pre_threshold_scored_results
        if score >= min_similarity
    ]

    # Post-threshold FTS rescue:
    # If hybrid search produced candidates but thresholding removed all of them,
    # run the same keyword fallback used for empty hybrid results.
    if not scored_results and _pre_threshold_scored_results:
        _phase_t0 = _time.monotonic()
        fts_rescue = graph.search_fts(clean_query, limit=search_limit, owner_id=owner_id)
        seen_rescue_ids = set()
        for node, fts_rank in fts_rescue:
            if node.id in seen_rescue_ids:
                continue
            seen_rescue_ids.add(node.id)
            quality = max(0.5, 1.0 - fts_rank * 0.02)
            _attrs = node.attributes if isinstance(node.attributes, dict) else {}
            composite = _compute_composite_score(
                node,
                quality,
                config_retrieval,
                intent=intent,
                prefer_fresh=prefer_fresh,
                target_date=target_date,
                temporal_dimension=temporal_dimension,
            )
            if type_boosts and node.type in type_boosts:
                composite = min(composite * type_boosts[node.type], 1.0)
            if boosted_node_factors:
                boost_factor = boosted_node_factors.get(node.id)
                if boost_factor:
                    composite = min(composite * boost_factor, 1.0)
            composite = min(
                composite * _compute_query_fit_multiplier(
                    clean_query,
                    node,
                    _attrs,
                    intent=intent,
                    include_anchor_terms=include_lexical_anchor_shaping,
                    query_anchor_terms=query_anchor_terms,
                    allow_anchor_miss_penalty=allow_anchor_miss_penalty,
                    include_relation_keywords=not use_lightweight_config,
                ),
                1.0,
            )
            if composite >= min_similarity:
                scored_results.append((node, composite))
                if debug and debug_info is not None:
                    debug_info[node.id] = {
                        "raw_quality_score": round(quality, 4),
                        "composite_score": round(composite, 4),
                        "intent": intent,
                        "type_boost": type_boosts.get(node.type, 1.0) if type_boosts else 1.0,
                        "node_type": node.type,
                        "confidence": node.confidence,
                        "access_count": node.access_count,
                        "confirmation_count": node.confirmation_count,
                        "valid_from": node.valid_from,
                        "valid_until": node.valid_until,
                        "fts_rescue": True,
                    }
        if fts_rescue:
            _fts_fallback_used = True
        _phase_ms["fts_fallback_ms"] += round((_time.monotonic() - _phase_t0) * 1000)

    # Deliberate exact-anchor rescue:
    # single-token proper nouns can be present in FTS/LIKE but still miss the
    # small vector candidate cap. Preserve verbatim memory rows before MMR so
    # exact evidence is not displaced by semantically generic entity rows.
    if include_lexical_anchor_shaping and query_anchor_terms and scored_results:
        explicit_anchor_terms = _extract_explicit_query_anchor_terms(clean_query, limit=8)
        verbatim_anchor_terms: List[str] = []
        seen_anchor_terms: set[str] = set()
        for raw_term in list(explicit_anchor_terms) + list(query_anchor_terms or []):
            term = " ".join(str(raw_term or "").split()).strip().lower()
            if not term or term in seen_anchor_terms:
                continue
            if not _text_contains_anchor_term(clean_query, term):
                continue
            seen_anchor_terms.add(term)
            verbatim_anchor_terms.append(term)
            if len(verbatim_anchor_terms) >= 8:
                break

        if verbatim_anchor_terms:
            def _node_matches_verbatim_anchor(node: Node) -> bool:
                searchable = _node_searchable_text(node)
                return any(_text_contains_anchor_term(searchable, term) for term in verbatim_anchor_terms)

            def _is_informative_anchor_node(node: Node) -> bool:
                return str(getattr(node, "type", "") or "").strip().lower() not in {
                    "person",
                    "place",
                    "organization",
                    "entity",
                }

            top_has_exact_memory = any(
                _node_matches_verbatim_anchor(node) and _is_informative_anchor_node(node)
                for node, _score in scored_results[: max(1, limit)]
            )
            if not top_has_exact_memory:
                _phase_t0 = _time.monotonic()
                term_anchor_hits = _search_nodes_by_query_terms(
                    graph,
                    verbatim_anchor_terms,
                    limit=max(search_limit, limit * 4),
                    owner_id=owner_id,
                )
                if use_lightweight_config:
                    fts_anchor_hits = term_anchor_hits
                else:
                    try:
                        fts_anchor_hits = graph.search_fts(
                            clean_query,
                            limit=max(search_limit, limit * 4),
                            owner_id=owner_id,
                        )
                    except Exception as exc:
                        if _is_fail_hard_mode():
                            raise RuntimeError(
                                "FTS exact-anchor rescue failed during recall while failHard is enabled"
                            ) from exc
                        logger.warning("recall FTS exact-anchor rescue failed; continuing without rescue: %s", exc)
                        fts_anchor_hits = []
                    if term_anchor_hits:
                        fts_anchor_hits = list(term_anchor_hits) + list(fts_anchor_hits or [])
                if fts_anchor_hits:
                    scored_by_id: Dict[str, Tuple[Node, float]] = {
                        node.id: (node, score)
                        for node, score in scored_results
                        if getattr(node, "id", None)
                    }
                    passthrough: List[Tuple[Node, float]] = [
                        (node, score)
                        for node, score in scored_results
                        if not getattr(node, "id", None)
                    ]
                    touched = False
                    for node, fts_rank in fts_anchor_hits:
                        if not getattr(node, "id", None) or not _node_matches_verbatim_anchor(node):
                            continue
                        rank = max(1.0, float(fts_rank or 1.0))
                        informative = _is_informative_anchor_node(node)
                        base_score = 0.96 if informative else 0.74
                        rescue_score = min(
                            1.0,
                            max(
                                float(min_similarity or 0.0),
                                base_score + max(0.0, (5.0 - rank) * 0.008),
                            ),
                        )
                        existing = scored_by_id.get(node.id)
                        if existing is None:
                            scored_by_id[node.id] = (node, rescue_score)
                            _lexical_rescue_added += 1
                            touched = True
                        elif rescue_score > float(existing[1]):
                            scored_by_id[node.id] = (node, rescue_score)
                            _lexical_rescue_boosted += 1
                            touched = True
                    if touched:
                        scored_results = list(scored_by_id.values()) + passthrough
                        scored_results.sort(key=lambda x: x[1], reverse=True)
                        _fts_fallback_used = True
                _phase_ms["fts_fallback_ms"] += round((_time.monotonic() - _phase_t0) * 1000)

    # Fast hook lexical rescue:
    # deterministic pre-injection can get "good enough" vector rows for a broad
    # anchor while missing exact lexical details in a fresh pending row. Before returning generic context,
    # cheaply merge FTS hits that cover more query terms. This is DB-local and
    # stays inside existing project/domain/date filters below.
    planner_mode = str(lexical_anchor_planner_mode or "llm").strip().lower()
    if include_lexical_anchor_shaping and planner_mode == "deterministic" and scored_results:
        # Keep the hook path cheap: the full requirement helper consults the
        # relation keyword registry, while this rescue only needs lexical terms.
        query_terms = _extract_distinctive_query_terms(clean_query, limit=8)
        if query_terms:
            min_overlap = 1 if len(query_terms) <= 2 else 2
            best_overlap = max(
                (
                    _query_term_overlap({"text": _node_searchable_text(node)}, query_terms)
                    for node, _score in scored_results
                ),
                default=0,
            )
            existing_query_hits: Set[str] = set()
            for node, _score in scored_results:
                existing_query_hits.update(
                    _query_term_hits({"text": _node_searchable_text(node)}, query_terms)
                )
            missing_query_terms = [
                term for term in query_terms if term not in existing_query_hits
            ]
            missing_query_term_set = set(missing_query_terms)
            best_ratio = best_overlap / max(1, len(query_terms))
            if best_ratio >= 0.75 and best_overlap >= min_overlap:
                boosted_results: List[Tuple[Node, float]] = []
                boosted_existing = 0
                for node, score in scored_results:
                    overlap = _query_term_overlap({"text": _node_searchable_text(node)}, query_terms)
                    if overlap == best_overlap:
                        overlap_ratio = overlap / max(1, len(query_terms))
                        boosted_score = min(0.99, max(float(score), 0.60 + (overlap_ratio * 0.38)))
                        if boosted_score > float(score):
                            boosted_existing += 1
                        boosted_results.append((node, boosted_score))
                    else:
                        boosted_results.append((node, score))
                if boosted_existing:
                    scored_results = boosted_results
                    scored_results.sort(key=lambda x: x[1], reverse=True)
                    _lexical_rescue_boosted += boosted_existing
            if best_ratio < 0.67:
                _phase_t0 = _time.monotonic()
                term_rescue = _search_nodes_by_query_terms(
                    graph,
                    query_terms,
                    limit=max(search_limit, limit * 3),
                    owner_id=owner_id,
                )
                if use_lightweight_config:
                    fts_rescue = term_rescue
                else:
                    try:
                        fts_rescue = graph.search_fts(clean_query, limit=max(search_limit, limit * 3), owner_id=owner_id)
                    except Exception as exc:
                        if _is_fail_hard_mode():
                            raise RuntimeError(
                                "FTS lexical rescue failed during fast recall while failHard is enabled"
                            ) from exc
                        logger.warning("fast recall FTS lexical rescue failed; continuing without rescue: %s", exc)
                        fts_rescue = []
                    if term_rescue:
                        fts_rescue = list(fts_rescue or []) + list(term_rescue)
                if fts_rescue:
                    best_existing_score = max(
                        (float(score) for _node, score in scored_results),
                        default=float(min_similarity or 0.0),
                    )
                    scored_by_id: Dict[str, Tuple[Node, float]] = {
                        node.id: (node, score)
                        for node, score in scored_results
                        if getattr(node, "id", None)
                    }
                    passthrough: List[Tuple[Node, float]] = [
                        (node, score)
                        for node, score in scored_results
                        if not getattr(node, "id", None)
                    ]
                    for node, fts_rank in fts_rescue:
                        query_hits = _query_term_hits({"text": _node_searchable_text(node)}, query_terms)
                        overlap = len(query_hits)
                        covers_missing_terms = bool(query_hits & missing_query_term_set)
                        if overlap < min_overlap:
                            continue
                        if overlap <= best_overlap and not covers_missing_terms:
                            continue
                        rescue_score = _fast_term_rescue_score(
                            overlap=overlap,
                            query_term_count=len(query_terms),
                            rank=float(fts_rank or 0.0),
                            min_similarity=float(min_similarity or 0.0),
                            best_existing_score=best_existing_score,
                            best_existing_overlap=best_overlap,
                        )
                        if covers_missing_terms:
                            rescue_score = max(
                                rescue_score,
                                min(0.98, max(0.90, best_existing_score - 0.01)),
                            )
                        existing = scored_by_id.get(node.id)
                        if existing is None:
                            scored_by_id[node.id] = (node, rescue_score)
                            _lexical_rescue_added += 1
                        elif rescue_score > float(existing[1]):
                            scored_by_id[node.id] = (node, rescue_score)
                            _lexical_rescue_boosted += 1
                    if _lexical_rescue_added or _lexical_rescue_boosted:
                        scored_results = list(scored_by_id.values()) + passthrough
                        scored_results.sort(key=lambda x: x[1], reverse=True)
                        _fts_fallback_used = True
                _phase_ms["fts_fallback_ms"] += round((_time.monotonic() - _phase_t0) * 1000)

        explicit_anchor_terms = _extract_explicit_query_anchor_terms(clean_query, limit=8)
        if explicit_anchor_terms and (
            not use_lightweight_config
            or len(query_terms) <= len(explicit_anchor_terms) + 1
        ):
            def _node_matches_explicit_anchor(node: Node) -> bool:
                lower_text = _node_searchable_text(node).lower()
                return any(term in lower_text for term in explicit_anchor_terms)

            def _node_created_sort_key(node: Node) -> str:
                return str(getattr(node, "created_at", None) or "")

            anchor_scored = [
                (node, score)
                for node, score in scored_results
                if getattr(node, "id", None) and _node_matches_explicit_anchor(node)
            ]
            latest_anchor_created = max(
                (_node_created_sort_key(node) for node, _score in anchor_scored),
                default="",
            )
            best_anchor_score = max(
                (float(score) for _node, score in anchor_scored),
                default=float(min_similarity or 0.0),
            )
            if latest_anchor_created:
                _phase_t0 = _time.monotonic()
                term_anchor_hits = _search_nodes_by_query_terms(
                    graph,
                    explicit_anchor_terms,
                    limit=max(search_limit, limit * 4),
                    owner_id=owner_id,
                )
                if use_lightweight_config:
                    fts_anchor_hits = term_anchor_hits
                else:
                    try:
                        fts_anchor_hits = graph.search_fts(clean_query, limit=max(search_limit, limit * 4), owner_id=owner_id)
                    except Exception as exc:
                        if _is_fail_hard_mode():
                            raise RuntimeError(
                                "FTS fresh-anchor rescue failed during fast recall while failHard is enabled"
                            ) from exc
                        logger.warning("fast recall FTS fresh-anchor rescue failed; continuing without rescue: %s", exc)
                        fts_anchor_hits = []
                    if term_anchor_hits:
                        fts_anchor_hits = list(fts_anchor_hits or []) + list(term_anchor_hits)
                if fts_anchor_hits:
                    scored_by_id: Dict[str, Tuple[Node, float]] = {
                        node.id: (node, score)
                        for node, score in scored_results
                        if getattr(node, "id", None)
                    }
                    passthrough: List[Tuple[Node, float]] = [
                        (node, score)
                        for node, score in scored_results
                        if not getattr(node, "id", None)
                    ]
                    touched = False
                    for node, fts_rank in fts_anchor_hits:
                        if not getattr(node, "id", None) or not _node_matches_explicit_anchor(node):
                            continue
                        created_key = _node_created_sort_key(node)
                        if not created_key or created_key <= latest_anchor_created:
                            continue
                        existing = scored_by_id.get(node.id)
                        rescue_score = min(
                            1.0,
                            max(
                                best_anchor_score,
                                float(min_similarity or 0.0),
                                0.94 + max(0.0, (4.0 - float(fts_rank or 0.0)) * 0.015),
                            ),
                        )
                        if existing is None:
                            scored_by_id[node.id] = (node, rescue_score)
                            _lexical_rescue_added += 1
                            touched = True
                        elif rescue_score > float(existing[1]):
                            scored_by_id[node.id] = (node, rescue_score)
                            _lexical_rescue_boosted += 1
                            touched = True
                    if touched:
                        scored_results = list(scored_by_id.values()) + passthrough
                        scored_results.sort(
                            key=lambda item: (float(item[1]), _node_created_sort_key(item[0])),
                            reverse=True,
                        )
                        _fts_fallback_used = True
                _phase_ms["fts_fallback_ms"] += round((_time.monotonic() - _phase_t0) * 1000)

    # Multi-pass retrieval: if top results are low quality, try broader search
    _multi_pass_gate = 0.70
    if config_retrieval:
        _multi_pass_gate = getattr(config_retrieval, 'multi_pass_gate', 0.70)
    if use_multi_pass and scored_results and scored_results[0][1] < _multi_pass_gate and len(scored_results) < limit:
        _multi_pass_triggered = True
        _phase_t0 = _time.monotonic()
        # Extract entity names from query for targeted second pass
        entity_terms = [w for w in clean_query.split() if w[0:1].isupper() and len(w) > 2]
        # Also try individual key terms
        key_terms = _lib_extract_key_tokens(clean_query)

        second_pass_queries = []
        if entity_terms:
            second_pass_queries.append(" ".join(entity_terms))
        if key_terms and key_terms != [clean_query]:
            second_pass_queries.append(" ".join(key_terms[:5]))

        existing_ids = {node.id for node, _ in scored_results}
        for sq in second_pass_queries:
            if sq.strip() and sq.strip() != search_query.strip():
                try:
                    extra = graph.search_hybrid(
                        sq,
                        limit=limit * 2,
                        privacy=privacy,
                        owner_id=owner_id,
                        current_session_id=current_session_id,
                        compaction_time=compaction_time,
                        intent=intent,
                        timeout_seconds=search_timeout_s,
                    )
                    for node, quality_score in extra:
                        if node.id not in existing_ids:
                            _extra_attrs = node.attributes if isinstance(node.attributes, dict) else {}
                            composite = _compute_composite_score(
                                node,
                                quality_score,
                                config_retrieval,
                                intent=intent,
                                prefer_fresh=prefer_fresh,
                                target_date=target_date,
                                temporal_dimension=temporal_dimension,
                            )
                            if type_boosts and node.type in type_boosts:
                                composite = min(composite * type_boosts[node.type], 1.0)
                            if boosted_node_factors:
                                boost_factor = boosted_node_factors.get(node.id)
                                if boost_factor:
                                    composite = min(composite * boost_factor, 1.0)
                            composite = min(
                                composite * _compute_query_fit_multiplier(
                                    clean_query,
                                    node,
                                    _extra_attrs,
                                    intent=intent,
                                    include_anchor_terms=include_lexical_anchor_shaping,
                                    query_anchor_terms=query_anchor_terms,
                                    allow_anchor_miss_penalty=allow_anchor_miss_penalty,
                                    include_relation_keywords=not use_lightweight_config,
                                ),
                                1.0,
                            )
                            if composite >= min_similarity:
                                scored_results.append((node, composite))
                                existing_ids.add(node.id)
                                _multi_pass_ids.add(node.id)
                                if debug and debug_info is not None:
                                    debug_info[node.id] = {
                                        "raw_quality_score": round(quality_score, 4),
                                        "composite_score": round(composite, 4),
                                        "intent": intent,
                                        "type_boost": 1.0,
                                        "node_type": node.type,
                                        "confidence": node.confidence,
                                        "access_count": node.access_count,
                                        "confirmation_count": node.confirmation_count,
                                        "valid_from": node.valid_from,
                                        "valid_until": node.valid_until,
                                        "multi_pass": True,
                                    }
                except Exception:
                    pass  # Second pass is best-effort

        # Re-sort after adding second-pass results
        scored_results.sort(key=lambda x: x[1], reverse=True)
        _phase_ms["multi_pass_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Filter by minimum similarity before MMR (first-pass results were unfiltered)
    scored_results = [(node, score) for node, score in scored_results if score >= min_similarity]

    # Apply temporal constraints before candidate capping/MMR. Otherwise later
    # high-similarity facts can fill the top-K candidate set and then get
    # filtered out, leaving older in-range facts unreachable.
    if date_from or date_to:
        def _node_in_date_range(node: Node) -> bool:
            start_date, end_date, _basis = _node_temporal_bounds(
                node,
                temporal_dimension=temporal_dimension,
            )
            return _date_bounds_overlap_filter(
                start_date,
                end_date,
                date_from=date_from,
                date_to=date_to,
            )
        scored_results = [
            (node, score)
            for node, score in scored_results
            if _node_in_date_range(node)
        ]
        scored_results = _apply_open_ended_asof_temporal_rerank(
            scored_results,
            date_from=date_from,
            date_to=date_to,
            temporal_dimension=temporal_dimension,
        )

    scored_results = _apply_relative_temporal_freshness_rerank(
        scored_results,
        freshness_preferred=prefer_fresh and not (date_to and not date_from),
        target_date=target_date,
        temporal_dimension=temporal_dimension,
    )

    scored_results = _prefer_user_provenance_for_full_fit_rows(
        scored_results,
        clean_query,
        intent=intent,
    )

    # Apply MMR diversity (select diverse top-N from candidates)
    _mmr_lambda, _mmr_candidate_cap = _resolve_mmr_settings(
        config_retrieval,
        limit=limit,
        default_candidate_cap=max(limit * 4, 12),
    )
    _mmr_input_candidates = len(scored_results)
    if include_mmr:
        if len(scored_results) > _mmr_candidate_cap:
            scored_results = scored_results[:_mmr_candidate_cap]
        _phase_t0 = _time.monotonic()
        diverse_results = _apply_mmr(scored_results, graph, limit, mmr_lambda=_mmr_lambda)
        _phase_ms["mmr_ms"] = round((_time.monotonic() - _phase_t0) * 1000)
    else:
        diverse_results = scored_results[:limit]
        _phase_ms["mmr_ms"] = 0

    output = []
    seen_ids = set()

    for node, score in diverse_results:
        seen_ids.add(node.id)
        _attrs = node.attributes if isinstance(node.attributes, dict) else {}
        result_dict = {
            "text": _sanitize_for_context(node.name),
            "category": node.type.lower(),
            "similarity": round(score, 3),
            "verified": node.verified,
            "pinned": node.pinned,
            "id": node.id,
            "extraction_confidence": node.extraction_confidence,
            **_node_recall_temporal_fields(node),
            "source_id": node.source_id,
            "source_chunk_id": node.source_chunk_id,
            "privacy": node.privacy,
            "owner_id": node.owner_id,
            "_multi_pass": node.id in _multi_pass_ids,
            "domains": _domains_from_attrs(_attrs),
            "source_type": _attrs.get("source_type"),
            "structural_anchor_kind": _attrs.get("structural_anchor_kind"),
            "keywords": getattr(node, "keywords", None),
            "project": _attrs.get("project"),
            "source_channel": _attrs.get("source_channel"),
            "source_conversation_id": _attrs.get("source_conversation_id"),
            "source_author_id": _attrs.get("source_author_id"),
            "actor_id": _attrs.get("actor_id"),
            "speaker_entity_id": _attrs.get("speaker_entity_id", node.speaker_entity_id),
            "subject_entity_id": _attrs.get("subject_entity_id"),
            "conversation_id": _attrs.get("conversation_id", node.conversation_id),
            "visibility_scope": _attrs.get("visibility_scope", node.visibility_scope),
            "sensitivity": _attrs.get("sensitivity", node.sensitivity),
            "provenance_confidence": _attrs.get("provenance_confidence", node.provenance_confidence),
            "participant_entity_ids": _attrs.get("participant_entity_ids"),
        }
        if debug and debug_info and node.id in debug_info:
            result_dict["_debug"] = debug_info[node.id]
        output.append(result_dict)

    # Temporal contiguity: facts from the same session were co-encoded
    # and likely share context — surface them as bonus candidates
    if diverse_results and include_co_session:
        _phase_t0 = _time.monotonic()
        session_ids = {}
        for node, score in diverse_results[:5]:
            if node.session_id and node.session_id not in session_ids:
                session_ids[node.session_id] = score
        # A bounded wider pool fixes arbitrary LIMIT-order misses while keeping
        # same-session fanout cheap on broad recall queries.
        co_session_candidate_limit = max(5, min(50, limit * 4))
        query_embedding = None
        for sid, anchor_score in session_ids.items():
            try:
                with graph._get_conn() as conn:
                    if seen_ids:
                        exclude_clause = "AND id NOT IN ({})".format(",".join("?" for _ in seen_ids))
                        params = [sid] + list(seen_ids)
                    else:
                        exclude_clause = ""
                        params = [sid]
                    params.append(co_session_candidate_limit)
                    rows = conn.execute(
                        "SELECT * FROM nodes WHERE session_id = ? AND status IN ('active', 'approved', 'pending') {} LIMIT ?".format(
                            exclude_clause
                        ),
                        params
                    ).fetchall()
                    if rows and query_embedding is None:
                        try:
                            query_embedding = graph.get_embedding(clean_query)
                        except Exception:
                            query_embedding = None
                    co_candidates = []
                    for row in rows:
                        co_node = graph._row_to_node(row)
                        if co_node.id not in seen_ids and (not owner_id or co_node.owner_id == owner_id):
                            if date_from or date_to:
                                start_date, end_date, _basis = _node_temporal_bounds(
                                    co_node,
                                    temporal_dimension=temporal_dimension,
                                )
                                if not _date_bounds_overlap_filter(
                                    start_date,
                                    end_date,
                                    date_from=date_from,
                                    date_to=date_to,
                                ):
                                    continue
                            co_attrs = co_node.attributes if isinstance(co_node.attributes, dict) else {}
                            semantic_score = 0.4
                            if query_embedding and co_node.embedding:
                                try:
                                    semantic_score = max(0.0, graph.cosine_similarity(query_embedding, co_node.embedding))
                                except Exception:
                                    semantic_score = 0.4
                            rank_score = _compute_composite_score(
                                co_node,
                                semantic_score,
                                config_retrieval,
                                intent=intent,
                                prefer_fresh=prefer_fresh,
                                target_date=target_date,
                                temporal_dimension=temporal_dimension,
                            )
                            rank_score = min(
                                rank_score * _compute_query_fit_multiplier(
                                    clean_query,
                                    co_node,
                                    co_attrs,
                                    intent=intent,
                                    include_anchor_terms=True,
                                    query_anchor_terms=query_anchor_terms,
                                    # Keep exact-anchor boosts, but never apply
                                    # the stricter anchor-miss penalty to
                                    # same-session expansion candidates.
                                    allow_anchor_miss_penalty=False,
                                    include_relation_keywords=not use_lightweight_config,
                                ),
                                1.0,
                            )
                            co_candidates.append((co_node, co_attrs, rank_score))
                    co_candidates.sort(key=lambda item: item[2], reverse=True)
                    for co_node, _co_attrs, rank_score in co_candidates[:5]:
                        if co_node.id not in seen_ids:
                            seen_ids.add(co_node.id)
                            # Co-encoded facts inherit some anchor confidence, but
                            # relevance-ranked same-session rows can still survive.
                            _co_decay = 0.6
                            if config_retrieval:
                                _co_decay = getattr(config_retrieval, 'co_session_decay', 0.6)
                            # A strong same-session match should be allowed to
                            # clear the expansion threshold; decay still keeps
                            # the serialized score below its own direct rank.
                            # min() was tried in 47e6c0950; r1387 regressed q1.
                            co_score = max(anchor_score, rank_score) * _co_decay
                            # Use a lower threshold for co-session facts (75% of min_similarity)
                            co_threshold = min_similarity * 0.75
                            if co_score >= co_threshold:
                                _co_session_added += 1
                                output.append({
                                    "text": _sanitize_for_context(co_node.name),
                                    "category": co_node.type.lower(),
                                    "similarity": round(co_score, 3),
                                    "verified": co_node.verified,
                                    "pinned": co_node.pinned,
                                    "id": co_node.id,
                                    "via_relation": "co_session",
                                    "hop_depth": 0,
                                    **_node_recall_temporal_fields(co_node),
                                    "domains": _domains_from_attrs(_co_attrs),
                                    "source_type": _co_attrs.get("source_type"),
                                    "project": _co_attrs.get("project"),
                                })
            except Exception:
                pass  # Temporal contiguity is best-effort
        _phase_ms["co_session_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Add related nodes via multi-hop graph traversal
    # Uses BEAM search (scored, pruned) or BFS (exhaustive) based on config
    if diverse_results and include_graph_traversal:
        _phase_t0 = _time.monotonic()
        _use_beam = True  # Default matches TraversalConfig.use_beam
        _beam_width = 5
        _traversal_depth = 2
        _hop_decay_factor = 0.7
        if config_retrieval:
            trav = getattr(config_retrieval, 'traversal', None)
            if trav:
                _use_beam = getattr(trav, 'use_beam', True)
                _beam_width = getattr(trav, 'beam_width', 5)
                _traversal_depth = getattr(trav, 'max_depth', 2)
                _hop_decay_factor = getattr(trav, 'hop_decay', 0.7)
            else:
                _use_beam = True  # Default to BEAM

        for node, score in diverse_results[:3]:  # Only traverse top 3
            if _use_beam:
                try:
                    related = graph.beam_search_graph(
                        query=clean_query,
                        start_id=node.id,
                        beam_width=_beam_width,
                        max_depth=_traversal_depth,
                        max_results=10,
                        intent=intent,
                        type_boosts=type_boosts,
                        hop_decay=_hop_decay_factor,
                        config_retrieval=config_retrieval,
                    )
                except Exception:
                    # BEAM failed — fall back to BFS for this node
                    related = []
                    try:
                        bfs_related = graph.get_related_bidirectional(
                            node.id, depth=_traversal_depth, max_results=10
                        )
                        for rel_node, relation, direction, hop_depth, path in bfs_related:
                            hop_decay = _hop_decay_factor ** hop_depth
                            related.append((rel_node, relation, direction, hop_depth, path, hop_decay))
                    except Exception:
                        pass  # Best-effort graph traversal
                for rel_node, relation, direction, hop_depth, path, beam_score in related:
                    if rel_node.id not in seen_ids:
                        seen_ids.add(rel_node.id)
                        _graph_discoveries += 1
                        rel_score = score * beam_score
                        if rel_score < min_similarity:
                            continue

                        graph_path = _render_bidirectional_graph_path(
                            node.name,
                            rel_node.name,
                            relation,
                            direction,
                            path,
                        )
                        graph_text = _render_bidirectional_graph_text(
                            node.name,
                            rel_node.name,
                            relation,
                            direction,
                        )

                        _rel_attrs = rel_node.attributes if isinstance(rel_node.attributes, dict) else {}
                        output.append({
                            "text": _sanitize_for_context(graph_text),
                            "category": rel_node.type.lower(),
                            "similarity": round(rel_score, 3),
                            "verified": rel_node.verified,
                            "pinned": rel_node.pinned,
                            "id": rel_node.id,
                            "via_relation": relation,
                            "hop_depth": hop_depth,
                            "graph_path": graph_path,
                            "_multi_pass": rel_node.id in _multi_pass_ids,
                            **_node_recall_temporal_fields(rel_node),
                            "domains": _domains_from_attrs(_rel_attrs),
                            "project": _rel_attrs.get("project"),
                        })
            else:
                # BFS fallback
                related = graph.get_related_bidirectional(
                    node.id, depth=_traversal_depth, max_results=10
                )
                for rel_node, relation, direction, hop_depth, path in related:
                    if rel_node.id not in seen_ids:
                        seen_ids.add(rel_node.id)
                        _graph_discoveries += 1
                        hop_decay = _hop_decay_factor ** hop_depth
                        rel_score = score * hop_decay
                        if rel_score < min_similarity:
                            continue

                        graph_path = _render_bidirectional_graph_path(
                            node.name,
                            rel_node.name,
                            relation,
                            direction,
                            path,
                        )
                        graph_text = _render_bidirectional_graph_text(
                            node.name,
                            rel_node.name,
                            relation,
                            direction,
                        )

                        _rel_attrs = rel_node.attributes if isinstance(rel_node.attributes, dict) else {}
                        output.append({
                            "text": _sanitize_for_context(graph_text),
                            "category": rel_node.type.lower(),
                            "similarity": round(rel_score, 3),
                            "verified": rel_node.verified,
                            "pinned": rel_node.pinned,
                            "id": rel_node.id,
                            "via_relation": relation,
                            "hop_depth": hop_depth,
                            "graph_path": graph_path,
                            "_multi_pass": rel_node.id in _multi_pass_ids,
                            **_node_recall_temporal_fields(rel_node),
                            "domains": _domains_from_attrs(_rel_attrs),
                            "project": _rel_attrs.get("project"),
                        })
        _phase_ms["graph_traversal_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    _phase_t0 = _time.monotonic()
    def _enforce_selected_domain_scope(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if include_all_domains:
            return rows
        if not included_domains:
            # Explicit {"all": false} with no selected domains means return nothing.
            return []
        try:
            with graph._get_conn() as conn:
                placeholders = ",".join("?" for _ in included_domains)
                lookup_rows = conn.execute(
                    f"SELECT DISTINCT node_id FROM node_domains WHERE domain IN ({placeholders})",
                    list(included_domains),
                ).fetchall()
                allowed_ids = {r[0] for r in lookup_rows}
            return [
                r for r in rows
                if (
                    r.get("id") in allowed_ids
                    or bool(set(_domains_from_attrs({"domains": r.get("domains")})) & included_domains)
                    or (
                        include_unscoped
                        and not _domains_from_attrs({"domains": r.get("domains")})
                    )
                )
            ]
        except Exception as exc:
            logger.warning("Domain filter join table unavailable; falling back to row attributes: %s", exc)
            if _is_fail_hard_mode():
                raise
            return [
                r for r in rows
                if (
                    bool(set(_domains_from_attrs({"domains": r.get("domains")})) & included_domains)
                    or (
                        include_unscoped
                        and not _domains_from_attrs({"domains": r.get("domains")})
                    )
                )
            ]

    if not include_all_domains:
        if included_domains:
            # Primary path: use indexed node_domains lookup for domain filtering.
            try:
                with graph._get_conn() as conn:
                    placeholders = ",".join("?" for _ in included_domains)
                    rows = conn.execute(
                        f"SELECT DISTINCT node_id FROM node_domains WHERE domain IN ({placeholders})",
                        list(included_domains),
                    ).fetchall()
                    allowed_ids = {r[0] for r in rows}
                output = [
                    r for r in output
                    if (
                        r.get("id") in allowed_ids
                        or bool(set(_domains_from_attrs({"domains": r.get("domains")})) & included_domains)
                        or (
                            include_unscoped
                            and not _domains_from_attrs({"domains": r.get("domains")})
                        )
                    )
                ]
            except Exception as exc:
                logger.warning("Domain filter join table unavailable; falling back to row attributes: %s", exc)
                if _is_fail_hard_mode():
                    raise
                # Fallback to attribute-based filtering if join table is unavailable.
                output = [
                    r for r in output
                    if (
                        bool(set(_domains_from_attrs({"domains": r.get("domains")})) & included_domains)
                        or (
                            include_unscoped
                            and not _domains_from_attrs({"domains": r.get("domains")})
                        )
                    )
                ]
        else:
            # Explicit {"all": false} with no selected domains means return nothing.
            output = []

    # Enforce strict selected-domain scope even if upstream filters allowed
    # unscoped rows; explicit domain selections must not leak unrelated rows.
    output = _enforce_selected_domain_scope(output)

    if requested_project:
        output = [
            r for r in output
            if _normalize_project_tag(r.get("project")) == requested_project
        ]

    # Defense-in-depth for rows injected after the primary pre-MMR temporal
    # filter, including co-session and graph traversal expansions.
    if date_from or date_to:
        def _in_date_range(r: Dict[str, Any]) -> bool:
            start_date, end_date, _basis = _row_temporal_bounds(
                r,
                temporal_dimension=temporal_dimension,
            )
            return _date_bounds_overlap_filter(
                start_date,
                end_date,
                date_from=date_from,
                date_to=date_to,
            )
        output = [r for r in output if _in_date_range(r)]

    anchor_expansion_mode = "cheap" if not include_graph_traversal else "rich"
    max_anchor_count = 1 if anchor_expansion_mode == "cheap" else 2
    expansion_limit_per_anchor = 1 if anchor_expansion_mode == "cheap" else 2
    anchor_rows, anchor_expansions = _expand_high_confidence_entity_anchors(
        graph,
        clean_query,
        output,
        intent=intent,
        limit=limit,
        expansion_mode=anchor_expansion_mode,
        max_anchor_count=max_anchor_count,
        expansion_limit_per_anchor=expansion_limit_per_anchor,
    )
    anchor_ids = {
        str(row.get("id") or "").strip()
        for row in anchor_rows
        if str(row.get("id") or "").strip()
    }

    # Hide low-information standalone entity nodes (e.g., single names) when
    # we have more informative factual/relational results. Keep as fallback,
    # but preserve any top-K node we decided to expand into a dedicated graph
    # anchor block.
    low_info = [r for r in output if _is_low_information_entity_result(r)]
    informative = [r for r in output if not _is_low_information_entity_result(r)]
    preserved_low_info = [
        r for r in low_info
        if (
            _should_preserve_low_information_entity_result(r, clean_query, intent=intent)
            or str(r.get("id") or "").strip() in anchor_ids
        )
    ]
    if informative:
        output = informative + preserved_low_info
    else:
        output = low_info

    if anchor_expansions:
        output.extend(anchor_expansions)
        # Anchor expansion can surface rows outside selected domain scope.
        output = _enforce_selected_domain_scope(output)
        if requested_project:
            output = [
                r for r in output
                if _normalize_project_tag(r.get("project")) == requested_project
            ]
        if date_from or date_to:
            def _anchor_in_date_range(r: Dict[str, Any]) -> bool:
                start_date, end_date, _basis = _row_temporal_bounds(
                    r,
                    temporal_dimension=temporal_dimension,
                )
                return _date_bounds_overlap_filter(
                    start_date,
                    end_date,
                    date_from=date_from,
                    date_to=date_to,
                )
            output = [r for r in output if _anchor_in_date_range(r)]

    # Sort by similarity and limit
    scope_filters = {
        "source_channel": source_channel,
        "source_conversation_id": source_conversation_id,
        "source_author_id": source_author_id,
        "actor_id": actor_id,
        "subject_entity_id": subject_entity_id,
    }
    active_scope_filters = {k: v for k, v in scope_filters.items() if v not in (None, "")}
    if active_scope_filters:
        filtered_output = []
        for row in output:
            is_unscoped = all(row.get(k) in (None, "") for k in active_scope_filters.keys())
            if is_unscoped and include_unscoped:
                filtered_output.append(row)
                continue

            matched = True
            for key, expected in active_scope_filters.items():
                actual = row.get(key)
                if actual in (None, ""):
                    matched = False
                    break
                if str(actual) != str(expected):
                    matched = False
                    break
            if matched:
                filtered_output.append(row)
        output = filtered_output

    if participant_entity_ids:
        requested = {str(p).strip() for p in participant_entity_ids if str(p).strip()}
        if requested:
            participant_filtered = []
            for row in output:
                row_participants = row.get("participant_entity_ids")
                if not isinstance(row_participants, list):
                    if include_unscoped:
                        participant_filtered.append(row)
                    continue
                row_set = {str(p).strip() for p in row_participants if str(p).strip()}
                if row_set & requested:
                    participant_filtered.append(row)
            output = participant_filtered

    output = _enforce_recall_rows_temporal_axis_validity(
        output,
        temporal_dimension=temporal_dimension,
    )
    output = _sort_recall_rows_for_final_selection(
        output,
        date_from=date_from,
        date_to=date_to,
        temporal_dimension=temporal_dimension,
    )
    final_output = _select_final_recall_rows(
        output,
        limit=limit,
        anchor_rows=anchor_rows,
        expansion_limit_per_anchor=expansion_limit_per_anchor,
    )
    final_output = _prioritize_named_entity_activity_anchor_rows(query, final_output)
    if include_lexical_anchor_shaping:
        final_output = _prioritize_fast_anchor_direct_rows(query, final_output)
    _phase_ms["filtering_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Update access stats for returned results (feeds into Ebbinghaus decay)
    if final_output and track_access:
        _phase_t0 = _time.monotonic()
        try:
            result_ids = {r["id"] for r in final_output}
            # Track access for both direct search results and graph-traversal results
            result_nodes = [(node, score) for node, score in diverse_results
                            if node.id in result_ids]
            # Also track graph-traversal nodes by looking them up
            tracked_ids = {node.id for node, _ in result_nodes}
            for r in final_output:
                if r["id"] not in tracked_ids and r.get("via_relation"):
                    node = graph.get_node(r["id"])
                    if node:
                        result_nodes.append((node, r["similarity"]))
            # Build retrieval difficulty map for storage strength updates (Bjork model)
            difficulty_map = {r["id"]: _compute_retrieval_difficulty(r) for r in final_output}
            graph._update_access(result_nodes, difficulty_map=difficulty_map)
        except Exception:
            pass  # Access tracking is best-effort
        _phase_ms["access_update_ms"] = round((_time.monotonic() - _phase_t0) * 1000)

    # Log recall metrics for observability
    _recall_elapsed_ms = int((_time.monotonic() - _recall_start) * 1000)
    _phase_ms["total_ms"] = _recall_elapsed_ms
    _similarities = [r["similarity"] for r in final_output]
    _log_recall(
        graph, query, owner_id, intent,
        results_count=len(final_output),
        avg_similarity=sum(_similarities) / len(_similarities) if _similarities else 0.0,
        top_similarity=max(_similarities) if _similarities else 0.0,
        multi_pass_triggered=_multi_pass_triggered,
        fts_fallback_used=_fts_fallback_used,
        reranker_used=reranker_enabled,
        reranker_changes=_reranker_changes,
        reranker_top1_changed=_reranker_top1_changed,
        reranker_avg_displacement=_reranker_avg_displacement,
        graph_discoveries=_graph_discoveries,
        latency_ms=_recall_elapsed_ms,
    )

    # Low-signal retry: if first pass produced no useful results, retry once with
    # an intent-shaped expanded query. This logic lives in datastore recall so it
    # applies consistently across interfaces, not in harnesses.
    recall_once_meta = {
        "query": query,
        "clean_query": clean_query,
        "search_query": search_query,
        "intent": intent,
        "phases_ms": _phase_ms,
        "counts": {
            "initial_candidates": len(results),
            "post_threshold_candidates": len(scored_results),
            "mmr_input_candidates": _mmr_input_candidates,
            "mmr_cap": _mmr_candidate_cap,
            "diverse_results": len(diverse_results),
            "co_session_added": _co_session_added,
            "graph_discoveries": _graph_discoveries,
            "lexical_rescue_added": _lexical_rescue_added,
            "lexical_rescue_boosted": _lexical_rescue_boosted,
            "final_results": len(final_output),
        },
        "flags": {
            "fts_fallback_used": _fts_fallback_used,
            "fast_lexical_preflight_used": _fast_lexical_preflight_used,
            "lexical_rescue_used": bool(_lexical_rescue_added or _lexical_rescue_boosted),
            "multi_pass_triggered": _multi_pass_triggered,
            "reranker_enabled": reranker_enabled,
            "mmr_enabled": include_mmr,
            "used_hyde": bool(_ollama_up and use_routing and _HAS_LLM_CLIENTS),
        },
        "lexical_anchor": dict(lexical_anchor_meta),
    }
    if _recall_telemetry_enabled():
        recall_once_meta["telemetry"] = {
            "inputs": {
                "limit": limit,
                "min_similarity": min_similarity,
                "privacy": list(privacy or []),
                "owner_id": owner_id,
                "project": requested_project,
                "date_from": date_from,
                "date_to": date_to,
                "temporal_dimension": temporal_dimension,
                "use_routing": bool(use_routing),
                "use_multi_pass": bool(use_multi_pass),
                "include_graph_traversal": bool(include_graph_traversal),
                "include_co_session": bool(include_co_session),
                "include_mmr": bool(include_mmr),
            },
            "filters": {
                "include_all_domains": include_all_domains,
                "included_domains": sorted(included_domains),
                "boosted_domains": dict(boosted_domains),
                "boosted_node_hits": len(boosted_node_factors),
                "prefer_fresh": prefer_fresh,
                "ollama_healthy": bool(_ollama_up),
                "threshold_basis": "composite_score",
                "lexical_anchor": {
                    "used_llm": bool(lexical_anchor_meta.get("used_llm")),
                    "anchor_count": int(lexical_anchor_meta.get("anchor_count") or 0),
                    "elapsed_ms": int(lexical_anchor_meta.get("elapsed_ms") or 0),
                    "bailout_reason": lexical_anchor_meta.get("bailout_reason"),
                    "source": lexical_anchor_meta.get("source"),
                },
            },
            "samples": {
                "initial_candidates": _sample_candidate_tuples(results, limit=8),
                "pre_threshold_candidates": _sample_candidate_tuples(
                    _pre_threshold_scored_results,
                    debug_info=debug_info,
                    limit=8,
                    threshold=min_similarity,
                ),
                "threshold_rejected": _sample_candidate_tuples(
                    _threshold_rejected_results,
                    debug_info=debug_info,
                    limit=8,
                    threshold=min_similarity,
                ),
                "graph_seed_candidates": _sample_candidate_tuples(
                    diverse_results,
                    debug_info=debug_info,
                    limit=3,
                    threshold=min_similarity,
                ),
                "graph_results": _sample_recall_rows(
                    [row for row in final_output if row.get("via_relation")],
                    limit=5,
                ),
                "final_results": _sample_recall_rows(final_output, limit=5),
            },
        }
        _append_recall_telemetry_trace(recall_once_meta)

    if low_signal_retry:
        low_info_count = sum(1 for r in final_output if _is_low_information_entity_result(r))
        low_signal = (len(final_output) == 0) or (
            len(final_output) <= max(1, limit // 3) and low_info_count == len(final_output)
        )
        if low_signal:
            retry_query = _expand_low_signal_query(clean_query, intent)
            if retry_query and retry_query != clean_query:
                try:
                    retry_output, retry_meta = _recall_once(
                        retry_query,
                        limit=limit,
                        privacy=privacy,
                        owner_id=owner_id,
                        min_similarity=min_similarity,
                        use_routing=use_routing,
                        use_aliases=use_aliases,
                        use_intent=use_intent,
                        use_multi_pass=use_multi_pass,
                        use_reranker=use_reranker,
                        include_graph_traversal=include_graph_traversal,
                        include_co_session=include_co_session,
                        include_mmr=include_mmr,
                        include_lexical_anchor_shaping=include_lexical_anchor_shaping,
                        lexical_anchor_planner_mode=lexical_anchor_planner_mode,
                        current_session_id=current_session_id,
                        compaction_time=compaction_time,
                        date_from=date_from,
                        date_to=date_to,
                        temporal_dimension=temporal_dimension,
                        debug=False,
                        domain=domain,
                        domain_boost=domain_boost,
                        low_signal_retry=False,
                        include_chunks=include_chunks,
                        max_chunk_tokens=max_chunk_tokens,
                        max_total_chunk_tokens=max_total_chunk_tokens,
                        return_meta=True,
                    )
                    if len(retry_output) > len(final_output):
                        retry_meta = dict(retry_meta or {})
                        retry_meta["retry_from_low_signal"] = True
                        return _return_validated_recall(
                            retry_output,
                            retry_meta,
                            return_meta,
                            include_chunks=include_chunks,
                            preserve_source_chunk_ids=preserve_source_chunk_ids,
                            max_chunk_tokens=max_chunk_tokens,
                            max_total_chunk_tokens=max_total_chunk_tokens,
                        )
                except Exception as exc:
                    logger.warning("low-signal recall retry failed: %s", exc)

    return _return_validated_recall(
        final_output,
        recall_once_meta,
        return_meta,
        include_chunks=include_chunks,
        preserve_source_chunk_ids=preserve_source_chunk_ids,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )


def _plan_recall_queries(query: str, max_queries: int = 3) -> List[str]:
    """Plan focused recall sub-queries from the original query.

    Best-effort: if planner LLM is unavailable or fails, return the original query.
    """
    clean_query = " ".join((query or "").split())
    if not clean_query:
        return []
    if len(clean_query) < 10:
        return [clean_query]
    if not _HAS_LLM_CLIENTS:
        return [clean_query]

    prompt = (
        "Generate focused memory-retrieval sub-queries for the user question.\n"
        "Rules:\n"
        "- Return JSON only: {\"queries\": [\"...\"]}\n"
        "- Keep original entities, names, dates, and projects.\n"
        "- Do not invent new facts.\n"
        "- Include 1 broad query and up to 2 focused query variants.\n\n"
        f"Question: {clean_query}"
    )

    try:
        result, _ = call_fast_reasoning(
            prompt=prompt,
            max_tokens=200,
            timeout=6.0,
            system_prompt=(
                "You output compact JSON for retrieval planning. "
                "No prose."
            ),
            max_retries=0,
        )
        parsed = parse_json_response(result)
        queries = parsed.get("queries") if isinstance(parsed, dict) else None
        if not isinstance(queries, list):
            return [clean_query]

        out: List[str] = []
        seen = set()
        for raw in queries:
            q = " ".join(str(raw or "").split())
            if not q:
                continue
            key = q.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(q)
            if len(out) >= max(1, max_queries):
                break
        if clean_query.lower() not in {q.lower() for q in out}:
            out.insert(0, clean_query)
        return out or [clean_query]
    except Exception:
        return [clean_query]


def _is_low_information_message(query: str) -> bool:
    """Return True when a message is too low-information to justify retrieval."""
    clean = " ".join((query or "").strip().lower().split())
    if not clean:
        return True
    if not any(ch.isalnum() for ch in clean):
        return True
    if clean.isascii() and len(clean) <= 3:
        return True
    return False


_GRAPH_RECALL_METADATA_KEYS = (
    "via",
    "via_relation",
    "graph_path",
    "graph_relation_sequence",
    "graph_relation_groups",
    "graph_discovery_kind",
    "source_name",
    "hop_depth",
    "depth",
    "direction",
    "relation",
    "_graph_anchor_expansion",
    "anchor_id",
    "anchor_text",
    "anchor_similarity",
    "anchor_category",
)


def _graph_metadata_richness(row: Dict[str, Any]) -> Tuple[int, int, int, int]:
    if not isinstance(row, dict) or not _has_structured_graph_discovery(row):
        return (0, 0, 0, 0)
    sequence = row.get("graph_relation_sequence")
    if isinstance(sequence, list):
        relation_count = sum(1 for item in sequence if str(item or "").strip())
    else:
        relation_count = 0
    path_len = len(str(row.get("graph_path") or "").strip())
    fact_bonus = 1 if str(row.get("via") or "") == "graph_attached_fact" else 0
    try:
        hop_depth = int(row.get("hop_depth") or row.get("depth") or 0)
    except Exception:
        hop_depth = 0
    return (relation_count, fact_bonus, hop_depth, path_len)


def _merge_recall_row_variants(preferred: Dict[str, Any], alternate: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(preferred)
    if alternate.get("_facet_rescue") and not merged.get("_facet_rescue"):
        # The same memory can arrive through vector/session branches and facet
        # rescue. Keep the stronger score/text from the preferred variant, but
        # preserve rescue provenance so final selection can reserve exact facts.
        merged["_facet_rescue"] = True
        if alternate.get("via"):
            merged["via"] = alternate.get("via")
    if merged.get("_debug") is None and isinstance(alternate.get("_debug"), dict):
        merged["_debug"] = dict(alternate["_debug"])
    if not _has_structured_graph_discovery(merged) and _has_structured_graph_discovery(alternate):
        for key in _GRAPH_RECALL_METADATA_KEYS:
            if alternate.get(key) is not None:
                merged[key] = alternate.get(key)
    elif _has_structured_graph_discovery(merged) and _has_structured_graph_discovery(alternate):
        if _graph_metadata_richness(alternate) > _graph_metadata_richness(merged):
            for key in _GRAPH_RECALL_METADATA_KEYS:
                if alternate.get(key) is not None:
                    merged[key] = alternate.get(key)
    else:
        for key in _GRAPH_RECALL_METADATA_KEYS:
            if merged.get(key) is None and alternate.get(key) is not None:
                merged[key] = alternate.get(key)
    if isinstance(merged.get("_debug"), dict):
        debug_payload = dict(merged["_debug"])
        try:
            debug_payload["composite_score"] = round(float(merged.get("similarity", 0.0)), 4)
        except (TypeError, ValueError):
            pass
        merged["_debug"] = debug_payload
    return merged


def _merge_recall_batches(batches: List[List[Dict[str, Any]]], limit: int) -> List[Dict[str, Any]]:
    """Merge recall batches by memory id, keeping highest similarity variant."""

    by_id: Dict[str, Dict[str, Any]] = {}
    fallback_rows: List[Dict[str, Any]] = []
    for batch in batches:
        for row in batch or []:
            if not isinstance(row, dict):
                continue
            rid = str(row.get("id") or "").strip()
            if not rid:
                fallback_rows.append(row)
                continue
            prev = by_id.get(rid)
            if prev is None:
                by_id[rid] = row
                continue
            if float(row.get("similarity", 0.0)) > float(prev.get("similarity", 0.0)):
                by_id[rid] = _merge_recall_row_variants(row, prev)
            else:
                by_id[rid] = _merge_recall_row_variants(prev, row)

    merged = list(by_id.values()) + fallback_rows
    merged.sort(key=lambda x: float(x.get("similarity", 0.0)), reverse=True)
    return merged[: max(1, limit)]


def _rrf_recall_row_identity(row: Dict[str, Any]) -> str:
    source_type = str(row.get("source_type") or row.get("category") or "").strip().lower()
    if source_type in {"source_chunk", "session_chunk"}:
        chunk_id = str(row.get("chunk_id") or row.get("session_chunk_id") or row.get("source_chunk_id") or "").strip()
        if chunk_id:
            return f"session_chunk:{chunk_id}"
    if _is_graph_anchor_expansion_row(row):
        return "|".join([
            "graph_anchor_expansion",
            str(row.get("anchor_id") or ""),
            str(row.get("id") or ""),
            str(row.get("via_relation") or ""),
            str(row.get("text") or ""),
        ])
    row_id = str(row.get("id") or "").strip()
    if row_id:
        return f"id:{row_id}"
    return f"text:{str(row.get('text') or '').strip()}"


def _reciprocal_rank_fuse_recall_branches(
    branches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    limit: int,
    k: Optional[int] = None,
    branch_weights: Optional[Dict[str, float]] = None,
    confidence_aware: bool = False,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Fuse named ranked recall branches with RRF without mutating inputs."""
    if limit <= 0:
        return [], {"enabled": True, "k": max(1, int(k or 1)), "branch_count": 0, "candidate_count": 0}
    if k is None:
        try:
            k = _get_configured_rrf_k(60)
        except Exception:
            if _is_fail_hard_mode():
                raise
            k = 60
    try:
        rrf_k = max(1, int(k or 60))
    except (TypeError, ValueError):
        if _is_fail_hard_mode():
            raise
        rrf_k = 60

    scores: Dict[str, float] = {}
    source_ranks: Dict[str, Dict[str, int]] = {}
    source_confidences: Dict[str, Dict[str, float]] = {}
    source_weights: Dict[str, Dict[str, float]] = {}
    rows_by_key: Dict[str, Dict[str, Any]] = {}
    branch_counts: Dict[str, int] = {}
    normalized_weights = _normalize_rrf_branch_weights(branch_weights)

    for branch_name, branch_rows in branches or []:
        name = str(branch_name or "").strip() or "unnamed"
        branch_weight = normalized_weights.get(name, 1.0)
        if not isinstance(branch_rows, list):
            if _is_fail_hard_mode():
                raise RuntimeError(f"RRF branch '{name}' is not a list")
            logger.warning("RRF branch %s is not a list; skipping", name)
            continue
        seen_in_branch: Set[str] = set()
        accepted = 0
        for rank, row in enumerate(branch_rows, 1):
            if not isinstance(row, dict):
                if _is_fail_hard_mode():
                    raise RuntimeError(f"RRF branch '{name}' row {rank} is not a dict")
                logger.warning("RRF branch %s row %d is not a dict; skipping", name, rank)
                continue
            key = _rrf_recall_row_identity(row)
            if not key or key in seen_in_branch:
                continue
            seen_in_branch.add(key)
            accepted += 1
            confidence = _rrf_row_confidence(row, name) if confidence_aware else 1.0
            confidence_factor = _rrf_confidence_factor(confidence) if confidence_aware else 1.0
            scores[key] = scores.get(key, 0.0) + (
                branch_weight * confidence_factor / float(rrf_k + rank)
            )
            source_ranks.setdefault(key, {})[name] = rank
            source_confidences.setdefault(key, {})[name] = round(float(confidence), 4)
            source_weights.setdefault(key, {})[name] = round(float(branch_weight), 4)
            existing = rows_by_key.get(key)
            if existing is None:
                rows_by_key[key] = dict(row)
            elif float(row.get("similarity") or 0.0) > float(existing.get("similarity") or 0.0):
                rows_by_key[key] = _merge_recall_row_variants(row, existing)
            else:
                rows_by_key[key] = _merge_recall_row_variants(existing, row)
        branch_counts[name] = accepted

    ordered_keys = sorted(
        scores,
        key=lambda key: (
            scores[key],
            len(source_ranks.get(key) or {}),
            float((rows_by_key.get(key) or {}).get("similarity") or 0.0),
        ),
        reverse=True,
    )
    fused: List[Dict[str, Any]] = []
    for rank, key in enumerate(ordered_keys[: max(1, int(limit or 1))], 1):
        row = dict(rows_by_key[key])
        row["rrf_score"] = scores[key]
        row["rrf_rank"] = rank
        row["source_ranks"] = dict(source_ranks.get(key) or {})
        if confidence_aware:
            row["source_confidences"] = dict(source_confidences.get(key) or {})
            row["source_weights"] = dict(source_weights.get(key) or {})
        fused.append(row)

    meta = {
        "enabled": True,
        "k": rrf_k,
        "confidence_aware": bool(confidence_aware),
        "branch_weights": {
            name: round(float(normalized_weights.get(name, 1.0)), 4)
            for name in branch_counts
        },
        "branch_count": len(branch_counts),
        "branch_counts": branch_counts,
        "candidate_count": len(scores),
        "returned_count": len(fused),
        "top_keys": ordered_keys[: max(1, int(limit or 1))],
    }
    return fused, meta


def _normalize_rrf_branch_weights(value: Optional[Dict[str, float]]) -> Dict[str, float]:
    out: Dict[str, float] = {}
    if not isinstance(value, dict):
        return out
    for raw_name, raw_weight in value.items():
        name = str(raw_name or "").strip()
        if not name:
            continue
        try:
            weight = float(raw_weight)
        except (TypeError, ValueError):
            if _is_fail_hard_mode():
                raise
            logger.warning("Ignoring invalid RRF branch weight for %s: %r", name, raw_weight)
            continue
        out[name] = max(0.0, min(3.0, weight))
    return out


def _rrf_unit_interval(value: Any) -> Optional[float]:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(number):
        return None
    return max(0.0, min(1.0, number))


def _rrf_row_confidence(row: Dict[str, Any], branch_name: str) -> float:
    for key in ("retrieval_confidence", "rank_confidence", "confidence"):
        value = _rrf_unit_interval(row.get(key))
        if value is not None:
            return value
    for key in ("similarity", "semantic_score", "lexical_score"):
        value = _rrf_unit_interval(row.get(key))
        if value is not None:
            return value
    defaults = {
        "vector": 0.75,
        "graph": 0.70,
        "session_chunks": 0.70,
        "docs": 0.55,
        "journal": 0.60,
        "insights": 0.60,
    }
    return defaults.get(str(branch_name or "").strip(), 0.60)


def _rrf_confidence_factor(confidence: float) -> float:
    bounded = max(0.0, min(1.0, float(confidence)))
    return 0.25 + (0.75 * bounded)


def _shadow_rrf_recall_store_plan(
    named_batches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    limit: int,
    branch_weights: Optional[Dict[str, float]] = None,
    confidence_aware: bool = False,
) -> Dict[str, Any]:
    if len(named_batches) < 2:
        return {"enabled": False, "reason": "single_branch"}
    try:
        fused, meta = _reciprocal_rank_fuse_recall_branches(
            named_batches,
            limit=max(1, int(limit or 1)),
            branch_weights=branch_weights,
            confidence_aware=confidence_aware,
        )
    except Exception:
        if _is_fail_hard_mode():
            raise
        logger.warning("RRF shadow fusion failed; continuing without shadow telemetry", exc_info=True)
        return {"enabled": False, "failed": True}
    meta["top_rows"] = [
        {
            "key": _rrf_recall_row_identity(row),
            "rank": int(row.get("rrf_rank") or 0),
            "score": float(row.get("rrf_score") or 0.0),
            "source_ranks": dict(row.get("source_ranks") or {}),
            "source_confidences": dict(row.get("source_confidences") or {}),
            "source_weights": dict(row.get("source_weights") or {}),
            "category": row.get("category"),
            "source_type": row.get("source_type"),
            "id": row.get("id"),
            "chunk_id": row.get("chunk_id") or row.get("source_chunk_id"),
            "text": str(row.get("text") or "")[:160],
        }
        for row in fused[: min(len(fused), 5)]
    ]
    return meta


def _coerce_bool_config(value: Any, default: bool) -> bool:
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    normalized = str(value).strip().lower()
    if normalized in {"1", "true", "yes", "on"}:
        return True
    if normalized in {"0", "false", "no", "off"}:
        return False
    return bool(default)


def _should_apply_rrf_store_plan_fusion(normalized_stores: List[str]) -> bool:
    """Enable active RRF for mixed store plans."""
    stores = [str(store or "").strip() for store in normalized_stores or []]
    if len({store for store in stores if store}) < 2:
        return False
    cfg = _get_retrieval_lightweight_config()
    raw = getattr(cfg, "store_plan_rrf_fusion", None)
    if raw is None:
        raw = getattr(cfg, "storePlanRrfFusion", True)
    return _coerce_bool_config(raw, True)


def _store_plan_rrf_branch_weights(
    normalized_stores: List[str],
    *,
    planner_meta: Optional[Dict[str, Any]],
    common_kwargs: Optional[Dict[str, Any]],
) -> Dict[str, float]:
    stores = [str(store or "").strip() for store in normalized_stores or [] if str(store or "").strip()]
    weights: Dict[str, float] = {store: 1.0 for store in stores}
    raw: Any = None
    for container in (common_kwargs, planner_meta):
        if not isinstance(container, dict):
            continue
        raw = (
            container.get("store_weights")
            or container.get("storeWeights")
            or container.get("branch_weights")
            or container.get("branchWeights")
        )
        if raw is not None:
            break
    if isinstance(raw, dict):
        for store, weight in _normalize_rrf_branch_weights(raw).items():
            if store in weights:
                weights[store] = weight
    return weights


def _active_rrf_recall_store_plan(
    named_batches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    normalized_stores: List[str],
    limit: int,
    branch_weights: Optional[Dict[str, float]] = None,
) -> Tuple[Optional[List[Dict[str, Any]]], Dict[str, Any]]:
    try:
        fused, meta = _reciprocal_rank_fuse_recall_branches(
            named_batches,
            limit=max(1, int(limit or 1)),
            branch_weights=branch_weights,
            confidence_aware=True,
        )
    except Exception:
        if _is_fail_hard_mode():
            raise
        logger.warning("RRF active fusion failed; falling back to legacy merge", exc_info=True)
        return None, {"enabled": False, "failed": True}
    out = dict(meta)
    out["enabled"] = True
    out["mode"] = "active"
    out["applied_to_stores"] = list(normalized_stores or [])
    return fused, out


def _has_store_plan_branch_result(rows: List[Dict[str, Any]], branch_name: str) -> bool:
    branch = str(branch_name or "").strip()
    if not branch:
        return False
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        source_ranks = row.get("source_ranks")
        if isinstance(source_ranks, dict) and branch in source_ranks:
            return True
        source_type = str(row.get("source_type") or row.get("category") or "").strip().lower()
        if branch == "session_chunks" and source_type in {"session_chunk", "source_chunk"}:
            return True
        if branch == "docs" and source_type in {"doc", "docs", "document", "project_doc"}:
            return True
        if branch == "graph" and (
            str(row.get("via") or "").startswith("graph")
            or row.get("graph_path")
            or row.get("graph_relation_sequence")
        ):
            return True
        if branch == "journal" and source_type == "journal":
            return True
        if branch == "insights" and source_type in {"insight", "snippet", "journal"}:
            return True
    return False


def _store_plan_row_best_confidence(row: Dict[str, Any]) -> float:
    if not isinstance(row, dict):
        return 0.0
    source_confidences = row.get("source_confidences")
    if isinstance(source_confidences, dict) and source_confidences:
        values = [
            _rrf_unit_interval(value)
            for value in source_confidences.values()
        ]
        bounded = [value for value in values if value is not None]
        if bounded:
            return max(bounded)
    for key in ("retrieval_confidence", "rank_confidence", "confidence", "similarity"):
        value = _rrf_unit_interval(row.get(key))
        if value is not None:
            return value
    return 0.0


def _preserve_strong_store_plan_rows(
    rows: List[Dict[str, Any]],
    named_batches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Keep high-confidence branch-top rows from being erased by cross-store fusion."""
    if not rows or not named_batches:
        return rows, {"preserved": 0}
    top_limit = max(1, int(limit or 1))
    out = list(rows[:top_limit])
    existing_keys = {_rrf_recall_row_identity(row) for row in out if isinstance(row, dict)}
    preserved: List[Dict[str, Any]] = []
    for branch_name, branch_rows in named_batches:
        branch = str(branch_name or "").strip()
        if branch == "docs":
            # Docs have a dedicated preservation path that also carries docs
            # bundle metadata; do not preempt it here.
            continue
        branch_already_present = _has_store_plan_branch_result(out, branch)
        if not branch or (branch_already_present and branch != "session_chunks"):
            continue
        if not branch_rows:
            continue
        candidate_limit = 1
        branch_candidates = [
            row for row in branch_rows
            if isinstance(row, dict)
        ][:candidate_limit]
        for candidate in branch_candidates:
            key = _rrf_recall_row_identity(candidate)
            if key in existing_keys:
                continue
            confidence = _rrf_row_confidence(candidate, branch)
            min_confidence = 0.65 if branch == "session_chunks" else 0.70
            if confidence < min_confidence:
                continue
            replacement = dict(candidate)
            replacement["store_plan_preserved_branch_top"] = branch
            replacement["store_plan_preserved_confidence"] = round(float(confidence), 4)
            # Preserve first-order session evidence in the final window, but do
            # not force it above a higher-confidence compact fact for ordinary
            # fact lookups. Source-specific queries are promoted by the
            # first-order coverage gates before this preservation step.
            insert_at = len(out)
            for idx, existing in enumerate(out):
                if _store_plan_row_best_confidence(existing) < confidence:
                    insert_at = idx
                    break
            if insert_at >= top_limit and len(out) >= top_limit:
                replacement_idx = next(
                    (
                        idx
                        for idx in range(len(out) - 1, -1, -1)
                        if not out[idx].get("store_plan_preserved_branch_top")
                    ),
                    len(out) - 1,
                )
                out[replacement_idx] = replacement
            else:
                out.insert(insert_at, replacement)
            if len(out) > top_limit:
                out = out[:top_limit]
            existing_keys.add(key)
            preserved.append({
                "store": branch,
                "confidence": round(float(confidence), 4),
                "key": key,
            })
    return out, {"preserved": len(preserved), "rows": preserved}


def _preserve_shared_quoted_item_rows(
    query: str,
    rows: List[Dict[str, Any]],
    named_batches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Keep distinct shared quoted-item source rows in the final recall window."""
    if not rows or not named_batches or limit <= 0 or not _is_multi_entity_shared_source_query(query):
        return rows, {"preserved": 0}
    out = list(rows[: max(1, int(limit or 1))])
    existing_keys = {_rrf_recall_row_identity(row) for row in out if isinstance(row, dict)}
    present_item_keys: Set[str] = set()
    for row in out:
        if not isinstance(row, dict):
            continue
        for key in list(row.get("shared_quoted_item_keys") or []):
            normalized = str(key or "").strip().lower()
            if normalized:
                present_item_keys.add(normalized)

    session_branch_rows: List[Dict[str, Any]] = []
    for branch_name, branch_rows in named_batches:
        if str(branch_name or "").strip() != "session_chunks":
            continue
        session_branch_rows.extend(row for row in branch_rows or [] if isinstance(row, dict))
    candidates = [
        row for row in session_branch_rows
        if float(row.get("shared_quoted_item_score") or 0.0) >= 0.97
        and any(str(key or "").strip().lower() for key in list(row.get("shared_quoted_item_keys") or []))
    ]
    if not candidates:
        return rows, {"preserved": 0}
    candidates.sort(
        key=lambda row: (
            len({
                str(key or "").strip().lower()
                for key in list(row.get("shared_quoted_item_keys") or [])
                if str(key or "").strip()
            } - present_item_keys),
            float(row.get("shared_quoted_item_score") or 0.0),
            _store_plan_row_best_confidence(row),
        ),
        reverse=True,
    )
    preserved: List[Dict[str, Any]] = []
    for candidate in candidates:
        candidate_item_keys = {
            str(key or "").strip().lower()
            for key in list(candidate.get("shared_quoted_item_keys") or [])
            if str(key or "").strip()
        }
        new_item_keys = candidate_item_keys - present_item_keys
        if not new_item_keys:
            continue
        key = _rrf_recall_row_identity(candidate)
        if key in existing_keys:
            present_item_keys.update(candidate_item_keys)
            continue
        replacement = dict(candidate)
        replacement["store_plan_preserved_shared_quoted_item"] = True
        confidence = _store_plan_row_best_confidence(replacement)
        insert_at = min(len(out), max(0, sum(
            1 for row in out
            if isinstance(row, dict)
            and (
                row.get("store_plan_preserved_shared_quoted_item")
                or "shared_quoted_item" in list(row.get("match_modes") or [])
            )
        )))
        if len(out) >= max(1, int(limit or 1)):
            replacement_idx = next(
                (
                    idx
                    for idx in range(len(out) - 1, -1, -1)
                    if not (
                        isinstance(out[idx], dict)
                        and (
                            out[idx].get("store_plan_preserved_shared_quoted_item")
                            or "shared_quoted_item" in list(out[idx].get("match_modes") or [])
                        )
                    )
                ),
                len(out) - 1,
            )
            out[replacement_idx] = replacement
        else:
            out.insert(insert_at, replacement)
        if len(out) > max(1, int(limit or 1)):
            out = out[: max(1, int(limit or 1))]
        existing_keys.add(key)
        present_item_keys.update(candidate_item_keys)
        preserved.append({
            "key": key,
            "item_keys": sorted(new_item_keys),
            "confidence": round(float(confidence), 4),
        })
        if len(preserved) >= max(1, min(3, int(limit or 1) - 1)):
            break
    return out, {"preserved": len(preserved), "rows": preserved}


def _preserve_source_dated_session_rows_for_selected_facts(
    query: str,
    rows: List[Dict[str, Any]],
    named_batches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Keep dated first-order source rows that ground selected synthetic facts."""
    if not rows or not named_batches or limit <= 0:
        return rows, {"preserved": 0}
    query_terms = _source_chunk_query_terms(query, limit=12)
    if not query_terms:
        return rows, {"preserved": 0}
    selected_fact_rows = [
        row for row in rows
        if isinstance(row, dict)
        and str(row.get("source_type") or row.get("category") or "").strip().lower()
        in {"fact", "preference", "event", "user"}
    ]
    if not selected_fact_rows:
        return rows, {"preserved": 0}

    def _row_terms(row: Dict[str, Any]) -> Set[str]:
        return {
            term for term in _extract_vocabulary_free_query_terms(str(row.get("text") or ""), limit=24)
            if len(term) >= _recall_query_term_min_len(term)
        }

    fact_term_sets: List[Set[str]] = []
    for fact in selected_fact_rows:
        fact_text = str(fact.get("text") or "")
        if sum(1 for term in query_terms if _text_matches_query_term(fact_text, term)) <= 0:
            continue
        terms = _row_terms(fact)
        if terms:
            fact_term_sets.append(terms)
    if not fact_term_sets:
        return rows, {"preserved": 0}

    session_branch_rows: List[Dict[str, Any]] = []
    for branch_name, branch_rows in named_batches:
        if str(branch_name or "").strip() != "session_chunks":
            continue
        session_branch_rows.extend(row for row in branch_rows or [] if isinstance(row, dict))
    out = list(rows[: max(1, int(limit or 1))])
    existing_keys = {_rrf_recall_row_identity(row) for row in out if isinstance(row, dict)}
    scored: List[Tuple[Tuple[int, int, float], Dict[str, Any]]] = []
    for candidate in session_branch_rows:
        if not _is_first_order_session_source_row(candidate) or not _date_part(candidate.get("source_date")):
            continue
        key = _rrf_recall_row_identity(candidate)
        if key in existing_keys:
            continue
        candidate_text = str(candidate.get("session_scoring_context_text") or candidate.get("text") or "")
        if not candidate_text:
            continue
        candidate_terms = _row_terms({"text": candidate_text})
        if not candidate_terms:
            continue
        fact_bridge_overlap = max((len(candidate_terms & terms) for terms in fact_term_sets), default=0)
        query_overlap = sum(1 for term in query_terms if _text_matches_query_term(candidate_text, term))
        if fact_bridge_overlap < 2 or query_overlap < 1:
            continue
        scored.append((
            (
                fact_bridge_overlap,
                query_overlap,
                float(candidate.get("similarity") or candidate.get("score") or 0.0),
            ),
            candidate,
        ))
    if not scored:
        return rows, {"preserved": 0}
    scored.sort(key=lambda item: item[0], reverse=True)
    out_limit = max(1, int(limit or 1))
    score_key, candidate = scored[0]
    replacement = dict(candidate)
    replacement["store_plan_preserved_source_dated_fact_evidence"] = True
    replacement["source_dated_fact_bridge_score"] = {
        "fact_overlap": score_key[0],
        "query_overlap": score_key[1],
    }
    if len(out) >= out_limit:
        replacement_idx = next(
            (
                idx
                for idx in range(len(out) - 1, -1, -1)
                if isinstance(out[idx], dict)
                and not _date_part(out[idx].get("source_date"))
                and not out[idx].get("store_plan_preserved_branch_top")
            ),
            len(out) - 1,
        )
        out[replacement_idx] = replacement
    else:
        out.append(replacement)
    if len(out) > out_limit:
        out = out[:out_limit]
    return out, {
        "preserved": 1,
        "rows": [{
            "key": _rrf_recall_row_identity(candidate),
            "fact_overlap": score_key[0],
            "query_overlap": score_key[1],
        }],
    }


def _query_term_overlap_count(row: Dict[str, Any], query_terms: List[str]) -> int:
    if not query_terms:
        return 0
    search_text = " ".join([
        str((row or {}).get("text") or ""),
        str((row or {}).get("keywords") or ""),
    ]).lower()
    return sum(
        1 for term in query_terms
        if term and (term in search_text or _text_contains_anchor_term(search_text, term))
    )


def _suppress_weaker_synthetic_temporal_conflicts_after_session_source(
    query: str,
    rows: List[Dict[str, Any]],
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Prefer first-order session evidence over weaker conflicting temporal facts."""
    if not rows:
        return rows, {"suppressed": 0}
    query_terms = [
        term for term in _extract_vocabulary_free_query_terms(query, limit=12)
        if len(str(term or "")) >= 5
    ]
    if len(query_terms) < 3:
        return rows, {"suppressed": 0}
    session_candidates: List[Tuple[int, Dict[str, Any]]] = []
    for row in rows:
        if not isinstance(row, dict) or not _is_first_order_session_source_row(row):
            continue
        source_date = _date_part(row.get("source_date"))
        if not source_date:
            continue
        overlap = _query_term_overlap_count(row, query_terms)
        if overlap >= 3:
            session_candidates.append((overlap, row))
    if not session_candidates:
        return rows, {"suppressed": 0}
    best_overlap, best_source = max(
        session_candidates,
        key=lambda item: (
            item[0],
            _store_plan_row_best_confidence(item[1]),
        ),
    )
    source_date = _date_part(best_source.get("source_date"))
    if not source_date:
        return rows, {"suppressed": 0}
    kept: List[Dict[str, Any]] = []
    suppressed: List[Dict[str, Any]] = []
    for row in rows:
        if not isinstance(row, dict):
            kept.append(row)
            continue
        if _is_first_order_session_source_row(row):
            kept.append(row)
            continue
        overlap = _query_term_overlap_count(row, query_terms)
        row_temporal = _date_part(row.get("occurred_start") or row.get("occurred_end") or row.get("source_date"))
        temporal_conflicts_with_source = False
        if row_temporal and row_temporal != source_date:
            try:
                temporal_conflicts_with_source = (
                    datetime.fromisoformat(row_temporal).date()
                    > datetime.fromisoformat(source_date).date()
                )
            except Exception:
                if _is_fail_hard_mode():
                    raise
                temporal_conflicts_with_source = False
        if temporal_conflicts_with_source and overlap < best_overlap:
            suppressed.append(row)
            continue
        kept.append(row)
    if not suppressed:
        return rows, {"suppressed": 0}
    return kept, {
        "suppressed": len(suppressed),
        "source_date": source_date,
        "source_overlap": best_overlap,
        "suppressed_rows": [
            {
                "id": row.get("id"),
                "source_type": row.get("source_type") or row.get("category"),
                "via": row.get("via"),
                "source_date": row.get("source_date"),
                "occurred_start": row.get("occurred_start"),
                "occurred_end": row.get("occurred_end"),
                "overlap": _query_term_overlap_count(row, query_terms),
            }
            for row in suppressed[:5]
            if isinstance(row, dict)
        ],
    }


def _annotate_rrf_shadow_comparison(
    shadow_meta: Dict[str, Any],
    final_rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> Dict[str, Any]:
    if not isinstance(shadow_meta, dict) or not shadow_meta.get("enabled"):
        return shadow_meta
    top_limit = max(1, int(limit or 1))
    current_keys = [
        _rrf_recall_row_identity(row)
        for row in (final_rows or [])[:top_limit]
        if isinstance(row, dict)
    ]
    rrf_keys = [
        str(key)
        for key in list(shadow_meta.get("top_keys") or [])[:top_limit]
        if str(key)
    ]
    current_pos = {key: idx + 1 for idx, key in enumerate(current_keys)}
    rrf_pos = {key: idx + 1 for idx, key in enumerate(rrf_keys)}
    displacement: List[Dict[str, Any]] = []
    max_abs_displacement = 0
    for key in rrf_keys:
        current_rank = current_pos.get(key)
        rrf_rank = rrf_pos.get(key)
        if current_rank is None or rrf_rank is None:
            continue
        delta = current_rank - rrf_rank
        if delta:
            max_abs_displacement = max(max_abs_displacement, abs(delta))
            displacement.append({
                "key": key,
                "current_rank": current_rank,
                "rrf_rank": rrf_rank,
                "delta": delta,
            })

    rrf_only = [key for key in rrf_keys if key not in current_pos]
    current_only = [key for key in current_keys if key not in rrf_pos]
    rrf_only_set = set(rrf_only)
    top_rows = [
        row for row in list(shadow_meta.get("top_rows") or [])
        if isinstance(row, dict)
    ]
    branch_contribution: Dict[str, int] = {}
    for row in top_rows:
        source_ranks = row.get("source_ranks")
        if not isinstance(source_ranks, dict):
            continue
        for branch in source_ranks:
            key = str(branch or "").strip()
            if key:
                branch_contribution[key] = branch_contribution.get(key, 0) + 1

    out = dict(shadow_meta)
    out["comparison"] = {
        "current_top_keys": current_keys,
        "rrf_top_keys": rrf_keys,
        "same_top_order": current_keys == rrf_keys,
        "displacement_count": len(displacement),
        "max_abs_displacement": max_abs_displacement,
        "displacement": displacement[:top_limit],
        "rrf_only_top_keys": rrf_only,
        "current_only_top_keys": current_only,
        "rrf_only_top_rows": [
            row for row in top_rows
            if str(row.get("key") or "") in rrf_only_set
        ],
        "branch_contribution": branch_contribution,
    }
    return out


def _prioritize_fast_anchor_direct_rows(query: str, rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Keep direct answer-bearing memory rows ahead of broader fast-recall context."""
    if not rows:
        return rows
    explicit_anchor_terms = _extract_explicit_query_anchor_terms(query, limit=8)
    query_terms = _extract_distinctive_query_terms(query, limit=8)
    event_focus_terms = [
        term
        for term in query_terms
        if term not in explicit_anchor_terms
    ]
    def _row_text(row: Dict[str, Any]) -> str:
        return str((row or {}).get("text") or "")

    def _row_matches_anchor(row: Dict[str, Any]) -> bool:
        lower_text = _row_text(row).lower()
        return any(term in lower_text for term in explicit_anchor_terms)

    def _row_created_sort_key(row: Dict[str, Any]) -> str:
        for key in ("created_at", "source_date", "valid_from"):
            raw = str((row or {}).get(key) or "").strip()
            if raw:
                return raw
        return ""

    def _row_confidence_sort_key(row: Dict[str, Any]) -> float:
        for key in ("extraction_confidence", "confidence"):
            raw = (row or {}).get(key)
            if raw is None or raw == "":
                continue
            try:
                return float(raw)
            except (TypeError, ValueError):
                continue
        return 0.0

    def _is_direct_memory_row(row: Dict[str, Any]) -> bool:
        if str((row or {}).get("category") or "").strip().lower() == "docs":
            return False
        if (row or {}).get("via_relation") or (row or {}).get("graph_path"):
            return False
        return bool(str((row or {}).get("id") or "").strip())

    direct_anchor_rows = [
        row
        for row in rows
        if isinstance(row, dict) and _is_direct_memory_row(row) and _row_matches_anchor(row)
    ]
    if not explicit_anchor_terms:
        direct_rows = [
            row
            for row in rows
            if isinstance(row, dict) and _is_direct_memory_row(row)
        ]
        if len(query_terms) < 2 or not direct_rows:
            return rows
        overlap_by_id = {
            str(row.get("id")): _query_term_overlap({"text": _row_text(row)}, query_terms)
            for row in direct_rows
        }
        max_overlap = max(overlap_by_id.values(), default=0)
        # Without an explicit entity anchor, only promote rows that directly
        # cover every distinctive query term. Partial lexical hits remain in
        # the store's ranked order to avoid broad fast-recall reshaping.
        if max_overlap < len(query_terms):
            return rows
        priority_rows = [
            row for row in direct_rows
            if overlap_by_id.get(str(row.get("id")), 0) == max_overlap
        ]
        priority_rows.sort(
            key=lambda row: (
                _row_confidence_sort_key(row),
                _row_created_sort_key(row),
                float(row.get("similarity", 0.0) or 0.0),
            ),
            reverse=True,
        )
        priority_keys = {_recall_row_identity(row) for row in priority_rows}
        return priority_rows + [
            row for row in rows
            if _recall_row_identity(row) not in priority_keys
        ]
    if not direct_anchor_rows:
        return rows

    overlap_by_id = {
        str(row.get("id")): _query_term_overlap({"text": _row_text(row)}, query_terms)
        for row in direct_anchor_rows
    }
    event_overlap_by_id = {
        str(row.get("id")): _query_term_overlap({"text": _row_text(row)}, event_focus_terms)
        for row in direct_anchor_rows
    }
    max_overlap = max(overlap_by_id.values(), default=0)
    if max_overlap >= 2:
        priority_rows = [
            row for row in direct_anchor_rows
            if overlap_by_id.get(str(row.get("id")), 0) == max_overlap
        ]
    else:
        # Broad anchor prompts have little lexical detail. In that shape, direct
        # same-anchor memory recency is a better hook context signal than graph
        # expansions or older generic anchor facts.
        priority_rows = list(direct_anchor_rows)

    priority_rows.sort(
        key=lambda row: (
            event_overlap_by_id.get(str(row.get("id")), 0),
            overlap_by_id.get(str(row.get("id")), 0),
            _row_confidence_sort_key(row),
            _row_created_sort_key(row),
            float(row.get("similarity", 0.0) or 0.0),
        ),
        reverse=True,
    )
    priority_keys = {_recall_row_identity(row) for row in priority_rows}
    residual_anchor_rows = [
        row for row in direct_anchor_rows
        if _recall_row_identity(row) not in priority_keys
    ]
    residual_anchor_rows.sort(
        key=lambda row: (
            event_overlap_by_id.get(str(row.get("id")), 0),
            overlap_by_id.get(str(row.get("id")), 0),
            _row_confidence_sort_key(row),
            _row_created_sort_key(row),
            float(row.get("similarity", 0.0) or 0.0),
        ),
        reverse=True,
    )
    residual_keys = {_recall_row_identity(row) for row in residual_anchor_rows}
    return priority_rows + residual_anchor_rows + [
        row for row in rows
        if _recall_row_identity(row) not in priority_keys
        and _recall_row_identity(row) not in residual_keys
    ]


def _prioritize_deliberate_confident_direct_anchor_rows(query: str, rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Prefer confident direct same-anchor facts over entity stubs and support chunks."""
    if not rows:
        return rows
    anchor_terms = _extract_explicit_query_anchor_terms(query, limit=8)
    if not anchor_terms:
        return rows
    query_terms = _extract_distinctive_query_terms(query, limit=8)
    if not query_terms:
        return rows

    def _row_text(row: Dict[str, Any]) -> str:
        return str((row or {}).get("text") or "")

    def _row_matches_anchor(row: Dict[str, Any]) -> bool:
        lower_text = _row_text(row).lower()
        return any(term in lower_text for term in anchor_terms)

    def _row_created_sort_key(row: Dict[str, Any]) -> str:
        for key in ("created_at", "source_date", "valid_from"):
            raw = str((row or {}).get(key) or "").strip()
            if raw:
                return raw
        return ""

    def _row_confidence_sort_key(row: Dict[str, Any]) -> float:
        for key in ("extraction_confidence", "confidence"):
            raw = (row or {}).get(key)
            if raw is None or raw == "":
                continue
            try:
                return float(raw)
            except (TypeError, ValueError):
                continue
        return 0.0

    def _is_direct_memory_row(row: Dict[str, Any]) -> bool:
        if str((row or {}).get("category") or "").strip().lower() == "docs":
            return False
        if (row or {}).get("via_relation") or (row or {}).get("graph_path"):
            return False
        return bool(str((row or {}).get("id") or "").strip())

    direct_anchor_rows = [
        row
        for row in rows
        if isinstance(row, dict) and _is_direct_memory_row(row) and _row_matches_anchor(row)
    ]
    if len(direct_anchor_rows) < 2:
        return rows

    overlap_by_id = {
        str(row.get("id")): _query_term_overlap({"text": _row_text(row)}, query_terms)
        for row in direct_anchor_rows
    }
    max_overlap = max(overlap_by_id.values(), default=0)
    if max_overlap < 2 or (max_overlap / max(1, len(query_terms))) < 0.67:
        return rows
    priority_rows = [
        row for row in direct_anchor_rows
        if overlap_by_id.get(str(row.get("id")), 0) == max_overlap
    ]
    if len(priority_rows) < 2:
        return rows

    priority_rows.sort(
        key=lambda row: (
            _row_confidence_sort_key(row),
            _row_created_sort_key(row),
            float(row.get("similarity", 0.0) or 0.0),
        ),
        reverse=True,
    )
    priority_keys = {_recall_row_identity(row) for row in priority_rows}
    return priority_rows + [
        row for row in rows
        if _recall_row_identity(row) not in priority_keys
    ]


_DATE_RANGE_CONNECTION_QUERY_RE = re.compile(
    r"\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|"
    r"jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|"
    r"nov(?:ember)?|dec(?:ember)?)\s+\d{1,2}\s*[-/]\s*\d{1,2}\b"
)
_MONTH_NAME_TOKENS = {
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept", "oct", "nov", "dec",
}


def _is_date_relation_callback_query(query: str) -> bool:
    lower = str(query or "").lower()
    if not lower:
        return False
    return bool(_DATE_RANGE_CONNECTION_QUERY_RE.search(lower))


def _prioritize_date_relation_callback_rows(query: str, rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Prefer assistant callback rows that express date-to-date connections explicitly."""
    if not rows or not _is_date_relation_callback_query(query):
        return rows

    query_terms = _extract_distinctive_query_terms(query, limit=8)
    query_months = {
        token
        for token in re.findall(r"[a-z]+", str(query or "").lower())
        if token in _MONTH_NAME_TOKENS
    }

    def _row_text(row: Dict[str, Any]) -> str:
        return str((row or {}).get("text") or "")

    def _row_created_sort_key(row: Dict[str, Any]) -> str:
        for key in ("created_at", "source_date", "valid_from"):
            raw = str((row or {}).get(key) or "").strip()
            if raw:
                return raw
        return ""

    def _is_direct_memory_row(row: Dict[str, Any]) -> bool:
        if str((row or {}).get("category") or "").strip().lower() == "docs":
            return False
        if (row or {}).get("via_relation") or (row or {}).get("graph_path"):
            return False
        return bool(str((row or {}).get("id") or "").strip())

    def _row_date_relation_score(row: Dict[str, Any]) -> int:
        if not isinstance(row, dict) or not _is_direct_memory_row(row):
            return 0
        lower_text = _row_text(row).lower()
        score = 0
        row_months = {
            token
            for token in re.findall(r"[a-z]+", lower_text)
            if token in _MONTH_NAME_TOKENS
        }
        if row_months & query_months:
            score += 1
        if score <= 0:
            return 0
        if str((row or {}).get("structural_anchor_kind") or "") == "assistant_callback_anchor":
            score += 2
        if str((row or {}).get("source_type") or "") == "assistant":
            score += 1
        return score

    scored_rows = [
        row for row in rows
        if _row_date_relation_score(row) > 0
    ]
    if not scored_rows:
        return rows

    scored_rows.sort(
        key=lambda row: (
            _row_date_relation_score(row),
            _query_term_overlap({"text": _row_text(row)}, query_terms),
            _row_created_sort_key(row),
            float((row or {}).get("similarity", 0.0) or 0.0),
        ),
        reverse=True,
    )
    scored_keys = {_recall_row_identity(row) for row in scored_rows}
    return scored_rows + [
        row for row in rows
        if _recall_row_identity(row) not in scored_keys
    ]


_NAMED_ENTITY_ACTIVITY_QUERY_RE = re.compile(r"\bwhat\s+do(?:es)?\b")


def _prioritize_named_entity_activity_anchor_rows(query: str, rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Prefer direct attached facts from the explicit entity on 'what does X do' queries."""
    if not rows:
        return rows
    lower_query = str(query or "").strip().lower()
    if not lower_query or not _NAMED_ENTITY_ACTIVITY_QUERY_RE.search(lower_query):
        return rows
    anchor_terms = {
        str(term or "").strip().lower()
        for term in _extract_explicit_query_anchor_terms(query, limit=4)
        if str(term or "").strip()
    }
    if not anchor_terms:
        return rows

    def _is_direct_anchor_attached_fact(row: Dict[str, Any]) -> bool:
        if str((row or {}).get("via") or "") != "graph_attached_fact":
            return False
        source_name = str((row or {}).get("source_name") or "").strip().lower()
        if source_name and source_name in anchor_terms:
            return True
        graph_path = str((row or {}).get("graph_path") or "").strip().lower()
        return any(graph_path.startswith(f"{term} --has_fact-->") for term in anchor_terms)

    if not any(_is_direct_anchor_attached_fact(row) for row in rows):
        return rows

    return sorted(
        rows,
        key=lambda row: (
            1 if _is_direct_anchor_attached_fact(row) else 0,
            float((row or {}).get("similarity", 0.0) or 0.0),
        ),
        reverse=True,
    )


def _is_docs_recall_row(row: Dict[str, Any]) -> bool:
    return str(row.get("category") or "").strip() == "docs" or str(row.get("source_type") or "").strip() == "docs"


def _recall_row_identity(row: Dict[str, Any]) -> Tuple[str, str]:
    rid = str(row.get("id") or "").strip()
    if rid:
        return ("id", rid)
    return ("text", str(row.get("text") or "").strip())


def _docs_row_latest_iso_date(row: Dict[str, Any]) -> str:
    dates = re.findall(r"(?<!\d)(20\d{2}-\d{2}-\d{2})(?!\d)", str((row or {}).get("text") or ""))
    return max(dates) if dates else ""


def _is_first_order_session_source_row(row: Dict[str, Any]) -> bool:
    source_type = str((row or {}).get("source_type") or (row or {}).get("category") or "").strip().lower()
    return source_type in {"session_chunk", "source_chunk"} or str((row or {}).get("via") or "") == "session_chunks"


def _normalize_query_echo_text(value: Any) -> str:
    return re.sub(r"\s+", " ", unicodedata.normalize("NFKC", str(value or "")).casefold()).strip()


def _recall_text_dedup_key(row: Dict[str, Any]) -> str:
    return _normalize_query_echo_text((row or {}).get("text"))


def _dedupe_exact_docs_text_recall_rows(
    rows: List[Dict[str, Any]],
    candidate_rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Keep exact duplicate docs evidence from consuming multiple recall slots."""
    top_limit = max(1, int(limit or 1))
    selected = [row for row in list(rows or [])[:top_limit] if isinstance(row, dict)]
    if not selected:
        return rows, {"deduped": False}

    seen_texts: set[str] = set()
    out: List[Dict[str, Any]] = []
    removed = 0
    for row in selected:
        if not _is_docs_recall_row(row):
            out.append(row)
            continue
        text_key = _recall_text_dedup_key(row)
        if text_key and text_key in seen_texts:
            removed += 1
            continue
        if text_key:
            seen_texts.add(text_key)
        out.append(row)
    if not removed:
        return rows, {"deduped": False}

    seen_rows = {_rrf_recall_row_identity(row) for row in out}
    refilled = 0
    for row in [*list(rows or [])[top_limit:], *list(candidate_rows or [])]:
        if len(out) >= top_limit:
            break
        if not isinstance(row, dict):
            continue
        row_key = _rrf_recall_row_identity(row)
        if row_key in seen_rows:
            continue
        text_key = _recall_text_dedup_key(row) if _is_docs_recall_row(row) else ""
        if _is_docs_recall_row(row) and text_key and text_key in seen_texts:
            continue
        if text_key:
            seen_texts.add(text_key)
        seen_rows.add(row_key)
        out.append(row)
        refilled += 1

    return out[:top_limit], {
        "deduped": True,
        "removed": removed,
        "refilled": refilled,
        "selected_count": len(selected),
    }


# Protocol role labels emitted by Quaid transcript parsers, not user-language content.
_QUERY_ECHO_USER_ROLE_KEYS = frozenset({"user", "human", "operator"})


def _query_echo_line_matches(query: str, line: str) -> bool:
    normalized_query = _normalize_query_echo_text(query)
    if not normalized_query:
        return False
    current = unicodedata.normalize("NFKC", str(line or "")).strip()
    for _ in range(3):
        match = re.match(r"^(?:\[[^\]]+\]\s*)?([^:\r\n]{1,80})\s*:\s*(.*)$", current)
        if not match:
            return False
        label = match.group(1).strip().casefold()
        payload = match.group(2).strip()
        role_key = re.sub(r"[\s_-]+", " ", label.rsplit("/", 1)[-1]).strip()
        if role_key in _QUERY_ECHO_USER_ROLE_KEYS:
            return _normalize_query_echo_text(payload) == normalized_query
        current = payload
    return False


def _is_current_query_echo_session_row(query: str, row: Dict[str, Any]) -> bool:
    if not _is_first_order_session_source_row(row):
        return False
    normalized_query = _normalize_query_echo_text(query)
    if len(normalized_query) < 8:
        return False
    return any(_query_echo_line_matches(normalized_query, line) for line in str(row.get("text") or "").splitlines())


def _session_row_provenance_source_type(row: Dict[str, Any]) -> str:
    if not isinstance(row, dict):
        return ""
    value = str(row.get("source_provenance_type") or "").strip().lower()
    if value:
        return value
    source_type = str(row.get("source_type") or "").strip().lower()
    if source_type and source_type not in {"session_chunk", "source_chunk"}:
        return source_type
    return ""


def _is_assistant_provenance_session_row(row: Dict[str, Any]) -> bool:
    if not _is_first_order_session_source_row(row):
        return False
    return _session_row_provenance_source_type(row) in _ASSISTANT_PROVENANCE_SOURCE_TYPES


def _query_requests_assistant_source(query: str) -> bool:
    try:
        analysis = _derive_query_requirements(
            query,
            intent="GENERAL",
            include_relation_keywords=False,
        )
    except Exception:
        if _is_fail_hard_mode():
            raise
        return False
    return "assistant_source" in set(analysis.get("requirements") or [])


def _suppress_assistant_session_rows_when_strong_evidence_exists(
    query: str,
    rows: List[Dict[str, Any]],
    candidate_rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Keep assistant transcript echoes below durable evidence for fact/docs recall."""
    top_limit = max(1, int(limit or 1))
    selected = [row for row in list(rows or [])[:top_limit] if isinstance(row, dict)]
    if not selected:
        return rows, {"applied": False}
    assistant_rows = [row for row in selected if _is_assistant_provenance_session_row(row)]
    if not assistant_rows:
        return rows, {"applied": False}
    if _query_requests_assistant_source(query):
        return rows, {"applied": False, "skipped_reason": "assistant_source_query"}

    def _row_score(row: Dict[str, Any]) -> float:
        try:
            return float(row.get("similarity") or row.get("score") or 0.0)
        except (TypeError, ValueError):
            return 0.0

    strong_evidence = [
        row for row in selected
        if not _is_assistant_provenance_session_row(row)
        and _row_score(row) >= 0.75
        and str(row.get("text") or "").strip()
    ]
    if not strong_evidence:
        return rows, {"applied": False, "assistant_session_count": len(assistant_rows)}

    selected_keys = {_rrf_recall_row_identity(row) for row in selected}
    out = [row for row in selected if not _is_assistant_provenance_session_row(row)]
    original_kept_count = len(out)
    for candidate in list(candidate_rows or []):
        if len(out) >= top_limit:
            break
        if not isinstance(candidate, dict) or _is_assistant_provenance_session_row(candidate):
            continue
        key = _rrf_recall_row_identity(candidate)
        if not key or key in selected_keys:
            continue
        if not str(candidate.get("text") or "").strip():
            continue
        selected_keys.add(key)
        out.append(candidate)

    return out[:top_limit], {
        "applied": True,
        "suppressed": len(assistant_rows),
        "strong_evidence_count": len(strong_evidence),
        "refilled": max(0, len(out) - original_kept_count),
    }


def _mixed_session_chunk_result_cap(limit: int) -> int:
    if limit <= 1:
        return max(0, int(limit or 0))
    return max(1, min(3, math.ceil(int(limit) / 2)))


def _cap_mixed_session_chunk_results(
    rows: List[Dict[str, Any]],
    candidate_rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Prevent first-order transcript hits from crowding all compact memories out."""
    top_limit = max(1, int(limit or 1))
    selected = [row for row in list(rows or [])[:top_limit] if isinstance(row, dict)]
    if not selected:
        return rows, {"applied": False}
    selected_session_count = sum(1 for row in selected if _is_first_order_session_source_row(row))
    cap = _mixed_session_chunk_result_cap(top_limit)
    if selected_session_count <= cap:
        return rows, {"applied": False, "cap": cap, "selected_session_count": selected_session_count}

    selected_keys = {_rrf_recall_row_identity(row) for row in selected}
    candidate_pool: List[Dict[str, Any]] = []
    for row in list(candidate_rows or []):
        if not isinstance(row, dict) or _is_first_order_session_source_row(row):
            continue
        key = _rrf_recall_row_identity(row)
        if not key or key in selected_keys:
            continue
        if not str(row.get("text") or "").strip():
            continue
        selected_keys.add(key)
        candidate_pool.append(row)
    selected_non_session_count = len(selected) - selected_session_count
    if not candidate_pool and not selected_non_session_count:
        return rows, {
            "applied": False,
            "cap": cap,
            "selected_session_count": selected_session_count,
            "candidate_count": 0,
        }

    out: List[Dict[str, Any]] = []
    kept_session = 0
    for row in selected:
        if _is_first_order_session_source_row(row):
            if kept_session >= cap:
                continue
            kept_session += 1
        out.append(row)
    for candidate in candidate_pool:
        if len(out) >= top_limit:
            break
        out.append(candidate)

    return out[:top_limit], {
        "applied": True,
        "cap": cap,
        "selected_session_count": selected_session_count,
        "final_session_count": sum(1 for row in out if _is_first_order_session_source_row(row)),
        "candidate_count": len(candidate_pool),
        "replaced": max(0, selected_session_count - kept_session),
    }


def _defer_query_echo_session_rows(
    query: str,
    rows: List[Dict[str, Any]],
    candidate_rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Keep prior turns that quote the current query behind answer evidence."""
    top_limit = max(1, int(limit or 1))
    selected = [row for row in list(rows or [])[:top_limit] if isinstance(row, dict)]
    if not selected:
        return rows, {"applied": False}
    echo_rows = [row for row in selected if _is_current_query_echo_session_row(query, row)]
    if not echo_rows:
        return rows, {"applied": False}

    out = [row for row in selected if not _is_current_query_echo_session_row(query, row)]
    out_keys = {_rrf_recall_row_identity(row) for row in out}
    candidate_pool: List[Dict[str, Any]] = []
    for row in [*list(rows or [])[top_limit:], *list(candidate_rows or [])]:
        if not isinstance(row, dict) or _is_current_query_echo_session_row(query, row):
            continue
        key = _rrf_recall_row_identity(row)
        if not key or key in out_keys:
            continue
        if not str(row.get("text") or "").strip():
            continue
        out_keys.add(key)
        candidate_pool.append(row)
        if len(out) + len(candidate_pool) >= top_limit:
            break

    for candidate in candidate_pool:
        if len(out) >= top_limit:
            break
        out.append(candidate)
    for row in echo_rows:
        if len(out) >= top_limit:
            break
        out.append(row)
        out_keys.add(_rrf_recall_row_identity(row))

    return out[:top_limit], {
        "applied": True,
        "deferred": len(echo_rows),
        "refilled": len(candidate_pool),
        "selected_session_count": sum(1 for row in selected if _is_first_order_session_source_row(row)),
    }


def _preserve_requested_docs_rows(
    final_rows: List[Dict[str, Any]],
    docs_rows: List[Dict[str, Any]],
    *,
    limit: int,
    date_to: Optional[str] = None,
) -> Tuple[List[Dict[str, Any]], int]:
    """Ensure a requested docs lane does not disappear in mixed-store recall.

    Vector rows can all score 1.0 after recall normalization; when docs were
    explicitly planned, dropping every docs row hides exact project-log evidence
    even though the store returned it. Preserve a bounded docs evidence lane
    instead of letting score ties crowd it out.
    """
    if limit <= 0 or not docs_rows:
        return final_rows, 0

    target_date = _normalize_recall_date_bound(date_to) if date_to else None
    out = list(final_rows)
    if target_date:
        out = [
            row for row in out
            if not _is_docs_recall_row(row) or _docs_row_latest_iso_date(row) == target_date
        ]

    seen = {_recall_row_identity(row) for row in out}
    candidate_pool = [
        row
        for row in docs_rows
        if isinstance(row, dict)
        and str(row.get("text") or "").strip()
        and _recall_row_identity(row) not in seen
    ]
    if not candidate_pool:
        return final_rows, 0

    existing_docs = [row for row in out if _is_docs_recall_row(row)]
    existing_target_docs = [
        row for row in existing_docs
        if target_date and _docs_row_latest_iso_date(row) == target_date
    ]
    target_docs_count = 2 if target_date else 1
    if target_date and len(existing_target_docs) >= target_docs_count:
        return final_rows, 0
    if not target_date and len(existing_docs) >= target_docs_count:
        return final_rows, 0

    if target_date:
        candidate_pool.sort(
            key=lambda row: (
                1 if _docs_row_latest_iso_date(row) == target_date else 0,
                str(_docs_row_latest_iso_date(row) or ""),
                float((row or {}).get("similarity") or 0.0),
            ),
            reverse=True,
        )

    preserved = 0
    for candidate in candidate_pool:
        if sum(1 for row in out if _is_docs_recall_row(row)) >= target_docs_count:
            break
        if len(out) < limit:
            out.append(candidate)
            preserved += 1
            continue
        replace_idx = next((idx for idx in range(len(out) - 1, -1, -1) if not _is_docs_recall_row(out[idx])), None)
        if replace_idx is None:
            break
        out.pop(replace_idx)
        out.append(candidate)
        preserved += 1
    return (out[:limit], preserved) if preserved else (final_rows, 0)


def _is_graph_fact_cluster_row(row: Dict[str, Any]) -> bool:
    return str((row or {}).get("via") or "") == "graph_fact_cluster"


def _is_compact_graph_relation_row(row: Dict[str, Any]) -> bool:
    if not isinstance(row, dict):
        return False
    if str(row.get("via") or "") not in {"graph_relation_summary", "graph_fact_cluster"}:
        return False
    return int(row.get("relation_evidence_count") or 0) > 0


def _compact_graph_relation_query_overlap(query: str, row: Dict[str, Any]) -> int:
    query_tokens = {
        token.lower()
        for token in re.findall(r"\w+", str(query or ""), flags=re.UNICODE)
        if len(token) >= 4
    }
    if not query_tokens:
        return 0
    row_text = str((row or {}).get("text") or "")
    compact_relation_text = str((row or {}).get("compact_relation_query_text") or "").strip()
    if compact_relation_text and str((row or {}).get("via") or "") == "graph_fact_cluster":
        row_text = compact_relation_text
    row_tokens = {
        token.lower()
        for token in re.findall(r"\w+", row_text, flags=re.UNICODE)
        if len(token) >= 4
    }
    return len(query_tokens & row_tokens)


def _prioritize_compact_graph_relation_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> List[Dict[str, Any]]:
    """Keep compact structured graph evidence near first-order transcript hits."""
    if not rows:
        return rows
    candidates: List[Tuple[int, int, Dict[str, Any]]] = []
    for idx, row in enumerate(rows):
        if not _is_compact_graph_relation_row(row):
            continue
        overlap = _compact_graph_relation_query_overlap(query, row)
        if overlap < 2:
            continue
        candidates.append((overlap, -idx, row))
    if not candidates:
        return rows
    candidates.sort(
        key=lambda item: (
            item[0],
            int((item[2] or {}).get("relation_support_count") or 0),
            float((item[2] or {}).get("similarity") or 0.0),
            item[1],
        ),
        reverse=True,
    )
    selected = candidates[0][2]
    selected_key = _rrf_recall_row_identity(selected)
    out = [
        row for row in rows
        if _rrf_recall_row_identity(row) != selected_key
    ]
    target_idx = 1 if out and _is_first_order_session_source_row(out[0]) else 0
    out.insert(target_idx, selected)
    return out[: max(1, int(limit or 1))]


def _graph_fact_cluster_query_overlap(query: str, row: Dict[str, Any]) -> int:
    query_tokens = {
        token.lower()
        for token in re.findall(r"\w+", str(query or ""), flags=re.UNICODE)
        if len(token) >= _recall_query_term_min_len(token)
    }
    if not query_tokens:
        return 0
    row_tokens = {
        token.lower()
        for token in re.findall(r"\w+", str((row or {}).get("text") or ""), flags=re.UNICODE)
        if len(token) >= _recall_query_term_min_len(token)
    }
    return len(query_tokens & row_tokens)


def _prioritize_graph_fact_cluster_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> List[Dict[str, Any]]:
    """Keep query-matching graph clusters near first-order transcript hits."""
    if not rows:
        return rows
    candidates: List[Tuple[int, int, Dict[str, Any]]] = []
    for idx, row in enumerate(rows):
        if not _is_graph_fact_cluster_row(row):
            continue
        overlap = _graph_fact_cluster_query_overlap(query, row)
        if overlap < 2:
            continue
        candidates.append((overlap, -idx, row))
    if not candidates:
        return rows
    candidates.sort(
        key=lambda item: (
            item[0],
            int((item[2] or {}).get("cluster_size") or 0),
            float((item[2] or {}).get("similarity") or 0.0),
            item[1],
        ),
        reverse=True,
    )
    selected = candidates[0][2]
    selected_key = _rrf_recall_row_identity(selected)
    out = [
        row for row in rows
        if _rrf_recall_row_identity(row) != selected_key
    ]
    target_idx = 1 if out and _is_first_order_session_source_row(out[0]) else 0
    out.insert(target_idx, selected)
    return out[: max(1, int(limit or 1))]


def _interpret_selected_graph_fact_cluster_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    fast_mode: bool,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Add one query-focused LLM interpretation to a large graph fact cluster.

    Graph clusters are first-order evidence packets. In deliberate recall, one
    compact interpretation can help the answerer use a broad cluster without
    pushing benchmark-specific lexical semantics into deterministic ranking.
    """
    meta: Dict[str, Any] = {
        "enabled": bool(not fast_mode),
        "attempted": 0,
        "annotated": 0,
    }
    if fast_mode or not rows:
        return rows, meta

    selected_idx: Optional[int] = None
    selected_row: Optional[Dict[str, Any]] = None
    for idx, row in enumerate(rows):
        if not isinstance(row, dict) or not _is_graph_fact_cluster_row(row):
            continue
        try:
            cluster_size = int(row.get("cluster_size") or 0)
        except (TypeError, ValueError):
            cluster_size = 0
        if cluster_size < _GRAPH_FACT_CLUSTER_INTERPRETATION_MIN_CLUSTER_SIZE:
            continue
        text = str(row.get("text") or "").strip()
        if not text:
            continue
        query_overlap = _graph_fact_cluster_query_overlap(query, row)
        source_name = str(row.get("source_name") or "").strip()
        source_name_hit = bool(source_name and _text_mentions_graph_anchor(query, source_name))
        if (
            query_overlap < _GRAPH_FACT_CLUSTER_INTERPRETATION_MIN_QUERY_OVERLAP
            and not source_name_hit
        ):
            continue
        selected_idx = idx
        selected_row = row
        break
    if selected_idx is None or selected_row is None:
        meta["skipped_reason"] = "no_large_graph_cluster"
        return rows, meta
    if not _HAS_LLM_CLIENTS:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Graph fact cluster interpretation unavailable while failHard is enabled "
                "(no_llm_clients)"
            )
        logger.warning("Graph fact cluster interpretation unavailable; leaving cluster unchanged")
        meta["skipped_reason"] = "no_llm_clients"
        return rows, meta

    evidence = str(selected_row.get("text") or "").strip()
    if len(evidence) > _GRAPH_FACT_CLUSTER_INTERPRETATION_MAX_EVIDENCE_CHARS:
        evidence = evidence[:_GRAPH_FACT_CLUSTER_INTERPRETATION_MAX_EVIDENCE_CHARS].rsplit("\n", 1)[0].strip()
    if not evidence:
        meta["skipped_reason"] = "empty_evidence"
        return rows, meta

    prompt = (
        "Write one concise query-focused interpretation from first-order graph evidence.\n"
        "Rules:\n"
        "- Use only the evidence below; do not invent facts, entities, dates, counts, or preferences.\n"
        "- Only summarize affirmative evidence that helps answer or narrow the query.\n"
        "- Preserve uncertainty when the evidence is incomplete or ambiguous.\n"
        "- Do not claim that something never happened or that no evidence exists; this cluster is not the full memory.\n"
        "- If the evidence does not affirmatively help answer or narrow the query, set supported=false and interpretation=\"\".\n"
        "- Respond in the same language as the Query.\n"
        f"- Keep interpretation under {_GRAPH_FACT_CLUSTER_INTERPRETATION_MAX_CHARS} characters.\n"
        "- Return JSON only: {\"supported\": true|false, \"interpretation\": \"...\"}\n\n"
        f"Query:\n{str(query or '').strip()}\n\n"
        f"First-order graph evidence:\n{evidence}"
    )
    meta["attempted"] = 1
    try:
        result, _duration = call_fast_reasoning(
            prompt=prompt,
            max_tokens=_GRAPH_FACT_CLUSTER_INTERPRETATION_MAX_TOKENS,
            timeout=_GRAPH_FACT_CLUSTER_INTERPRETATION_TIMEOUT_S,
            system_prompt=(
                "You produce a strict evidence-grounded recall interpretation. "
                "Match the user's query language. "
                "Return only the requested JSON object."
            ),
            max_retries=0,
        )
        if not result:
            if _is_fail_hard_mode():
                raise RuntimeError("graph fact cluster interpretation returned no result")
            meta["skipped_reason"] = "empty_result"
            return rows, meta
        parsed = parse_json_response(result)
        if not isinstance(parsed, dict):
            if _is_fail_hard_mode():
                raise RuntimeError("graph fact cluster interpretation returned invalid JSON payload")
            meta["skipped_reason"] = "invalid_payload"
            return rows, meta
        if "supported" not in parsed:
            if _is_fail_hard_mode():
                raise RuntimeError("graph fact cluster interpretation missing supported flag")
            meta["skipped_reason"] = "missing_supported"
            return rows, meta
        if parsed.get("supported") is not True:
            meta["skipped_reason"] = "unsupported_evidence"
            return rows, meta
        interpretation = ""
        interpretation = " ".join(str(parsed.get("interpretation") or "").split()).strip()
        if not interpretation:
            if _is_fail_hard_mode():
                raise RuntimeError("graph fact cluster interpretation returned empty interpretation")
            meta["skipped_reason"] = "empty_interpretation"
            return rows, meta
        interpretation = _sanitize_for_context(interpretation)
        if len(interpretation) > _GRAPH_FACT_CLUSTER_INTERPRETATION_MAX_CHARS:
            interpretation = interpretation[:_GRAPH_FACT_CLUSTER_INTERPRETATION_MAX_CHARS].rsplit(" ", 1)[0].strip()
        if not interpretation:
            if _is_fail_hard_mode():
                raise RuntimeError("graph fact cluster interpretation became empty after truncation")
            meta["skipped_reason"] = "empty_interpretation"
            return rows, meta
        out = list(rows)
        annotated = dict(selected_row)
        annotated["graph_cluster_interpretation"] = interpretation
        annotated["graph_cluster_interpretation_model"] = "fast_reasoning"
        annotated["text"] = _sanitize_for_context(
            "Query-focused interpretation from first-order graph evidence:\n"
            f"- {interpretation}\n\n"
            f"{str(selected_row.get('text') or '').strip()}"
        )
        out[selected_idx] = annotated
        meta["annotated"] = 1
        meta["cluster_id"] = str(selected_row.get("id") or "")
        return out, meta
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Graph fact cluster interpretation failed while failHard is enabled "
                f"({type(exc).__name__}: {exc})"
            ) from exc
        logger.warning("Graph fact cluster interpretation failed; leaving cluster unchanged: %s", exc)
        meta["skipped_reason"] = "exception"
        meta["error_type"] = type(exc).__name__
        return rows, meta


def _preserve_compact_graph_relation_summary_row(
    query: str,
    final_rows: List[Dict[str, Any]],
    named_batches: List[Tuple[str, List[Dict[str, Any]]]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], int]:
    """Surface compact graph relation evidence when RRF truncates it out."""
    if limit <= 0 or not final_rows or not named_batches:
        return final_rows, 0
    existing_keys = {_rrf_recall_row_identity(row) for row in final_rows if isinstance(row, dict)}
    candidates: List[Tuple[int, int, Dict[str, Any]]] = []
    for branch_name, branch_rows in named_batches:
        if str(branch_name or "").strip() != "graph":
            continue
        for idx, row in enumerate(branch_rows or []):
            if not isinstance(row, dict):
                continue
            if str(row.get("via") or "") != "graph_relation_summary":
                continue
            key = _rrf_recall_row_identity(row)
            if key in existing_keys:
                continue
            overlap = _compact_graph_relation_query_overlap(query, row)
            if overlap < 2:
                continue
            candidates.append((overlap, -idx, row))
    if not candidates:
        return final_rows, 0
    candidates.sort(
        key=lambda item: (
            item[0],
            int((item[2] or {}).get("relation_support_count") or 0),
            float((item[2] or {}).get("similarity") or 0.0),
            item[1],
        ),
        reverse=True,
    )
    selected = dict(candidates[0][2])
    selected["store_plan_preserved_branch_top"] = "graph"
    selected["store_plan_preserved_reason"] = "compact_graph_relation_summary"
    out = list(final_rows[: max(1, int(limit or 1))])
    target_idx = 1 if out and _is_first_order_session_source_row(out[0]) else 0
    if len(out) < max(1, int(limit or 1)):
        out.insert(target_idx, selected)
        return out[: max(1, int(limit or 1))], 1
    replace_idx = next(
        (
            idx
            for idx in range(len(out) - 1, -1, -1)
            if not _is_first_order_session_source_row(out[idx])
        ),
        len(out) - 1,
    )
    out.pop(replace_idx)
    out.insert(min(target_idx, len(out)), selected)
    return out[: max(1, int(limit or 1))], 1


def _preserve_graph_fact_cluster_row(
    final_rows: List[Dict[str, Any]],
    candidate_rows: List[Dict[str, Any]],
    *,
    limit: int,
) -> Tuple[List[Dict[str, Any]], int]:
    """Keep one compact graph cluster when RRF would otherwise truncate it out."""
    if limit <= 0 or not candidate_rows:
        return final_rows, 0
    if any(_is_graph_fact_cluster_row(row) for row in final_rows):
        return final_rows, 0
    seen = {_recall_row_identity(row) for row in final_rows}
    clusters = [
        row
        for row in candidate_rows
        if isinstance(row, dict)
        and _is_graph_fact_cluster_row(row)
        and _recall_row_identity(row) not in seen
        and int(row.get("cluster_size") or 0) >= 4
    ]
    if not clusters:
        return final_rows, 0
    clusters.sort(
        key=lambda row: (
            float(row.get("rrf_score") or 0.0),
            float(row.get("similarity") or 0.0),
            int(row.get("cluster_size") or 0),
        ),
        reverse=True,
    )
    out = list(final_rows)
    candidate = clusters[0]
    if len(out) < limit:
        out.append(candidate)
        return out[:limit], 1

    def _replaceable(row: Dict[str, Any]) -> bool:
        category = str((row or {}).get("category") or "").strip().lower()
        source_type = str((row or {}).get("source_type") or "").strip().lower()
        if category in {"session_chunk", "docs"} or source_type in {"session_chunk", "docs"}:
            return False
        return not _is_graph_fact_cluster_row(row)

    replace_idx = next((idx for idx in range(len(out) - 1, -1, -1) if _replaceable(out[idx])), None)
    if replace_idx is None:
        replace_idx = len(out) - 1
    out[replace_idx] = candidate
    return out[:limit], 1


def _resolve_reranker_enabled(use_reranker: Optional[bool], config_retrieval=None) -> bool:
    reranker_enabled = False
    if config_retrieval is not None:
        try:
            reranker_enabled = bool(getattr(config_retrieval, "reranker_enabled", False))
        except Exception:
            reranker_enabled = False
    if use_reranker is not None:
        reranker_enabled = bool(use_reranker)
    return reranker_enabled


def _apply_post_merge_rank_refinement(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    limit: int,
    use_reranker: Optional[bool],
    include_mmr: bool,
    config_retrieval=None,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Apply one reranker/MMR pass to merged multi-branch candidates."""
    if not rows:
        return [], {
            "applied": False,
            "candidate_count": 0,
            "reranker_enabled": False,
            "reranker_ms": 0,
            "mmr_enabled": False,
            "mmr_ms": 0,
            "total_ms": 0,
        }

    reranker_enabled = _resolve_reranker_enabled(use_reranker, config_retrieval)
    mmr_enabled = bool(include_mmr)
    if not reranker_enabled and not mmr_enabled:
        return rows[: max(1, limit)], {
            "applied": False,
            "candidate_count": len(rows),
            "reranker_enabled": False,
            "reranker_ms": 0,
            "mmr_enabled": False,
            "mmr_ms": 0,
            "total_ms": 0,
        }

    rows_with_ids: List[Dict[str, Any]] = []
    idless_rows: List[Dict[str, Any]] = []
    for row in rows:
        rid = str((row or {}).get("id") or "").strip()
        if rid:
            rows_with_ids.append(row)
        else:
            idless_rows.append(row)

    if not rows_with_ids:
        return rows[: max(1, limit)], {
            "applied": False,
            "candidate_count": len(rows),
            "reranker_enabled": reranker_enabled,
            "reranker_ms": 0,
            "mmr_enabled": mmr_enabled,
            "mmr_ms": 0,
            "total_ms": 0,
        }

    graph = get_graph()
    candidate_ids = [str(row.get("id")) for row in rows_with_ids]
    placeholders = ",".join("?" * len(candidate_ids))
    node_map: Dict[str, Node] = {}
    with graph._get_conn() as conn:
        fetched = conn.execute(f"SELECT * FROM nodes WHERE id IN ({placeholders})", candidate_ids).fetchall()
        for fetched_row in fetched:
            node = graph._row_to_node(fetched_row)
            node_map[node.id] = node

    ranked: List[tuple] = []
    retained_rows: Dict[str, Dict[str, Any]] = {}
    for row in rows_with_ids:
        rid = str(row.get("id"))
        node = node_map.get(rid)
        if node is None:
            idless_rows.append(row)
            continue
        retained_rows[rid] = row
        ranked.append((node, float(row.get("similarity", 0.0) or 0.0)))

    if not ranked:
        out = list(idless_rows)
        out.sort(key=lambda item: float(item.get("similarity", 0.0)), reverse=True)
        return out[: max(1, limit)], {
            "applied": False,
            "candidate_count": len(rows),
            "reranker_enabled": reranker_enabled,
            "reranker_ms": 0,
            "mmr_enabled": mmr_enabled,
            "mmr_ms": 0,
            "total_ms": 0,
        }

    started = time.monotonic()
    reranker_ms = 0
    mmr_ms = 0

    if reranker_enabled:
        _t0 = time.monotonic()
        ranked = _rerank_with_cross_encoder(query, ranked, config_retrieval)
        reranker_ms = round((time.monotonic() - _t0) * 1000)

    if mmr_enabled:
        _mmr_lambda, _mmr_candidate_cap = _resolve_mmr_settings(
            config_retrieval,
            limit=limit,
            default_candidate_cap=max(limit, 12),
        )
        if len(ranked) > _mmr_candidate_cap:
            ranked = ranked[:_mmr_candidate_cap]
        _t0 = time.monotonic()
        ranked = _apply_mmr(ranked, graph, limit, mmr_lambda=_mmr_lambda)
        mmr_ms = round((time.monotonic() - _t0) * 1000)
    else:
        ranked = ranked[: max(1, limit)]

    ordered_rows: List[Dict[str, Any]] = []
    seen = set()
    for node, score in ranked:
        row = dict(retained_rows.get(node.id) or {})
        if not row:
            continue
        row["similarity"] = round(float(score), 3)
        ordered_rows.append(row)
        seen.add(node.id)

    if len(ordered_rows) < limit:
        leftovers = [row for row in rows_with_ids if str(row.get("id")) not in seen]
        leftovers.sort(key=lambda item: float(item.get("similarity", 0.0)), reverse=True)
        ordered_rows.extend(leftovers[: max(0, limit - len(ordered_rows))])

    if idless_rows:
        idless_rows.sort(key=lambda item: float(item.get("similarity", 0.0)), reverse=True)
        ordered_rows.extend(idless_rows)

    ordered_rows = ordered_rows[: max(1, limit)]
    return ordered_rows, {
        "applied": True,
        "candidate_count": len(rows),
        "reranker_enabled": reranker_enabled,
        "reranker_ms": reranker_ms,
        "mmr_enabled": mmr_enabled,
        "mmr_ms": mmr_ms,
        "total_ms": round((time.monotonic() - started) * 1000),
    }


def _extract_recall_meta(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Return shared recall metadata attached to a recall result batch."""
    for row in results or []:
        if isinstance(row, dict) and isinstance(row.get("_recall_meta"), dict):
            return dict(row["_recall_meta"])
    return {}


def _attach_recall_meta(results: List[Dict[str, Any]], meta: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Attach the same recall metadata to each result row."""
    for row in results or []:
        if isinstance(row, dict):
            row["_recall_meta"] = dict(meta)
    return results


def _strip_recall_transport_meta_from_output_rows(rows: Any) -> Any:
    """Remove internal recall transport metadata from public JSON result rows."""
    if not isinstance(rows, list):
        return rows
    output: List[Any] = []
    for row in rows:
        if isinstance(row, dict) and "_recall_meta" in row:
            clean = dict(row)
            clean.pop("_recall_meta", None)
            output.append(clean)
        else:
            output.append(row)
    return output


def _print_recall_results(results: List[Dict[str, Any]]) -> None:
    """Render recall results in the legacy plain-text CLI format."""
    if not results:
        print("No memories found")
        return
    for r in results:
        source = str(r.get("source") or "").strip()
        chunk_index = r.get("chunk_index")
        fallback_id = f"{source}:{chunk_index}" if source and chunk_index is not None else ""
        result_id = str(r.get("id") or fallback_id)
        text = str(r.get("text") or r.get("content") or "")
        category = str(r.get("category") or ("docs" if source else "memory"))
        similarity = float(r.get("similarity", r.get("score", 0.0)) or 0.0)
        flags = []
        if r.get('verified'):
            flags.append('V')
        if r.get('pinned'):
            flags.append('P')
        flag_str = f"[{''.join(flags)}]" if flags else ""
        conf = r.get('extraction_confidence', 0.5)
        created = r.get('created_at', '')
        source_date = r.get('source_date', '')
        privacy = r.get('privacy', 'shared')
        owner = r.get('owner_id', '')
        source_suffix = f"|source_date:{source_date}" if source_date else ""
        if _is_session_chunk_output_row(r):
            print(f"[{similarity:.2f}] [{category}]{flag_str}[C:{conf:.1f}] {text}")
        else:
            print(f"[{similarity:.2f}] [{category}]{flag_str}[C:{conf:.1f}] {text} |ID:{result_id}|T:{created}{source_suffix}|P:{privacy}|O:{owner}")
        graph_path = str(r.get("graph_path") or "").strip()
        if graph_path:
            print(f"  [graph_path] {graph_path}")
        if r.get('_debug'):
            d = r['_debug']
            print(f"  [debug] raw_quality={d['raw_quality_score']} composite={d['composite_score']} intent={d['intent']} type_boost={d['type_boost']} conf={d['confidence']} access={d['access_count']} confirms={d['confirmation_count']}")


def _summarize_phase_stats(phase_values: List[float]) -> Dict[str, int]:
    """Summarize a list of phase durations in ms."""
    if not phase_values:
        return {"count": 0, "sum_ms": 0, "avg_ms": 0, "min_ms": 0, "max_ms": 0, "spread_ms": 0}
    values = [max(0, int(round(v))) for v in phase_values]
    return {
        "count": len(values),
        "sum_ms": sum(values),
        "avg_ms": round(sum(values) / len(values)),
        "min_ms": min(values),
        "max_ms": max(values),
        "spread_ms": max(values) - min(values),
    }


def _summarize_result_coverage(results: List[Dict[str, Any]]) -> Dict[str, int]:
    """Summarize result breadth so quality-gate behavior is auditable."""
    categories = set()
    projects = set()
    source_types = set()
    domains = set()
    temporal_hits = 0
    total_chars = 0

    for row in results or []:
        if not isinstance(row, dict):
            continue
        category = str(row.get("category") or "").strip()
        if category:
            categories.add(category)
        project = str(row.get("project") or "").strip()
        if project:
            projects.add(project)
        source_type = str(row.get("source_type") or "").strip()
        if source_type:
            source_types.add(source_type)
        for domain in row.get("domains") or []:
            clean = str(domain or "").strip()
            if clean:
                domains.add(clean)
        if row.get("created_at") or row.get("valid_from") or row.get("valid_until"):
            temporal_hits += 1
        total_chars += len(str(row.get("text") or ""))

    result_count = len(results or [])
    return {
        "result_count": result_count,
        "unique_categories": len(categories),
        "unique_projects": len(projects),
        "unique_source_types": len(source_types),
        "unique_domains": len(domains),
        "temporal_hits": temporal_hits,
        "text_chars": total_chars,
        "avg_text_chars": round(total_chars / result_count) if result_count else 0,
    }


_QUERY_STOPWORDS = {
    "a", "about", "an", "and", "are", "as", "at", "be", "by", "did", "do", "does", "for",
    "from", "had", "has", "have", "how", "i", "if", "in", "is", "it", "its",
    "me", "my", "of", "on", "or", "our", "she", "so", "still", "tell", "that",
    "the", "their", "them", "there", "these", "they", "this", "to", "up", "was",
    "we", "what", "when", "where", "which", "who", "why", "with", "would", "yet",
    "know",
    "you", "your", "current", "currently", "latest", "most", "recent", "now",
}
_SHORT_SIGNAL_TOKENS = {"api", "app", "db", "ui", "ux", "sql", "mom", "dad", "dog", "a1c"}


def _extract_distinctive_query_terms(query: str, *, limit: int = 8) -> List[str]:
    tokens = re.findall(r"[\w][\w._-]*", str(query or "").lower(), flags=re.UNICODE)
    out: List[str] = []
    seen = set()
    for token in tokens:
        token = token.strip(".,;:!?\"'“”¿¡")
        if not token:
            continue
        if token in seen:
            continue
        if token in _QUERY_STOPWORDS:
            continue
        min_len = _recall_query_term_min_len(token)
        if len(token) < min_len and token not in _SHORT_SIGNAL_TOKENS:
            continue
        seen.add(token)
        out.append(token)
        if len(out) >= limit:
            break
    return out


def _extract_vocabulary_free_query_terms(query: str, *, limit: int = 8) -> List[str]:
    """Return overlap terms without language-specific stopword filtering."""
    tokens = re.findall(r"[\w][\w._-]*", str(query or "").lower(), flags=re.UNICODE)
    out: List[str] = []
    seen = set()
    for idx, token in enumerate(tokens):
        token = token.strip(".,;:!?\"'“”¿¡")
        if not token:
            continue
        if token in seen:
            continue
        # Length is a language-neutral noise floor; do not consult stopword
        # vocabularies here because deliberate recall already has LLM planning.
        min_len = _recall_query_term_min_len(token)
        if len(token) < min_len:
            continue
        if idx == 0 and token.isascii() and len(token) < 5:
            continue
        seen.add(token)
        out.append(token)
        if len(out) >= limit:
            break
    return out


def _extract_explicit_query_anchor_terms(query: str, *, limit: int = 4) -> List[str]:
    """Return explicit entity-like anchors from the original query text.

    These anchors are intentionally conservative. They are only used to keep
    named queries like "my dog <Name>" from being buried by hotter global
    profile/setup rows that do not mention the named entity at all.
    """
    tokens = re.findall(r"[\w][\w._'-]*", str(query or ""), flags=re.UNICODE)
    out: List[str] = []
    seen = set()
    sentence_starter_noise = {
        "what", "who", "where", "when", "why", "how", "if", "tell", "list", "name",
        "do", "does", "did", "is", "are", "can", "could", "would", "should",
        "que", "qué", "quien", "quién", "donde", "dónde", "cuando", "cuándo",
    }
    for idx, token in enumerate(tokens):
        token = token.strip(".,;:!?\"'“”¿¡")
        if not token:
            continue
        lower = token.lower()
        if lower.endswith(("'s", "’s")):
            lower = lower[:-2]
        if lower in seen:
            continue
        if lower in _QUERY_STOPWORDS:
            continue
        if idx == 0 and lower in sentence_starter_noise:
            continue
        if len(lower) < 3:
            continue
        if token[:1].isupper():
            seen.add(lower)
            out.append(lower)
        if len(out) >= limit:
            break
    return out


def _is_single_structural_exact_query(query: str) -> bool:
    """Return True for one-token exact codeword lookups.

    These queries are usually operational canaries or human-provided handles.
    They benefit from a bounded direct lookup path, not the full deliberate
    drill/reranker loop.
    """
    clean = " ".join(str(query or "").split()).strip()
    if not clean:
        return False
    tokens = re.findall(r"[\w][\w._'-]*", clean, flags=re.UNICODE)
    if len(tokens) != 1:
        return False
    token = tokens[0].strip(".,;:!?\"'“”¿¡").lower()
    if len(token) < 8:
        return False
    if not re.fullmatch(r"[a-z0-9][a-z0-9._'-]*", token):
        return False
    if not (re.search(r"[-._']", token) or re.search(r"\d", token)):
        return False
    alnum = re.sub(r"[^a-z0-9]", "", token)
    return len(alnum) >= 6


def _resolve_lexical_anchor_limit(query: str, config_retrieval: Any) -> int:
    """Resolve lexical anchor planner cap from config or query shape.

    Config override:
    - retrieval.lexical_anchor_limit > 0: use exact override (clamped 1..24)

    Adaptive default:
    - scales with explicit named-entity hints in the query
    - scales with query length to avoid clipping multi-entity lists
    - bounded by a safety ceiling to keep planner output manageable
    """
    cfg_limit = 0
    try:
        cfg_limit = int(getattr(config_retrieval, "lexical_anchor_limit", 0) or 0)
    except Exception:
        cfg_limit = 0
    if cfg_limit > 0:
        return max(1, min(24, cfg_limit))

    clean = str(query or "")
    explicit_count = len(_extract_explicit_query_anchor_terms(clean, limit=24))
    token_count = len(re.findall(r"[\w][\w._'-]*", clean, flags=re.UNICODE))
    size_hint = max(1, min(12, token_count // 4))
    adaptive_limit = max(2, explicit_count, size_hint)
    return min(16, adaptive_limit)


# Live Anthropic fast-model calls can exceed the old 2s cap under normal latency;
# r1420 hit failHard on lexical-anchor planning before this bounded 8s ceiling.
_LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS = 8000
_LEXICAL_ANCHOR_MAX_TIMEOUT_S = 8.0
_LEXICAL_ANCHOR_EXPLICIT_TIMEOUT_CAP_MS = 30000
_LEXICAL_ANCHOR_FAST_MAX_TIMEOUT_S = 0.75
_LEXICAL_ANCHOR_FAST_RESERVE_MS = 250
_LEXICAL_ANCHOR_DEFAULT_MAX_RETRIES = 1
_LEXICAL_ANCHOR_MAX_RETRIES_CEILING = 2
_LEXICAL_ANCHOR_RETRY_BASE_DELAY_S = 0.25
_DRILL_PLANNER_MAX_RETRIES_CEILING = 2
_DRILL_PLANNER_RETRY_BASE_DELAY_S = 0.25


def _resolve_lexical_anchor_max_retries(config_retrieval: Any) -> int:
    try:
        raw = getattr(
            config_retrieval,
            "lexical_anchor_max_retries",
            _LEXICAL_ANCHOR_DEFAULT_MAX_RETRIES,
        )
    except Exception:
        if _is_fail_hard_mode():
            raise
        raw = _LEXICAL_ANCHOR_DEFAULT_MAX_RETRIES
    try:
        return max(0, min(_LEXICAL_ANCHOR_MAX_RETRIES_CEILING, int(raw or 0)))
    except (TypeError, ValueError):
        return _LEXICAL_ANCHOR_DEFAULT_MAX_RETRIES


def _resolve_drill_planner_max_retries(max_retries: int) -> int:
    try:
        return max(0, min(_DRILL_PLANNER_MAX_RETRIES_CEILING, int(max_retries or 0)))
    except (TypeError, ValueError):
        return 0


def _is_lexical_anchor_retryable_exception(exc: BaseException) -> bool:
    current: Optional[BaseException] = exc
    seen: set[int] = set()
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        if isinstance(current, urllib.error.HTTPError):
            if current.code in {408, 429, 500, 502, 503, 504, 529}:
                return True
        elif isinstance(current, (TimeoutError, ConnectionError, OSError, urllib.error.URLError)):
            return True
        current = current.__cause__ or current.__context__
    return False


def _lexical_anchor_planner_timeout_s(
    planner_timeout_ms: int,
    *,
    fast_context: bool,
    timeout_ms: Optional[int],
) -> float:
    cap_s = _LEXICAL_ANCHOR_MAX_TIMEOUT_S
    if timeout_ms is not None and not fast_context:
        try:
            explicit_budget_s = max(0.2, float(timeout_ms) / 1000.0)
            if explicit_budget_s > _LEXICAL_ANCHOR_MAX_TIMEOUT_S:
                explicit_cap_s = max(
                    _LEXICAL_ANCHOR_MAX_TIMEOUT_S,
                    float(_LEXICAL_ANCHOR_EXPLICIT_TIMEOUT_CAP_MS) / 1000.0,
                )
                cap_s = min(explicit_cap_s, explicit_budget_s)
        except (TypeError, ValueError):
            pass
    if fast_context:
        cap_s = min(cap_s, _LEXICAL_ANCHOR_FAST_MAX_TIMEOUT_S)
        if timeout_ms is not None:
            try:
                budget_ms = max(200.0, float(timeout_ms) - _LEXICAL_ANCHOR_FAST_RESERVE_MS)
                cap_s = min(cap_s, budget_ms / 1000.0)
            except (TypeError, ValueError):
                pass
    try:
        requested_s = float(planner_timeout_ms) / 1000.0
    except (TypeError, ValueError):
        requested_s = cap_s
    return max(0.2, min(cap_s, requested_s))


def _plan_query_anchor_terms(
    query: str,
    *,
    limit: int = 4,
    timeout_s: float = _LEXICAL_ANCHOR_MAX_TIMEOUT_S,
    timeout_cap_s: Optional[float] = None,
    max_retries: int = 0,
) -> Tuple[List[str], Dict[str, Any]]:
    """Plan lexical anchor terms with a tiny LLM call.

    This keeps lexical anchoring in the model-driven lane for multilingual
    behavior instead of hard-coded language regex.
    """
    import time as _time

    started = _time.monotonic()
    clean = " ".join(str(query or "").split()).strip()
    limit = max(1, min(24, int(limit or 4)))
    effective_timeout_cap_s = _LEXICAL_ANCHOR_MAX_TIMEOUT_S
    if timeout_cap_s is not None:
        try:
            effective_timeout_cap_s = max(_LEXICAL_ANCHOR_MAX_TIMEOUT_S, float(timeout_cap_s))
        except Exception:
            effective_timeout_cap_s = _LEXICAL_ANCHOR_MAX_TIMEOUT_S
    timeout_s = max(0.2, min(effective_timeout_cap_s, float(timeout_s or _LEXICAL_ANCHOR_MAX_TIMEOUT_S)))
    max_retries = max(0, int(max_retries or 0))
    timeout_ms = int(round(timeout_s * 1000))
    meta: Dict[str, Any] = {
        "used_llm": False,
        "bailout_reason": None,
        "elapsed_ms": 0,
        "timeout_ms": timeout_ms,
        "attempts": 0,
        "max_retries": max_retries,
        "anchor_count": 0,
        "limit": limit,
        "anchors": [],
        "source": "none",
    }

    def _finish(anchors: List[str], bailout_reason: Optional[str], source: str) -> Tuple[List[str], Dict[str, Any]]:
        meta["bailout_reason"] = bailout_reason
        meta["elapsed_ms"] = round((_time.monotonic() - started) * 1000)
        meta["anchor_count"] = len(anchors)
        meta["anchors"] = list(anchors)
        meta["source"] = source
        return anchors, meta

    if not clean:
        return _finish([], "empty_query", "none")
    if not _HAS_LLM_CLIENTS:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Lexical anchor planner unavailable while fail-hard mode is enabled "
                "(no_llm_clients)."
            )
        logger.warning(
            "Recall lexical anchor planner unavailable; proceeding without lexical anchors"
        )
        return _finish([], "no_llm_clients", "none")

    lexical_candidates: List[str] = []
    lexical_seen: set[str] = set()
    for candidate in (
        _extract_explicit_query_anchor_terms(clean, limit=24)
        + _extract_distinctive_query_terms(clean, limit=24)
    ):
        norm = " ".join(str(candidate or "").split()).strip().lower()
        if not norm or norm in lexical_seen:
            continue
        lexical_seen.add(norm)
        lexical_candidates.append(norm)
        if len(lexical_candidates) >= 24:
            break
    candidate_text = ", ".join(lexical_candidates) if lexical_candidates else "(none)"

    structural_anchors: List[str] = []
    structural_seen: set[str] = set()
    for candidate in lexical_candidates:
        norm = " ".join(str(candidate or "").split()).strip().lower()
        if (
            len(norm) >= 8
            and " " not in norm
            and re.search(r"[\d._/-]", norm)
            and norm not in structural_seen
        ):
            structural_seen.add(norm)
            structural_anchors.append(norm)
            if len(structural_anchors) >= limit:
                break
    if structural_anchors:
        return _finish(structural_anchors, "structural_exact_anchor", "deterministic")

    prompt = (
        "Extract high-precision lexical anchors from this recall query.\n"
        "Rules:\n"
        '- Return JSON only: {"anchors": ["..."]}\n'
        f"- Return at most {limit} anchors.\n"
        "- Keep anchors in the same language and script as the query.\n"
        "- Do not translate query content.\n"
        "- Be strict: include only concrete entities or distinctive noun phrases likely to appear verbatim in memory text.\n"
        "- Prefer anchors from the candidate list below.\n"
        "- Only add anchors outside the candidate list when they appear verbatim in the query and are concrete.\n"
        "- For list-style queries with multiple named entities, include each concrete name/phrase up to the limit.\n"
        "- Exclude generic words (for example: name, live, current, remember, know, happened, project, work).\n"
        "- Exclude question starters, helper verbs, and broad filler terms.\n"
        "- If the query has no concrete disambiguating anchors, return an empty list.\n"
        "- Preserve subject/object and ownership directionality.\n\n"
        f"Candidate anchors: {candidate_text}\n\n"
        f"Query: {clean}"
    )

    try:
        meta["used_llm"] = True
        result = None
        for attempt in range(max_retries + 1):
            meta["attempts"] = attempt + 1
            try:
                result, _ = call_fast_reasoning(
                    prompt=prompt,
                    max_tokens=_LEXICAL_ANCHOR_JSON_PLANNER_MAX_TOKENS,
                    timeout=timeout_s,
                    system_prompt=(
                        "You output exactly one compact JSON object for lexical anchor extraction. "
                        "No markdown, prose, explanation, or reasoning."
                    ),
                    max_retries=0,
                )
                break
            except Exception as call_exc:
                if attempt >= max_retries or not _is_lexical_anchor_retryable_exception(call_exc):
                    raise
                delay_s = min(1.0, _LEXICAL_ANCHOR_RETRY_BASE_DELAY_S * (2 ** attempt))
                logger.warning(
                    "Recall lexical anchor planner retryable provider error; "
                    "attempt %s/%s failed, retrying in %.2fs: %s",
                    attempt + 1,
                    max_retries + 1,
                    delay_s,
                    call_exc,
                )
                _time.sleep(delay_s)
        if result is None:
            if _is_fail_hard_mode():
                raise RuntimeError("lexical anchor planner returned no result")
            logger.warning(
                "Recall lexical anchor planner returned no result; proceeding without lexical anchors"
            )
            return _finish([], "planner_returned_none", "none")
        parsed = parse_json_response(result)
        anchors_raw = parsed.get("anchors") if isinstance(parsed, dict) else None
        if not isinstance(anchors_raw, list):
            if _is_fail_hard_mode():
                raise RuntimeError("lexical anchor planner returned invalid JSON payload")
            logger.warning(
                "Recall lexical anchor planner returned invalid payload; proceeding without lexical anchors"
            )
            return _finish([], "invalid_payload", "none")

        anchors: List[str] = []
        seen = set()
        query_lower = clean.lower()
        candidate_set = set(lexical_candidates)

        def _appears_in_query(term: str) -> bool:
            normalized = " ".join(str(term or "").split()).strip().lower()
            if not normalized:
                return False
            if normalized in query_lower:
                return True
            pattern = rf"(?<!\w){re.escape(normalized)}(?!\w)"
            return bool(re.search(pattern, query_lower, flags=re.UNICODE))

        def _composed_of_candidates(term: str) -> bool:
            bridge_terms = {
                "a", "an", "and", "de", "del", "des", "do", "dos", "da", "das",
                "di", "du", "e", "el", "for", "in", "la", "las", "le", "les",
                "los", "of", "on", "or", "the", "to", "with", "y",
            }
            pieces = [
                re.sub(r"(?:['’]s)$", "", piece.lower())
                for piece in re.findall(r"[\w][\w._'-]*", term, flags=re.UNICODE)
            ]
            pieces = [piece for piece in pieces if piece]
            if not pieces:
                return False
            significant = [piece for piece in pieces if piece not in bridge_terms]
            return bool(significant) and all(
                piece in candidate_set or piece in bridge_terms
                for piece in pieces
            )

        def _anchor_piece_min_len(term: str) -> int:
            return 2 if _has_compact_unicode_char(term) else 3

        for raw in anchors_raw:
            term = " ".join(str(raw or "").split()).strip().strip("\"'")
            if not term:
                continue
            lower = term.lower()
            if lower in seen:
                continue
            if len(lower) < 2:
                continue
            if lower in _QUERY_STOPWORDS:
                continue
            # Keep the planner strict: when candidates are available, anchors must
            # resolve to candidate tokens. For multilingual/sparse candidate sets,
            # allow exact query spans.
            if candidate_set:
                if lower not in candidate_set and not _composed_of_candidates(lower):
                    continue
            elif not _appears_in_query(lower):
                continue
            pieces = re.findall(r"[\w][\w._'-]*", lower, flags=re.UNICODE)
            if pieces and all(
                (piece in _QUERY_STOPWORDS or len(piece) < _anchor_piece_min_len(piece))
                for piece in pieces
            ):
                continue
            seen.add(lower)
            anchors.append(lower)
            if len(anchors) >= limit:
                break

        # Keep a deterministic floor so English quality does not collapse while
        # LLM lexical planning expands multilingual coverage.
        explicit_floor: List[str] = []
        explicit_seen: set[str] = set()
        for candidate in _extract_explicit_query_anchor_terms(clean, limit=24):
            norm = " ".join(str(candidate or "").split()).strip().strip(".,;:!?\"'").lower()
            if not norm or norm in explicit_seen:
                continue
            explicit_seen.add(norm)
            explicit_floor.append(norm)
            if len(explicit_floor) >= 24:
                break

        distinctive_floor: List[str] = []
        if len(anchors) <= 1 and len(explicit_floor) <= 1:
            # Sparse-anchor recovery: allow one additional distinctive token
            # when LLM output is too narrow.
            floor_noise = {
                "about", "going", "how", "know", "live", "now", "que", "qué", "recall",
                "remember", "recuerdas", "tell", "when", "where", "who", "why", "what",
            }
            for candidate in _extract_distinctive_query_terms(clean, limit=24):
                norm = " ".join(str(candidate or "").split()).strip().lower()
                if not norm or norm in floor_noise or norm in explicit_seen:
                    continue
                distinctive_floor.append(norm)
                break

        deterministic_floor = explicit_floor + distinctive_floor
        final_anchors: List[str] = []
        final_seen = set()

        def _is_covered_by_existing(term: str, items: List[str]) -> bool:
            for item in items:
                if _text_contains_anchor_term(item, term):
                    return True
            return False

        for term in anchors:
            lower = " ".join(str(term or "").split()).strip().lower()
            if not lower or lower in final_seen:
                continue
            final_seen.add(lower)
            final_anchors.append(lower)
            if len(final_anchors) >= limit:
                break

        for term in deterministic_floor:
            lower = " ".join(str(term or "").split()).strip().strip(".,;:!?\"'").lower()
            if not lower or lower in final_seen:
                continue
            if lower in {"i", "im", "i'm", "i’m", "ive", "i've", "i’ve", "id", "i'd", "i’d", "ill", "i'll", "i’ll"}:
                continue
            if len(lower) < _anchor_piece_min_len(lower):
                continue
            if lower in _QUERY_STOPWORDS:
                continue
            pieces = re.findall(r"[\w][\w._'-]*", lower, flags=re.UNICODE)
            if pieces and all(
                (piece in _QUERY_STOPWORDS or len(piece) < _anchor_piece_min_len(piece))
                for piece in pieces
            ):
                continue
            if _is_covered_by_existing(lower, anchors):
                continue
            final_seen.add(lower)
            final_anchors.append(lower)
            if len(final_anchors) >= limit:
                break

        if explicit_floor:
            explicit_set = set(explicit_floor)
            ordered: List[str] = []
            ordered_seen = set()
            for term in final_anchors:
                if term in explicit_set and term not in ordered_seen:
                    ordered_seen.add(term)
                    ordered.append(term)
            for term in final_anchors:
                if term not in ordered_seen:
                    ordered_seen.add(term)
                    ordered.append(term)
            final_anchors = ordered

        return _finish(final_anchors[:limit], None, "llm")
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Lexical anchor planner failed while fail-hard mode is enabled "
                f"(timeout_ms={timeout_ms}, max_retries={max_retries}, cause={type(exc).__name__}: {exc})"
            ) from exc
        logger.warning(
            "Recall lexical anchor planner failed; proceeding without lexical anchors: %s",
            exc,
        )
        return _finish([], "planner_exception", "none")


def _derive_query_requirements(
    query: str,
    intent: str = "GENERAL",
    *,
    include_relation_keywords: bool = True,
) -> Dict[str, Any]:
    query_text = str(query or "")
    lower = _unicode_casefold(query_text)
    query_terms = _extract_distinctive_query_terms(query)
    relation_matches = _relation_matches_for_query(query) if include_relation_keywords else []
    graph_like = bool(relation_matches)
    assistant_like = bool(re.search(r"\b(agent|assistant|ai|ki|ia|ии)\b", lower))
    current_like = False
    temporal_like = bool(
        intent == "WHEN"
        or re.search(r"(?<!\d)(?:\d{4}-\d{2}-\d{2}|20\d{2})(?!\d)", query_text)
        or re.search(r"(?<!\d)\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?(?!\d)", query_text)
        or _DATE_RANGE_CONNECTION_QUERY_RE.search(query_text)
    )
    progression_like = False
    enumeration_like = False
    requirements: List[str] = []

    def _add(requirement: str) -> None:
        if requirement not in requirements:
            requirements.append(requirement)

    if assistant_like:
        _add("assistant_source")
    if temporal_like:
        _add("temporal")
    if intent == "WHO" or graph_like:
        _add("identity")
    if intent == "WHERE":
        _add("location")
    if intent == "ORGANIZATION":
        _add("organization")
    if intent == "WHY":
        _add("causal")
    if graph_like:
        _add("graph")
    if enumeration_like:
        _add("enumeration")
    if intent == "PROJECT":
        _add("technical")

    return {
        "requirements": requirements,
        "assistant_like": assistant_like,
        "temporal_like": temporal_like,
        "current_like": current_like,
        "progression_like": progression_like,
        "enumeration_like": enumeration_like,
        "graph_like": graph_like,
        "relation_matches": relation_matches,
        "query_terms": query_terms,
    }


def _row_matches_requirement(row: Dict[str, Any], requirement: str) -> bool:
    text = str((row or {}).get("text") or "")
    category = str((row or {}).get("category") or (row or {}).get("type") or "").strip().lower()
    source_type = str((row or {}).get("source_type") or "").strip().lower()
    provenance_type = str((row or {}).get("source_provenance_type") or "").strip().lower()

    if requirement == "assistant_source":
        return source_type in {"assistant", "subagent", "both", "tool"} or provenance_type in {
            "assistant",
            "subagent",
            "tool",
        }
    if requirement == "identity":
        return category in {"person", "identity", "participant"}
    if requirement == "location":
        return category in {"place", "location"}
    if requirement == "organization":
        return category in {"organization", "org", "company", "team"}
    if requirement == "temporal":
        if category in {"event", "temporal"}:
            return True
        if _collect_recall_temporal_markers(row):
            return True
        return bool(re.search(r"(?<!\d)(?:\d{4}-\d{2}-\d{2}|20\d{2})(?!\d)", text))
    if requirement == "causal":
        return category in {"causal", "cause"}
    if requirement == "enumeration":
        comma_count = text.count(",")
        semicolon_count = text.count(";")
        if comma_count + semicolon_count >= 2:
            return True
        if ":" in text and ("," in text or ";" in text):
            return True
        if len(re.findall(r"(?:^|[\s,;])\d+[\).:-]", text)) >= 2:
            return True
        return False
    if requirement == "technical":
        if category in {"docs", "technical", "code", "project"} or source_type in {"docs", "code", "project"}:
            return True
        return bool(re.search(r"(?<!\w)[\w./-]+\.[A-Za-z0-9]{1,8}(?!\w)", text, flags=re.UNICODE))
    return False


def _query_term_overlap(row: Dict[str, Any], query_terms: List[str]) -> int:
    return len(_query_term_hits(row, query_terms))


def _query_term_hits(row: Dict[str, Any], query_terms: List[str]) -> Set[str]:
    if not query_terms:
        return set()
    text = str((row or {}).get("text") or "").lower()
    return {term for term in query_terms if term in text}


def _quality_gate_row_text(row: Dict[str, Any]) -> str:
    if not isinstance(row, dict):
        return ""
    parts: List[str] = []
    for key in ("text", "name", "summary", "content", "title", "category", "source_type"):
        value = row.get(key)
        if value is not None:
            parts.append(str(value))
    return " ".join(part for part in parts if part)


def _covered_query_terms_for_rows(
    rows: List[Dict[str, Any]],
    query_terms: List[str],
) -> List[str]:
    if not query_terms:
        return []
    row_texts = [
        _quality_gate_row_text(row)
        for row in rows or []
        if isinstance(row, dict)
    ]
    covered: List[str] = []
    for term in query_terms:
        if any(_text_matches_query_term(text, term) for text in row_texts):
            covered.append(term)
    return covered


def _text_contains_anchor_term(text: str, term: str) -> bool:
    clean_term = " ".join(str(term or "").split()).strip().lower()
    if not clean_term:
        return False
    clean_text = str(text or "").lower()
    if not clean_term.isascii():
        return clean_term in clean_text
    return bool(re.search(rf"(?<!\w){re.escape(clean_term)}(?!\w)", clean_text, flags=re.UNICODE))


def _text_contains_anchor_term_fuzzy(text: str, term: str) -> bool:
    if _text_contains_anchor_term(text, term):
        return True
    clean_term = " ".join(str(term or "").split()).strip().lower()
    if len(clean_term) < 4:
        return False
    clean_text = str(text or "").lower()
    tokens = re.findall(r"[\w][\w._-]*", clean_text, flags=re.UNICODE)
    # A single character edit catches ordinary typos and light inflection
    # differences without adding language-specific vocabulary.
    if any(_single_token_edit_distance_leq_one(clean_term, token) for token in tokens):
        return True
    if len(clean_term) >= 6:
        for token in tokens:
            if len(token) >= 4 and clean_term.startswith(token):
                return True
    return any(
        token.startswith(clean_term)
        for token in tokens
    )


def _single_token_edit_distance_leq_one(left: str, right: str) -> bool:
    left = str(left or "").strip().lower()
    right = str(right or "").strip().lower()
    if not left or not right:
        return False
    if left == right:
        return True
    if abs(len(left) - len(right)) > 1:
        return False
    if len(left) == len(right):
        edits = 0
        for a, b in zip(left, right):
            if a != b:
                edits += 1
                if edits > 1:
                    return False
        return True
    if len(left) > len(right):
        left, right = right, left
    i = j = edits = 0
    while i < len(left) and j < len(right):
        if left[i] == right[j]:
            i += 1
            j += 1
            continue
        edits += 1
        if edits > 1:
            return False
        j += 1
    return True


def _node_searchable_text(node: Node) -> str:
    """Return the text surface FTS can match for a node."""
    parts: List[str] = [str(getattr(node, "name", "") or "")]
    if getattr(node, "keywords", None):
        parts.append(str(getattr(node, "keywords") or ""))
    attrs = getattr(node, "attributes", None)
    if isinstance(attrs, dict) and attrs:
        try:
            parts.append(json.dumps(attrs, ensure_ascii=False, sort_keys=True))
        except Exception:
            parts.extend(str(value) for value in attrs.values() if value is not None)
    elif attrs:
        parts.append(str(attrs))
    return " ".join(part for part in parts if part)


def _search_nodes_by_query_terms(
    graph: "MemoryGraph",
    query_terms: List[str],
    *,
    limit: int,
    owner_id: Optional[str] = None,
) -> List[tuple[Node, float]]:
    """Bounded LIKE fallback for fresh rows not yet visible in FTS."""
    terms = []
    seen = set()
    for raw in query_terms or []:
        term = " ".join(str(raw or "").split()).strip().lower()
        if not term or term in seen:
            continue
        seen.add(term)
        terms.append(term)
        if len(terms) >= 8:
            break
    if not terms:
        return []

    scan_terms = sorted(terms, key=lambda value: (len(value), value), reverse=True)[:3]
    clauses = []
    params: List[Any] = []
    for term in scan_terms:
        pattern = f"%{term}%"
        clauses.append("LOWER(COALESCE(n.name, '') || ' ' || COALESCE(n.keywords, '')) LIKE ?")
        params.append(pattern)
    def _fetch_rows(scoped_owner_id: Optional[str]) -> List[Any]:
        fetch_params = list(params)
        owner_clause = "AND (n.owner_id = ? OR n.owner_id IS NULL)" if scoped_owner_id else ""
        if scoped_owner_id:
            fetch_params.append(scoped_owner_id)
        fetch_params.append(max(limit * 8, 32))
        with graph._get_conn() as conn:
            return conn.execute(
                f"""
                SELECT n.*
                FROM nodes n
                WHERE ({' OR '.join(clauses)})
                  AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
                  AND n.deleted_at IS NULL
                  AND n.superseded_by IS NULL
                  {owner_clause}
                ORDER BY COALESCE(n.created_at, '') DESC
                LIMIT ?
                """,
                fetch_params,
            ).fetchall()

    rows = _fetch_rows(owner_id)
    if owner_id:
        seen_rowids = {row["id"] for row in rows if "id" in row.keys()}
        for row in _fetch_rows(None):
            row_id = row["id"] if "id" in row.keys() else None
            if row_id and row_id in seen_rowids:
                continue
            if row_id:
                seen_rowids.add(row_id)
            rows.append(row)

    scored: List[Tuple[Node, int, str]] = []
    for row in rows:
        node = graph._row_to_node(row)
        overlap = _query_term_overlap({"text": _node_searchable_text(node)}, terms)
        if overlap <= 0:
            continue
        scored.append((node, overlap, str(getattr(node, "created_at", "") or "")))
    scored.sort(key=lambda item: (item[1], item[2]), reverse=True)
    return [(node, float(rank)) for rank, (node, _overlap, _created) in enumerate(scored[:limit], 1)]


def _facet_rescue_query_terms(query: str, anchor_terms: List[str], *, limit: int = 6) -> List[str]:
    """Language-preserving fallback facet terms from the query itself."""
    anchor_set = {" ".join(str(term or "").split()).strip().lower() for term in anchor_terms or []}
    out: List[str] = []
    seen: Set[str] = set(anchor_set)
    for term in _extract_distinctive_query_terms(query, limit=24):
        clean = " ".join(str(term or "").split()).strip().lower()
        if not clean or clean in seen:
            continue
        seen.add(clean)
        out.append(clean)
        if len(out) >= limit:
            break
    return out


def _facet_rescue_anchor_terms(
    graph: "MemoryGraph",
    query: str,
    *,
    owner_id: Optional[str],
    limit: int = 4,
) -> List[str]:
    """Find query entity anchors without assuming English capitalization."""
    query_text = " ".join(str(query or "").split()).strip()
    query_fold = query_text.casefold()
    out: List[str] = []
    seen: Set[str] = set()

    def _add(term: str) -> None:
        clean = " ".join(str(term or "").split()).strip()
        key = clean.casefold()
        if not clean or key in seen:
            return
        seen.add(key)
        out.append(clean)

    for term in _extract_explicit_query_anchor_terms(query_text, limit=limit):
        _add(term)

    try:
        owner_clause = "AND (n.owner_id = ? OR n.owner_id IS NULL)" if owner_id else ""
        params: List[Any] = [query_text, query_fold]
        if owner_id:
            params.append(owner_id)
        params.append(max(16, int(limit or 1) * 8))
        with graph._get_conn() as conn:
            rows = conn.execute(
                f"""
                SELECT n.*
                FROM nodes n
                WHERE LOWER(n.type) IN ('person', 'place', 'pet', 'entity', 'concept', 'organization')
                  AND length(n.name) >= 2
                  AND (instr(?, n.name) > 0 OR instr(?, lower(n.name)) > 0)
                  AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
                  AND n.deleted_at IS NULL
                  AND n.superseded_by IS NULL
                  {owner_clause}
                ORDER BY length(n.name) DESC, COALESCE(n.updated_at, n.created_at, n.accessed_at, '') DESC
                LIMIT ?
                """,
                params,
            ).fetchall()
        for row in rows:
            node = graph._row_to_node(row)
            if str(getattr(node, "type", "") or "").strip().lower() in _LOW_INFO_ENTITY_CATEGORIES:
                _add(str(getattr(node, "name", "") or ""))
                if len(out) >= limit:
                    break
    except Exception:
        if _is_fail_hard_mode():
            raise

    if len(out) < limit:
        lookup_terms = list(out) + _extract_distinctive_query_terms(query_text, limit=16)
        for node, _rank in _search_nodes_by_query_terms(
            graph,
            lookup_terms,
            limit=max(16, int(limit or 1) * 8),
            owner_id=owner_id,
        ):
            node_type = str(getattr(node, "type", "") or "").strip().lower()
            node_name = " ".join(str(getattr(node, "name", "") or "").split()).strip()
            if node_type not in _LOW_INFO_ENTITY_CATEGORIES or not node_name:
                continue
            if node_name.casefold() not in query_fold:
                continue
            _add(node_name)
            if len(out) >= limit:
                break

    return out[:limit]


def _should_run_explicit_entity_facet_rescue(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    intent: Optional[str] = None,
    anchor_terms: Optional[List[str]] = None,
) -> bool:
    if not anchor_terms:
        return False
    return bool(_facet_rescue_query_terms(query, anchor_terms, limit=1))


def _score_facet_rescue_row(
    query: str,
    row: Dict[str, Any],
    *,
    anchor_terms: List[str],
    facet_terms: List[str],
) -> float:
    text = str((row or {}).get("text") or "")
    search_text = " ".join([
        text,
        str((row or {}).get("keywords") or ""),
    ]).lower()

    anchor_hit = any(_text_contains_anchor_term(search_text, term) for term in anchor_terms)
    facet_hit_count = sum(
        1 for term in facet_terms
        if term and (term in search_text or _text_contains_anchor_term(search_text, term))
    )

    score = 0.72
    if anchor_hit:
        score += 0.08
    if (
        str((row or {}).get("via_relation") or "") == "has_fact"
        or str((row or {}).get("via") or "").startswith("facet_rescue_attached_fact")
    ):
        score += 0.04
    if facet_hit_count:
        score += min(0.18, 0.06 * facet_hit_count)

    return round(max(0.0, min(0.985, score)), 4)


def _facet_rescue_attached_fact_rows(
    graph: "MemoryGraph",
    *,
    anchor_node: Node,
    anchor_text: str,
    anchor_score: float,
    limit: int,
) -> List[Dict[str, Any]]:
    """Return a broad attached-fact pool for caller-side facet scoring."""
    try:
        edges = list(graph.get_edges(anchor_node.id, direction="both"))
    except Exception as exc:
        if _is_fail_hard_mode():
            raise
        logger.warning("Recall facet rescue failed to fetch graph edges for %s: %s", anchor_node.id, exc)
        return []
    rows: List[Dict[str, Any]] = []
    seen_ids: Set[str] = set()
    for edge in edges:
        if str(getattr(edge, "relation", "") or "") != "has_fact":
            continue
        fact_id = edge.target_id if edge.source_id == anchor_node.id else edge.source_id
        if not fact_id or fact_id in seen_ids:
            continue
        seen_ids.add(fact_id)
        try:
            fact = graph.get_node(fact_id)
        except Exception as exc:
            if _is_fail_hard_mode():
                raise
            logger.warning("Recall facet rescue failed to fetch attached fact %s: %s", fact_id, exc)
            continue
        if not fact or str(getattr(fact, "type", "") or "").lower() != "fact":
            continue
        row = _build_recall_row_from_node(fact, similarity=max(0.72, min(0.90, float(anchor_score or 0.0))))
        row["via"] = "facet_rescue_attached_fact"
        row["via_relation"] = "has_fact"
        row["source_name"] = anchor_text
        row["graph_path"] = f"{anchor_text} --has_fact--> {fact.name}"
        row["_facet_rescue"] = True
        _annotate_graph_traversal_fields(row, ["has_fact"], discovery_kind="facet_rescue_attached_fact")
        rows.append(row)
        if len(rows) >= max(1, int(limit or 1)):
            break
    return rows


_FACET_RESCUE_MEMORY_TYPES = {"fact", "preference", "decision", "relationship"}
# A rescued row may outrank first-order session evidence only when it matches
# multiple non-entity query details. One detail is too broad for generic recall.
_FACET_RESCUE_LEADING_NON_ANCHOR_SIGNAL = 2


def _is_related_entity_facet_rescue_row(row: Dict[str, Any]) -> bool:
    """Return true for facts found through an explicit anchor's graph neighbor."""
    if not isinstance(row, dict):
        return False
    return (
        str(row.get("via") or "").strip() == "facet_rescue_related_lexical"
        and bool(str(row.get("graph_path") or "").strip())
    )


def _facet_rescue_leading_signal_threshold(row: Dict[str, Any]) -> int:
    # A related-entity row already has graph evidence connecting it to the
    # explicit query anchor, so one non-anchor facet term is enough to reserve
    # it. Generic lexical rescues still need two details to avoid broad drift.
    return 1 if _is_related_entity_facet_rescue_row(row) else _FACET_RESCUE_LEADING_NON_ANCHOR_SIGNAL


def _facet_rescue_signal_terms(query: str, *, limit: int = 12) -> List[str]:
    """Return language-neutral facet terms plus configured short signal terms."""
    out: List[str] = []
    seen: Set[str] = set()
    for term in (
        list(_extract_vocabulary_free_query_terms(query, limit=limit))
        + list(_extract_distinctive_query_terms(query, limit=limit))
    ):
        clean = " ".join(str(term or "").split()).strip().lower()
        if not clean or clean in seen:
            continue
        seen.add(clean)
        out.append(clean)
        if len(out) >= limit:
            break
    return out


def _facet_rescue_lexical_memory_rows(
    graph: "MemoryGraph",
    *,
    anchor_terms: List[str],
    facet_terms: List[str],
    owner_id: Optional[str],
    limit: int,
) -> List[Dict[str, Any]]:
    """Scan memory rows by entity + facet text/keywords.

    This covers valid memories whose subject->fact graph edge is missing. It is
    still bounded and lexical: explicit entity mention plus a query-language
    facet/keyword match are required.

    TODO(recall): replace ad hoc query-term lexical matching with a datastore
    lexical contract before adding curated facet/relation vocabulary. That
    contract should be multilingual and data-backed, not hardcoded English
    rules in the core recall path.
    """
    anchors = [
        " ".join(str(term or "").split()).strip().lower()
        for term in anchor_terms or []
        if " ".join(str(term or "").split()).strip()
    ][:4]
    facets = [
        " ".join(str(term or "").split()).strip().lower()
        for term in facet_terms or []
        if " ".join(str(term or "").split()).strip()
    ][:16]
    if not anchors or not facets:
        return []

    anchor_clauses: List[str] = []
    params: List[Any] = []
    for anchor in anchors:
        anchor_clauses.append("LOWER(COALESCE(n.name, '') || ' ' || COALESCE(n.keywords, '')) LIKE ?")
        params.append(f"%{anchor}%")
    facet_clauses: List[str] = []
    for facet in facets:
        facet_clauses.append("LOWER(COALESCE(n.name, '') || ' ' || COALESCE(n.keywords, '')) LIKE ?")
        params.append(f"%{facet}%")

    owner_clause = "AND (n.owner_id = ? OR n.owner_id IS NULL)" if owner_id else ""
    if owner_id:
        params.append(owner_id)
    params.append(max(32, min(240, int(limit or 1) * 24)))

    try:
        with graph._get_conn() as conn:
            rows = conn.execute(
                f"""
                SELECT n.*
                FROM nodes n
                WHERE LOWER(n.type) IN ('fact', 'preference', 'decision', 'relationship')
                  AND ({' OR '.join(anchor_clauses)})
                  AND ({' OR '.join(facet_clauses)})
                  AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
                  AND n.deleted_at IS NULL
                  AND n.superseded_by IS NULL
                  {owner_clause}
                ORDER BY COALESCE(n.updated_at, n.created_at, n.accessed_at, '') DESC, n.rowid DESC
                LIMIT ?
                """,
                params,
            ).fetchall()
    except Exception:
        if _is_fail_hard_mode():
            raise
        return []

    out: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for row in rows:
        node = graph._row_to_node(row)
        if str(getattr(node, "type", "") or "").strip().lower() not in _FACET_RESCUE_MEMORY_TYPES:
            continue
        if node.id in seen:
            continue
        seen.add(node.id)
        rec = _build_recall_row_from_node(node, similarity=0.82)
        rec["via"] = "facet_rescue_lexical"
        rec["_facet_rescue"] = True
        out.append(rec)
        if len(out) >= max(1, int(limit or 1)):
            break
    return out


def _recover_explicit_entity_facet_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    owner_id: Optional[str],
    limit: int,
    intent: Optional[str] = None,
    domain: Optional[Dict[str, bool]] = None,
    include_unscoped: bool = True,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    """Recover stored entity facts for property/list questions before final truncation.

    This is intentionally deterministic and generic. It does not know about any
    benchmark schema; it only uses explicit query entities plus same-language
    query terms to rescue already-stored graph facts.
    """
    meta: Dict[str, Any] = {
        "applied": False,
        "candidate_count": 0,
        "anchor_terms": [],
        "facet_terms": [],
        "error": None,
    }
    if limit <= 0:
        return [], meta
    try:
        graph = get_graph()
        anchor_terms = _facet_rescue_anchor_terms(
            graph,
            query,
            owner_id=owner_id,
            limit=4,
        )
        if not _should_run_explicit_entity_facet_rescue(
            query,
            rows,
            intent=intent,
            anchor_terms=anchor_terms,
        ):
            return [], meta

        facet_terms: List[str] = []
        facet_seen: Set[str] = set()
        for term in _facet_rescue_query_terms(query, anchor_terms, limit=8):
            clean = " ".join(str(term or "").split()).strip().lower()
            if not clean or clean in facet_seen:
                continue
            facet_seen.add(clean)
            facet_terms.append(clean)
            if len(facet_terms) >= 8:
                break
        if not facet_terms:
            return [], meta
        meta["anchor_terms"] = list(anchor_terms)
        meta["facet_terms"] = list(facet_terms)

        existing_ids = {str((row or {}).get("id") or "") for row in rows if str((row or {}).get("id") or "")}
        candidates_by_id: Dict[str, Dict[str, Any]] = {}
        active_domains = _active_domains_for_filter(graph) if domain else set()
        include_all_domains, included_domains = _normalize_domain_filter(domain, active_domains)

        def _row_in_domain_scope(row: Dict[str, Any]) -> bool:
            if include_all_domains:
                return True
            if not included_domains:
                return False
            row_domains = set(_domains_from_attrs({"domains": row.get("domains")}))
            if row_domains:
                return bool(row_domains & included_domains)
            return bool(include_unscoped)

        def _add_candidate(
            row: Dict[str, Any],
            *,
            score_anchor_terms: Optional[List[str]] = None,
        ) -> None:
            rid = str((row or {}).get("id") or "").strip()
            if not rid:
                return
            if not _row_in_domain_scope(row):
                return
            score = _score_facet_rescue_row(
                query,
                row,
                anchor_terms=score_anchor_terms or anchor_terms,
                facet_terms=facet_terms,
            )
            if score < 0.76:
                return
            candidate = dict(row)
            candidate["similarity"] = score
            candidate["via"] = candidate.get("via") or "facet_rescue"
            candidate["_facet_rescue"] = True
            prev = candidates_by_id.get(rid)
            if prev is None or (
                float(candidate.get("similarity", 0.0))
                > float(prev.get("similarity", 0.0))
            ):
                candidates_by_id[rid] = candidate

        for anchor in anchor_terms:
            anchor_key = " ".join(str(anchor or "").split()).strip().casefold()
            anchor_nodes: List[Node] = []
            for node, _rank in _search_nodes_by_query_terms(
                graph,
                [anchor],
                limit=12,
                owner_id=owner_id,
            ):
                node_name = str(getattr(node, "name", "") or "").strip().casefold()
                node_type = str(getattr(node, "type", "") or "").strip().lower()
                if node_type in _LOW_INFO_ENTITY_CATEGORIES and node_name == anchor_key:
                    anchor_nodes.append(node)
            for anchor_node in anchor_nodes[:2]:
                for row in _facet_rescue_attached_fact_rows(
                    graph,
                    anchor_node=anchor_node,
                    anchor_text=str(getattr(anchor_node, "name", "") or anchor),
                    anchor_score=0.84,
                    limit=max(40, int(limit or 1) * 8),
                ):
                    _add_candidate(row)
                attached_rows = _graph_attached_fact_rows(
                    graph,
                    anchor_node=anchor_node,
                    anchor_text=str(getattr(anchor_node, "name", "") or anchor),
                    anchor_score=0.82,
                    graph_path=str(getattr(anchor_node, "name", "") or anchor),
                    relation_sequence=[],
                    hop_depth=0,
                    seen_ids=set(existing_ids) | set(candidates_by_id.keys()),
                    query=query,
                    per_anchor_limit=max(3, min(10, int(limit or 1) * 2)),
                )
                for row in attached_rows:
                    _add_candidate(row)

                try:
                    related_nodes = graph.get_related_bidirectional(
                        anchor_node.id,
                        depth=1,
                        max_results=max(8, min(24, int(limit or 1) * 4)),
                    )
                except Exception as exc:
                    if _is_fail_hard_mode():
                        raise
                    logger.warning(
                        "Recall facet rescue failed to fetch related anchors for %s: %s",
                        anchor_node.id,
                        exc,
                    )
                    related_nodes = []

                related_seen: Set[str] = set()
                for related_node, relation, direction, _depth, _path in related_nodes:
                    related_type = str(getattr(related_node, "type", "") or "").strip().lower()
                    related_name = " ".join(str(getattr(related_node, "name", "") or "").split()).strip()
                    related_key = related_name.casefold()
                    if (
                        related_type not in _LOW_INFO_ENTITY_CATEGORIES
                        or not related_name
                        or related_key == anchor_key
                        or related_key in related_seen
                    ):
                        continue
                    related_seen.add(related_key)
                    relation_label = str(relation or "").strip() or "related_to"
                    if direction == "in":
                        graph_path = f"{related_name} --{relation_label}--> {anchor_node.name}"
                    else:
                        graph_path = f"{anchor_node.name} --{relation_label}--> {related_name}"
                    for row in _facet_rescue_lexical_memory_rows(
                        graph,
                        anchor_terms=[related_name],
                        facet_terms=facet_terms,
                        owner_id=owner_id,
                        limit=max(12, int(limit or 1) * 4),
                    ):
                        row["via"] = "facet_rescue_related_lexical"
                        row["source_name"] = str(getattr(anchor_node, "name", "") or anchor)
                        row["graph_path"] = graph_path
                        _add_candidate(row, score_anchor_terms=[anchor, related_name])

            for row in _facet_rescue_lexical_memory_rows(
                graph,
                anchor_terms=[anchor],
                facet_terms=facet_terms,
                owner_id=owner_id,
                limit=max(24, int(limit or 1) * 8),
            ):
                _add_candidate(row)

            lexical_term_sets: List[List[str]] = []
            for facet in facet_terms:
                lexical_term_sets.append([anchor, facet])
                pieces = [
                    piece for piece in re.findall(r"[\w][\w._'-]*", facet, flags=re.UNICODE)
                    if len(piece) >= 4 and piece not in _QUERY_STOPWORDS
                ]
                if pieces:
                    lexical_term_sets.append([anchor] + pieces)

            for term_set in lexical_term_sets[:8]:
                for node, _rank in _search_nodes_by_query_terms(
                    graph,
                    term_set,
                    limit=max(12, int(limit or 1) * 4),
                    owner_id=owner_id,
                ):
                    if str(getattr(node, "type", "") or "").strip().lower() not in _FACET_RESCUE_MEMORY_TYPES:
                        continue
                    row = _build_recall_row_from_node(
                        node,
                        similarity=0.80,
                    )
                    _add_candidate(row)

        def _facet_sort_key(row: Dict[str, Any]) -> Tuple[int, float, int, int]:
            text = str((row or {}).get("text") or "")
            search_text = " ".join([
                text,
                str((row or {}).get("keywords") or ""),
            ]).lower()
            overlap = sum(
                1 for term in facet_terms
                if term and (term in search_text or _text_contains_anchor_term(search_text, term))
            )
            return (
                overlap,
                float((row or {}).get("similarity", 0.0) or 0.0),
                1 if _is_related_entity_facet_rescue_row(row) else 0,
                len(str((row or {}).get("keywords") or "")),
            )

        recovered = sorted(
            candidates_by_id.values(),
            key=_facet_sort_key,
            reverse=True,
        )[: max(1, min(12, int(limit or 1)))]
        meta["applied"] = bool(recovered)
        meta["candidate_count"] = len(recovered)
        return recovered, meta
    except Exception as exc:
        meta["error"] = f"{type(exc).__name__}: {exc}"
        if _is_fail_hard_mode():
            raise RuntimeError("Recall facet rescue failed while failHard is enabled") from exc
        logger.warning("Recall facet rescue failed; proceeding without rescued rows: %s", exc)
        return [], meta


def _filter_low_information_rows_for_query(
    rows: List[Dict[str, Any]],
    query: str,
    *,
    intent: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Drop bare entity anchors from answer context unless the query needs identity."""
    out: List[Dict[str, Any]] = []
    for row in rows or []:
        if _is_low_information_entity_result(row) and not _should_preserve_low_information_entity_result(
            row,
            query,
            intent=intent,
        ):
            continue
        out.append(row)
    return out


def _facet_rescue_reservation_count(
    query: str,
    *,
    intent: Optional[str],
    limit: int,
) -> int:
    if limit <= 1:
        return 0
    return min(limit - 1, max(2, min(4, int(round(limit * 0.4)))))


def _select_final_recall_rows_with_facet_rescue(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    limit: int,
    intent: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Reserve a few slots for high-signal rescued evidence before truncation."""
    if limit <= 0:
        return []
    filtered = _filter_low_information_rows_for_query(rows, query, intent=intent)
    if not filtered:
        return []
    filtered = _prioritize_first_order_session_query_coverage(query, filtered)
    filtered = _prioritize_source_dated_session_rows_for_temporal_answers(query, filtered)

    def _key(row: Dict[str, Any]) -> str:
        return str(row.get("id") or row.get("text") or "")

    facet_rows = [
        row for row in filtered
        if row.get("_facet_rescue") and float(row.get("similarity", 0.0) or 0.0) >= 0.82
    ]
    if not facet_rows:
        return filtered[:limit]

    query_terms = _facet_rescue_signal_terms(query, limit=12)
    anchor_tokens: Set[str] = set()
    for anchor in _extract_explicit_query_anchor_terms(query, limit=6):
        for token in re.findall(r"[\w][\w._'-]*", str(anchor or "").lower(), flags=re.UNICODE):
            token = token.strip(".,;:!?\"'“”¿¡")
            if token:
                anchor_tokens.add(token)
    non_anchor_query_terms = [
        term for term in query_terms
        if term and term not in anchor_tokens
    ]
    scoring_query_terms = [
        term for term in non_anchor_query_terms
        if term not in _QUERY_STOPWORDS
    ] or non_anchor_query_terms or query_terms

    def _facet_signal(row: Dict[str, Any]) -> int:
        search_text = " ".join([
            str((row or {}).get("text") or ""),
            str((row or {}).get("keywords") or ""),
        ]).lower()
        return sum(
            1 for term in scoring_query_terms
            if term and (term in search_text or _text_contains_anchor_term(search_text, term))
        )

    def _facet_text_signal(row: Dict[str, Any]) -> int:
        search_text = str((row or {}).get("text") or "").lower()
        return sum(
            1 for term in query_terms
            if term and (term in search_text or _text_contains_anchor_term(search_text, term))
        )

    def _facet_non_anchor_signal(row: Dict[str, Any]) -> int:
        search_text = " ".join([
            str((row or {}).get("text") or ""),
            str((row or {}).get("keywords") or ""),
        ]).lower()
        return sum(
            1 for term in scoring_query_terms
            if term and (term in search_text or _text_contains_anchor_term(search_text, term))
        )

    source_dated_session_signal = max(
        (
            _facet_non_anchor_signal(row)
            for row in filtered
            if isinstance(row, dict)
            and _is_first_order_session_source_row(row)
            and str(row.get("source_date") or "").strip()
        ),
        default=0,
    )
    direct_memory_signal = max(
        (
            _facet_non_anchor_signal(row)
            for row in filtered
            if isinstance(row, dict)
            and not row.get("_facet_rescue")
        ),
        default=0,
    )
    facet_rows.sort(
        key=lambda row: (
            _facet_signal(row),
            _facet_text_signal(row),
            1 if _is_related_entity_facet_rescue_row(row) else 0,
            float(row.get("similarity", 0.0) or 0.0),
            len(str(row.get("keywords") or "")),
        ),
        reverse=True,
    )
    reserve_count = min(len(facet_rows), _facet_rescue_reservation_count(query, intent=intent, limit=limit))
    reserved = facet_rows[:reserve_count]
    reserved_keys = {_key(row) for row in reserved}
    leading_reserved = [
        row for row in reserved
        if _facet_non_anchor_signal(row) > max(source_dated_session_signal, direct_memory_signal)
        and (
            _facet_non_anchor_signal(row) >= _facet_rescue_leading_signal_threshold(row)
            or _facet_text_signal(row) >= len(query_terms)
        )
    ]
    leading_reserved_keys = {_key(row) for row in leading_reserved}
    trailing_reserved = [
        row for row in reserved
        if _key(row) not in leading_reserved_keys
    ]

    selected: List[Dict[str, Any]] = []
    selected_keys: Set[str] = set()
    for row in leading_reserved:
        key = _key(row)
        if not key or key in selected_keys:
            continue
        selected.append(row)
        selected_keys.add(key)
        if len(selected) >= limit:
            return selected[:limit]
    primary_slots = max(0, limit - len(reserved))
    for row in filtered:
        key = _key(row)
        if not key or key in selected_keys or key in reserved_keys:
            continue
        selected.append(row)
        selected_keys.add(key)
        if len(selected) >= primary_slots:
            break
    for row in trailing_reserved:
        key = _key(row)
        if not key or key in selected_keys:
            continue
        selected.append(row)
        selected_keys.add(key)
        if len(selected) >= limit:
            break
    if len(selected) < limit:
        for row in filtered:
            key = _key(row)
            if not key or key in selected_keys:
                continue
            selected.append(row)
            selected_keys.add(key)
            if len(selected) >= limit:
                break
    return selected[:limit]


def _prioritize_high_signal_facet_rescue_rows(
    query: str,
    rows: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    if not rows:
        return rows
    query_terms = _facet_rescue_signal_terms(query, limit=12)
    if not query_terms:
        return rows
    anchor_tokens: Set[str] = set()
    for anchor in _extract_explicit_query_anchor_terms(query, limit=6):
        for token in re.findall(r"[\w][\w._'-]*", str(anchor or "").lower(), flags=re.UNICODE):
            token = token.strip(".,;:!?\"'“”¿¡")
            if token:
                anchor_tokens.add(token)
    non_anchor_query_terms = [
        term for term in query_terms
        if term and term not in anchor_tokens
    ]
    scoring_query_terms = [
        term for term in non_anchor_query_terms
        if term not in _QUERY_STOPWORDS
    ] or non_anchor_query_terms
    if not scoring_query_terms:
        return rows

    def _non_anchor_signal(row: Dict[str, Any]) -> int:
        search_text = " ".join([
            str((row or {}).get("text") or ""),
            str((row or {}).get("keywords") or ""),
        ]).lower()
        return sum(
            1 for term in scoring_query_terms
            if term and (term in search_text or _text_contains_anchor_term(search_text, term))
        )

    def _text_signal(row: Dict[str, Any]) -> int:
        search_text = str((row or {}).get("text") or "").lower()
        return sum(
            1 for term in query_terms
            if term and (term in search_text or _text_contains_anchor_term(search_text, term))
        )

    source_dated_session_signal = max(
        (
            _non_anchor_signal(row)
            for row in rows
            if isinstance(row, dict)
            and _is_first_order_session_source_row(row)
            and str(row.get("source_date") or "").strip()
        ),
        default=0,
    )
    direct_memory_signal = max(
        (
            _non_anchor_signal(row)
            for row in rows
            if isinstance(row, dict)
            and not row.get("_facet_rescue")
        ),
        default=0,
    )
    leading: List[Tuple[int, int, int, float, int, Dict[str, Any]]] = []
    trailing: List[Dict[str, Any]] = []
    for index, row in enumerate(rows):
        signal = _non_anchor_signal(row) if isinstance(row, dict) and row.get("_facet_rescue") else 0
        text_signal = _text_signal(row) if isinstance(row, dict) and row.get("_facet_rescue") else 0
        if (
            signal > max(source_dated_session_signal, direct_memory_signal)
            and (
                signal >= _facet_rescue_leading_signal_threshold(row)
                or text_signal >= len(query_terms)
            )
        ):
            leading.append((
                signal,
                text_signal,
                1 if _is_related_entity_facet_rescue_row(row) else 0,
                float(row.get("similarity", 0.0) or 0.0),
                -index,
                row,
            ))
        else:
            trailing.append(row)
    if not leading:
        return rows
    leading.sort(key=lambda item: item[:5], reverse=True)
    return [
        row
        for _signal, _text_signal_count, _related, _similarity, _negative_index, row in leading
    ] + trailing


def _parse_recall_timestamp(value: Any) -> Optional[datetime]:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        try:
            parsed = datetime.fromisoformat(raw[:10])
        except Exception:
            return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _date_part(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    match = re.search(r"\b(\d{4}-\d{2}-\d{2})\b", raw)
    if match:
        candidate = match.group(1)
        try:
            datetime.strptime(candidate, "%Y-%m-%d")
        except ValueError:
            return ""
        return candidate
    candidate = raw.split("T", 1)[0] if "T" in raw else raw[:10]
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", candidate):
        return ""
    try:
        datetime.strptime(candidate, "%Y-%m-%d")
    except ValueError:
        return ""
    return candidate


def _temporal_value_is_present(value: Any) -> bool:
    return bool(str(value or "").strip())


def _temporal_date_part_for_bounds(value: Any, field_name: str) -> str:
    date = _date_part(value)
    if not date and _temporal_value_is_present(value):
        message = (
            f"Invalid temporal value for {field_name}: expected YYYY-MM-DD or ISO timestamp, "
            f"got {str(value).strip()!r}"
        )
        if _is_fail_hard_mode():
            raise ValueError(message)
        logger.warning("[memory_graph] %s", message)
    return date


def _normalize_recall_date_bound(value: Any) -> Optional[str]:
    raw = str(value or "").strip()
    if not raw:
        return None
    match = re.search(r"\b(20\d{2}-\d{2}-\d{2})\b", raw)
    if not match:
        raise ValueError(
            f"Recall date filters must be concrete YYYY-MM-DD dates, got {raw!r}"
        )
    normalized = match.group(1)
    try:
        date.fromisoformat(normalized)
    except ValueError as exc:
        raise ValueError(f"Recall date filters must be valid YYYY-MM-DD dates, got {raw!r}") from exc
    return normalized


def _normalize_recall_temporal_dimension(value: Any) -> str:
    """Normalize which temporal axis date-bounded recall should use."""
    raw = str(value or "").strip().lower().replace("-", "_")
    if not raw:
        return "auto"
    aliases = {
        "auto": "auto",
        "occurred": "occurred",
        "occurred_at": "occurred",
        "occurred_start": "occurred",
        "occurred_end": "occurred",
        "mentioned": "mentioned",
        "mentioned_at": "mentioned",
        "record": "record",
        "created_at": "record",
    }
    normalized = aliases.get(raw)
    if normalized is None:
        raise ValueError(
            "temporal_dimension must be one of auto, occurred, mentioned, or record "
            f"(got {value!r})"
        )
    return normalized


def _temporal_date_bounds_from_values(
    start_value: Any,
    end_value: Any = None,
    *,
    start_field: str = "temporal_start",
    end_field: str = "temporal_end",
) -> Tuple[str, str]:
    start = _temporal_date_part_for_bounds(start_value, start_field)
    end = _temporal_date_part_for_bounds(end_value, end_field)
    if start and end and end < start:
        start, end = end, start
    if start and not end:
        end = start
    if end and not start:
        start = end
    return start, end


_SOURCE_CHUNK_TEMPORAL_ROW_TYPES = {
    "session_chunk",
    "session_chunks",
    "source_chunk",
    "source_chunks",
}


def _row_is_source_chunk_temporal_evidence(row: Dict[str, Any]) -> bool:
    """First-order transcript chunks need source dates for event-date filters."""
    if not isinstance(row, dict):
        return False
    for field_name in ("category", "source_type", "via", "store"):
        value = str(row.get(field_name) or "").strip().lower()
        if value in _SOURCE_CHUNK_TEMPORAL_ROW_TYPES:
            return True
    return False


def _row_temporal_bounds(
    row: Dict[str, Any],
    *,
    temporal_dimension: Any = None,
) -> Tuple[str, str, str]:
    """Return date bounds and the axis used for date-bounded recall rows."""
    dimension = _normalize_recall_temporal_dimension(temporal_dimension)
    row = row or {}

    if dimension == "mentioned":
        start, end = _temporal_date_bounds_from_values(
            row.get("mentioned_at") or row.get("source_date") or row.get("created_at"),
            start_field=(
                "mentioned_at"
                if _temporal_value_is_present(row.get("mentioned_at"))
                else "source_date"
                if _temporal_value_is_present(row.get("source_date"))
                else "created_at"
            ),
        )
        return start, end, "mentioned"

    if dimension == "record":
        start, end = _temporal_date_bounds_from_values(row.get("created_at"), start_field="created_at")
        return start, end, "record"

    if dimension == "occurred":
        if not _temporal_value_is_present(row.get("occurred_start")):
            return "", "", "occurred"
        start, end = _temporal_date_bounds_from_values(
            row.get("occurred_start"),
            row.get("occurred_end"),
            start_field="occurred_start",
            end_field="occurred_end",
        )
        return start, end, "occurred"

    # Auto mode keeps legacy rows searchable by falling back through historical
    # event/source/record axes. Explicit dimensions above stay strict.
    occurred_start = row.get("occurred_start") or row.get("valid_from")
    occurred_end = row.get("occurred_end") or row.get("valid_until")
    if occurred_start or occurred_end:
        start, end = _temporal_date_bounds_from_values(
            occurred_start,
            occurred_end,
            start_field="occurred_start" if row.get("occurred_start") else "valid_from",
            end_field="occurred_end" if row.get("occurred_end") else "valid_until",
        )
        return start, end, "occurred"

    source_date = row.get("source_date")
    if source_date:
        start, end = _temporal_date_bounds_from_values(source_date, start_field="source_date")
        return start, end, "source"

    if _row_is_source_chunk_temporal_evidence(row):
        return "", "", "source"

    start, end = _temporal_date_bounds_from_values(row.get("created_at"), start_field="created_at")
    return start, end, "record"


def _date_bounds_overlap_filter(
    start_date: str,
    end_date: str,
    *,
    date_from: Optional[str],
    date_to: Optional[str],
) -> bool:
    if not start_date:
        return False
    effective_end = end_date or start_date
    if date_from and effective_end < date_from:
        return False
    if date_to and start_date > date_to:
        return False
    return True


def _node_temporal_bounds(
    node: "Node",
    *,
    temporal_dimension: Any = None,
) -> Tuple[str, str, str]:
    row = {
        "occurred_start": getattr(node, "occurred_start", None),
        "occurred_end": getattr(node, "occurred_end", None),
        "mentioned_at": getattr(node, "mentioned_at", None),
        "valid_from": getattr(node, "valid_from", None),
        "valid_until": getattr(node, "valid_until", None),
        "created_at": getattr(node, "created_at", None),
        "source_date": _source_date_from_session_id(getattr(node, "session_id", None)),
    }
    return _row_temporal_bounds(row, temporal_dimension=temporal_dimension)


def _first_present_config_value(config: Dict[str, Any], *keys: str) -> Any:
    for key in keys:
        if key in config and config.get(key) not in (None, ""):
            return config.get(key)
    return None


def _resolve_recall_command_date_bounds(
    config: Dict[str, Any],
    *,
    cli_date_from: Optional[str] = None,
    cli_date_to: Optional[str] = None,
) -> Tuple[Optional[Any], Optional[Any]]:
    """Resolve recall CLI/config date aliases to canonical bounds."""
    cfg = config if isinstance(config, dict) else {}
    date_range = cfg.get("date_range") if isinstance(cfg.get("date_range"), dict) else {}
    date_from = (
        cli_date_from
        or _first_present_config_value(cfg, "date_from", "dateFrom", "after", "since")
        or _first_present_config_value(date_range, "from", "date_from", "dateFrom", "after", "since")
    )
    date_to = (
        cli_date_to
        or _first_present_config_value(cfg, "date_to", "dateTo", "before", "until", "as_of", "asOf")
        or _first_present_config_value(date_range, "to", "date_to", "dateTo", "before", "until", "as_of", "asOf")
    )
    return _normalize_recall_date_bound(date_from), _normalize_recall_date_bound(date_to)


def _resolve_recall_command_temporal_dimension(
    config: Dict[str, Any],
    *,
    cli_temporal_dimension: Optional[str] = None,
    cli_after: Optional[str] = None,
) -> str:
    cfg = config if isinstance(config, dict) else {}
    explicit_dimension = _first_present_config_value(
        cfg,
        "temporal_dimension",
        "temporalDimension",
        "time_dimension",
        "timeDimension",
        "date_dimension",
        "dateDimension",
    )
    if cli_temporal_dimension or explicit_dimension:
        return _normalize_recall_temporal_dimension(cli_temporal_dimension or explicit_dimension)
    if cli_after not in (None, ""):
        return "occurred"
    date_range = cfg.get("date_range") if isinstance(cfg.get("date_range"), dict) else {}
    if (
        _first_present_config_value(cfg, "after", "since") is not None
        or _first_present_config_value(date_range, "after", "since") is not None
    ):
        return "occurred"
    return "auto"


def _recall_row_temporal_date(
    row: Dict[str, Any],
    *,
    temporal_dimension: Any = None,
) -> str:
    """Best available source/record date for recall date filtering."""
    start, _end, _basis = _row_temporal_bounds(row or {}, temporal_dimension=temporal_dimension)
    return start


def _filter_recall_rows_by_date_bounds(
    rows: List[Dict[str, Any]],
    *,
    date_from: Optional[str],
    date_to: Optional[str],
    keep_undated: bool = False,
    temporal_dimension: Any = None,
) -> List[Dict[str, Any]]:
    """Return rows whose selected temporal interval overlaps the requested bounds.

    Matching rows are annotated in-place with temporal_filter_basis so downstream
    debug output can show which stored time axis was used.
    """
    normalized_from = _normalize_recall_date_bound(date_from)
    normalized_to = _normalize_recall_date_bound(date_to)
    if not normalized_from and not normalized_to:
        return list(rows or [])
    filtered: List[Dict[str, Any]] = []
    undated_dropped = 0
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        start_date, end_date, basis = _row_temporal_bounds(
            row,
            temporal_dimension=temporal_dimension,
        )
        if not start_date:
            if keep_undated and not _row_is_source_chunk_temporal_evidence(row):
                filtered.append(row)
            else:
                undated_dropped += 1
            continue
        if normalized_from and (end_date or start_date) < normalized_from:
            continue
        if normalized_to and start_date > normalized_to:
            continue
        row.setdefault("temporal_filter_basis", basis)
        filtered.append(row)
    if undated_dropped:
        logger.debug(
            "Date-bounded recall excluded %d undated row(s) date_from=%r date_to=%r "
            "temporal_dimension=%s keep_undated=%s",
            undated_dropped,
            date_from,
            date_to,
            temporal_dimension,
            keep_undated,
        )
    return filtered


def _keep_undated_rows_for_temporal_dimension(temporal_dimension: Any) -> bool:
    return _normalize_recall_temporal_dimension(temporal_dimension) == "auto"


def _selected_temporal_values_for_dimension(
    row: Dict[str, Any],
    *,
    temporal_dimension: Any = None,
) -> List[Tuple[str, Any]]:
    """Return the stored values selected by an explicit recall temporal axis."""
    dimension = _normalize_recall_temporal_dimension(temporal_dimension)
    row = row or {}
    if dimension == "mentioned":
        if _temporal_value_is_present(row.get("mentioned_at")):
            return [("mentioned_at", row.get("mentioned_at"))]
        if _temporal_value_is_present(row.get("source_date")):
            return [("source_date", row.get("source_date"))]
        if _temporal_value_is_present(row.get("created_at")):
            return [("created_at", row.get("created_at"))]
        return []
    if dimension == "record":
        return [("created_at", row.get("created_at"))] if _temporal_value_is_present(row.get("created_at")) else []
    if dimension == "occurred":
        values: List[Tuple[str, Any]] = []
        if _temporal_value_is_present(row.get("occurred_start")):
            values.append(("occurred_start", row.get("occurred_start")))
        if _temporal_value_is_present(row.get("occurred_end")):
            values.append(("occurred_end", row.get("occurred_end")))
        return values
    return []


def _enforce_recall_rows_temporal_axis_validity(
    rows: List[Dict[str, Any]],
    *,
    temporal_dimension: Any = None,
) -> List[Dict[str, Any]]:
    """Validate explicit temporal-axis rows even when no date range is supplied."""
    dimension = _normalize_recall_temporal_dimension(temporal_dimension)
    if dimension == "auto":
        return list(rows or [])
    filtered: List[Dict[str, Any]] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        invalid: Optional[Tuple[str, Any]] = None
        selected_values = _selected_temporal_values_for_dimension(
            row,
            temporal_dimension=dimension,
        )
        if not selected_values:
            continue
        for field_name, value in selected_values:
            if not _date_part(value):
                invalid = (field_name, value)
                break
        if invalid is not None:
            field_name, value = invalid
            message = (
                f"Invalid temporal value for {field_name}: expected YYYY-MM-DD or ISO timestamp, "
                f"got {str(value).strip()!r}"
            )
            if _is_fail_hard_mode():
                raise ValueError(message)
            logger.warning("[memory_graph] %s", message)
            continue
        filtered.append(row)
    return filtered


def _source_date_from_session_id(session_id: Any) -> str:
    """Extract a durable source date from runtime session identifiers.

    Some project/runtime extraction facts are stored later than the transcript
    that produced them. For historical recall, the source session date is often
    the event-time signal; created_at is only the storage time.
    """
    raw = str(session_id or "").strip()
    if not raw:
        return ""
    match = re.search(r"\b(20\d{2}-\d{2}-\d{2})\b", raw)
    return match.group(1) if match else ""


def _node_recall_temporal_fields(node: Node) -> Dict[str, Any]:
    """Temporal fields required by serialized recall date filters."""
    source_date = _source_date_from_session_id(getattr(node, "session_id", None))
    return {
        "occurred_start": getattr(node, "occurred_start", None),
        "occurred_end": getattr(node, "occurred_end", None),
        "mentioned_at": getattr(node, "mentioned_at", None),
        "created_at": getattr(node, "created_at", None),
        "valid_from": getattr(node, "valid_from", None),
        "valid_until": getattr(node, "valid_until", None),
        "source_date": source_date or None,
        "session_id": getattr(node, "session_id", None),
    }


def _query_target_date(query: str) -> str:
    """Return the latest explicit ISO date mentioned in a recall query."""
    matches = re.findall(r"(?<!\d)(20\d{2}-\d{2}-\d{2})(?!\d)", str(query or ""))
    return max(matches) if matches else ""


def _resolve_fast_recall_date_bounds(
    query: str,
    *,
    date_from: Optional[str],
    date_to: Optional[str],
) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """Normalize explicit bounds and infer a fast-recall cutoff from an ISO query date."""
    normalized_from = _normalize_recall_date_bound(date_from)
    normalized_to = _normalize_recall_date_bound(date_to)
    inferred_to: Optional[str] = None
    if normalized_from is None and normalized_to is None:
        # Fast pre-injection has no agent tool turn to translate "as of" into
        # arguments. Explicit tool-supplied before/after ranges still win.
        inferred_to = _query_target_date(query) or None
        if inferred_to:
            normalized_to = inferred_to
    return normalized_from, normalized_to, inferred_to


def _node_temporal_date(node: Node, *, temporal_dimension: Any = None) -> str:
    """Best available event/source date for temporal ranking."""
    start, _end, _basis = _node_temporal_bounds(
        node,
        temporal_dimension=temporal_dimension,
    )
    return start


def _asof_temporal_score_delta(
    node: Node,
    target_date: str,
    *,
    temporal_dimension: Any = None,
) -> float:
    """Small generic ranking nudge for explicit dated historical queries."""
    if not target_date:
        return 0.0
    node_date = _node_temporal_date(node, temporal_dimension=temporal_dimension)
    if not node_date:
        return 0.0
    try:
        target = datetime.fromisoformat(target_date).date()
        event_date = datetime.fromisoformat(node_date).date()
    except Exception:
        return 0.0
    if event_date <= target:
        days_old = max(0, (target - event_date).days)
        if days_old <= 14:
            return 0.10
        if days_old <= 45:
            return 0.07
        if days_old <= 120:
            return 0.04
        return 0.02
    days_future = max(1, (event_date - target).days)
    return -min(0.18, 0.06 + days_future * 0.004)


def _apply_relative_temporal_freshness_rerank(
    scored_results: List[Tuple["Node", float]],
    *,
    freshness_preferred: bool,
    target_date: str,
    temporal_dimension: Any = None,
) -> List[Tuple["Node", float]]:
    """Prefer newer temporal candidates for current/open-ended schedule queries.

    This compares candidate rows to each other, not to wall-clock time. That keeps
    benchmark and prod replay paths stable even when transcript dates run ahead of
    the executing machine's current date.
    """
    if target_date or not freshness_preferred:
        return scored_results
    if len(scored_results) < 2:
        return scored_results

    dated: List[Tuple[Node, float, datetime]] = []
    for node, score in scored_results:
        date_part = _node_temporal_date(node, temporal_dimension=temporal_dimension)
        if not date_part:
            continue
        try:
            parsed = datetime.fromisoformat(date_part)
        except Exception:
            continue
        dated.append((node, score, parsed))
    if len(dated) < 2:
        return scored_results

    latest = max(parsed for _, _, parsed in dated)
    earliest = min(parsed for _, _, parsed in dated)
    span_days = max(1, abs((latest - earliest).days))
    # Only intervene when the candidate set really spans time; otherwise the
    # rerank just adds noise to essentially equivalent facts.
    if span_days < 14:
        return scored_results

    max_boost = 0.12
    reranked: List[Tuple[Node, float]] = []
    for node, score in scored_results:
        date_part = _node_temporal_date(node, temporal_dimension=temporal_dimension)
        if not date_part:
            reranked.append((node, score))
            continue
        try:
            parsed = datetime.fromisoformat(date_part)
        except Exception:
            reranked.append((node, score))
            continue
        age_days = max(0, (latest - parsed).days)
        freshness = max(0.0, 1.0 - (age_days / span_days))
        reranked.append((node, min(1.0, float(score) + max_boost * freshness)))
    reranked.sort(key=lambda item: item[1], reverse=True)
    return reranked


def _apply_open_ended_asof_temporal_rerank(
    scored_results: List[Tuple["Node", float]],
    *,
    date_from: Optional[str],
    date_to: Optional[str],
    temporal_dimension: Any = None,
) -> List[Tuple["Node", float]]:
    """Prefer the newest eligible dated candidates for upper-bound as-of recall."""
    normalized_to = _normalize_recall_date_bound(date_to)
    if date_from or not normalized_to or len(scored_results) < 2:
        return scored_results
    try:
        target = datetime.fromisoformat(normalized_to).date()
    except Exception:
        return scored_results

    dated: List[Tuple[Node, float, date]] = []
    for node, score in scored_results:
        date_part = _node_temporal_date(node, temporal_dimension=temporal_dimension)
        if not date_part:
            continue
        try:
            event_date = datetime.fromisoformat(date_part).date()
        except Exception:
            continue
        if event_date <= target:
            dated.append((node, score, event_date))
    if len(dated) < 2:
        return scored_results

    earliest = min(event_date for _node, _score, event_date in dated)
    latest = max(event_date for _node, _score, event_date in dated)
    span_days = max(1, (latest - earliest).days)
    if span_days < 14:
        return scored_results

    date_by_node_id = {id(node): event_date for node, _score, event_date in dated}
    # Date_to-only recall is an as-of view: recency within the eligible window is
    # load-bearing, but semantic score still wins unless stale rows are close.
    max_boost = 0.22
    reranked: List[Tuple[Node, float]] = []
    for node, score in scored_results:
        event_date = date_by_node_id.get(id(node))
        if event_date is None:
            reranked.append((node, score))
            continue
        relative_recency = max(0.0, min(1.0, (event_date - earliest).days / span_days))
        reranked.append((node, min(1.0, float(score) + max_boost * relative_recency)))
    reranked.sort(
        key=lambda item: (
            round(item[1], 3),
            date_by_node_id.get(id(item[0]), date.min).toordinal(),
            item[1],
        ),
        reverse=True,
    )
    return reranked


def _recall_row_similarity(row: Dict[str, Any]) -> float:
    try:
        return float((row or {}).get("similarity", 0.0) or 0.0)
    except Exception:
        return 0.0


def _sort_recall_rows_for_final_selection(
    rows: List[Dict[str, Any]],
    *,
    date_from: Optional[str],
    date_to: Optional[str],
    temporal_dimension: Any = None,
) -> List[Dict[str, Any]]:
    sorted_rows = sorted(rows or [], key=_recall_row_similarity, reverse=True)
    if date_from or len(sorted_rows) < 2:
        return sorted_rows
    try:
        normalized_to = _normalize_recall_date_bound(date_to)
    except Exception:
        return sorted_rows
    if not normalized_to:
        return sorted_rows
    try:
        target = datetime.fromisoformat(normalized_to).date()
    except Exception:
        return sorted_rows

    dated: List[Tuple[int, date]] = []
    for index, row in enumerate(rows or []):
        if not isinstance(row, dict):
            continue
        start_date, _end_date, _basis = _row_temporal_bounds(
            row,
            temporal_dimension=temporal_dimension,
        )
        if not start_date:
            continue
        try:
            event_date = datetime.fromisoformat(start_date).date()
        except Exception:
            continue
        if event_date <= target:
            dated.append((index, event_date))
    if len(dated) < 2:
        return sorted_rows

    earliest = min(event_date for _index, event_date in dated)
    latest = max(event_date for _index, event_date in dated)
    if max(1, (latest - earliest).days) < 14:
        return sorted_rows

    date_by_index = dict(dated)
    return [
        row
        for _index, row in sorted(
            enumerate(rows or []),
            key=lambda item: (
                _recall_row_similarity(item[1]),
                date_by_index.get(item[0], date.min).toordinal(),
            ),
            reverse=True,
        )
    ]


def _collect_recall_temporal_markers(row: Dict[str, Any]) -> List[datetime]:
    markers: List[datetime] = []
    for key in ("occurred_start", "occurred_end", "mentioned_at", "valid_from", "source_date", "created_at", "valid_until"):
        parsed = _parse_recall_timestamp((row or {}).get(key))
        if parsed is not None:
            markers.append(parsed)
    return markers


def _evaluate_quality_gate_readiness(
    query: str,
    results: List[Dict[str, Any]],
    *,
    intent: str = "GENERAL",
    limit: int = 5,
    include_relation_keywords: bool = True,
) -> Dict[str, Any]:
    analysis = _derive_query_requirements(
        query,
        intent=intent,
        include_relation_keywords=include_relation_keywords,
    )
    query_terms = list(analysis["query_terms"])
    sample = list(results or [])[: max(limit, 8)]
    overlap_counts = sorted((_query_term_overlap(row, query_terms) for row in sample), reverse=True)
    best_overlap = overlap_counts[0] if overlap_counts else 0
    overlap_ratio = (best_overlap / len(query_terms)) if query_terms else 1.0
    covered_query_terms = _covered_query_terms_for_rows(sample, query_terms)
    covered_query_term_set = set(covered_query_terms)
    unsupported_query_terms = [
        term for term in query_terms
        if term not in covered_query_term_set
    ]
    min_overlap = 0 if not query_terms else (1 if len(query_terms) <= 2 else 2)
    lexical_ready = (best_overlap >= min_overlap) if min_overlap else bool(sample)
    similarities = sorted(
        (
            float((row or {}).get("similarity", 0.0) or 0.0)
            for row in sample
            if isinstance(row, dict)
        ),
        reverse=True,
    )
    top_similarity = similarities[0] if similarities else 0.0
    close_competitor_count = (
        sum(1 for sim in similarities if (top_similarity - sim) <= 0.05)
        if similarities
        else 0
    )
    temporal_rows = sum(1 for row in sample if _row_matches_requirement(row, "temporal"))
    temporal_markers: List[datetime] = []
    for row in sample:
        temporal_markers.extend(_collect_recall_temporal_markers(row))
    temporal_span_days = 0
    if len(temporal_markers) >= 2:
        latest = max(temporal_markers)
        earliest = min(temporal_markers)
        temporal_span_days = abs((latest - earliest).days)
    requirement_rows = {
        requirement: sum(1 for row in sample if _row_matches_requirement(row, requirement))
        for requirement in analysis.get("requirements") or []
    }
    missing_requirements = [
        requirement for requirement in analysis.get("requirements") or []
        if requirement != "enumeration" and requirement_rows.get(requirement, 0) == 0
    ]
    ready = bool(sample) and lexical_ready
    needs_validation = bool(sample) and (
        (query_terms and overlap_ratio < 0.67)
        or (analysis["temporal_like"] and temporal_rows == 0)
        or analysis["current_like"]
        or analysis["progression_like"]
        or bool(missing_requirements)
    )
    unresolved: List[str] = []
    if not ready:
        unresolved.append("low_query_term_coverage")
    return {
        "requirements": list(analysis.get("requirements") or []),
        "coverage": requirement_rows,
        "missing_requirements": missing_requirements,
        "query_terms": query_terms,
        "covered_query_terms": covered_query_terms,
        "unsupported_query_terms": unsupported_query_terms,
        "best_overlap": best_overlap,
        "overlap_ratio": round(overlap_ratio, 3),
        "covered_terms_ratio": round(overlap_ratio, 3),
        "min_overlap": min_overlap,
        "lexical_ready": lexical_ready,
        "top_similarity": round(top_similarity, 3),
        "close_competitor_count": close_competitor_count,
        "temporal_like": analysis["temporal_like"],
        "temporal_rows": temporal_rows,
        "temporal_span_days": temporal_span_days,
        "current_like": analysis["current_like"],
        "progression_like": analysis["progression_like"],
        "enumeration_like": analysis.get("enumeration_like", False),
        "ready": ready,
        "needs_validation": needs_validation,
        "unresolved": unresolved,
    }


def _summarize_memory_quality(
    query: str,
    results: List[Dict[str, Any]],
    *,
    gate_eval: Optional[Dict[str, Any]] = None,
    intent: str = "GENERAL",
    limit: int = 5,
    include_relation_keywords: bool = True,
) -> Dict[str, Any]:
    gate = dict(gate_eval or _evaluate_quality_gate_readiness(
        query,
        results,
        intent=intent,
        limit=limit,
        include_relation_keywords=include_relation_keywords,
    ))
    sample = list(results or [])[: max(limit, 8)]
    top_similarity = float(gate.get("top_similarity", 0.0) or 0.0)
    close_competitor_count = int(gate.get("close_competitor_count", 0) or 0)
    temporal_span_days = int(gate.get("temporal_span_days", 0) or 0)
    overlap_ratio = float(gate.get("overlap_ratio", 0.0) or 0.0)
    needs_validation = bool(gate.get("needs_validation"))
    ready = bool(gate.get("ready"))
    current_like = bool(gate.get("current_like"))
    progression_like = bool(gate.get("progression_like"))
    unsupported_query_terms = [
        str(term)
        for term in (gate.get("unsupported_query_terms") or [])
        if str(term or "").strip()
    ]
    has_docs_evidence = any(_is_docs_recall_row(row) for row in sample if isinstance(row, dict))
    docs_evidence_ready = has_docs_evidence and ready
    unsupported_anchor_gap = (
        bool(sample)
        and len(unsupported_query_terms) >= 2
        and overlap_ratio < 0.67
        and not docs_evidence_ready
    )

    low_similarity = bool(sample) and top_similarity < 0.60
    ambiguity_risk = (
        bool(sample)
        and needs_validation
        and not docs_evidence_ready
        and close_competitor_count >= 2
        and overlap_ratio < 0.85
    )
    mixed_temporal_candidates = (
        bool(sample)
        and not docs_evidence_ready
        and (current_like or progression_like)
        and close_competitor_count >= 2
        and temporal_span_days >= 30
    )
    assistant_memory_cluster_ready = _assistant_memory_surface_resolved(
        query,
        sample,
        gate_eval=gate,
    )
    if assistant_memory_cluster_ready:
        ambiguity_risk = False

    signals: List[str] = []
    if not ready:
        signals.append("low_query_term_coverage")
    if unsupported_anchor_gap:
        signals.append("unsupported_query_terms")
    if needs_validation and not docs_evidence_ready:
        signals.append("needs_validation")
    if close_competitor_count >= 2 and not docs_evidence_ready:
        signals.append("close_competitors")
    if temporal_span_days >= 30 and not docs_evidence_ready:
        signals.append("wide_temporal_span")
    if mixed_temporal_candidates:
        signals.append("mixed_temporal_candidates")
    if low_similarity:
        signals.append("low_similarity")

    surface_quality = "good"
    if not sample:
        surface_quality = "empty"
    elif not ready or low_similarity or unsupported_anchor_gap:
        surface_quality = "low"
    elif assistant_memory_cluster_ready:
        surface_quality = "good"
    elif mixed_temporal_candidates or ambiguity_risk:
        surface_quality = "conflicted"
    elif needs_validation and not docs_evidence_ready:
        surface_quality = "mixed"

    another_recall_may_help = surface_quality in {"low", "mixed", "conflicted"}
    note: Optional[str] = None
    if another_recall_may_help:
        if surface_quality == "conflicted":
            note = "Retrieved memory for this topic looks conflicted. Another recall pass may help if exactness matters."
        elif surface_quality == "low":
            if "low_query_term_coverage" in signals or "unsupported_query_terms" in signals:
                unsupported_note = ""
                if unsupported_query_terms:
                    unsupported_note = (
                        " No retrieved evidence covers these requested terms: "
                        f"{', '.join(unsupported_query_terms[:6])}. Treat the requested event, "
                        "relationship, participant, or object that depends on those terms as "
                        "unsupported by retrieved memory; state that there is no record or evidence "
                        "for it."
                    )
                note = (
                    "Retrieved memory for this topic looks low-confidence because retrieved evidence "
                    "does not cover all important query terms. Do not assume presupposed events, "
                    "relationships, or missing entities from partial matches; answer only from evidence "
                    "or say you do not have information."
                    f"{unsupported_note} If the important terms are absent, say the "
                    "retrieved memory contains no record or evidence that the presupposed event, "
                    "relationship, participant, or object occurred or exists."
                )
            else:
                note = "Retrieved memory for this topic looks low-confidence. Another recall pass may help if exactness matters."
        else:
            note = "Retrieved memory for this topic looks under-validated. Another recall pass may help if exactness matters."

    return {
        "surface_quality": surface_quality,
        "another_recall_may_help": another_recall_may_help,
        "signals": signals,
        "top_similarity": round(top_similarity, 3),
        "close_competitor_count": close_competitor_count,
        "temporal_span_days": temporal_span_days,
        "unsupported_query_terms": unsupported_query_terms,
        "note": note,
    }


def _build_requirement_refinement_queries(
    query: str,
    gate_eval: Dict[str, Any],
    already_searched: List[str],
    *,
    max_queries: int = 2,
) -> List[str]:
    return []


def _should_fast_drill_follow_up(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    planner_meta: Optional[Dict[str, Any]],
    docs_bundle: Optional[Dict[str, Any]],
    limit: int,
) -> Tuple[bool, Dict[str, Any], List[str], str]:
    """Decide whether recall_fast should spend one extra cheap drill turn.

    This keeps the trigger generic by reusing the same quality-gate analysis
    deliberate recall already uses, instead of hard-coding query categories or
    benchmark-specific slots.
    """
    gate_intent = "GENERAL"
    try:
        gate_intent, _ = classify_intent(query)
    except Exception:
        gate_intent = "GENERAL"

    gate_eval = _evaluate_quality_gate_readiness(
        query,
        rows,
        intent=gate_intent,
        limit=limit,
        include_relation_keywords=False,
    )
    meta = dict(planner_meta or {})
    used_llm = bool(meta.get("used_llm"))
    bailout_reason = str(meta.get("bailout_reason") or "")
    query_shape = str(meta.get("query_shape") or "")
    planned_stores = _planner_store_plan(meta.get("planned_stores") or ["vector"])
    preserved_exact = bailout_reason == "preserve_short_exact_query"
    allow_planner_disabled_assistant_memory_drill = (
        bailout_reason == "planner_disabled"
        and _is_assistant_memory_query(query, gate_eval)
        and bool(gate_eval.get("needs_validation"))
        and "docs" not in planned_stores
    )
    reasons: List[str] = []
    if not rows:
        return False, gate_eval, reasons, gate_intent
    if not used_llm and not preserved_exact and not allow_planner_disabled_assistant_memory_drill:
        return False, gate_eval, reasons, gate_intent
    if bailout_reason.endswith("_fallback_off"):
        return False, gate_eval, reasons, gate_intent
    if "docs" in planned_stores:
        # Fast drill is a memory-lane retry. Docs lanes already fan out through
        # docs RAG; re-adding docs drill needs a generic docs-quality gate.
        return False, gate_eval, reasons, gate_intent

    if gate_eval.get("needs_validation"):
        reasons.append("needs_validation")
    if preserved_exact and "docs" not in planned_stores and float(gate_eval.get("overlap_ratio") or 0.0) < 0.85:
        reasons.append("preserved_exact_low_overlap")

    if query_shape not in {"broad", "focused"} and not (preserved_exact and reasons):
        return False, gate_eval, [], gate_intent
    return bool(reasons), gate_eval, reasons, gate_intent


def _build_fast_drill_fallback_queries(
    query: str,
    *,
    gate_eval: Optional[Dict[str, Any]],
    planner_meta: Optional[Dict[str, Any]],
    owner_id: Optional[str] = None,
    current_rows: Optional[List[Dict[str, Any]]] = None,
) -> List[str]:
    """Cheap deterministic fallback when the drill planner returns nothing.

    Keep this narrow: only for broad, LLM-planned queries where the first pass
    has middling lexical overlap and the planned store set is still in the
    memory lane. This avoids reopening the wide/expensive r668 trigger while
    giving a small number of under-resolved synthesis/current-state prompts one
    extra lexical probe.
    """
    gate = dict(gate_eval or {})
    planner = dict(planner_meta or {})
    preserved_exact = str(planner.get("bailout_reason") or "") == "preserve_short_exact_query"
    stores = _planner_store_plan(planner.get("planned_stores") or ["vector"])
    allow_planner_disabled_assistant_memory_fallback = (
        str(planner.get("bailout_reason") or "") == "planner_disabled"
        and _is_assistant_memory_query(query, gate)
        and bool(gate.get("needs_validation"))
        and "docs" not in stores
    )
    if (
        not planner.get("used_llm")
        and not preserved_exact
        and not allow_planner_disabled_assistant_memory_fallback
    ):
        return []
    if str(planner.get("query_shape") or "") not in {"broad", "focused", "narrow"}:
        return []
    if stores not in (["vector"], ["vector", "graph"]):
        return []
    assistant_coverage = int((gate.get("coverage") or {}).get("assistant_source") or 0)
    requirements = {str(item) for item in (gate.get("requirements") or []) if str(item)}

    def _normalize_term(raw: Any) -> str:
        return " ".join(str(raw or "").split()).strip().strip(".,;:!?\"'").lower()

    def _build_assistant_source_fallback() -> List[str]:
        assistant_memory_needs_refine = (
            _is_assistant_memory_query(query, gate)
            and bool(gate.get("needs_validation"))
        )
        if "assistant_source" not in requirements:
            return []
        if assistant_coverage > 0 and not assistant_memory_needs_refine:
            return []
        explicit_terms = [
            _normalize_term(raw)
            for raw in _extract_explicit_query_anchor_terms(query, limit=6)
        ]
        explicit_terms = [term for term in explicit_terms if term]
        if not explicit_terms:
            explicit_terms = [
                _normalize_term(raw)
                for raw in _extract_vocabulary_free_query_terms(query, limit=4)
            ]
            explicit_terms = [term for term in explicit_terms if term]
        anchor_terms: List[str] = []
        seen_anchor_terms: set[str] = set()
        for term in explicit_terms:
            if term in seen_anchor_terms:
                continue
            seen_anchor_terms.add(term)
            anchor_terms.append(term)
            if len(anchor_terms) >= 4:
                break
        if not anchor_terms:
            return []
        queries: List[str] = []
        if len(anchor_terms) >= 2:
            queries.append(" ".join(anchor_terms[:2]))
        queries.append(anchor_terms[0])
        return queries

    assistant_fallback = _build_assistant_source_fallback()
    if assistant_fallback:
        return assistant_fallback

    overlap = float(gate.get("overlap_ratio") or 0.0)
    if overlap < 0.45 or overlap > 0.75:
        return []
    terms = _extract_distinctive_query_terms(query, limit=6)
    if len(terms) < 3:
        return []
    fallback = " ".join(terms).strip()
    if not fallback:
        return []
    if fallback.lower() == " ".join((query or "").lower().split()):
        return []
    return [fallback]


_ASSISTANT_STRUCTURAL_LIST_ANCHOR_KINDS = {
    "assistant_option_bullet_anchor",
    "assistant_callback_anchor",
    "assistant_plan_anchor",
}


def _is_assistant_suggestion_list_query(query: str, gate_eval: Optional[Dict[str, Any]]) -> bool:
    gate = dict(gate_eval or {})
    requirements = {str(item) for item in (gate.get("requirements") or []) if str(item)}
    if "assistant_source" not in requirements or "enumeration" not in requirements:
        return False
    lower = str(query or "").lower()
    return bool(
        re.search(
            r"\b(suggest|suggested|recommend|recommended|options?|ideas?|restaurants?|places?|spots?|venues?)\b",
            lower,
        )
    )


def _is_assistant_memory_query(query: str, gate_eval: Optional[Dict[str, Any]]) -> bool:
    gate = dict(gate_eval or {})
    requirements = {str(item) for item in (gate.get("requirements") or []) if str(item)}
    if "assistant_source" not in requirements or "enumeration" in requirements:
        return False
    return True


def _prioritize_fast_assistant_memory_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    gate_eval: Optional[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    if not rows:
        return rows
    if not _is_assistant_memory_query(query, gate_eval):
        return rows
    anchor_terms = [
        str(term or "").strip().lower()
        for term in _extract_explicit_query_anchor_terms(query, limit=6)
        if str(term or "").strip()
    ]
    if not anchor_terms:
        return rows
    primary_anchor = anchor_terms[0]

    def _row_anchor_match(row: Dict[str, Any]) -> bool:
        lower_text = str((row or {}).get("text") or "").lower()
        if primary_anchor:
            return primary_anchor in lower_text
        return any(term in lower_text for term in anchor_terms)

    def _row_primary_anchor_match(row: Dict[str, Any]) -> bool:
        lower_text = str((row or {}).get("text") or "").lower()
        return bool(primary_anchor and primary_anchor in lower_text)

    priority_rows: List[Dict[str, Any]] = []
    remaining_rows: List[Dict[str, Any]] = []
    anchor_kind_priority = {
        "assistant_callback_anchor": 3,
        "assistant_option_list_anchor": 2,
        "assistant_option_bullet_anchor": 1,
    }
    for row in rows:
        if not isinstance(row, dict):
            remaining_rows.append(row)
            continue
        if row.get("via_relation") or row.get("graph_path") or _is_docs_recall_row(row):
            remaining_rows.append(row)
            continue
        if str((row or {}).get("source_type") or "").strip().lower() != "assistant":
            remaining_rows.append(row)
            continue
        lower_text = str((row or {}).get("text") or "").lower()
        kind = str((row or {}).get("structural_anchor_kind") or "").strip().lower()
        if kind not in anchor_kind_priority and not row.get("_assistant_memory_recovery"):
            remaining_rows.append(row)
            continue
        if not row.get("_assistant_memory_recovery") and not _row_anchor_match(row):
            remaining_rows.append(row)
            continue
        priority_rows.append(row)

    priority_rows.sort(
        key=lambda row: (
            1 if row.get("_assistant_memory_recovery") else 0,
            anchor_kind_priority.get(str((row or {}).get("structural_anchor_kind") or "").strip().lower(), 0),
            1 if _row_primary_anchor_match(row) else 0,
            1 if _row_anchor_match(row) else 0,
            float((row or {}).get("similarity", 0.0) or 0.0),
        ),
        reverse=True,
    )
    remaining_rows.sort(
        key=lambda row: (
            1 if isinstance(row, dict) and _row_primary_anchor_match(row) else 0,
            1 if isinstance(row, dict) and _row_anchor_match(row) else 0,
            float((row or {}).get("similarity", 0.0) or 0.0) if isinstance(row, dict) else 0.0,
        ),
        reverse=True,
    )
    return priority_rows + remaining_rows


def _assistant_memory_surface_resolved(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    gate_eval: Optional[Dict[str, Any]],
) -> bool:
    if not _is_assistant_memory_query(query, gate_eval):
        return False
    sample = [row for row in list(rows or [])[:5] if isinstance(row, dict)]
    if not sample:
        return False
    anchor_terms = [
        str(term or "").strip().lower()
        for term in _extract_explicit_query_anchor_terms(query, limit=6)
        if str(term or "").strip()
    ]
    if not anchor_terms:
        return False
    primary_anchor = anchor_terms[0]

    def _row_assistant_memory_match(row: Dict[str, Any]) -> bool:
        lower_text = str((row or {}).get("text") or "").lower()
        source_type = str((row or {}).get("source_type") or "").strip().lower()
        kind = str((row or {}).get("structural_anchor_kind") or "").strip().lower()
        if source_type != "assistant":
            return False
        if kind not in {
            "assistant_callback_anchor",
            "assistant_option_list_anchor",
            "assistant_option_bullet_anchor",
        } and not row.get("_assistant_memory_recovery"):
            return False
        return bool(row.get("_assistant_memory_recovery") or (primary_anchor and primary_anchor in lower_text))

    assistant_rows = [row for row in sample if _row_assistant_memory_match(row)]
    if not assistant_rows:
        return False
    return _row_assistant_memory_match(sample[0])


def _build_recall_row_from_node(
    node: "Node",
    *,
    similarity: float,
    structural_anchor_kind: Optional[str] = None,
    recovered_assistant_list: bool = False,
) -> Dict[str, Any]:
    attrs = node.attributes if isinstance(node.attributes, dict) else {}
    row = {
        "text": node.name,
        "category": node.type.lower(),
        "similarity": round(float(similarity), 4),
        "verified": bool(node.verified),
        "pinned": bool(node.pinned),
        "id": node.id,
        "extraction_confidence": float(node.extraction_confidence),
        "created_at": node.created_at,
        "occurred_start": node.occurred_start,
        "occurred_end": node.occurred_end,
        "mentioned_at": node.mentioned_at,
        "valid_from": node.valid_from,
        "valid_until": node.valid_until,
        "source_date": attrs.get("source_date"),
        "source_id": node.source_id,
        "source_chunk_id": node.source_chunk_id,
        "session_id": str(attrs.get("source_session_id") or node.session_id or "").strip() or None,
        "privacy": node.privacy,
        "owner_id": node.owner_id,
        "_multi_pass": False,
        "domains": attrs.get("domains"),
        "keywords": getattr(node, "keywords", None),
        "source_type": attrs.get("source_type"),
        "project": attrs.get("project"),
        "source_channel": str(attrs.get("source_channel") or "").strip().lower() or None,
        "source_conversation_id": str(attrs.get("source_conversation_id") or attrs.get("conversation_id") or node.conversation_id or "").strip() or None,
        "source_author_id": str(attrs.get("source_author_id") or "").strip() or None,
        "actor_id": str(attrs.get("actor_id") or "").strip() or None,
        "speaker_entity_id": str(attrs.get("speaker_entity_id") or node.speaker_entity_id or "").strip() or None,
        "subject_entity_id": str(attrs.get("subject_entity_id") or "").strip() or None,
        "conversation_id": str(attrs.get("conversation_id") or node.conversation_id or "").strip() or None,
        "visibility_scope": str(attrs.get("visibility_scope") or node.visibility_scope or "source_shared").strip(),
        "sensitivity": str(attrs.get("sensitivity") or node.sensitivity or "normal").strip(),
        "provenance_confidence": attrs.get("provenance_confidence", node.provenance_confidence),
        "participant_entity_ids": attrs.get("participant_entity_ids"),
    }
    if structural_anchor_kind:
        row["structural_anchor_kind"] = structural_anchor_kind
    if recovered_assistant_list:
        row["_assistant_list_recovery"] = True
    return row


def _cluster_sibling_fallback_score(cluster_best_score: float) -> float:
    """Default sibling cluster score, floored to the normalized score range."""
    return max(0.0, float(cluster_best_score) - 0.08)


def _recover_assistant_suggestion_cluster_rows(
    query: str,
    *,
    gate_eval: Optional[Dict[str, Any]],
    owner_id: Optional[str],
    limit: int,
) -> List[Dict[str, Any]]:
    if not _is_assistant_suggestion_list_query(query, gate_eval):
        return []

    graph = get_graph()
    search_limit = max(160, min(400, max(1, int(limit)) * 50))
    try:
        raw_results = graph.search_hybrid(query, limit=search_limit, owner_id=owner_id)
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Assistant suggestion cluster recovery search failed while failHard is enabled"
            ) from exc
        logger.debug("assistant suggestion cluster recovery search failed", exc_info=True)
        return []

    cluster_scores: Dict[str, Tuple[float, int]] = {}
    candidate_scores: Dict[str, float] = {}
    candidate_nodes: Dict[str, Node] = {}
    for node, score in raw_results:
        attrs = node.attributes if isinstance(node.attributes, dict) else {}
        if str(attrs.get("source_type") or "").strip().lower() != "assistant":
            continue
        kind = str(attrs.get("structural_anchor_kind") or "").strip().lower()
        if kind not in _ASSISTANT_STRUCTURAL_LIST_ANCHOR_KINDS:
            continue
        created_at = str(node.created_at or "").strip()
        if not created_at:
            continue
        adjusted = float(score)
        if kind == "assistant_option_bullet_anchor":
            adjusted += 0.10
        elif kind == "assistant_callback_anchor":
            adjusted += 0.06
        else:
            adjusted += 0.03
        candidate_nodes[node.id] = node
        candidate_scores[node.id] = adjusted
        prior_best, prior_count = cluster_scores.get(created_at, (0.0, 0))
        cluster_scores[created_at] = (max(prior_best, adjusted), prior_count + 1)

    if not cluster_scores:
        return []

    target_created_at = max(
        cluster_scores.items(),
        key=lambda item: (item[1][0], item[1][1], item[0]),
    )[0]
    cluster_best_score = float(cluster_scores[target_created_at][0])

    params: List[Any] = [target_created_at]
    owner_sql = ""
    if owner_id:
        owner_sql = " AND owner_id = ?"
        params.append(owner_id)
    sibling_rows: List[sqlite3.Row] = []
    try:
        with graph._get_conn() as conn:
            sibling_rows = conn.execute(
                f"""
                SELECT *
                FROM nodes
                WHERE created_at = ?
                  {owner_sql}
                  AND json_extract(attributes, '$.source_type') = 'assistant'
                  AND json_extract(attributes, '$.structural_anchor_kind') IN (
                    'assistant_option_bullet_anchor',
                    'assistant_callback_anchor',
                    'assistant_plan_anchor'
                  )
                ORDER BY created_at, id
                """,
                params,
            ).fetchall()
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Assistant suggestion cluster sibling fetch failed while failHard is enabled"
            ) from exc
        logger.debug("assistant suggestion cluster sibling fetch failed", exc_info=True)
        return []

    recovered: List[Dict[str, Any]] = []
    for sql_row in sibling_rows:
        node = graph._row_to_node(sql_row)
        attrs = node.attributes if isinstance(node.attributes, dict) else {}
        kind = str(attrs.get("structural_anchor_kind") or "").strip().lower()
        similarity = candidate_scores.get(node.id, _cluster_sibling_fallback_score(cluster_best_score))
        recovered.append(
            _build_recall_row_from_node(
                node,
                similarity=similarity,
                structural_anchor_kind=kind,
                recovered_assistant_list=True,
            )
        )

    if not recovered:
        return []

    kind_priority = {
        "assistant_option_bullet_anchor": 3,
        "assistant_callback_anchor": 2,
        "assistant_plan_anchor": 1,
    }
    recovered.sort(
        key=lambda row: (
            kind_priority.get(str(row.get("structural_anchor_kind") or ""), 0),
            float(row.get("similarity") or 0.0),
            str(row.get("text") or ""),
        ),
        reverse=True,
    )
    return recovered


def _recover_assistant_memory_cluster_rows(
    query: str,
    *,
    gate_eval: Optional[Dict[str, Any]],
    owner_id: Optional[str],
    limit: int,
    current_rows: Optional[List[Dict[str, Any]]] = None,
) -> List[Dict[str, Any]]:
    if not _is_assistant_memory_query(query, gate_eval):
        return []

    anchor_terms = [
        str(term or "").strip().lower()
        for term in _extract_explicit_query_anchor_terms(query, limit=6)
        if str(term or "").strip()
    ]
    if anchor_terms:
        anchor_terms = [anchor_terms[0]]
    if not anchor_terms:
        return []

    owner_ids = sorted({
        str((row or {}).get("owner_id") or "").strip()
        for row in (current_rows or [])
        if isinstance(row, dict) and str((row or {}).get("owner_id") or "").strip()
    })

    cluster_scores: Dict[str, Tuple[float, int]] = {}
    candidate_scores: Dict[str, float] = {}
    graph = get_graph()
    raw_results: List[Tuple["Node", float]] = []

    def _accumulate_candidate(
        *,
        node_id: str,
        lower_text: str,
        kind: str,
        score: float,
        created_at: str,
        require_anchor_match: bool,
    ) -> None:
        if anchor_terms and not any(term in lower_text for term in anchor_terms):
            if require_anchor_match or kind != "assistant_callback_anchor":
                return
            if float(score) < 0.40:
                return
        adjusted = float(score)
        if kind == "assistant_callback_anchor":
            adjusted += 0.02
        elif kind == "assistant_option_list_anchor":
            adjusted += 0.06
        else:
            adjusted += 0.03
        candidate_scores[node_id] = adjusted
        prior_best, prior_count = cluster_scores.get(created_at, (0.0, 0))
        cluster_scores[created_at] = (max(prior_best, adjusted), prior_count + 1)

    if current_rows:
        for row in current_rows:
            if not isinstance(row, dict):
                continue
            if str(row.get("source_type") or "").strip().lower() != "assistant":
                continue
            kind = str(row.get("structural_anchor_kind") or "").strip().lower()
            if kind not in {
                "assistant_callback_anchor",
                "assistant_option_list_anchor",
                "assistant_option_bullet_anchor",
            }:
                continue
            created_at = str(row.get("created_at") or "").strip()
            if not created_at:
                continue
            _accumulate_candidate(
                node_id=str(row.get("id") or ""),
                lower_text=str(row.get("text") or "").lower(),
                kind=kind,
                score=float(row.get("similarity") or 0.0),
                created_at=created_at,
                require_anchor_match=True,
            )
    else:
        search_limit = max(120, min(320, max(1, int(limit)) * 40))
        try:
            raw_results = graph.search_hybrid(query, limit=search_limit, owner_id=owner_id)
        except Exception as exc:
            if _is_fail_hard_mode():
                raise RuntimeError(
                    "Assistant memory cluster recovery search failed while failHard is enabled"
                ) from exc
            logger.debug("assistant memory cluster recovery search failed", exc_info=True)
            return []

        for node, score in raw_results:
            attrs = node.attributes if isinstance(node.attributes, dict) else {}
            if str(attrs.get("source_type") or "").strip().lower() != "assistant":
                continue
            kind = str(attrs.get("structural_anchor_kind") or "").strip().lower()
            if kind not in {
                "assistant_callback_anchor",
                "assistant_option_list_anchor",
                "assistant_option_bullet_anchor",
            }:
                continue
            created_at = str(node.created_at or "").strip()
            if not created_at:
                continue
            _accumulate_candidate(
                node_id=str(node.id),
                lower_text=str(node.name or "").lower(),
                kind=kind,
                score=float(score or 0.0),
                created_at=created_at,
                require_anchor_match=False,
            )

    if not cluster_scores:
        seed_params: List[Any] = []
        owner_sql = ""
        if owner_ids:
            owner_sql = " AND owner_id IN ({})".format(",".join("?" for _ in owner_ids))
            seed_params.extend(owner_ids)
        elif owner_id:
            owner_sql = " AND owner_id = ?"
            seed_params.append(owner_id)
        anchor_clause = " OR ".join("LOWER(name) LIKE ?" for _ in anchor_terms)
        seed_params.extend(f"%{term}%" for term in anchor_terms)
        try:
            with graph._get_conn() as conn:
                seed_rows = conn.execute(
                    f"""
                    SELECT *
                    FROM nodes
                    WHERE json_extract(attributes, '$.source_type') = 'assistant'
                      AND json_extract(attributes, '$.structural_anchor_kind') IN (
                        'assistant_callback_anchor',
                        'assistant_option_list_anchor',
                        'assistant_option_bullet_anchor'
                      )
                      {owner_sql}
                      AND ({anchor_clause})
                    ORDER BY created_at, id
                    """,
                    seed_params,
                ).fetchall()
        except Exception as exc:
            if _is_fail_hard_mode():
                raise RuntimeError(
                    "Assistant memory fallback seed fetch failed while failHard is enabled"
                ) from exc
            logger.debug("assistant memory fallback seed fetch failed", exc_info=True)
            seed_rows = []

        seed_score_by_kind = {
            "assistant_option_list_anchor": 0.47,
            "assistant_callback_anchor": 0.43,
            "assistant_option_bullet_anchor": 0.35,
        }
        for sql_row in seed_rows:
            node = graph._row_to_node(sql_row)
            attrs = node.attributes if isinstance(node.attributes, dict) else {}
            kind = str(attrs.get("structural_anchor_kind") or "").strip().lower()
            created_at = str(node.created_at or "").strip()
            if not created_at or kind not in seed_score_by_kind:
                continue
            base_score = float(seed_score_by_kind[kind])
            raw_results.append((node, base_score))
            _accumulate_candidate(
                node_id=str(node.id),
                lower_text=str(node.name or "").lower(),
                kind=kind,
                score=base_score,
                created_at=created_at,
                require_anchor_match=True,
            )

    if not cluster_scores:
        return []

    target_created_at = max(
        cluster_scores.items(),
        key=lambda item: (item[1][0], item[1][1], item[0]),
    )[0]
    cluster_best_score = float(cluster_scores[target_created_at][0])

    params: List[Any] = [target_created_at]
    owner_sql = ""
    if owner_ids:
        owner_sql = " AND owner_id IN ({})".format(",".join("?" for _ in owner_ids))
        params.extend(owner_ids)
    elif owner_id:
        owner_sql = " AND owner_id = ?"
        params.append(owner_id)
    try:
        with graph._get_conn() as conn:
            sibling_rows = conn.execute(
                f"""
                SELECT *
                FROM nodes
                WHERE created_at = ?
                  {owner_sql}
                  AND json_extract(attributes, '$.source_type') = 'assistant'
                  AND json_extract(attributes, '$.structural_anchor_kind') IN (
                    'assistant_callback_anchor',
                    'assistant_option_list_anchor',
                    'assistant_option_bullet_anchor'
                  )
                ORDER BY created_at, id
                """,
                params,
            ).fetchall()
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError(
                "Assistant memory cluster sibling fetch failed while failHard is enabled"
            ) from exc
        logger.debug("assistant memory cluster sibling fetch failed", exc_info=True)
        return []

    recovered: List[Dict[str, Any]] = []
    for sql_row in sibling_rows:
        node = graph._row_to_node(sql_row)
        attrs = node.attributes if isinstance(node.attributes, dict) else {}
        kind = str(attrs.get("structural_anchor_kind") or "").strip().lower()
        lower_text = str(node.name or "").lower()
        if anchor_terms and not any(term in lower_text for term in anchor_terms):
            if kind != "assistant_callback_anchor":
                continue
            if candidate_scores.get(node.id, 0.0) <= 0.0:
                continue
        similarity = candidate_scores.get(node.id, _cluster_sibling_fallback_score(cluster_best_score))
        recovered.append(
            _build_recall_row_from_node(
                node,
                similarity=similarity,
                structural_anchor_kind=kind,
            )
        )

    if not recovered:
        return []

    kind_priority = {
        "assistant_callback_anchor": 3,
        "assistant_option_list_anchor": 2,
        "assistant_option_bullet_anchor": 1,
    }
    recovered.sort(
        key=lambda row: (
            1 if row.get("_assistant_memory_recovery") else 0,
            kind_priority.get(str(row.get("structural_anchor_kind") or ""), 0),
            float(row.get("similarity") or 0.0),
            str(row.get("text") or ""),
        ),
        reverse=True,
    )
    return recovered


def _prioritize_recovered_assistant_list_rows(
    query: str,
    rows: List[Dict[str, Any]],
    *,
    gate_eval: Optional[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    if not rows or not _is_assistant_suggestion_list_query(query, gate_eval):
        return rows

    kind_priority = {
        "assistant_option_bullet_anchor": 3,
        "assistant_callback_anchor": 2,
        "assistant_plan_anchor": 1,
    }
    indexed: List[Tuple[Tuple[int, int, float, float, int], Dict[str, Any]]] = []
    for index, row in enumerate(rows):
        recovered = 1 if row.get("_assistant_list_recovery") else 0
        kind = kind_priority.get(str(row.get("structural_anchor_kind") or ""), 0)
        source_type = 1 if str(row.get("source_type") or "").strip().lower() == "assistant" else 0
        similarity = float(row.get("similarity") or 0.0)
        indexed.append(((recovered, kind, source_type, similarity, -index), row))
    indexed.sort(key=lambda item: item[0], reverse=True)
    return [row for _, row in indexed]


def _compute_query_fit_multiplier(
    query: str,
    node: Node,
    attrs: Optional[Dict[str, Any]],
    *,
    intent: str = "GENERAL",
    include_anchor_terms: bool = True,
    query_anchor_terms: Optional[List[str]] = None,
    allow_anchor_miss_penalty: bool = True,
    include_relation_keywords: bool = True,
) -> float:
    # Recall shaping policy: keep this deterministic scorer language-agnostic.
    # Do not add English semantic mappings here (for example family, org-chart,
    # location, or device relationship rules). Semantic interpretation belongs
    # in the fast LLM planner/reranker or the final calling model so multilingual
    # queries are handled by the model instead of hand-written lexical guards.
    analysis = _derive_query_requirements(
        query,
        intent=intent,
        include_relation_keywords=include_relation_keywords,
    )
    query_terms = list(analysis["query_terms"])
    text = f"{node.name} {' '.join(str(v) for v in (attrs or {}).values() if isinstance(v, (str, int, float)))}"
    row = {
        "text": text,
        "category": node.type.lower(),
        "source_type": (attrs or {}).get("source_type"),
        "visibility_scope": (attrs or {}).get("visibility_scope"),
    }

    bonus = 0.0
    overlap = _query_term_overlap(row, query_terms)
    if overlap:
        bonus += min(0.12, overlap * 0.04)
    requirement_bonus = {
        "assistant_source": 0.08,
        "temporal": 0.05,
        "identity": 0.05,
        "location": 0.05,
        "organization": 0.05,
        "causal": 0.05,
        "enumeration": 0.05,
        "technical": 0.04,
    }
    structured_enumeration = bool({"technical", "assistant_source"} & set(analysis.get("requirements") or []))
    for requirement in analysis.get("requirements") or []:
        if requirement == "enumeration" and not structured_enumeration:
            continue
        if _row_matches_requirement(row, requirement):
            bonus += requirement_bonus.get(requirement, 0.0)
    multiplier = 1.0 + min(0.24, bonus)

    anchor_terms = (
        list(query_anchor_terms or [])
        if query_anchor_terms is not None
        else (_extract_explicit_query_anchor_terms(query) if include_anchor_terms else [])
    )
    if anchor_terms:
        lower_text = text.lower()
        matched_anchor_terms = [
            term for term in anchor_terms
            if _text_contains_anchor_term(lower_text, term)
        ]
        if matched_anchor_terms:
            anchor_boost = 1.22 + min(0.16, 0.06 * (len(matched_anchor_terms) - 1))
            multiplier *= anchor_boost
        elif allow_anchor_miss_penalty:
            # Keep anchor shaping helpful without over-punishing strict planner misses.
            # With restrictive LLM anchors, a full miss should down-rank, but not as
            # aggressively as the legacy lexical path.
            missing_count = max(1, len(anchor_terms))
            anchor_miss_penalty = 0.88 if missing_count <= 1 else 0.84
            multiplier *= anchor_miss_penalty
            source_type = str((attrs or {}).get("source_type") or "").strip().lower()
            visibility_scope = str((attrs or {}).get("visibility_scope") or "").strip().lower()
            if source_type in {"import", "tool"}:
                multiplier *= 0.92
            if visibility_scope in {"global_shared", "system"}:
                multiplier *= 0.92

    return max(0.35, min(1.45, multiplier))


def _estimate_fanout_profile(query: str, max_queries: int, planner_profile: str = "full") -> Dict[str, Any]:
    """Estimate fanout breadth before paying for multiple retrieval branches."""
    clean = " ".join((query or "").split())
    tokens = [tok for tok in clean.split() if tok]
    lower = clean.lower()
    named_tokens = [tok for tok in tokens if tok[:1].isupper() and len(tok) > 2]
    try:
        estimated_tokens = max(len(tokens), int(_lib_estimate_tokens(clean or "")))
    except Exception:
        estimated_tokens = max(1, len(tokens))
    alpha_chars = sum(1 for ch in clean if str(ch).isalpha())
    low_space_query = (
        bool(clean)
        and len(tokens) <= 2
        and alpha_chars >= 6
        and estimated_tokens >= max(4, len(tokens) * 2)
    )

    signals: List[str] = []
    if len(tokens) >= 8:
        signals.append("long_query")
    if len(named_tokens) >= 2:
        signals.append("multi_entity")
    if low_space_query:
        signals.append("low_space_query")
    if any(phrase in lower for phrase in [
        "over time", "what changed", "changed about", "trace ", "timeline",
        "career arc", "relationship", "week of", "what's new", "whats new",
        "update me", "catch me up", "summarize", "everything", "why ",
        "how did", "plan ", "walk me through", "compare",
    ]):
        signals.append("broad_intent")
    if any(word in lower for word in [" and ", " then ", " plus ", " also "]):
        signals.append("multi_clause")

    if any(sig in signals for sig in ("broad_intent", "multi_entity")) or len(signals) >= 2:
        shape = "broad"
    elif len(tokens) <= 4 and len(named_tokens) <= 1 and not signals:
        shape = "narrow"
    else:
        shape = "focused"

    budget = max_queries

    return {
        "shape": shape,
        "fanout_budget": max(1, budget),
        "token_count": len(tokens),
        "estimated_token_count": estimated_tokens,
        "named_entity_tokens": len(named_tokens),
        "segmentation_confidence": "low" if low_space_query else "high",
        "low_space_query": low_space_query,
        "signals": signals,
        "planner_profile": planner_profile,
    }


def _should_preserve_query_after_empty_plan(
    query: str,
    *,
    profile: Optional[Dict[str, Any]] = None,
    default_stores: Optional[List[str]] = None,
    default_project: Optional[str] = None,
) -> bool:
    """Keep a meaningful recall query alive when the planner returns [].

    The planner is allowed to short-circuit obvious filler/greetings earlier.
    Once we reach this branch, an empty LLM plan on a concrete recall prompt is
    more likely planner over-conservatism than genuine "no retrieval needed".
    Preserve the user's exact query for focused/exact prompts rather than
    converting a real recall ask into planner_returned_empty.
    """
    clean = " ".join(str(query or "").split()).strip()
    if not clean:
        return False
    if _is_single_structural_exact_query(clean):
        return True

    query_profile = dict(profile or {})
    token_count = int(query_profile.get("token_count") or len(clean.split()))
    shape = str(query_profile.get("shape") or "")
    planned_default_stores = list(_planner_store_plan(default_stores))
    explicit_anchors = _extract_explicit_query_anchor_terms(clean, limit=4)
    distinctive_terms = _extract_distinctive_query_terms(clean, limit=6)
    has_anchor_signal = bool(explicit_anchors) or len(distinctive_terms) >= 2

    if default_project or "docs" in planned_default_stores:
        return has_anchor_signal
    if shape in {"narrow", "focused"} and token_count <= 24 and has_anchor_signal:
        return True
    if token_count >= 8 and len(distinctive_terms) >= 3:
        return True
    return False


def _build_branch_telemetry(
    queries: List[str],
    branch_metas: List[Dict[str, Any]],
    wall_ms: float,
    max_workers: int,
) -> Dict[str, Any]:
    """Build per-branch telemetry plus parallelism summaries for a fanout turn."""
    branches: List[Dict[str, Any]] = []
    for index, meta in enumerate(branch_metas):
        phases = meta.get("phases_ms") or {}
        branch = {
            "index": index,
            "query": queries[index] if index < len(queries) else meta.get("query"),
            "total_ms": max(0, int(round(float(phases.get("total_ms", 0) or 0)))),
            "phases_ms": {
                str(k): max(0, int(round(float(v))))
                for k, v in phases.items()
                if isinstance(v, (int, float))
            },
            "counts": {
                str(k): int(v)
                for k, v in (meta.get("counts") or {}).items()
                if isinstance(v, (int, float))
            },
            "flags": {
                str(k): bool(v)
                for k, v in (meta.get("flags") or {}).items()
                if isinstance(v, bool)
            },
            "intent": meta.get("intent"),
            "search_query": meta.get("search_query"),
            "telemetry": meta.get("telemetry") if isinstance(meta.get("telemetry"), dict) else None,
        }
        if meta.get("error_type"):
            branch["error_type"] = meta.get("error_type")
            branch["error"] = meta.get("error")
            branch["timed_out"] = bool(meta.get("timed_out"))
        branches.append(branch)

    total_values = [float(branch["total_ms"]) for branch in branches]
    search_values = [float((branch.get("phases_ms") or {}).get("search_hybrid_ms", 0)) for branch in branches]
    graph_values = [float((branch.get("phases_ms") or {}).get("graph_traversal_ms", 0)) for branch in branches]
    reranker_values = [float((branch.get("phases_ms") or {}).get("reranker_ms", 0)) for branch in branches]
    mmr_values = [float((branch.get("phases_ms") or {}).get("mmr_ms", 0)) for branch in branches]
    serial_sum_ms = int(round(sum(total_values))) if total_values else 0
    fastest_branch = min(branches, key=lambda branch: branch["total_ms"]) if branches else None
    slowest_branch = max(branches, key=lambda branch: branch["total_ms"]) if branches else None
    wall_ms_i = max(0, int(round(wall_ms)))
    speedup_x = round(serial_sum_ms / wall_ms_i, 2) if wall_ms_i > 0 else 0.0
    efficiency_pct = round((speedup_x / max(1, max_workers)) * 100, 1) if wall_ms_i > 0 else 0.0

    return {
        "queries": queries[:],
        "branch_count": len(branches),
        "max_workers": max_workers,
        "wall_ms": wall_ms_i,
        "serial_sum_ms": serial_sum_ms,
        "saved_vs_serial_ms": max(0, serial_sum_ms - wall_ms_i),
        "overhead_vs_slowest_ms": max(0, wall_ms_i - int((slowest_branch or {}).get("total_ms", 0))),
        "parallel_speedup_x": speedup_x,
        "parallel_efficiency_pct": efficiency_pct,
        "branch_total_ms": _summarize_phase_stats(total_values),
        "branch_search_ms": _summarize_phase_stats(search_values),
        "branch_graph_ms": _summarize_phase_stats(graph_values),
        "branch_reranker_ms": _summarize_phase_stats(reranker_values),
        "branch_mmr_ms": _summarize_phase_stats(mmr_values),
        "fastest_branch": fastest_branch,
        "slowest_branch": slowest_branch,
        "branches": branches,
    }


def _canonicalize_lexical_anchor_meta(raw: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(raw, dict):
        return None
    anchors_raw = raw.get("anchors")
    anchors = [str(x).strip() for x in anchors_raw[:24]] if isinstance(anchors_raw, list) else []
    anchors = [a for a in anchors if a]
    anchor_count = int(raw.get("anchor_count") or len(anchors) or 0)
    return {
        "used_llm": bool(raw.get("used_llm")),
        "bailout_reason": raw.get("bailout_reason"),
        "elapsed_ms": int(raw.get("elapsed_ms") or 0),
        "timeout_ms": int(raw.get("timeout_ms") or 0),
        "anchor_count": anchor_count,
        "limit": int(raw.get("limit") or 0),
        "anchors": anchors,
        "source": raw.get("source"),
    }


def _summarize_branch_lexical_anchor(branch_metas: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = []
    for meta in branch_metas:
        lexical = _canonicalize_lexical_anchor_meta(meta.get("lexical_anchor"))
        if lexical is not None:
            candidates.append(lexical)
    if not candidates:
        return None

    # Prefer useful anchors from LLM-driven branches; otherwise pick the
    # strongest non-empty branch and keep observability counters.
    selected = sorted(
        candidates,
        key=lambda entry: (
            1 if entry.get("used_llm") else 0,
            int(entry.get("anchor_count") or 0),
            -int(entry.get("elapsed_ms") or 0),
        ),
        reverse=True,
    )[0]
    out = dict(selected)
    out["branch_count"] = len(candidates)
    out["used_llm_branches"] = sum(1 for entry in candidates if entry.get("used_llm"))
    out["non_empty_branches"] = sum(1 for entry in candidates if int(entry.get("anchor_count") or 0) > 0)
    return out


def _plan_fanout_queries(
    query: str,
    max_queries: int = 5,
    timeout_s: float = 1.5,
    return_meta: bool = False,
    planner_profile: str = "full",
    max_retries: int = 0,
):
    """Generate multiple HyDE-style search queries in a single fast LLM call.

    Replaces both route_query() and _plan_recall_queries() for injection path.
    Returns 1-N declarative search queries (the LLM decides fanout), or []
    when retrieval should be skipped.
    """
    import time as _time
    started = _time.monotonic()
    try:
        timeout_s = max(0.1, float(timeout_s))
    except Exception:
        timeout_s = _RECALL_PLANNER_TIMEOUT_CAP_S
    _trace_m15(
        "planner.fanout.entry",
        query=query,
        max_queries=max_queries,
        timeout_s=timeout_s,
        planner_profile=planner_profile,
        return_meta=return_meta,
    )
    meta = {
        "query": query,
        "timeout_ms": round(timeout_s * 1000),
        "used_llm": False,
        "bailout_reason": None,
        "queries_count": 0,
        "elapsed_ms": 0,
        "query_shape": "unknown",
        "fanout_budget": max(1, max_queries),
        "token_count": 0,
        "named_entity_tokens": 0,
        "shape_signals": [],
        "planner_profile": planner_profile,
        "planned_stores": ["vector"],
        "planned_project": None,
        "freshness_preferred": False,
    }

    def _finish(out: List[str], bailout_reason: Optional[str] = None):
        meta["queries_count"] = len(out)
        meta["bailout_reason"] = bailout_reason
        meta["elapsed_ms"] = round((_time.monotonic() - started) * 1000)
        _trace_m15(
            "planner.fanout.finish",
            query=clean,
            output_queries=out,
            bailout_reason=bailout_reason,
            meta=meta,
            called_fast_reasoning=bool(meta.get("used_llm")),
        )
        if return_meta:
            return out, meta
        return out

    def _planner_fallback_or_raise(
        bailout_reason: str,
        message: str,
        *,
        exc: Optional[Exception] = None,
    ):
        meta["bailout_reason"] = bailout_reason
        meta["elapsed_ms"] = round((_time.monotonic() - started) * 1000)
        try:
            from lib.fail_policy import is_fail_hard_enabled
            fail_hard = bool(is_fail_hard_enabled())
        except Exception:
            fail_hard = True
        detail_lc = " ".join(part for part in [message, str(exc or "")] if part).lower()
        timeout_like = (
            bailout_reason == "planner_exception_fallback"
            and (
                isinstance(exc, TimeoutError)
                or "timed out" in detail_lc
                or "timeout" in detail_lc
            )
        )
        _trace_m15(
            "planner.fanout.fallback_or_raise",
            query=clean,
            bailout_reason=bailout_reason,
            message=message,
            exc_type=type(exc).__name__ if exc is not None else None,
            error=str(exc) if exc is not None else "",
            timeout_like=timeout_like,
            fail_hard=fail_hard,
            meta=meta,
        )
        if timeout_like and not fail_hard:
            # The fast fanout planner is a best-effort query-expansion gate.
            # If it times out, use the original query rather than fail the
            # entire recall path. Under failHard, LLM/provider failures must
            # surface instead of being scored as degraded recall.
            return _finish([clean], "planner_timeout_fallback")
        if fail_hard:
            # failHard=true means dev: surface planner failures loudly rather than
            # silently degrading. Fallback only happens when failHard=false (prod).
            detail = (
                f"{message} "
                f"(planner_timeout_ms={meta.get('timeout_ms', 0)}, "
                f"planner_elapsed_ms={meta.get('elapsed_ms', 0)}, "
                f"planner_profile={meta.get('planner_profile')}, "
                f"query_shape={meta.get('query_shape')})"
            )
            if exc is not None:
                raise RuntimeError(
                    f"Recall fanout planner failed while failHard is enabled: {detail}"
                ) from exc
            raise RuntimeError(
                f"Recall fanout planner failed while failHard is enabled: {detail}"
            )
        return _finish([clean], bailout_reason)

    clean = " ".join((query or "").split())
    default_stores, default_project = _infer_recall_store_defaults(clean)
    profile = _estimate_fanout_profile(clean, max_queries=max_queries, planner_profile=planner_profile)
    _trace_m15(
        "planner.fanout.classification",
        query=clean,
        default_stores=default_stores,
        default_project=default_project,
        profile=profile,
        low_information=_is_low_information_message(clean),
        clean_len=len(clean),
    )
    meta["query_shape"] = str(profile["shape"])
    meta["fanout_budget"] = int(profile["fanout_budget"])
    meta["token_count"] = int(profile["token_count"])
    meta["estimated_token_count"] = int(profile.get("estimated_token_count") or profile["token_count"])
    meta["named_entity_tokens"] = int(profile["named_entity_tokens"])
    meta["segmentation_confidence"] = str(profile.get("segmentation_confidence") or "high")
    meta["low_space_query"] = bool(profile.get("low_space_query"))
    meta["shape_signals"] = list(profile["signals"])
    meta["planner_profile"] = str(profile.get("planner_profile") or planner_profile)
    meta["planned_stores"] = list(_planner_store_plan(default_stores))
    meta["planned_project"] = default_project
    max_queries = max(1, int(profile["fanout_budget"]))
    if not clean:
        _trace_m15("planner.fanout.short_circuit", query=clean, reason="empty_query")
        return _finish([], "empty_query")
    if _is_low_information_message(clean):
        _trace_m15("planner.fanout.short_circuit", query=clean, reason="low_information_message")
        return _finish([], "low_information_message")
    if len(clean) < 10:
        _trace_m15("planner.fanout.short_circuit", query=clean, reason="too_short", clean_len=len(clean))
        return _finish([clean], "too_short")
    if planner_profile == "off":
        _trace_m15("planner.fanout.short_circuit", query=clean, reason="planner_disabled")
        return _finish([clean], "planner_disabled")
    planned_default_stores = list(_planner_store_plan(default_stores))
    profile_signals = set(profile.get("signals") or [])
    short_broad_exact_query = (
        profile["shape"] == "broad"
        and int(profile["token_count"]) <= 5
        and "multi_clause" not in profile_signals
        and default_project is None
    )
    fast_anchored_exact_query = (
        planner_profile == "fast"
        and int(profile["token_count"]) <= 16
        and int(profile["named_entity_tokens"]) >= 1
        and "broad_intent" not in profile_signals
        and not bool(profile.get("low_space_query"))
    )
    fast_long_query = (
        planner_profile == "fast"
        and int(profile["token_count"]) > 16
        and not bool(profile.get("low_space_query"))
    )
    if short_broad_exact_query:
        _trace_m15(
            "planner.fanout.short_circuit",
            query=clean,
            reason="short_broad_exact_query",
            profile=profile,
            planned_default_stores=planned_default_stores,
        )
        return _finish([clean], "preserve_short_exact_query")
    if fast_anchored_exact_query:
        # Fast pre-inject should not depend on a provider fanout call for a
        # short anchored question; deliberate recall can still fan out later.
        _trace_m15(
            "planner.fanout.short_circuit",
            query=clean,
            reason="fast_anchored_exact_query",
            profile=profile,
            planned_default_stores=planned_default_stores,
        )
        return _finish([clean], "preserve_short_exact_query")
    if fast_long_query:
        # Fast pre-inject is a latency-sensitive context seed, not deliberate
        # recall. Preserve the full prompt as one search query rather than
        # making a provider planning call that can block the turn. Full and
        # deliberate recall still use the planner and surface failHard errors.
        reason = (
            "fast_long_broad_query"
            if profile["shape"] == "broad"
            else "fast_long_focused_query"
        )
        _trace_m15(
            "planner.fanout.short_circuit",
            query=clean,
            reason=reason,
            profile=profile,
            planned_default_stores=planned_default_stores,
        )
        return _finish([clean], reason)
    short_causal_lookup = (
        int(profile["token_count"]) <= 12
        and "multi_clause" not in profile_signals
        and any(
            marker in clean.lower()
            for marker in ("why ", "reason ", "because ", "cause ", "how come")
        )
        and (
            default_project is not None
            or "docs" in planned_default_stores
            or int(profile["named_entity_tokens"]) >= 1
        )
    )
    exact_short_query = (
        int(profile["token_count"]) <= 12
        and (
            "broad_intent" not in set(profile["signals"])
            or short_causal_lookup
        )
        and (
            "multi_clause" not in set(profile["signals"])
            or int(profile["named_entity_tokens"]) >= 2
        )
    )
    preserve_exact_query = (
        exact_short_query
        and (
            default_project is not None
            or "docs" in planned_default_stores
            or int(profile["named_entity_tokens"]) >= 1
            or profile["shape"] in {"narrow", "focused"}
        )
    )
    multilingual_store_plan_only = (
        preserve_exact_query
        and _requires_llm_store_classification_for_exact_query(
            clean,
            default_stores=planned_default_stores,
            default_project=default_project,
            profile=profile,
        )
    )
    store_plan_only = (planner_profile == "full" and preserve_exact_query) or multilingual_store_plan_only
    structural_exact_store_plan_only = store_plan_only and _is_single_structural_exact_query(clean)
    if preserve_exact_query and not store_plan_only:
        _trace_m15(
            "planner.fanout.short_circuit",
            query=clean,
            reason="preserve_short_exact_query",
            profile=profile,
            exact_short_query=exact_short_query,
            short_causal_lookup=short_causal_lookup,
            planned_default_stores=planned_default_stores,
            default_project=default_project,
        )
        return _finish([clean], "preserve_short_exact_query")
    if store_plan_only and not _HAS_LLM_CLIENTS:
        _trace_m15("planner.fanout.short_circuit", query=clean, reason="store_plan_only_no_llm_clients")
        return _finish([clean], "preserve_short_exact_query")
    if not _HAS_LLM_CLIENTS:
        return _planner_fallback_or_raise(
            "no_llm_clients",
            "LLM planner is unavailable",
        )

    conservative_guidance = ""
    if planner_profile == "aggressive":
        conservative_guidance = (
            "- Be extremely conservative for pre-injection. Default to exactly 1 query.\n"
            "- Only emit 2 to 5 queries if the message clearly requires multiple distinct retrieval angles.\n"
        )
    elif planner_profile == "fast":
        conservative_guidance = (
            "- Be conservative for pre-injection. Prefer 1 query.\n"
            "- Only emit extra queries when the message clearly spans multiple entities, times, or facets.\n"
        )

    prompt = (
        f"Generate 1 to {max_queries} search queries to find relevant stored knowledge for this message.\n"
        "Rules:\n"
        '- Return JSON only: {"queries": ["..."], "stores": ["vector","graph","docs","session_chunks"], "project": "project-alpha", "freshness_preferred": false}\n'
        '- "stores" is optional, but when present it must be an array containing any of: "vector", "graph", "docs", "session_chunks".\n'
        '- "project" is optional and should be set only when the message clearly names a project.\n'
        '- "freshness_preferred" is optional. Set it true only when the user asks for current/latest/current-state information or an open-ended schedule date, and not for explicit historical/as-of date lookups.\n'
        "- If the message is just a greeting, acknowledgement, filler, or otherwise has no meaningful information need, return an empty list.\n"
        "- Each query must be a short declarative statement (HyDE style), NOT a question.\n"
        "- First query: rephrase the core intent as a factual statement.\n"
        "- Additional queries: alternative angles, related entities, or broader context.\n"
        "- Keep all original names, dates, projects, and entities.\n"
        "- Preserve the original user language/script in the first query.\n"
        "- Do not translate general personal/life queries into another language unless explicitly requested.\n"
        "- For project/code/docs questions, if likely evidence lives in source code, filenames, package names, APIs, config keys, or project slugs in another language/script, you may add at most one cross-language or code-identifier query variant.\n"
        "- Keep any added cross-language variant tightly scoped to those likely source artifacts; do not rewrite the whole request into broad translated paraphrases.\n"
        "- Keep literal identifiers (project names, API names, file names, package names, code symbols) exactly as they appear when useful.\n"
        "- Preserve subject/object roles and possession exactly; never rewrite into the opposite ownership or relation direction.\n"
        "- Do not guess a relationship subtype unless the user explicitly stated it.\n"
        "- For short focused factual questions, returning only the original query is often best.\n"
        "- For short exact queries, preserve the exact user message and only classify stores/project.\n"
        "- Only add queries if they would genuinely find different memories.\n"
        "- Fewer good queries beats more weak ones.\n"
        "- Default to stores=['vector'] for ordinary recall.\n"
        "- Add 'graph' only for explicit relationship, family, or causal multi-hop questions.\n"
        "- Add 'docs' for codebase, architecture, schema, API, tests, source-file, project history/as-of, exact project lists, labels, constants, config, or value questions.\n"
        "- Prefer ['vector','docs'] over docs-only when project history or lived context may matter.\n"
        "- Add 'session_chunks' only when raw session wording or exact conversation evidence may be needed.\n"
        "- Prefer ['vector','session_chunks'] over session_chunks-only when extracted facts may also answer.\n"
        f"{conservative_guidance}\n"
        f"Message: {clean}"
    )

    try:
        from lib.llm_clients import call_fast_reasoning
        meta["used_llm"] = True
        _trace_m15(
            "planner.fanout.call_fast_reasoning",
            query=clean,
            timeout_s=timeout_s,
            max_queries=max_queries,
            planner_profile=planner_profile,
            prompt_preview=prompt[:1000],
        )
        result, _ = call_fast_reasoning(
            prompt=prompt,
            max_tokens=_RECALL_JSON_PLANNER_MAX_TOKENS,
            timeout=timeout_s,
            system_prompt=(
                "You output exactly one compact JSON object for memory retrieval. "
                "No markdown, no prose, no reasoning."
            ),
            max_retries=max(0, int(max_retries or 0)),
        )
        if result is None:
            _trace_m15("planner.fanout.call_fast_reasoning_none", query=clean)
            return _planner_fallback_or_raise(
                "planner_exception_fallback",
                "planner returned no result",
            )
        parsed = parse_json_response(result)
        _trace_m15(
            "planner.fanout.llm_result",
            query=clean,
            raw_result=result,
            parsed_type=type(parsed).__name__,
            parsed=parsed if isinstance(parsed, dict) else None,
        )
        queries = parsed.get("queries") if isinstance(parsed, dict) else None
        if isinstance(parsed, dict):
            parsed_stores = _planner_store_plan(parsed.get("stores")) or planned_default_stores
            parsed_project = _sanitize_planned_project(parsed.get("project"))
            if structural_exact_store_plan_only and default_project is None:
                planned_stores = planned_default_stores
                planned_project = None
            else:
                planned_stores = parsed_stores
                planned_project = parsed_project or default_project
            if isinstance(parsed.get("freshness_preferred"), bool):
                meta["freshness_preferred"] = bool(parsed.get("freshness_preferred"))
            if "docs" in planned_default_stores and "docs" not in planned_stores:
                planned_stores = _planner_store_plan([*planned_stores, "docs"])
            if "graph" in planned_default_stores and "graph" not in planned_stores:
                planned_stores = _planner_store_plan([*planned_stores, "graph"])
            if "session_chunks" in planned_default_stores and "session_chunks" not in planned_stores:
                planned_stores = _planner_store_plan([*planned_stores, "session_chunks"])
            if _is_multi_entity_shared_source_query(clean) and "graph" not in planned_default_stores:
                planned_stores = _planner_store_plan([
                    store for store in planned_stores if store != "graph"
                ])
        else:
            planned_stores = planned_default_stores
            planned_project = default_project
        meta["planned_stores"] = planned_stores
        meta["planned_project"] = planned_project
        if store_plan_only:
            return _finish([clean], "preserve_short_exact_query")
        if not isinstance(queries, list):
            return _planner_fallback_or_raise(
                "planner_exception_fallback",
                "planner returned invalid query payload",
            )

        out: List[str] = []
        seen = set()
        for raw in queries:
            q = " ".join(str(raw or "").split()).strip().strip("\"'")
            if not q or len(q) < 5:
                continue
            key = q.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(q)
            if len(out) >= max_queries:
                break

        # Include the original query as an anchor only when retrieval is
        # actually warranted.
        if out and clean.lower() not in {q.lower() for q in out}:
            out.insert(0, clean)
        if not out:
            if _should_preserve_query_after_empty_plan(
                clean,
                profile=profile,
                default_stores=planned_default_stores,
                default_project=default_project,
            ):
                return _finish([clean], "preserve_query_after_empty_plan")
            return _finish([], "planner_returned_empty")
        return _finish(out)
    except Exception as exc:
        return _planner_fallback_or_raise(
            "planner_exception_fallback",
            str(exc) or exc.__class__.__name__,
            exc=exc,
        )


_FAST_RECALL_PLANNER_EXPLICIT_TIMEOUT_CAP_S = 8.0


def _recall_planner_timeout_s(
    timeout_ms: Optional[int],
    *,
    fast_mode: bool = False,
) -> float:
    """Bound recall planner latency independently of full recall work.

    Deliberate shell recall should remain thorough, so its planner keeps the
    larger window. Short caps are only for explicit fast recall lanes.
    """
    default_cap = 2.0 if fast_mode else _RECALL_PLANNER_TIMEOUT_CAP_S
    if timeout_ms is None:
        return default_cap
    try:
        budget_s = max(0.1, float(timeout_ms) / 1000.0)
    except Exception:
        return default_cap
    if fast_mode:
        explicit_cap = max(default_cap, _FAST_RECALL_PLANNER_EXPLICIT_TIMEOUT_CAP_S)
        return max(0.1, min(explicit_cap, budget_s * 0.5))
    return max(0.1, min(default_cap, budget_s * 0.5))


def _resolve_lexical_anchor_timeout_ms(
    timeout_ms: Optional[int],
    *,
    fast_mode: bool = False,
) -> int:
    """Resolve lexical-anchor planner timeout from the overall recall budget."""
    default_ms = _LEXICAL_ANCHOR_DEFAULT_TIMEOUT_MS
    if timeout_ms is None:
        return default_ms
    try:
        budget_ms = max(200, int(timeout_ms))
    except Exception:
        return default_ms
    if fast_mode:
        return min(default_ms, budget_ms)
    if budget_ms <= default_ms:
        return budget_ms
    scaled_ms = int(budget_ms * 0.25)
    return max(default_ms, min(_LEXICAL_ANCHOR_EXPLICIT_TIMEOUT_CAP_MS, scaled_ms))


_FAST_DRILL_RESERVE_MS = 250
_FAST_DRILL_MIN_TIMEOUT_MS = 4000
_FAST_DRILL_MAX_TIMEOUT_MS = 8000
_FAST_DRILL_MIN_REMAINING_MS = _FAST_DRILL_RESERVE_MS + _FAST_DRILL_MIN_TIMEOUT_MS


def _fast_drill_timeout_ms_from_remaining(
    remaining_ms: Optional[int],
    *,
    explicit_timeout_ms: Optional[int] = None,
) -> Optional[int]:
    if remaining_ms is None:
        return None
    try:
        usable_ms = int(remaining_ms) - _FAST_DRILL_RESERVE_MS
    except (TypeError, ValueError):
        return None
    if usable_ms < _FAST_DRILL_MIN_TIMEOUT_MS:
        return None
    max_timeout_ms = _FAST_DRILL_MAX_TIMEOUT_MS
    if explicit_timeout_ms is not None:
        try:
            explicit_budget_ms = int(explicit_timeout_ms)
        except (TypeError, ValueError):
            explicit_budget_ms = 0
        if explicit_budget_ms > 0:
            max_timeout_ms = max(
                _FAST_DRILL_MAX_TIMEOUT_MS,
                explicit_budget_ms - _FAST_DRILL_RESERVE_MS,
            )
    return min(max_timeout_ms, usable_ms)


def _normalize_planned_stores(value: Any) -> List[str]:
    allowed = {"vector", "graph", "docs", "session_chunks"}
    if not isinstance(value, list):
        return []
    out: List[str] = []
    for item in value:
        store_name = str(item or "").strip().lower()
        if store_name == "source_chunks":
            store_name = "session_chunks"
        if store_name in allowed and store_name not in out:
            out.append(store_name)
    return out


def _sanitize_planned_project(value: Any) -> Optional[str]:
    import re as _re

    text = unicodedata.normalize("NFKC", str(value or "")).casefold().strip()
    if not text:
        return None
    text = _re.sub(r"[^\w.-]+", "-", text, flags=_re.UNICODE).strip("-")
    if not text:
        return None
    return text[:64]


def _registered_project_name_in_query(lowered_query: str) -> Optional[str]:
    """Return a mentioned project name without triggering docs reconciliation."""
    import re as _re

    text = str(lowered_query or "").strip().lower()
    if not text:
        return None

    def _mentions_project(clean: str) -> bool:
        # Registered project names are often short fixtures (for example
        # "other"). Treat them as slugs/tokens, not arbitrary substrings, so
        # "brother" does not route a kinship query to docs through "other".
        pattern = rf"(?<![\w.-]){_re.escape(clean)}(?![\w.-])"
        if _re.search(pattern, text):
            return True
        spaced = clean.replace("-", " ")
        if spaced != clean:
            spaced_pattern = rf"(?<![\w.-]){_re.escape(spaced)}(?![\w.-])"
            return bool(_re.search(spaced_pattern, text))
        return False

    try:
        import json as _json
        from lib.instance import shared_registry_path

        path = shared_registry_path()
        if not path.is_file():
            return None
        data = _json.loads(path.read_text(encoding="utf-8"))
        projects = data.get("projects", {}) if isinstance(data, dict) else {}
        deleted = set((data.get("deleted_projects", {}) if isinstance(data, dict) else {}).keys())
        if not isinstance(projects, dict):
            return None
        for name in sorted(projects.keys(), key=lambda item: len(str(item or "")), reverse=True):
            clean = str(name or "").strip().lower()
            if clean and name not in deleted and _mentions_project(clean):
                return str(name)
    except Exception:
        return None
    return None


def _infer_recall_store_defaults(text: str) -> Tuple[List[str], Optional[str]]:
    lowered = str(text or "").lower()
    stores: List[str] = ["vector"]
    project_name: Optional[str] = _registered_project_name_in_query(lowered)

    project_docs_like = bool(project_name)
    try:
        relation_chain_groups = _relation_chain_groups_for_query(text)
        relation_chain_like = (
            len(relation_chain_groups) >= 2
            and _has_relation_chain_structure(text)
        )
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError("Relation-chain store classification failed while failHard is enabled") from exc
        logger.warning("relation-chain store classification failed: %s", exc)
        relation_chain_like = False

    if project_docs_like:
        stores = ["vector", "docs"]
    elif _is_multi_entity_shared_source_query(text):
        stores = ["vector", "session_chunks"]
    elif _is_named_entity_graph_fact_lookup(text):
        stores = ["vector", "graph"]
    if relation_chain_like and "graph" not in stores:
        stores = [*stores, "graph"]

    return _planner_store_plan(stores), project_name


def _shared_source_anchor_terms(text: str, *, limit: int = 6) -> List[str]:
    """Return explicit entity anchors for shared-source/intersection questions."""
    clean = " ".join(str(text or "").split()).strip()
    if not clean:
        return []
    anchors: List[str] = []
    seen: set[str] = set()
    try:
        entities = extract_entities_from_text(clean)
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError("Shared-source store classification failed while failHard is enabled") from exc
        logger.warning("shared-source store classification failed: %s", exc)
        entities = []
    for entity in entities or []:
        entity_id = str(getattr(entity, "id", "") or "").strip().lower()
        entity_name = str(getattr(entity, "name", "") or "").strip().lower()
        entity_type = str(getattr(entity, "type", "") or "").strip().lower()
        anchor = entity_name or entity_id
        if not anchor or entity_type in {"fact", "event", "preference"} or anchor in seen:
            continue
        seen.add(anchor)
        anchors.append(anchor)
        if len(anchors) >= limit:
            return anchors
    return anchors


def _is_multi_entity_shared_source_query(text: str) -> bool:
    """Return true when multiple explicit entities may need transcript context."""
    clean = " ".join(str(text or "").split()).strip()
    if not clean:
        return False
    return len(_shared_source_anchor_terms(clean, limit=6)) >= 2


def _is_named_entity_graph_fact_lookup(text: str) -> bool:
    """Return true when a factual lookup names an entity present in the graph.

    Compact graph summaries are first-order memory evidence for named entities,
    not only for explicit relationship/multi-hop questions. Keep this bounded to
    query-shaped lookups so plain keyword searches stay vector-first.
    """
    clean = " ".join(str(text or "").split()).strip()
    if not clean:
        return False
    if not _extract_explicit_query_anchor_terms(clean, limit=1):
        return False
    try:
        entities = extract_entities_from_text(clean)
    except Exception as exc:
        if _is_fail_hard_mode():
            raise RuntimeError("Named-entity graph store classification failed while failHard is enabled") from exc
        logger.warning("named-entity graph store classification failed: %s", exc)
        return False
    for entity in entities or []:
        entity_id = str(getattr(entity, "id", "") or "").strip()
        entity_type = str(getattr(entity, "type", "") or "").strip().lower()
        if entity_id and entity_type not in {"fact", "event", "preference"}:
            return True
    return False


def _requires_llm_store_classification_for_exact_query(
    text: str,
    *,
    default_stores: List[str],
    default_project: Optional[str],
    profile: Optional[Dict[str, Any]] = None,
) -> bool:
    """Use the LLM store classifier for exact queries when heuristics are weak."""
    if default_project is not None:
        return False
    normalized_stores = list(_planner_store_plan(default_stores))
    if normalized_stores != ["vector"]:
        return False
    profile_dict = dict(profile or {})
    segmentation_confidence = str(profile_dict.get("segmentation_confidence") or "high").lower()
    low_space_query = bool(profile_dict.get("low_space_query"))
    signals = {str(sig) for sig in profile_dict.get("signals") or []}
    shape = str(profile_dict.get("shape") or "")
    named_entity_tokens = int(profile_dict.get("named_entity_tokens") or 0)
    store_classification_uncertain = (
        shape in {"narrow", "focused"}
        and named_entity_tokens <= 1
        and "broad_intent" not in signals
        and "multi_clause" not in signals
    )
    return (segmentation_confidence == "low" or low_space_query) and store_classification_uncertain


def _load_tools_md() -> Optional[str]:
    """Load TOOLS.md content from the quaid project docs, or any project TOOLS.md found.

    Search order:
      1. projects/quaid/TOOLS.md  (canonical quaid project)
      2. First TOOLS.md found in projects/*/TOOLS.md
    Returns None if no file is found or readable.
    """
    from pathlib import Path as _Path
    try:
        from lib.adapter import get_adapter
        projects_dir = _Path(get_adapter().projects_dir())
    except Exception:
        import os as _os
        visible = _os.environ.get("QUAID_VISIBLE_HOME", "").strip()
        home = _os.environ.get("QUAID_HOME", "").strip()
        if visible:
            projects_dir = _Path(visible).expanduser()
        elif home:
            root = _Path(home).expanduser()
            projects_dir = root.with_name(root.name[1:]) if root.name.startswith(".") and len(root.name) > 1 else root
        else:
            return None
        projects_dir = projects_dir / "projects"

    candidates = [projects_dir / "quaid" / "TOOLS.md"]
    try:
        candidates += sorted(projects_dir.glob("*/TOOLS.md"))
    except Exception as exc:
        logger.debug("_load_tools_hint: project TOOLS.md glob failed: %s", exc)

    for p in candidates:
        try:
            content = p.read_text(encoding="utf-8").strip()
            if content:
                return content
        except Exception:
            continue
    return None


def plan_tool_hint(
    query: str,
    timeout_s: Optional[float] = None,
    commands: Optional[list] = None,
) -> Optional[str]:
    """Return a <tool_hint> string if the query warrants one, or None.

    Uses the command registry (lib/command_registry.py) to build a compact
    structured prompt. Recall routing now lives in the recall pipeline itself,
    so the tool hint stays generic and simply reminds the agent that recall is
    available.

    Args:
        query: The user message to classify.
        timeout_s: Override the LLM timeout (seconds). Defaults to
            retrieval.tool_hint_timeout_ms from config (default 1.5s).
        commands: Override the resolved command registry (used in tests).

    Returns:
        A ``<tool_hint>…</tool_hint>`` string, or None.
    """
    from lib.llm_clients import call_fast_reasoning
    from lib.command_registry import resolve_command_registry
    import json as _json
    import re as _re

    clean = " ".join((query or "").split())
    if not clean:
        return None

    def _safe_shell_text(value: str) -> str:
        return str(value or "").replace("\\", "\\\\").replace('"', '\\"').strip()

    def _render_tool_hint(
        *,
        command_id: str,
        entry: Dict[str, Any],
        data: Dict[str, Any],
    ) -> Optional[str]:
        if command_id == "recall":
            quoted_query = _safe_shell_text(clean)
            return (
                f"<tool_hint>Search memories (thorough, can take 10-30s): "
                f"quaid recall \"{quoted_query}\"</tool_hint>"
            )

        if command_id == "store":
            quoted_query = _safe_shell_text(clean)
            return f"<tool_hint>Store memory: quaid store \"{quoted_query}\"</tool_hint>"

        hint_text = str(entry.get("hint") or "").strip()
        if not hint_text:
            return None
        return f"<tool_hint>{hint_text}</tool_hint>"


    registry = commands if commands is not None else resolve_command_registry()
    if not registry:
        return None

    cfg = _get_memory_config()
    effective_timeout = timeout_s or (getattr(cfg.retrieval, "tool_hint_timeout_ms", 1500) / 1000)

    command_list = "\n".join(
        f'- [{c["id"]}] {c["description"]}\n  hint: "{c["hint"]}"'
        for c in registry
    )
    prompt = (
        "Respond with exactly one JSON object and nothing else.\n\n"
        'Format: {"command_id": "<id>"} or {"command_id": null}\n\n'
        f"Available commands:\n{command_list}\n\n"
        "Pick the command whose description best matches the message, "
        "or null if none clearly apply.\n\n"
        f"Message: {clean}"
    )
    try:
        result, _ = call_fast_reasoning(
            prompt=prompt,
            max_tokens=60,
            timeout=effective_timeout,
            system_prompt=(
                "You are a JSON-only router. Your entire response must be exactly "
                "one JSON object — no other characters, no markdown, no explanation."
            ),
            max_retries=0,
        )
        if result:
            _match = _re.search(r'\{[\s\S]*?\}', result)
            if not _match:
                return None
            data = _json.loads(_match.group(0))
            command_id = data.get("command_id")
            if not command_id or not isinstance(command_id, str):
                return None
            entry = next((c for c in registry if c["id"] == command_id), None)
            if entry:
                return _render_tool_hint(
                    command_id=command_id,
                    entry=entry,
                    data=data if isinstance(data, dict) else {},
                )
    except Exception:
        pass
    return None


def recall_fast(
    query: str,
    limit: int = 10,
    privacy: Optional[List[str]] = None,
    owner_id: Optional[str] = None,
    min_similarity: Optional[float] = None,
    current_session_id: Optional[str] = None,
    compaction_time: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    source_channel: Optional[str] = None,
    source_conversation_id: Optional[str] = None,
    source_author_id: Optional[str] = None,
    actor_id: Optional[str] = None,
    subject_entity_id: Optional[str] = None,
    viewer_entity_id: Optional[str] = None,
    participant_entity_ids: Optional[List[str]] = None,
    include_unscoped: bool = True,
    debug: bool = False,
    domain: Optional[Dict[str, bool]] = None,
    domain_boost: Optional[Any] = None,
    project: Optional[str] = None,
    temporal_dimension: Optional[str] = None,
    timeout_ms: Optional[int] = None,
    planner_profile: str = "fast",
    return_meta: bool = False,
    include_chunks: bool = False,
    preserve_source_chunk_ids: bool = False,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
) -> Any:
    """Pre-injection recall: thin wrapper over recall() with single-pass settings."""
    import time as _time

    recall_fast_started = _time.monotonic()
    try:
        recall_fast_deadline = recall_fast_started + _recall_store_plan_timeout_s(timeout_ms, fast_mode=True)
    except Exception as exc:
        logger.warning("recall_fast: failed to compute deadline, running unbounded: %s", exc)
        if _is_fail_hard_mode():
            raise
        recall_fast_deadline = None

    _trace_m15(
        "memory_graph.recall_fast.entry",
        query=query,
        owner_id=owner_id,
        limit=limit,
        planner_profile=planner_profile,
        return_meta=return_meta,
        timeout_ms=timeout_ms,
    )
    if not query or not query.strip():
        meta = {
            "mode": "fast",
            "query": query,
            "turns": 0,
            "total_ms": 0,
            "stop_reason": "empty_query",
            "bailout_counts": {
                "initial_low_information": 0,
                "planner_returned_empty": 0,
                "empty_query": 1,
                "low_information_message": 0,
                "too_short": 0,
                "no_llm_clients": 0,
            },
        }
        _trace_m15("memory_graph.recall_fast.short_circuit", query=query, reason="empty_query", meta=meta)
        return ([], meta) if return_meta else []
    if _is_low_information_message(query):
        meta = {
            "mode": "fast",
            "query": query,
            "turns": 0,
            "total_ms": 0,
            "stop_reason": "initial_low_information",
            "bailout_counts": {
                "initial_low_information": 1,
                "planner_returned_empty": 0,
                "empty_query": 0,
                "low_information_message": 1,
                "too_short": 0,
                "no_llm_clients": 0,
            },
        }
        _trace_m15("memory_graph.recall_fast.short_circuit", query=query, reason="initial_low_information", meta=meta)
        return ([], meta) if return_meta else []

    date_from, date_to, inferred_date_to = _resolve_fast_recall_date_bounds(
        query,
        date_from=date_from,
        date_to=date_to,
    )
    temporal_dimension = _normalize_recall_temporal_dimension(temporal_dimension)
    def _enforce_fast_temporal_filters(candidate_rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        filtered_rows = list(candidate_rows or [])
        if date_from or date_to:
            filtered_rows = _filter_recall_rows_by_date_bounds(
                filtered_rows,
                date_from=date_from,
                date_to=date_to,
                temporal_dimension=temporal_dimension,
                keep_undated=_keep_undated_rows_for_temporal_dimension(temporal_dimension),
            )
        return _enforce_recall_rows_temporal_axis_validity(
            filtered_rows,
            temporal_dimension=temporal_dimension,
        )

    effective_limit = min(limit, 6 if planner_profile == "aggressive" else 8)
    # Fast recall still returns the requested small hook payload, but stores
    # need a wider pool so compact answer facts can survive exact entity stubs
    # and first-order chunks before direct-row prioritizers trim the result.
    store_plan_limit = max(effective_limit, min(20, effective_limit * 2))
    planner_timeout_s = _recall_planner_timeout_s(timeout_ms, fast_mode=True)
    planner_started = _time.monotonic()
    try:
        planned = _plan_fanout_queries(
            query,
            max_queries=5,
            timeout_s=planner_timeout_s,
            return_meta=True,
            planner_profile=planner_profile,
            max_retries=0,
        )
        planned_queries, planner_meta = planned if isinstance(planned, tuple) and len(planned) == 2 else ([query], {})
        _trace_m15(
            "memory_graph.recall_fast.planned",
            query=query,
            planned_queries=planned_queries,
            planner_meta=planner_meta,
        )
    except Exception as exc:
        # If the LLM planner was actually invoked and failed, this is a real
        # planner failure. Under failHard, raise immediately — no soft fallback.
        # Pre-LLM structured bailouts (too_short, preserve_short_exact_query,
        # no_entities) are returned as values, not raised, so they never reach here.
        if planner_profile != "off" and _is_fail_hard_mode():
            _trace_m15(
                "memory_graph.recall_fast.planner_exception_raise",
                query=query,
                planner_profile=planner_profile,
                exc_type=type(exc).__name__,
                error=str(exc),
            )
            raise RuntimeError(
                f"Recall fanout planner failed while failHard is enabled "
                f"(profile={planner_profile}, elapsed_ms={round((_time.monotonic() - planner_started) * 1000)}): {exc}"
            ) from exc
        fallback_stores, fallback_project = _infer_recall_store_defaults(query)
        detail = str(exc or "").lower()
        timeout_like = isinstance(exc, TimeoutError) or ("timed out" in detail) or ("timeout" in detail)
        planner_meta = {
            "query": query,
            "timeout_ms": round(planner_timeout_s * 1000),
            "used_llm": planner_profile != "off",
            "bailout_reason": "planner_timeout_fallback_off" if timeout_like else "planner_exception_fallback_off",
            "queries_count": 1,
            "elapsed_ms": round((_time.monotonic() - planner_started) * 1000),
            "query_shape": str(_estimate_fanout_profile(query, max_queries=5, planner_profile="off").get("shape") or "unknown"),
            "fanout_budget": 1,
            "token_count": len(str(query or "").split()),
            "named_entity_tokens": 0,
            "shape_signals": [],
            "planner_profile": "off",
            "planned_stores": list(_planner_store_plan(fallback_stores or ["vector"])),
            "planned_project": project or fallback_project,
            "fallback_detail": str(exc)[:240],
        }
        planned_queries = [query]
        _trace_m15(
            "memory_graph.recall_fast.planner_exception_fallback",
            query=query,
            planner_meta=planner_meta,
            planned_queries=planned_queries,
            exc_type=type(exc).__name__,
            error=str(exc),
        )
    planned_stores = _planner_store_plan((planner_meta or {}).get("planned_stores") or ["vector"])
    planned_project = (planner_meta or {}).get("planned_project") or project
    auto_inject_graph_depth = _resolve_auto_inject_graph_depth()

    rows, meta, docs_bundle = _run_recall_store_plan(
        query,
        stores=planned_stores,
        limit=store_plan_limit,
        owner_id=owner_id,
        min_similarity=min_similarity,
        planner_profile=planner_profile,
        planned_queries=planned_queries,
        planner_meta=planner_meta,
        fast_mode=True,
        graph_depth=auto_inject_graph_depth,
        common_kwargs={
            "privacy": privacy,
            "current_session_id": current_session_id,
            "compaction_time": compaction_time,
            "date_from": date_from,
            "date_to": date_to,
            "temporal_dimension": temporal_dimension,
            "source_channel": source_channel,
            "source_conversation_id": source_conversation_id,
            "source_author_id": source_author_id,
            "actor_id": actor_id,
            "subject_entity_id": subject_entity_id,
            "viewer_entity_id": viewer_entity_id,
            "participant_entity_ids": participant_entity_ids,
            "include_unscoped": include_unscoped,
            "debug": debug,
            "domain": domain,
            "domain_boost": domain_boost,
            "project": planned_project,
            "timeout_ms": timeout_ms,
            "max_chunk_tokens": max_chunk_tokens,
            "max_total_chunk_tokens": max_total_chunk_tokens,
        },
    )
    meta = dict(meta or {})
    meta["mode"] = "fast"
    meta["auto_inject_graph_depth"] = auto_inject_graph_depth
    if inferred_date_to:
        meta["inferred_date_to"] = inferred_date_to
    if docs_bundle:
        meta["docs_rows_count"] = len((docs_bundle.get("chunks") or []) if isinstance(docs_bundle, dict) else [])

    initial_gate_eval = _evaluate_quality_gate_readiness(
        query,
        rows,
        intent="GENERAL",
        limit=effective_limit,
        include_relation_keywords=False,
    )
    assistant_memory_rows = _recover_assistant_memory_cluster_rows(
        query,
        gate_eval=initial_gate_eval,
        owner_id=owner_id,
        limit=effective_limit,
        current_rows=rows,
    )
    if assistant_memory_rows:
        rows = _merge_recall_batches(
            [rows, assistant_memory_rows],
            limit=max(effective_limit * 2, 20),
        )
    assistant_list_rows = _recover_assistant_suggestion_cluster_rows(
        query,
        gate_eval=initial_gate_eval,
        owner_id=owner_id,
        limit=effective_limit,
    )
    if assistant_list_rows:
        rows = _merge_recall_batches(
            [rows, assistant_list_rows],
            limit=max(effective_limit * 2, 20),
        )
    rows = _prioritize_fast_anchor_direct_rows(query, rows)
    rows = _prioritize_date_relation_callback_rows(query, rows)
    rows = _prioritize_fast_assistant_memory_rows(
        query,
        rows,
        gate_eval=initial_gate_eval,
    )
    rows = _prioritize_recovered_assistant_list_rows(
        query,
        rows,
        gate_eval=initial_gate_eval,
    )
    rows = _enforce_fast_temporal_filters(rows)[:effective_limit]

    should_fast_drill, gate_eval, fast_drill_reasons, gate_intent = _should_fast_drill_follow_up(
        query,
        rows,
        planner_meta=planner_meta,
        docs_bundle=docs_bundle,
        limit=effective_limit,
    )
    fast_drill_enabled = (
        "preserved_exact_low_overlap" in fast_drill_reasons
    )
    if (
        not fast_drill_enabled
        and "needs_validation" in fast_drill_reasons
        and (
            _is_assistant_memory_query(query, gate_eval)
        )
    ):
        fast_drill_enabled = True
    fast_drill_skip_reason = None
    fast_drill_remaining_ms: Optional[int] = None
    fast_drill_min_budget_ms = _FAST_DRILL_MIN_REMAINING_MS
    if recall_fast_deadline is not None:
        fast_drill_remaining_ms = int(round((recall_fast_deadline - _time.monotonic()) * 1000))
        if fast_drill_enabled and fast_drill_remaining_ms < fast_drill_min_budget_ms:
            fast_drill_enabled = False
            fast_drill_skip_reason = "time_budget_exhausted"
            _trace_m15(
                "memory_graph.recall_fast.fast_drill_skipped",
                query=query,
                reason=fast_drill_skip_reason,
                remaining_ms=fast_drill_remaining_ms,
                min_budget_ms=fast_drill_min_budget_ms,
                fast_drill_reasons=fast_drill_reasons,
            )
    meta["quality_gate"] = {
        "evaluation": gate_eval,
        "fast_drill_candidate": should_fast_drill,
        "fast_drill_reasons": fast_drill_reasons,
        "fast_drill_enabled": fast_drill_enabled,
    }
    if fast_drill_skip_reason:
        meta["quality_gate"]["fast_drill_skip_reason"] = fast_drill_skip_reason
        meta["quality_gate"]["fast_drill_remaining_ms"] = fast_drill_remaining_ms
    meta["memory_quality"] = _summarize_memory_quality(
        query,
        rows,
        gate_eval=gate_eval,
        intent=gate_intent,
        limit=effective_limit,
        include_relation_keywords=False,
    )

    if should_fast_drill and fast_drill_enabled:
        drill_initial_timeout_ms = timeout_ms
        if recall_fast_deadline is not None:
            fast_drill_remaining_ms = int(round((recall_fast_deadline - _time.monotonic()) * 1000))
            drill_initial_timeout_ms = _fast_drill_timeout_ms_from_remaining(
                fast_drill_remaining_ms,
                explicit_timeout_ms=timeout_ms,
            )
            if drill_initial_timeout_ms is None:
                meta["quality_gate"] = {
                    "evaluation": gate_eval,
                    "fast_drill_candidate": True,
                    "fast_drill_reasons": fast_drill_reasons,
                    "fast_drill_enabled": False,
                    "fast_drill_skip_reason": "time_budget_exhausted",
                    "fast_drill_remaining_ms": fast_drill_remaining_ms,
                    "fast_drill_min_budget_ms": fast_drill_min_budget_ms,
                }
                meta["memory_quality"] = _summarize_memory_quality(
                    query,
                    rows,
                    gate_eval=gate_eval,
                    intent=gate_intent,
                    limit=effective_limit,
                    include_relation_keywords=False,
                )
                rows = _enforce_fast_temporal_filters(rows)
                rows, meta = _prepare_recall_output_rows(
                    rows,
                    meta,
                    include_chunks=include_chunks,
                    max_chunk_tokens=max_chunk_tokens,
                    max_total_chunk_tokens=max_total_chunk_tokens,
                )
                _attach_recall_meta(rows, meta)
                _trace_m15(
                    "memory_graph.recall_fast.exit",
                    query=query,
                    rows_count=len(rows or []),
                    meta=meta,
                )
                return (rows, meta) if return_meta else rows
        _trace_m15(
            "memory_graph.recall_fast.fast_drill_considered",
            query=query,
            fast_drill_reasons=fast_drill_reasons,
            preserved_exact_fast_path=str((planner_meta or {}).get("bailout_reason") or "") == "preserve_short_exact_query",
        )
        preserved_exact_fast_path = str((planner_meta or {}).get("bailout_reason") or "") == "preserve_short_exact_query"
        drill_queries = _build_fast_drill_fallback_queries(
            query,
            gate_eval=gate_eval,
            planner_meta=planner_meta,
            owner_id=owner_id,
            current_rows=rows,
        )
        if drill_queries:
            lowered_drill = {" ".join(str(item or "").lower().split()) for item in drill_queries}
            clean_query = " ".join((query or "").split())
            if clean_query and clean_query.lower() not in lowered_drill:
                drill_queries.insert(0, clean_query)
            drill_meta = {
                "used_llm": False,
                "queries_count": len(drill_queries),
                "elapsed_ms": 0,
                "bailout_reason": "deterministic_keyword_fallback",
                "done": False,
                "planned_stores": list(planned_stores),
                "planned_project": planned_project,
            }
        elif preserved_exact_fast_path:
            drill_meta = {
                "used_llm": False,
                "queries_count": 0,
                "elapsed_ms": 0,
                "bailout_reason": "preserved_exact_skip_llm_drill",
                "done": False,
                "planned_stores": list(planned_stores),
                "planned_project": planned_project,
            }
        else:
            drill_budget_s = max(
                float(_FAST_DRILL_MIN_TIMEOUT_MS) / 1000.0,
                float(drill_initial_timeout_ms or _FAST_DRILL_MIN_TIMEOUT_MS) / 1000.0,
            )
            _trace_m15(
                "memory_graph.recall_fast.drill_planner_call",
                query=query,
                drill_budget_s=drill_budget_s,
                rows_count=len(rows or []),
            )
            planned_drill = _drill_plan_queries(
                query,
                rows,
                planned_queries,
                timeout_s=drill_budget_s,
                return_meta=True,
                raise_on_error=_is_fail_hard_mode(),
            )
            if isinstance(planned_drill, tuple) and len(planned_drill) == 2:
                drill_queries, drill_meta = planned_drill
            else:
                drill_queries = planned_drill if isinstance(planned_drill, list) else []
                drill_meta = {
                    "used_llm": False,
                    "queries_count": len(drill_queries),
                    "elapsed_ms": 0,
                    "bailout_reason": None,
                    "done": False,
                }
        if not drill_queries:
            drill_queries = _build_fast_drill_fallback_queries(
                query,
                gate_eval=gate_eval,
                planner_meta=planner_meta,
                owner_id=owner_id,
                current_rows=rows,
            )
            if drill_queries:
                drill_meta = dict(drill_meta or {})
                drill_meta["used_llm"] = False
                drill_meta["bailout_reason"] = "deterministic_keyword_fallback"
                drill_meta["queries_count"] = len(drill_queries)
                drill_meta.setdefault("planned_stores", list(planned_stores))
                drill_meta.setdefault("planned_project", planned_project)
        if drill_queries:
            max_drill_queries = 3 if preserved_exact_fast_path else 2
            drill_queries = drill_queries[:max_drill_queries]
            drill_limit = min(effective_limit, 5)
            if _is_assistant_suggestion_list_query(query, gate_eval):
                drill_limit = max(drill_limit, min(120, max(40, effective_limit * 5)))
            elif _is_assistant_memory_query(query, gate_eval):
                drill_limit = max(drill_limit, 10)
            fast_drill_meta = dict(drill_meta or {})
            fast_drill_meta.setdefault("planned_stores", list(planned_stores))
            fast_drill_meta.setdefault("planned_project", planned_project)
            drill_timeout_ms = drill_initial_timeout_ms
            if recall_fast_deadline is not None:
                remaining = int(round((recall_fast_deadline - _time.monotonic()) * 1000))
                drill_timeout_ms = _fast_drill_timeout_ms_from_remaining(
                    remaining,
                    explicit_timeout_ms=timeout_ms,
                )
                if drill_timeout_ms is None:
                    meta["quality_gate"] = {
                        "evaluation": gate_eval,
                        "fast_drill_candidate": True,
                        "fast_drill_reasons": fast_drill_reasons,
                        "fast_drill_enabled": False,
                        "fast_drill_skip_reason": "time_budget_exhausted",
                        "fast_drill_remaining_ms": remaining,
                        "fast_drill_min_budget_ms": fast_drill_min_budget_ms,
                    }
                    meta["memory_quality"] = _summarize_memory_quality(
                        query,
                        rows,
                        gate_eval=gate_eval,
                        intent=gate_intent,
                        limit=effective_limit,
                        include_relation_keywords=False,
                    )
                    rows, meta = _prepare_recall_output_rows(
                        rows,
                        meta,
                        include_chunks=include_chunks,
                        max_chunk_tokens=max_chunk_tokens,
                        max_total_chunk_tokens=max_total_chunk_tokens,
                    )
                    _attach_recall_meta(rows, meta)
                    _trace_m15(
                        "memory_graph.recall_fast.exit",
                        query=query,
                        rows_count=len(rows or []),
                        meta=meta,
                    )
                    return (rows, meta) if return_meta else rows
            try:
                drill_rows, drill_store_meta, drill_docs_bundle = _run_recall_store_plan(
                    query,
                    stores=planned_stores,
                    limit=drill_limit,
                    owner_id=owner_id,
                    min_similarity=min_similarity,
                    planner_profile="off",
                    planned_queries=drill_queries,
                    planner_meta=fast_drill_meta,
                    fast_mode=True,
                    graph_depth=auto_inject_graph_depth,
                    common_kwargs={
                        "privacy": privacy,
                        "current_session_id": current_session_id,
                        "compaction_time": compaction_time,
                        "date_from": date_from,
                        "date_to": date_to,
                        "temporal_dimension": temporal_dimension,
                        "source_channel": source_channel,
                        "source_conversation_id": source_conversation_id,
                        "source_author_id": source_author_id,
                        "actor_id": actor_id,
                        "subject_entity_id": subject_entity_id,
                        "viewer_entity_id": viewer_entity_id,
                        "participant_entity_ids": participant_entity_ids,
                        "include_unscoped": include_unscoped,
                        "debug": debug,
                        "domain": domain,
                        "domain_boost": domain_boost,
                        "project": planned_project,
                        "timeout_ms": drill_timeout_ms,
                        "max_chunk_tokens": max_chunk_tokens,
                        "max_total_chunk_tokens": max_total_chunk_tokens,
                    },
                )
            except Exception as exc:
                timeout_like = _is_timeout_like_exception(exc)
                _trace_m15(
                    "memory_graph.recall_fast.fast_drill_error",
                    query=query,
                    timeout_like=timeout_like,
                    initial_rows=len(rows or []),
                    error_type=type(exc).__name__,
                    error=str(exc),
                )
                if _is_fail_hard_mode() or not timeout_like or not rows:
                    raise
                logger.warning(
                    "fast recall drill timed out; returning initial completed rows: %s",
                    exc,
                )
                meta["quality_gate"] = {
                    "evaluation": gate_eval,
                    "fast_drill_candidate": True,
                    "fast_drill_reasons": fast_drill_reasons,
                    "fast_drill_enabled": False,
                    "fast_drill_skip_reason": "timeout",
                    "fast_drill_error_type": type(exc).__name__,
                    "fast_drill_error": str(exc)[:240],
                    "fast_drill_queries": list(drill_queries),
                }
                meta["memory_quality"] = _summarize_memory_quality(
                    query,
                    rows,
                    gate_eval=gate_eval,
                    intent=gate_intent,
                    limit=effective_limit,
                    include_relation_keywords=False,
                )
                rows = _enforce_fast_temporal_filters(rows)
                rows, meta = _prepare_recall_output_rows(
                    rows,
                    meta,
                    include_chunks=include_chunks,
                    max_chunk_tokens=max_chunk_tokens,
                    max_total_chunk_tokens=max_total_chunk_tokens,
                )
                _attach_recall_meta(rows, meta)
                _trace_m15(
                    "memory_graph.recall_fast.exit",
                    query=query,
                    rows_count=len(rows or []),
                    meta=meta,
                )
                return (rows, meta) if return_meta else rows
            assistant_memory_rows = _recover_assistant_memory_cluster_rows(
                query,
                gate_eval=gate_eval,
                owner_id=owner_id,
                limit=drill_limit,
                current_rows=drill_rows,
            )
            if assistant_memory_rows:
                drill_rows = _merge_recall_batches(
                    [drill_rows, assistant_memory_rows],
                    limit=max(drill_limit * 3, effective_limit * 2),
                )
            assistant_list_rows = _recover_assistant_suggestion_cluster_rows(
                query,
                gate_eval=gate_eval,
                owner_id=owner_id,
                limit=drill_limit,
            )
            if assistant_list_rows:
                drill_rows = _merge_recall_batches(
                    [drill_rows, assistant_list_rows],
                    limit=max(drill_limit * 3, effective_limit * 2),
                )
            rows = _merge_recall_batches([rows, drill_rows], limit=max(effective_limit, drill_limit * 2))
            rows = _prioritize_fast_anchor_direct_rows(query, rows)
            rows = _prioritize_date_relation_callback_rows(query, rows)
            rows = _prioritize_fast_assistant_memory_rows(
                query,
                rows,
                gate_eval=gate_eval,
            )
            rows = _prioritize_recovered_assistant_list_rows(
                query,
                rows,
                gate_eval=gate_eval,
            )
            rows = _enforce_fast_temporal_filters(rows)[:effective_limit]
            if drill_docs_bundle:
                docs_bundle = _merge_docs_bundles(docs_bundle, drill_docs_bundle)
            meta.setdefault("turn_details", [])
            if isinstance(meta["turn_details"], list):
                meta["turn_details"].append({
                    "turn": len(meta["turn_details"]) + 1,
                    "planner": fast_drill_meta,
                    "store_runs": list((drill_store_meta or {}).get("store_runs") or []),
                    "quality_gate_eval": _evaluate_quality_gate_readiness(
                        query,
                        rows,
                        intent=gate_intent,
                        limit=effective_limit,
                        include_relation_keywords=False,
                    ),
                })
            phases = dict(meta.get("phases_ms") or {})
            drill_phases = dict((drill_store_meta or {}).get("phases_ms") or {})
            phases["fast_drill_wall_ms"] = int(drill_phases.get("store_plan_wall_ms") or drill_phases.get("total_ms") or 0)
            phases["total_ms"] = int(phases.get("total_ms") or 0) + phases["fast_drill_wall_ms"]
            meta["phases_ms"] = phases
            meta["stop_reason"] = "fast_drill_merged"
            meta["quality_gate"] = {
                "evaluation": _evaluate_quality_gate_readiness(
                    query,
                    rows,
                    intent=gate_intent,
                    limit=effective_limit,
                    include_relation_keywords=False,
                ),
                "fast_drill_candidate": True,
                "fast_drill_reasons": fast_drill_reasons,
                "fast_drill_enabled": True,
                "fast_drill_queries": list(drill_queries),
            }
            meta["memory_quality"] = _summarize_memory_quality(
                query,
                rows,
                gate_eval=meta["quality_gate"]["evaluation"],
                intent=gate_intent,
                limit=effective_limit,
                include_relation_keywords=False,
            )
    rows = _enforce_fast_temporal_filters(rows)
    rows, meta = _prepare_recall_output_rows(
        rows,
        meta,
        include_chunks=include_chunks,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
        preserve_source_chunk_ids=preserve_source_chunk_ids,
    )
    _attach_recall_meta(rows, meta)
    _trace_m15(
        "memory_graph.recall_fast.exit",
        query=query,
        rows_count=len(rows or []),
        meta=meta,
    )
    return (rows, meta) if return_meta else rows


def _drill_plan_queries(
    query: str,
    current_results: List[Dict[str, Any]],
    already_searched: List[str],
    timeout_s: float = 3.0,
    return_meta: bool = False,
    raise_on_error: bool = False,
    max_retries: int = 0,
) -> Any:
    """Given current results, identify gaps and generate new search queries.

    This is the "drilling" step: a tiny LLM call that sees only the query
    and short result summaries, then suggests queries to fill gaps.
    """
    import time as _time
    if not raise_on_error:
        raise_on_error = _is_fail_hard_mode()
    max_retries = _resolve_drill_planner_max_retries(max_retries)
    started = _time.monotonic()
    meta = {
        "query": query,
        "timeout_ms": round(timeout_s * 1000),
        "used_llm": False,
        "done": False,
        "bailout_reason": None,
        "queries_count": 0,
        "attempts": 0,
        "max_retries": max_retries,
        "elapsed_ms": 0,
    }

    def _finish(out: List[str], bailout_reason: Optional[str] = None, done: bool = False):
        meta["queries_count"] = len(out)
        meta["bailout_reason"] = bailout_reason
        meta["done"] = done
        meta["elapsed_ms"] = round((_time.monotonic() - started) * 1000)
        if return_meta:
            return out, meta
        return out

    def _planner_fallback_or_raise(
        bailout_reason: str,
        message: str,
        *,
        exc: Optional[Exception] = None,
    ):
        meta["bailout_reason"] = bailout_reason
        meta["elapsed_ms"] = round((_time.monotonic() - started) * 1000)
        if raise_on_error:
            detail = (
                f"{message} "
                f"(planner_timeout_ms={meta.get('timeout_ms', 0)}, "
                f"planner_max_retries={meta.get('max_retries', 0)}, "
                f"planner_attempts={meta.get('attempts', 0)}, "
                f"planner_elapsed_ms={meta.get('elapsed_ms', 0)})"
            )
            if exc is not None:
                raise RuntimeError(
                    f"Recall drill planner failed while failHard is enabled: {detail}"
                ) from exc
            raise RuntimeError(
                f"Recall drill planner failed while failHard is enabled: {detail}"
            )
        return _finish([], bailout_reason)

    if not _HAS_LLM_CLIENTS:
        return _planner_fallback_or_raise(
            "no_llm_clients",
            "LLM drill planner is unavailable",
        )

    # Build compact result summary with temporal/source hints so the drill
    # planner can tell the difference between broad related context and
    # directly answer-bearing evidence.
    result_summary = []
    for r in current_results[:10]:
        text = str(r.get("text", ""))[:80]
        score = float(r.get("similarity", 0))
        meta_bits = []
        if r.get("category"):
            meta_bits.append(f"type={r.get('category')}")
        if r.get("source_type"):
            meta_bits.append(f"source={r.get('source_type')}")
        if r.get("project"):
            meta_bits.append(f"project={r.get('project')}")
        if r.get("created_at"):
            meta_bits.append(f"created={str(r.get('created_at'))[:10]}")
        if r.get("valid_from") or r.get("valid_until"):
            valid_from = str(r.get("valid_from") or "")[:10] or "?"
            valid_until = str(r.get("valid_until") or "")[:10] or "open"
            meta_bits.append(f"valid={valid_from}->{valid_until}")
        meta_prefix = f" [{' '.join(meta_bits)}]" if meta_bits else ""
        result_summary.append(f"  [{score:.2f}]{meta_prefix} {text}")
    summary_text = "\n".join(result_summary) if result_summary else "  (no results)"

    searched_text = "\n".join(f"  - {q}" for q in already_searched[-8:])

    prompt = (
        "You are a memory retrieval drill agent. Given a query and current results, "
        "suggest 1-3 NEW search queries to find memories the current results missed.\n\n"
        f"Original query: {query}\n\n"
        f"Already searched:\n{searched_text}\n\n"
        f"Current results:\n{summary_text}\n\n"
        "Rules:\n"
        '- Return JSON only: {"queries": ["..."], "done": true/false}\n'
        '- Set "done": true ONLY if the current results directly and specifically answer the original query.\n'
        "- Each query must be a declarative statement (HyDE style).\n"
        "- Broad summaries, indirect context, stale evidence, or partial matches are NOT enough to set done=true.\n"
        "- If results mix older and newer states or seem conflicted, prefer a follow-up query that resolves the latest/current state explicitly.\n"
        "- If the results are about the same topic but miss the exact requested detail, write a narrower follow-up query for that missing detail.\n"
        "- Try different angles: related entities, temporal context, broader/narrower scope.\n"
        "- Do NOT repeat queries from the 'already searched' list.\n"
        "- Keep original names, dates, and entities.\n"
        "- Preserve the original language/script in the first follow-up query.\n"
        "- Do not translate general personal/life queries into another language unless explicitly requested.\n"
        "- For project/code/docs follow-ups, you may add at most one cross-language or code-identifier variant when likely evidence lives in source code, filenames, package names, APIs, config keys, or project slugs in another language/script.\n"
        "- Keep literal identifiers (project names, API names, file names, package names, code symbols) exactly as they appear when useful.\n"
        "- Prefer one precise follow-up over several vague rewrites.\n"
    )
    try:
        from lib.llm_clients import call_fast_reasoning
        meta["used_llm"] = True
        result = None
        for attempt in range(max_retries + 1):
            meta["attempts"] = attempt + 1
            try:
                result, _ = call_fast_reasoning(
                    prompt=prompt,
                    max_tokens=_RECALL_JSON_PLANNER_MAX_TOKENS,
                    timeout=timeout_s,
                    system_prompt=(
                        "You output exactly one compact JSON object for retrieval drilling. "
                        "No markdown, no prose, no reasoning."
                    ),
                    max_retries=0,
                )
                break
            except Exception as call_exc:
                if attempt >= max_retries or not _is_lexical_anchor_retryable_exception(call_exc):
                    raise
                delay_s = min(1.0, _DRILL_PLANNER_RETRY_BASE_DELAY_S * (2 ** attempt))
                logger.warning(
                    "Recall drill planner retryable provider error; "
                    "attempt %s/%s failed, retrying in %.2fs: %s",
                    attempt + 1,
                    max_retries + 1,
                    delay_s,
                    call_exc,
                )
                _time.sleep(delay_s)
        if result is None:
            return _planner_fallback_or_raise(
                "planner_returned_none",
                "drill planner returned no result",
            )
        parsed = parse_json_response(result)
        if not isinstance(parsed, dict):
            return _finish([], "invalid_response")

        # If LLM says we're done, stop drilling
        if parsed.get("done"):
            return _finish([], "drill_done", done=True)

        queries = parsed.get("queries")
        if not isinstance(queries, list):
            return _finish([], "missing_queries")

        searched_lower = {q.lower() for q in already_searched}
        out: List[str] = []
        for raw in queries:
            q = " ".join(str(raw or "").split()).strip().strip("\"'")
            if not q or len(q) < 5:
                continue
            if q.lower() in searched_lower:
                continue
            out.append(q)
            if len(out) >= 3:
                break
        clean = " ".join(str(query or "").split()).strip()
        if clean and out:
            out_lower = {q.lower() for q in out}
            clean_lower = clean.lower()
            if clean_lower not in searched_lower and clean_lower not in out_lower:
                out = [clean] + out[:2]
        if not out:
            return _finish([], "planner_returned_empty")
        return _finish(out)
    except Exception as exc:
        return _planner_fallback_or_raise(
            "planner_exception",
            str(exc) or exc.__class__.__name__,
            exc=exc,
        )


def recall(
    query: str,
    limit: int = 5,
    privacy: Optional[List[str]] = None,
    owner_id: Optional[str] = None,
    min_similarity: Optional[float] = None,
    use_routing: bool = True,
    use_aliases: bool = True,
    use_intent: bool = True,
    use_multi_pass: bool = True,
    use_reranker: Optional[bool] = None,
    current_session_id: Optional[str] = None,
    compaction_time: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    source_channel: Optional[str] = None,
    source_conversation_id: Optional[str] = None,
    source_author_id: Optional[str] = None,
    actor_id: Optional[str] = None,
    subject_entity_id: Optional[str] = None,
    viewer_entity_id: Optional[str] = None,
    participant_entity_ids: Optional[List[str]] = None,
    include_unscoped: bool = True,
    debug: bool = False,
    domain: Optional[Dict[str, bool]] = None,
    domain_boost: Optional[Any] = None,
    project: Optional[str] = None,
    low_signal_retry: bool = True,
    max_turns: int = 3,
    timeout_ms: Optional[int] = None,
    planner_profile: str = "full",
    include_graph_traversal: bool = True,
    include_co_session: bool = True,
    include_mmr: bool = True,
    include_lexical_anchor_shaping: bool = True,
    lexical_anchor_planner_mode: str = "llm",
    lexical_anchor_timeout_ms: Optional[int] = None,
    use_lightweight_config: bool = False,
    track_access: bool = True,
    return_meta: bool = False,
    planned_queries: Optional[List[str]] = None,
    planner_meta: Optional[Dict[str, Any]] = None,
    relative_temporal_freshness: bool = False,
    temporal_dimension: Optional[str] = None,
    include_chunks: bool = False,
    preserve_source_chunk_ids: bool = False,
    max_chunk_tokens: Optional[int] = None,
    max_total_chunk_tokens: Optional[int] = None,
) -> Any:
    """Orchestrated recall with iterative drilling.

    Turn 1: Parallel HyDE fanout (like recall_fast but with reranker + graph).
    Turn 2+: Evaluate results, identify gaps via small LLM call, search again.
    Stops when: max_turns reached, quality gate met, time budget exhausted,
    or drill agent says "done".

    Args:
        max_turns: Maximum drill turns (default 3). Turn 1 is always the
            initial fanout. Set to 1 for single-pass behavior.
        timeout_ms: Optional overall wall-clock budget in ms. If omitted,
            recall runs until it has enough evidence or completes its turns.
    """
    import time as _time

    temporal_dimension = _normalize_recall_temporal_dimension(temporal_dimension)

    if not query or not query.strip():
        meta = {
            "mode": "deliberate",
            "query": query,
            "search_queries": [],
            "turns": 0,
            "total_ms": 0,
            "budget_ms": timeout_ms,
            "over_budget": False,
            "drill_log": [],
            "turn_details": [],
            "stop_reason": "empty_query",
            "bailout_counts": {},
            "fanout_count": 0,
        }
        return ([], meta) if return_meta else []

    # Circuit breaker guard
    try:
        from lib.circuit_breaker import check_current_read_allowed

        breaker = check_current_read_allowed()
        if not breaker.allows_reads():
            logger.warning("recall blocked by circuit breaker (%s): %s", breaker.status, breaker.message)
            meta = {
                "mode": "deliberate",
                "query": query,
                "search_queries": [],
                "turns": 0,
                "total_ms": 0,
                "budget_ms": timeout_ms,
                "over_budget": False,
                "drill_log": [],
                "turn_details": [],
                "stop_reason": "circuit_breaker",
                "bailout_counts": {},
                "fanout_count": 0,
            }
            return ([], meta) if return_meta else []
    except Exception as exc:
        logger.warning("recall circuit breaker check failed: %s", exc)
        if _is_fail_hard_mode():
            raise RuntimeError("recall circuit breaker check failed") from exc

    if not use_lightweight_config:
        # Empty-DB short-circuit: skip all LLM calls when there is nothing to search.
        # On a fresh install with 0 searchable nodes, query expansion and reranking
        # are pointless and the LLM proxy calls block the bridge for 30-120s.
        try:
            _g = get_graph()
            with _g._get_conn() as _conn:
                _node_count = _conn.execute(
                    "SELECT COUNT(*) FROM nodes "
                    "WHERE status IS NULL OR status IN ('approved', 'pending', 'active')"
                ).fetchone()[0]
            if _node_count == 0 and not _owner_has_session_chunks(owner_id):
                if use_aliases:
                    try:
                        _g.resolve_alias(query, owner_id=owner_id)
                    except Exception:
                        pass
                logger.debug("[recall] empty DB — skipping recall pipeline (0 searchable nodes)")
                _empty_meta = {
                    "mode": "deliberate",
                    "query": query,
                    "search_queries": [],
                    "turns": 0,
                    "total_ms": 0,
                    "budget_ms": timeout_ms,
                    "over_budget": False,
                    "drill_log": [],
                    "turn_details": [],
                    "stop_reason": "empty_db",
                    "bailout_counts": {},
                    "fanout_count": 0,
                }
                return ([], _empty_meta) if return_meta else []
        except Exception as exc:
            logger.warning("recall empty DB short-circuit check failed: %s", exc)
            if _is_fail_hard_mode():
                raise RuntimeError("recall empty DB short-circuit check failed") from exc

    if (
        not use_lightweight_config
        and int(max_turns or 1) > 1
        and use_multi_pass
        and _is_single_structural_exact_query(query)
    ):
        fast_timeout_ms = timeout_ms
        if fast_timeout_ms is None:
            try:
                fast_timeout_ms = int(round(_recall_store_plan_timeout_s(None, fast_mode=True) * 1000))
            except Exception:
                fast_timeout_ms = 3000
        exact_planner_meta = {
            "query": query,
            "timeout_ms": fast_timeout_ms,
            "used_llm": False,
            "bailout_reason": "single_structural_exact_query",
            "queries_count": 1,
            "elapsed_ms": 0,
            "query_shape": "narrow",
            "fanout_budget": 1,
            "token_count": 1,
            "named_entity_tokens": 0,
            "shape_signals": ["structural_exact"],
            "planner_profile": "fast",
            "planned_stores": ["vector"],
            "planned_project": project,
            "freshness_preferred": False,
            "suppress_session_chunks_auto_include": True,
        }
        return recall(
            query=query,
            limit=limit,
            privacy=privacy,
            owner_id=owner_id,
            min_similarity=min_similarity,
            use_routing=True,
            use_aliases=False,
            use_intent=use_intent,
            use_multi_pass=False,
            use_reranker=False,
            current_session_id=current_session_id,
            compaction_time=compaction_time,
            date_from=date_from,
            date_to=date_to,
            temporal_dimension=temporal_dimension,
            source_channel=source_channel,
            source_conversation_id=source_conversation_id,
            source_author_id=source_author_id,
            actor_id=actor_id,
            subject_entity_id=subject_entity_id,
            viewer_entity_id=viewer_entity_id,
            participant_entity_ids=participant_entity_ids,
            include_unscoped=include_unscoped,
            debug=debug,
            domain=domain,
            domain_boost=domain_boost,
            project=project,
            low_signal_retry=False,
            max_turns=1,
            timeout_ms=fast_timeout_ms,
            planner_profile="fast",
            include_graph_traversal=False,
            include_co_session=False,
            include_mmr=False,
            include_lexical_anchor_shaping=True,
            lexical_anchor_planner_mode="deterministic",
            use_lightweight_config=True,
            track_access=track_access,
            return_meta=return_meta,
            planned_queries=[query],
            planner_meta=exact_planner_meta,
            relative_temporal_freshness=False,
            include_chunks=include_chunks,
            max_chunk_tokens=max_chunk_tokens,
            max_total_chunk_tokens=max_total_chunk_tokens,
        )

    # Load config
    overall_timeout_ms = timeout_ms
    if lexical_anchor_timeout_ms is None and overall_timeout_ms is not None:
        lexical_anchor_timeout_ms = _resolve_lexical_anchor_timeout_ms(overall_timeout_ms, fast_mode=False)
    quality_gate = 0.70
    config_retrieval = None
    try:
        if use_lightweight_config:
            config_retrieval = _get_retrieval_lightweight_config()
        else:
            from config import get_config
            config_retrieval = get_config().retrieval
        quality_gate = getattr(config_retrieval, "multi_pass_gate", 0.70)
    except Exception as exc:
        logger.warning("recall quality gate config load failed; using default: %s", exc)
        if _is_fail_hard_mode():
            raise RuntimeError("recall quality gate config load failed") from exc

    recall_start = _time.monotonic()
    deadline = None if overall_timeout_ms is None else (recall_start + (overall_timeout_ms / 1000.0))
    all_searched: List[str] = []
    all_batches: List[List[Dict[str, Any]]] = []
    all_branch_metas: List[Dict[str, Any]] = []
    drill_log: List[Dict[str, Any]] = []
    turn_phase_details: List[Dict[str, Any]] = []
    stop_reason = "max_turns"
    bailout_counts = {
        "initial_low_information": 0,
        "planner_returned_empty": 0,
        "empty_query": 0,
        "low_information_message": 0,
        "too_short": 0,
        "no_llm_clients": 0,
        "planner_invalid_response": 0,
        "planner_exception_fallback": 0,
        "drill_done": 0,
        "time_budget_exhausted": 0,
    }

    # Common kwargs for _recall_once
    common_kwargs = dict(
        privacy=privacy,
        owner_id=owner_id,
        min_similarity=min_similarity,
        use_aliases=use_aliases,
        use_intent=use_intent,
        current_session_id=current_session_id,
        compaction_time=compaction_time,
        date_from=date_from,
        date_to=date_to,
        temporal_dimension=temporal_dimension,
        source_channel=source_channel,
        source_conversation_id=source_conversation_id,
        source_author_id=source_author_id,
        actor_id=actor_id,
        subject_entity_id=subject_entity_id,
        viewer_entity_id=viewer_entity_id,
        participant_entity_ids=participant_entity_ids,
        include_unscoped=include_unscoped,
        debug=debug,
        domain=domain,
        domain_boost=domain_boost,
        project=project,
        timeout_ms=overall_timeout_ms,
        include_lexical_anchor_shaping=include_lexical_anchor_shaping,
        lexical_anchor_planner_mode=lexical_anchor_planner_mode,
        lexical_anchor_timeout_ms=lexical_anchor_timeout_ms,
        use_lightweight_config=use_lightweight_config,
        track_access=track_access,
        relative_temporal_freshness=bool(relative_temporal_freshness),
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )
    gate_intent = "GENERAL"
    if use_intent:
        try:
            gate_intent, _ = classify_intent(query)
        except Exception:
            gate_intent = "GENERAL"

    # --- Turn 1: Parallel fanout ---
    turn_start = _time.monotonic()
    if planned_queries is not None:
        fanout_queries = list(planned_queries)
        fanout_meta = dict(planner_meta or {})
        fanout_meta.setdefault("query", query)
        fanout_meta.setdefault("used_llm", False)
        fanout_meta.setdefault("bailout_reason", None)
        fanout_meta.setdefault("queries_count", len(fanout_queries))
        fanout_meta.setdefault("elapsed_ms", 0)
        fanout_meta.setdefault("planner_profile", planner_profile)
        fanout_meta.setdefault("planned_stores", ["vector"])
        fanout_meta.setdefault("planned_project", None)
        fanout_meta.setdefault("freshness_preferred", False)
    elif use_routing:
        planner_timeout_s = _recall_planner_timeout_s(overall_timeout_ms, fast_mode=False)
        if deadline is not None:
            planner_timeout_s = min(planner_timeout_s, max(0.1, (deadline - _time.monotonic()) * 0.5))
        planned = _plan_fanout_queries(
            query,
            max_queries=5,
            timeout_s=planner_timeout_s,
            return_meta=True,
            planner_profile=planner_profile,
            max_retries=1,
        )
        if isinstance(planned, tuple) and len(planned) == 2:
            fanout_queries, fanout_meta = planned
        else:
            fanout_queries = planned if isinstance(planned, list) else []
            fanout_meta = {
                "query": query,
                "timeout_ms": 0,
                "used_llm": False,
                "bailout_reason": None,
                "queries_count": len(fanout_queries),
                "elapsed_ms": 0,
                "planner_profile": planner_profile,
                "freshness_preferred": False,
            }
    else:
        fanout_queries = [query]
        fanout_meta = {
            "query": query,
            "timeout_ms": 0,
            "used_llm": False,
            "bailout_reason": None,
            "queries_count": len(fanout_queries),
            "elapsed_ms": 0,
            "planner_profile": planner_profile,
            "planned_stores": ["vector"],
            "planned_project": None,
            "freshness_preferred": False,
        }
    if fanout_meta.get("bailout_reason") in bailout_counts:
        bailout_counts[fanout_meta["bailout_reason"]] += 1
    all_searched.extend(fanout_queries)
    branch_common_kwargs = dict(common_kwargs)
    branch_common_kwargs["relative_temporal_freshness"] = bool(
        relative_temporal_freshness
        or (isinstance(fanout_meta, dict) and fanout_meta.get("freshness_preferred") is True)
    )
    planned_turn1_stores = _planner_store_plan(fanout_meta.get("planned_stores") or ["vector"])
    if (
        owner_id
        and not include_chunks
        and planned_turn1_stores == ["vector"]
        and not fanout_meta.get("suppress_session_chunks_auto_include")
        and "session_chunks" not in planned_turn1_stores
        and _owner_has_session_chunks(owner_id)
    ):
        # SessionDB is first-order transcript evidence. Include it in
        # owner-scoped deliberate recall even when the planner stays vector-only;
        # downstream RRF/coverage gates decide whether any chunk is useful.
        planned_turn1_stores = _planner_store_plan([*planned_turn1_stores, "session_chunks"])
        fanout_meta = dict(fanout_meta or {})
        fanout_meta["planned_stores"] = list(planned_turn1_stores)
        fanout_meta["session_chunks_auto_included"] = True
    turn1_relation_chain_groups = _relation_chain_groups_for_query(query)
    turn1_relation_chain_detected = (
        len(turn1_relation_chain_groups) >= 2
        and _has_relation_chain_structure(query)
    )
    if (
        turn1_relation_chain_detected
        and "graph" not in planned_turn1_stores
        and not fanout_meta.get("suppress_graph_auto_include")
    ):
        planned_turn1_stores = _planner_store_plan([*planned_turn1_stores, "graph"])
        fanout_meta = dict(fanout_meta or {})
        fanout_meta["planned_stores"] = list(planned_turn1_stores)
        fanout_meta["relation_chain_graph_auto_included"] = True
    turn1_relation_chain_query = (
        "graph" in planned_turn1_stores
        and turn1_relation_chain_detected
    )
    if (
        turn1_relation_chain_query
        or "session_chunks" in planned_turn1_stores
    ):
        store_plan_graph_depth = max(1, len(turn1_relation_chain_groups))
        # Deliberate recall still returns the requested limit, but store lanes
        # need a wider candidate pool so compact facts below entity stubs/chunks
        # can reach the post-merge priority chain.
        store_plan_limit = max(limit, min(20, limit * 2))
        try:
            rows, meta, docs_bundle = _run_recall_store_plan(
                query,
                stores=planned_turn1_stores,
                limit=store_plan_limit,
                owner_id=owner_id,
                min_similarity=min_similarity,
                planner_profile=planner_profile,
                planned_queries=fanout_queries,
                planner_meta=fanout_meta,
                fast_mode=False,
                graph_depth=store_plan_graph_depth,
                common_kwargs=branch_common_kwargs,
            )
            return _return_validated_recall(
                rows[:limit],
                meta,
                return_meta,
                include_chunks=include_chunks,
                max_chunk_tokens=max_chunk_tokens,
                max_total_chunk_tokens=max_total_chunk_tokens,
            )
        except TimeoutError as exc:
            if _is_fail_hard_mode():
                raise
            # Store-plan turn-1 routing is an optional shortcut outside failHard;
            # the established multi-pass recall path below remains authoritative.
            logger.warning(
                "turn-1 store-plan recall timed out; falling back to multi-pass recall: %s",
                exc,
            )
            fanout_meta = dict(fanout_meta or {})
            fallback_reason = (
                "relation_chain_timeout"
                if turn1_relation_chain_query
                else "turn1_store_plan_timeout"
            )
            fanout_meta["store_plan_fallback"] = {
                "reason": fallback_reason,
                "error_type": type(exc).__name__,
                "error": str(exc)[:240],
            }

    remaining = None if deadline is None else (deadline - _time.monotonic())
    if remaining is not None and remaining <= 0.5:
        # Almost out of time, do single direct search
        fanout_queries = [query]
        remaining = 1.0
        stop_reason = "near_deadline_fallback"

    # Keep all turn-1 branches full for the current quality-focused path.
    turn1_post_merge_refine = False
    search_callables = []
    for i, q in enumerate(fanout_queries):
        search_callables.append(lambda q=q: _recall_once(
            query=q, limit=limit,
            use_routing=False,  # Already HyDE'd
            use_multi_pass=use_multi_pass,
            use_reranker=use_reranker,
            include_graph_traversal=include_graph_traversal,
            include_co_session=include_co_session,
            include_mmr=False if turn1_post_merge_refine else include_mmr,
            low_signal_retry=low_signal_retry,
            return_meta=True,
            preserve_source_chunk_ids=True,
            **branch_common_kwargs,
        ))

    turn1_max_workers = min(len(search_callables), 5)
    if planned_queries is not None and not use_routing:
        turn1_max_workers = 1

    t1_batches, search_wall_ms = _run_recall_branch_callables(
        search_callables,
        max_workers=turn1_max_workers,
        pool_name="recall_drill",
        timeout_seconds=remaining,
    )

    turn1_batch_metas: List[Dict[str, Any]] = []
    for index, batch in enumerate(t1_batches):
        if isinstance(batch, tuple) and len(batch) == 2 and isinstance(batch[0], list):
            rows, meta = batch
            all_batches.append(rows)
            if isinstance(meta, dict):
                turn1_batch_metas.append(meta)
        elif isinstance(batch, list):
            all_batches.append(batch)
            meta = _extract_recall_meta(batch)
            if meta:
                turn1_batch_metas.append(meta)
        elif isinstance(batch, Exception):
            turn1_batch_metas.append(_handle_recall_branch_exception(
                parent_query=query,
                branch_query=fanout_queries[index] if index < len(fanout_queries) else "",
                branch_index=index,
                turn=1,
                exc=batch,
            ))
    all_branch_metas.extend(turn1_batch_metas)

    turn_elapsed = (_time.monotonic() - turn_start) * 1000
    turn1_merge_limit = max(limit * 3, 20) if turn1_post_merge_refine else (limit * 2)
    merged = _merge_recall_batches(all_batches, limit=turn1_merge_limit)
    turn1_refine_meta = {
        "applied": False,
        "candidate_count": len(merged),
        "reranker_enabled": False,
        "reranker_ms": 0,
        "mmr_enabled": False,
        "mmr_ms": 0,
        "total_ms": 0,
    }
    if turn1_post_merge_refine:
        merged, turn1_refine_meta = _apply_post_merge_rank_refinement(
            query,
            merged,
            limit=turn1_merge_limit,
            use_reranker=False,
            include_mmr=include_mmr,
            config_retrieval=config_retrieval,
        )
    top_score = float(merged[0].get("similarity", 0)) if merged else 0.0
    turn1_coverage = _summarize_result_coverage(merged)
    gate_eval = _evaluate_quality_gate_readiness(
        query,
        merged,
        intent=gate_intent,
        limit=limit,
        include_relation_keywords=not use_lightweight_config,
    )

    drill_log.append({
        "turn": 1,
        "queries": fanout_queries[:],
        "results": len(merged),
        "top_score": round(top_score, 3),
        "elapsed_ms": round(turn_elapsed),
        "coverage": turn1_coverage,
        "gate_eval": gate_eval,
    })
    turn_phase_details.append({
        "turn": 1,
        "turn_elapsed_ms": round(turn_elapsed),
        "planner": fanout_meta,
            "fanout": _build_branch_telemetry(
                fanout_queries,
                turn1_batch_metas,
                wall_ms=search_wall_ms,
                max_workers=turn1_max_workers,
            ),
            "post_merge_refine": turn1_refine_meta,
            "coverage": turn1_coverage,
            "quality_gate_eval": gate_eval,
        })

    logger.debug(
        "[recall] turn 1: %d queries, %d results, top=%.3f, %.0fms",
        len(fanout_queries), len(merged), top_score, turn_elapsed,
    )

    if not fanout_queries:
        stop_reason = fanout_meta.get("bailout_reason") or "planner_returned_empty"
        merged = _prioritize_date_relation_callback_rows(query, merged)
        merged = _prioritize_named_entity_activity_anchor_rows(query, merged)
        merged = _prioritize_deliberate_confident_direct_anchor_rows(query, merged)
        facet_rescue_rows, facet_rescue_meta = _recover_explicit_entity_facet_rows(
            query,
            merged,
            owner_id=owner_id,
            limit=limit,
            intent=gate_intent,
            domain=domain,
            include_unscoped=include_unscoped,
        )
        if facet_rescue_rows:
            merged = _merge_recall_batches(
                [merged, facet_rescue_rows],
                limit=max(limit * 2, len(merged) + len(facet_rescue_rows)),
            )
        if date_from or date_to:
            merged = _filter_recall_rows_by_date_bounds(
                merged,
                date_from=date_from,
                date_to=date_to,
                temporal_dimension=temporal_dimension,
                keep_undated=_keep_undated_rows_for_temporal_dimension(temporal_dimension),
            )
        final = _select_final_recall_rows_with_facet_rescue(
            query,
            merged,
            limit=limit,
            intent=gate_intent,
        )
        final = _prioritize_high_signal_facet_rescue_rows(query, final)
        final = _enforce_recall_rows_temporal_axis_validity(
            final,
            temporal_dimension=temporal_dimension,
        )
        total_elapsed = (_time.monotonic() - recall_start) * 1000
        total_planner_ms = sum(
            max(0, int(round(float((turn.get("planner") or {}).get("elapsed_ms", 0) or 0))))
            for turn in turn_phase_details
        )
        total_fanout_wall_ms = sum(
            max(0, int(round(float((turn.get("fanout") or {}).get("wall_ms", 0) or 0))))
            for turn in turn_phase_details
        )
        total_post_merge_refine_ms = sum(
            max(0, int(round(float((turn.get("post_merge_refine") or {}).get("total_ms", 0) or 0))))
            for turn in turn_phase_details
        )
        meta = {
            "mode": "deliberate",
            "query": query,
            "search_queries": list(all_searched),
            "turns": len(drill_log),
            "total_ms": round(total_elapsed),
            "budget_ms": overall_timeout_ms,
            "over_budget": (total_elapsed > overall_timeout_ms) if overall_timeout_ms is not None else False,
            "drill_log": drill_log[:],
            "turn_details": turn_phase_details[:],
            "phases_ms": {
                "planner_ms": total_planner_ms,
                "fanout_wall_ms": total_fanout_wall_ms,
                "post_merge_refine_ms": total_post_merge_refine_ms,
                "non_parallel_overhead_ms": max(0, round(total_elapsed) - total_planner_ms - total_fanout_wall_ms - total_post_merge_refine_ms),
                "total_ms": round(total_elapsed),
            },
            "serial_work_ms": {
                "branch_total_ms": sum(
                    max(0, int(round(float((turn.get("fanout") or {}).get("serial_sum_ms", 0) or 0))))
                    for turn in turn_phase_details
                ),
            },
            "coverage": _summarize_result_coverage(final),
            "quality_gate": {
                "threshold": round(float(quality_gate), 3),
                "met": False,
                "top_score": round(top_score, 3),
                "result_count": len(merged),
                "evaluation": gate_eval,
            },
            "memory_quality": _summarize_memory_quality(
                query,
                final,
                gate_eval=gate_eval,
                intent=gate_intent,
                limit=limit,
                include_relation_keywords=not use_lightweight_config,
            ),
            "facet_rescue": facet_rescue_meta,
            "stop_reason": stop_reason,
            "bailout_counts": bailout_counts,
        }
        lexical_summary = _summarize_branch_lexical_anchor(all_branch_metas)
        if lexical_summary is not None:
            meta["lexical_anchor"] = lexical_summary
        return _return_validated_recall(
            final,
            meta,
            return_meta,
            include_chunks=include_chunks,
            preserve_source_chunk_ids=preserve_source_chunk_ids,
            max_chunk_tokens=max_chunk_tokens,
            max_total_chunk_tokens=max_total_chunk_tokens,
        )

    # --- Turn 2+: Drill loop ---
    # Skip drill turns when fanout returned no results: there is nothing to
    # refine and each drill turn would just burn a 15s LLM timeout needlessly.
    if not merged:
        logger.debug("[recall] no results after turn 1, skipping drill loop")
        stop_reason = "no_initial_results"
        bailout_counts["no_initial_results"] = bailout_counts.get("no_initial_results", 0) + 1
    for turn in range(2, max(2, max_turns + 1)):
        if stop_reason == "no_initial_results":
            break
        remaining = None if deadline is None else (deadline - _time.monotonic())
        if remaining is not None and remaining < 1.0:
            logger.debug("[recall] time budget exhausted after turn %d (%.0fms remaining)", turn - 1, remaining * 1000)
            stop_reason = "time_budget_exhausted"
            bailout_counts["time_budget_exhausted"] += 1
            break

        # Quality gate: stop if top results are strong enough
        gate_eval = _evaluate_quality_gate_readiness(
            query,
            merged,
            intent=gate_intent,
            limit=limit,
            include_relation_keywords=not use_lightweight_config,
        )
        candidate_quality_gate = top_score >= quality_gate and len(merged) >= limit
        if candidate_quality_gate and gate_eval.get("ready") and not gate_eval.get("needs_validation"):
            logger.debug("[recall] quality gate met (top=%.3f >= %.3f), stopping after turn %d", top_score, quality_gate, turn - 1)
            stop_reason = "quality_gate_met"
            break
        # High-confidence early-stop for non-stateful queries (relational, personal, direct-answer).
        # The standard gate blocks on `needs_validation` when lexical overlap is low — expected
        # for indirect relational matches ("niece" -> "daughter of sister", "dog" -> "<Name> is a Lab").
        # These are not uncertain results; they just use different vocabulary. When the query is
        # not temporal/current/progression (those genuinely need deeper search), a strong score
        # is sufficient to stop drilling rather than exhausting the budget.
        _is_stateful_query = (
            gate_eval.get("temporal_like")
            or gate_eval.get("current_like")
            or gate_eval.get("progression_like")
        )
        if merged and not _is_stateful_query and top_score >= quality_gate:
            logger.debug(
                "[recall] high-confidence non-stateful early stop (top=%.3f >= %.3f), stopping after turn %d",
                top_score, quality_gate, turn - 1,
            )
            stop_reason = "quality_gate_met"
            break
        if candidate_quality_gate and gate_eval.get("needs_validation"):
            logger.debug(
                "[recall] quality gate candidate requires validation after turn %d: overlap=%.2f temporal_rows=%s",
                turn - 1,
                float(gate_eval.get("overlap_ratio", 0.0) or 0.0),
                gate_eval.get("temporal_rows"),
            )

        # Ask drill agent for new queries
        turn_start = _time.monotonic()
        drill_budget = min(15.0, remaining * 0.4) if remaining is not None else 15.0
        if candidate_quality_gate:
            drill_budget = min(drill_budget, 6.0)
        planned_drill = _drill_plan_queries(
            query, merged, all_searched, timeout_s=drill_budget,
            return_meta=True,
            max_retries=1,
        )
        if isinstance(planned_drill, tuple) and len(planned_drill) == 2:
            new_queries, drill_meta = planned_drill
        else:
            new_queries = planned_drill if isinstance(planned_drill, list) else []
            drill_meta = {
                "used_llm": False,
                "queries_count": len(new_queries),
                "elapsed_ms": 0,
                "bailout_reason": None,
                "done": False,
            }
        if candidate_quality_gate:
            drill_meta["quality_gate_validation"] = True
            drill_meta["quality_gate_eval"] = gate_eval
        if not new_queries:
            if candidate_quality_gate and (drill_meta.get("done") or gate_eval.get("ready")):
                logger.debug("[recall] quality gate validated after turn %d", turn - 1)
                stop_reason = "quality_gate_met"
                break
            logger.debug("[recall] drill agent returned no queries or said done, stopping after turn %d", turn - 1)
            stop_reason = "drill_done" if drill_meta.get("done") else (drill_meta.get("bailout_reason") or "drill_done")
            if stop_reason == "drill_done":
                bailout_counts["drill_done"] += 1
            break

        all_searched.extend(new_queries)
        search_remaining = None if deadline is None else (deadline - _time.monotonic())
        if search_remaining is not None and search_remaining < 0.5:
            logger.debug("[recall] no time left for search after drill planning, stopping")
            stop_reason = "time_budget_exhausted"
            bailout_counts["time_budget_exhausted"] += 1
            break

        # Search new queries in parallel (lightweight)
        drill_post_merge_refine = False
        drill_callables = [
            (lambda q=q: _recall_once(
                query=q, limit=min(max(3, limit), 12),
                use_routing=False,
                use_multi_pass=False,
                use_reranker=False,
                include_mmr=False if drill_post_merge_refine else include_mmr,
                low_signal_retry=False,
                return_meta=True,
                preserve_source_chunk_ids=True,
                **branch_common_kwargs,
            ))
            for q in new_queries
        ]

        drill_batches, search_wall_ms = _run_recall_branch_callables(
            drill_callables,
            max_workers=min(len(drill_callables), 3),
            pool_name="recall_drill",
            timeout_seconds=search_remaining,
        )

        drill_batch_metas: List[Dict[str, Any]] = []
        for index, batch in enumerate(drill_batches):
            if isinstance(batch, tuple) and len(batch) == 2 and isinstance(batch[0], list):
                rows, meta = batch
                all_batches.append(rows)
                if isinstance(meta, dict):
                    drill_batch_metas.append(meta)
            elif isinstance(batch, list):
                all_batches.append(batch)
                meta = _extract_recall_meta(batch)
                if meta:
                    drill_batch_metas.append(meta)
            elif isinstance(batch, Exception):
                drill_batch_metas.append(_handle_recall_branch_exception(
                    parent_query=query,
                    branch_query=new_queries[index] if index < len(new_queries) else "",
                    branch_index=index,
                    turn=turn,
                    exc=batch,
                ))
        all_branch_metas.extend(drill_batch_metas)

        drill_merge_limit = max(limit * 3, 20) if drill_post_merge_refine else (limit * 2)
        merged = _merge_recall_batches(all_batches, limit=drill_merge_limit)
        drill_refine_meta = {
            "applied": False,
            "candidate_count": len(merged),
            "reranker_enabled": False,
            "reranker_ms": 0,
            "mmr_enabled": False,
            "mmr_ms": 0,
            "total_ms": 0,
        }
        if drill_post_merge_refine:
            merged, drill_refine_meta = _apply_post_merge_rank_refinement(
                query,
                merged,
                limit=drill_merge_limit,
                use_reranker=False,
                include_mmr=include_mmr,
                config_retrieval=config_retrieval,
            )
        top_score = float(merged[0].get("similarity", 0)) if merged else 0.0
        turn_elapsed = (_time.monotonic() - turn_start) * 1000
        turn_coverage = _summarize_result_coverage(merged)
        turn_gate_eval = _evaluate_quality_gate_readiness(
            query,
            merged,
            intent=gate_intent,
            limit=limit,
            include_relation_keywords=not use_lightweight_config,
        )

        drill_log.append({
            "turn": turn,
            "queries": new_queries[:],
            "results": len(merged),
            "top_score": round(top_score, 3),
            "elapsed_ms": round(turn_elapsed),
            "coverage": turn_coverage,
            "gate_eval": turn_gate_eval,
        })
        turn_phase_details.append({
            "turn": turn,
            "turn_elapsed_ms": round(turn_elapsed),
            "planner": drill_meta,
            "fanout": _build_branch_telemetry(
                new_queries,
                drill_batch_metas,
                wall_ms=search_wall_ms,
                max_workers=min(len(drill_callables), 3),
            ),
            "post_merge_refine": drill_refine_meta,
            "coverage": turn_coverage,
            "quality_gate_eval": turn_gate_eval,
        })

        logger.debug(
            "[recall] turn %d: %d queries, %d results, top=%.3f, %.0fms",
            turn, len(new_queries), len(merged), top_score, turn_elapsed,
        )

    # Final merge to requested limit
    merged = _prioritize_date_relation_callback_rows(query, merged)
    merged = _prioritize_named_entity_activity_anchor_rows(query, merged)
    merged = _prioritize_deliberate_confident_direct_anchor_rows(query, merged)
    relation_chain_groups = _relation_chain_groups_for_query(query)
    relation_chain_query = (
        len(relation_chain_groups) >= 2
        and _has_relation_chain_structure(query)
    )
    if relation_chain_query and merged:
        _boost_relation_chain_row_scores(merged, relation_chain_groups, query=query)
        merged.sort(
            key=lambda row: _relation_chain_sort_key(row, relation_chain_groups, query=query),
            reverse=True,
        )
    facet_rescue_rows, facet_rescue_meta = _recover_explicit_entity_facet_rows(
        query,
        merged,
        owner_id=owner_id,
        limit=limit,
        intent=gate_intent,
        domain=domain,
        include_unscoped=include_unscoped,
    )
    if facet_rescue_rows:
        merged = _merge_recall_batches(
            [merged, facet_rescue_rows],
            limit=max(limit * 2, len(merged) + len(facet_rescue_rows)),
        )
    if date_from or date_to:
        merged = _filter_recall_rows_by_date_bounds(
            merged,
            date_from=date_from,
            date_to=date_to,
            temporal_dimension=temporal_dimension,
            keep_undated=_keep_undated_rows_for_temporal_dimension(temporal_dimension),
        )
    final = _select_final_recall_rows_with_facet_rescue(
        query,
        merged,
        limit=limit,
        intent=gate_intent,
    )
    final = _prioritize_high_signal_facet_rescue_rows(query, final)
    final = _enforce_recall_rows_temporal_axis_validity(
        final,
        temporal_dimension=temporal_dimension,
    )
    final, final_source_window_meta = _expand_final_recall_source_rows(
        query,
        final,
        owner_id=owner_id,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )
    if date_from or date_to:
        final = _filter_recall_rows_by_date_bounds(
            final,
            date_from=date_from,
            date_to=date_to,
            temporal_dimension=temporal_dimension,
            keep_undated=_keep_undated_rows_for_temporal_dimension(temporal_dimension),
        )
    final = _enforce_recall_rows_temporal_axis_validity(
        final,
        temporal_dimension=temporal_dimension,
    )
    total_elapsed = (_time.monotonic() - recall_start) * 1000
    if stop_reason == "max_turns" and len(drill_log) < max_turns:
        stop_reason = "completed"

    if overall_timeout_ms is not None and total_elapsed > overall_timeout_ms:
        logger.debug(
            "[recall] OVER BUDGET: %.0fms (budget: %dms) — "
            "turns: %d, total queries: %d, results: %d",
            total_elapsed, overall_timeout_ms,
            len(drill_log), len(all_searched), len(final),
        )

    # Always attach recall metadata so the consuming LLM knows what was searched
    total_planner_ms = sum(
        max(0, int(round(float((turn.get("planner") or {}).get("elapsed_ms", 0) or 0))))
        for turn in turn_phase_details
    )
    total_fanout_wall_ms = sum(
        max(0, int(round(float((turn.get("fanout") or {}).get("wall_ms", 0) or 0))))
        for turn in turn_phase_details
    )
    total_post_merge_refine_ms = sum(
        max(0, int(round(float((turn.get("post_merge_refine") or {}).get("total_ms", 0) or 0))))
        for turn in turn_phase_details
    )
    total_branch_serial_ms = sum(
        max(0, int(round(float((turn.get("fanout") or {}).get("serial_sum_ms", 0) or 0))))
        for turn in turn_phase_details
    )
    non_parallel_overhead_ms = max(0, round(total_elapsed) - total_planner_ms - total_fanout_wall_ms - total_post_merge_refine_ms)
    final_gate_eval = _evaluate_quality_gate_readiness(
        query,
        final,
        intent=gate_intent,
        limit=limit,
        include_relation_keywords=not use_lightweight_config,
    )
    meta = {
        "mode": "deliberate",
        "query": query,
        "search_queries": list(all_searched),
        "turns": len(drill_log),
        "total_ms": round(total_elapsed),
        "budget_ms": overall_timeout_ms,
        "over_budget": (total_elapsed > overall_timeout_ms) if overall_timeout_ms is not None else False,
        "drill_log": drill_log[:],
        "turn_details": turn_phase_details[:],
        "phases_ms": {
            "planner_ms": total_planner_ms,
            "fanout_wall_ms": total_fanout_wall_ms,
            "post_merge_refine_ms": total_post_merge_refine_ms,
            "non_parallel_overhead_ms": non_parallel_overhead_ms,
            "total_ms": round(total_elapsed),
        },
        "serial_work_ms": {
            "branch_total_ms": total_branch_serial_ms,
        },
        "coverage": _summarize_result_coverage(final),
        "quality_gate": {
            "threshold": round(float(quality_gate), 3),
            "met": stop_reason == "quality_gate_met",
            "top_score": round(top_score, 3),
            "result_count": len(merged),
            "evaluation": final_gate_eval,
        },
        "memory_quality": _summarize_memory_quality(
            query,
            final,
            gate_eval=final_gate_eval,
            intent=gate_intent,
            limit=limit,
            include_relation_keywords=not use_lightweight_config,
        ),
        "facet_rescue": facet_rescue_meta,
        "final_source_windows": final_source_window_meta,
        "stop_reason": stop_reason,
        "bailout_counts": bailout_counts,
        "fanout_count": len(turn_phase_details[0]["fanout"]["queries"]) if turn_phase_details else 0,
    }
    lexical_summary = _summarize_branch_lexical_anchor(all_branch_metas)
    if lexical_summary is not None:
        meta["lexical_anchor"] = lexical_summary
    if _recall_telemetry_enabled():
        meta["telemetry"] = {
            "inputs": {
                "limit": limit,
                "timeout_ms": overall_timeout_ms,
                "max_turns": max_turns,
                "planner_profile": planner_profile,
                "project": _normalize_project_tag(project),
                "date_from": date_from,
                "date_to": date_to,
                "use_routing": bool(use_routing),
                "use_multi_pass": bool(use_multi_pass),
                "include_graph_traversal": bool(include_graph_traversal),
                "include_co_session": bool(include_co_session),
                "include_mmr": bool(include_mmr),
            },
            "samples": {
                "final_results": _sample_recall_rows(final, limit=5),
            },
            "turn_count": len(turn_phase_details),
            "search_query_count": len(all_searched),
        }
    return _return_validated_recall(
        final,
        meta,
        return_meta,
        include_chunks=include_chunks,
        preserve_source_chunk_ids=preserve_source_chunk_ids,
        max_chunk_tokens=max_chunk_tokens,
        max_total_chunk_tokens=max_total_chunk_tokens,
    )


def _check_injection_blocklist(text: str) -> Optional[str]:
    """Check text for prompt injection patterns. Returns matched text if flagged, None otherwise."""
    for pattern in _INJECTION_PATTERNS:
        match = pattern.search(text)
        if match:
            return match.group(0)
    return None


def _is_low_information_entity_result(result: Dict[str, Any]) -> bool:
    """True if a result is just an entity stub (e.g. bare person name)."""
    if result.get("via_relation") or result.get("graph_path"):
        return False
    category = str(result.get("category", "")).strip().lower()
    if category not in _LOW_INFO_ENTITY_CATEGORIES:
        return False
    text = " ".join(str(result.get("text", "")).split())
    if not text or "→" in text or "--" in text:
        return False
    words = text.split()
    if len(words) > 2:
        return False
    return _LOW_INFO_ENTITY_TEXT_RE.fullmatch(text) is not None


def _should_preserve_low_information_entity_result(
    result: Dict[str, Any],
    query: str,
    *,
    intent: Optional[str] = None,
) -> bool:
    """Keep exact-name entity stubs for direct identity/relation lookups."""
    if not _is_low_information_entity_result(result):
        return False
    query_text = str(query or "").strip()
    if not query_text:
        return False
    if intent is None:
        try:
            intent, _ = classify_intent(query_text)
        except Exception:
            intent = "GENERAL"
    if intent not in {"WHO", "RELATION"} and not re.search(r"\bwho\b", query_text, re.IGNORECASE):
        return False

    query_terms = {
        key
        for term in _extract_distinctive_query_terms(query_text, limit=8)
        if (key := _identifier_key(term))
    }
    entity_text = " ".join(str(result.get("text", "")).split()).strip()
    entity_norm = _identifier_key(entity_text)
    query_norm = _identifier_key(query_text)
    if not entity_norm or not query_norm:
        return False
    if _has_non_ascii(entity_text) and len(entity_norm) >= 2 and entity_norm in query_norm:
        return True
    if not query_terms:
        return False
    if entity_norm in query_terms:
        return True

    entity_parts = [
        _identifier_key(token)
        for token in entity_text.split()
        if token
    ]
    return bool(entity_parts) and all(part in query_terms for part in entity_parts)


def _expand_high_confidence_entity_anchors(
    graph: "MemoryGraph",
    query: str,
    rows: List[Dict[str, Any]],
    *,
    intent: Optional[str] = None,
    limit: int = 5,
    expansion_mode: str = "cheap",
    max_anchor_count: int = 2,
    expansion_limit_per_anchor: int = 2,
    allow_graph_rows: bool = False,
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """Expand top-K graph anchors with a bounded one-hop graph walk."""
    query_text = str(query or "").strip()
    if not query_text:
        return [], []
    if intent is None:
        try:
            intent, _ = classify_intent(query_text)
        except Exception:
            intent = "GENERAL"

    ranked_rows = sorted(
        [row for row in rows if isinstance(row, dict)],
        key=lambda item: float(item.get("similarity", 0.0) or 0.0),
        reverse=True,
    )[: max(0, int(limit or 0))]
    anchors: List[Tuple[Dict[str, Any], float, str, Optional[List[str]]]] = []
    for row in ranked_rows:
        anchor_id = str(row.get("id") or "").strip()
        anchor_text = ""
        relation_filter: Optional[List[str]] = None
        if _is_low_information_entity_result(row):
            anchor_text = " ".join(str(row.get("text", "")).split()).strip()
        elif allow_graph_rows and (row.get("via_relation") or row.get("graph_path")) and anchor_id:
            try:
                anchor_node = graph.get_node(anchor_id)
            except Exception:
                anchor_node = None
            if anchor_node and str(anchor_node.type or "").strip().lower() in _LOW_INFO_ENTITY_CATEGORIES:
                anchor_text = " ".join(str(anchor_node.name or "").split()).strip()
                relation_filter = ["has_fact"]
        else:
            continue
        if not anchor_id or not anchor_text:
            continue
        anchors.append((row, float(row.get("similarity", 0.0) or 0.0), anchor_text, relation_filter))
        if len(anchors) >= max_anchor_count:
            break
    if not anchors:
        return [], []

    expanded: List[Dict[str, Any]] = []
    preserved_anchor_rows: List[Dict[str, Any]] = []
    seen_ids = {str(r.get("id") or "") for r in rows if str(r.get("id") or "")}
    for anchor_row, anchor_score, anchor_text, relation_filter in anchors:
        anchor_id = str(anchor_row.get("id") or "").strip()
        if not anchor_id or not anchor_text:
            continue
        preserved_anchor_rows.append(anchor_row)
        try:
            beam_width = 8 if expansion_mode == "cheap" else 4
            max_results = 8 if expansion_mode == "cheap" else 6
            related = graph.beam_search_graph(
                query=query_text,
                start_id=anchor_id,
                beam_width=beam_width,
                max_depth=1,
                max_results=max_results,
                intent=intent,
                relations=relation_filter,
                allow_llm_rerank=(expansion_mode != "cheap"),
            )
        except Exception:
            continue
        added_for_anchor = 0
        for rel_node, relation, direction, hop_depth, path, beam_score in related:
            if rel_node.id in seen_ids:
                continue
            seen_ids.add(rel_node.id)
            rel_score = max(0.0, float(anchor_score) * max(0.0, float(beam_score or 0.0)))
            rel_attrs = rel_node.attributes if isinstance(rel_node.attributes, dict) else {}
            graph_path = _render_bidirectional_graph_path(
                anchor_text,
                rel_node.name,
                relation,
                direction,
                path,
            )
            relation_sequence = _relation_sequence_from_path(path, terminal_relation=relation)
            if relation == "has_fact" and str(rel_node.type or "").strip().lower() == "fact":
                text = rel_node.name
            else:
                text = _render_bidirectional_graph_text(
                    anchor_text,
                    rel_node.name,
                    relation,
                    direction,
                )
            row = {
                "text": _sanitize_for_context(text),
                "category": rel_node.type.lower(),
                "similarity": round(rel_score, 3),
                "verified": rel_node.verified,
                "pinned": rel_node.pinned,
                "id": rel_node.id,
                "via": "graph_anchor_expansion",
                "via_relation": relation,
                "hop_depth": hop_depth,
                "graph_path": graph_path,
                "_graph_anchor_expansion": True,
                "anchor_id": anchor_id,
                "anchor_text": anchor_text,
                "anchor_similarity": round(anchor_score, 3),
                "anchor_category": str(anchor_row.get("category") or "").lower() or "entity",
                "domains": _domains_from_attrs(rel_attrs),
                "project": rel_attrs.get("project"),
                "source_type": rel_attrs.get("source_type"),
                "structural_anchor_kind": rel_attrs.get("structural_anchor_kind"),
                **_node_recall_temporal_fields(rel_node),
                "extraction_confidence": getattr(rel_node, "extraction_confidence", None),
                "privacy": getattr(rel_node, "privacy", None),
                "owner_id": getattr(rel_node, "owner_id", None),
            }
            _annotate_graph_traversal_fields(row, relation_sequence, discovery_kind="graph_anchor_expansion")
            expanded.append(row)
            added_for_anchor += 1
            if added_for_anchor >= max(1, int(expansion_limit_per_anchor or 1)):
                break
    return preserved_anchor_rows, expanded


def _is_graph_anchor_expansion_row(result: Dict[str, Any]) -> bool:
    return bool(result.get("_graph_anchor_expansion")) or str(result.get("via") or "").strip().lower() == "graph_anchor_expansion"


def _recall_row_identity(result: Dict[str, Any]) -> str:
    if _is_graph_anchor_expansion_row(result):
        return "|".join([
            "graph_anchor_expansion",
            str(result.get("anchor_id") or ""),
            str(result.get("id") or ""),
            str(result.get("via_relation") or ""),
            str(result.get("text") or ""),
        ])
    row_id = str(result.get("id") or "").strip()
    if row_id:
        return row_id
    return str(result.get("text") or "")


def _select_final_recall_rows(
    rows: List[Dict[str, Any]],
    *,
    limit: int,
    anchor_rows: Optional[List[Dict[str, Any]]] = None,
    expansion_limit_per_anchor: int = 2,
) -> List[Dict[str, Any]]:
    if limit <= 0:
        return []

    regular_rows = [row for row in rows if not _is_graph_anchor_expansion_row(row)]
    expansion_rows = [row for row in rows if _is_graph_anchor_expansion_row(row)]
    regular_rows.sort(key=lambda item: float(item.get("similarity", 0.0) or 0.0), reverse=True)
    expansion_rows.sort(key=lambda item: float(item.get("similarity", 0.0) or 0.0), reverse=True)

    selected: List[Dict[str, Any]] = []
    seen_keys: Set[str] = set()

    def _push(row: Dict[str, Any]) -> bool:
        key = _recall_row_identity(row)
        if key in seen_keys:
            return False
        selected.append(row)
        seen_keys.add(key)
        return True

    grouped_expansions: Dict[str, List[Dict[str, Any]]] = {}
    for row in expansion_rows:
        anchor_key = str(row.get("anchor_id") or row.get("anchor_text") or "")
        grouped_expansions.setdefault(anchor_key, []).append(row)

    normalized_anchor_rows: List[Dict[str, Any]] = []
    for row in anchor_rows or []:
        if isinstance(row, dict):
            normalized_anchor_rows.append(row)

    for anchor in normalized_anchor_rows:
        if len(selected) >= limit:
            break
        if not _push(anchor):
            continue
        anchor_key = str(anchor.get("id") or anchor.get("text") or "")
        for expansion in grouped_expansions.get(anchor_key, [])[: max(1, int(expansion_limit_per_anchor or 1))]:
            if len(selected) >= limit:
                break
            _push(expansion)

    for row in regular_rows:
        if len(selected) >= limit:
            break
        _push(row)

    return sorted(selected, key=lambda item: float(item.get("similarity", 0.0) or 0.0), reverse=True)[:limit]


def _sanitize_for_context(text: str) -> str:
    """Strip potential injection patterns from recalled text (defense-in-depth)."""
    result = text
    for pattern in _INJECTION_PATTERNS:
        result = pattern.sub("[FILTERED]", result)
    return result


def _validate_confidence_unit_interval(value: Any, field_name: str) -> float:
    """Normalize confidence-like values and enforce [0.0, 1.0]."""
    try:
        parsed = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} must be a number between 0.0 and 1.0") from exc
    if parsed < 0.0 or parsed > 1.0:
        raise ValueError(f"{field_name} must be between 0.0 and 1.0 (got {parsed})")
    return parsed


def _validate_storage_strength(value: Any) -> float:
    """Normalize persisted storage strength and enforce the model's [0.0, 10.0] cap."""
    try:
        parsed = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("storage_strength must be a number between 0.0 and 10.0") from exc
    if parsed < 0.0 or parsed > 10.0:
        raise ValueError(f"storage_strength must be between 0.0 and 10.0 (got {parsed})")
    return parsed


def _validate_node_persistence_scores(node: Node) -> None:
    """Reject invalid score fields before they enter persisted graph state."""
    node.confidence = _validate_confidence_unit_interval(node.confidence, "confidence")
    node.extraction_confidence = _validate_confidence_unit_interval(
        node.extraction_confidence,
        "extraction_confidence",
    )
    node.provenance_confidence = _validate_confidence_unit_interval(
        node.provenance_confidence,
        "provenance_confidence",
    )
    node.storage_strength = _validate_storage_strength(node.storage_strength)


def _load_dedup_candidates_vec(
    *,
    graph: "MemoryGraph",
    conn: sqlite3.Connection,
    query_embedding: List[float],
    owner_id: Optional[str],
    rowid_min: Optional[int],
    rowid_max: Optional[int],
    candidate_limit: int = 64,
) -> Tuple[List[Tuple[sqlite3.Row, float]], Dict[str, int]]:
    """Load bounded nearest-neighbor dedup candidates from sqlite-vec."""
    telemetry = {
        "vec_query_count": 0,
        "vec_candidates_returned": 0,
        "vec_candidate_limit": candidate_limit,
        "vec_limit_hits": 0,
    }

    try:
        conn.execute("SELECT 1 FROM vec_nodes LIMIT 0")
    except sqlite3.OperationalError as exc:
        if "no such table: vec_nodes" not in str(exc).lower():
            raise
        sample = conn.execute(
            "SELECT embedding FROM nodes WHERE embedding IS NOT NULL LIMIT 1"
        ).fetchone()
        if not sample:
            return [], telemetry
        graph._ensure_vec_table(conn, query_embedding)
        missing = conn.execute(
            """
                SELECT n.id, n.embedding FROM nodes n
                WHERE n.embedding IS NOT NULL
                  AND n.id NOT IN (SELECT node_id FROM vec_nodes)
            """
        ).fetchall()
        for row in missing:
            conn.execute(
                "INSERT OR REPLACE INTO vec_nodes(node_id, embedding) VALUES (?, ?)",
                (row["id"], row["embedding"]),
            )

    rowid_clause = ""
    rowid_params: List[Any] = []
    if rowid_min is not None and rowid_min >= 0:
        rowid_clause += " AND n.rowid > ?"
        rowid_params.append(rowid_min)
    if rowid_max is not None and rowid_max >= 0:
        rowid_clause += " AND n.rowid <= ?"
        rowid_params.append(rowid_max)

    owner_clause = ""
    owner_params: List[Any] = []
    if owner_id:
        owner_clause = " AND (n.owner_id = ? OR n.owner_id IS NULL)"
        owner_params.append(owner_id)

    has_candidates = conn.execute(
        f"""
            SELECT 1
            FROM nodes n
            WHERE n.embedding IS NOT NULL
              AND n.superseded_by IS NULL
              AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
              {rowid_clause}
              {owner_clause}
            LIMIT 1
        """,
        tuple(rowid_params + owner_params),
    ).fetchone()
    if not has_candidates:
        return [], telemetry

    packed_query = graph._pack_embedding(query_embedding)
    telemetry["vec_query_count"] = 1
    rows = conn.execute(
        f"""
            SELECT n.*, knn.distance AS vec_distance
            FROM (
                SELECT node_id, distance
                FROM vec_nodes
                WHERE embedding MATCH ? AND k = ?
            ) knn
            JOIN nodes n ON n.id = knn.node_id
            WHERE n.embedding IS NOT NULL
              AND n.superseded_by IS NULL
              AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
              {rowid_clause}
              {owner_clause}
            ORDER BY knn.distance
        """,
        tuple([packed_query, candidate_limit] + rowid_params + owner_params),
    ).fetchall()

    telemetry["vec_candidates_returned"] = len(rows)
    telemetry["vec_limit_hits"] = 1 if len(rows) >= candidate_limit else 0
    candidates: List[Tuple[sqlite3.Row, float]] = []
    for row in rows:
        distance = row["vec_distance"]
        similarity = max(-1.0, min(1.0, 1.0 - float(distance if distance is not None else 1.0)))
        candidates.append((row, similarity))
    return candidates, telemetry


def _load_dedup_candidates_fts(
    *,
    conn: sqlite3.Connection,
    owner_id: Optional[str],
    rowid_filter_sql: str,
    rowid_filter_params: List[Any],
    rowid_min: Optional[int],
    rowid_max: Optional[int],
    text: str,
    candidate_limit: int = 64,
) -> Tuple[List[Tuple[sqlite3.Row, Optional[float]]], Dict[str, int]]:
    """Load lexical dedup candidates through FTS with bounded fallback scan."""
    telemetry: Dict[str, int] = {
        "fts_query_count": 0,
        "fts_candidates_returned": 0,
        "fts_candidate_limit": 0,
        "fts_limit_hits": 0,
        "fallback_scan_count": 0,
        "fallback_candidates_returned": 0,
        "token_prefilter_terms": 0,
        "token_prefilter_skips": 0,
    }
    tokens = _lib_extract_key_tokens(text)
    telemetry["token_prefilter_terms"] += len(tokens)
    if not tokens:
        telemetry["token_prefilter_skips"] += 1
        return [], telemetry

    telemetry["fts_query_count"] += 1
    telemetry["fts_candidate_limit"] = candidate_limit
    fts_query = " OR ".join(f'"{t}"' for t in tokens)
    try:
        rowid_clause = ""
        rowid_clause_params: List[Any] = []
        if rowid_min is not None and rowid_min >= 0:
            rowid_clause += " AND n.rowid > ?"
            rowid_clause_params.append(rowid_min)
        if rowid_max is not None and rowid_max >= 0:
            rowid_clause += " AND n.rowid <= ?"
            rowid_clause_params.append(rowid_max)
        if owner_id:
            rows = conn.execute(
                f"""
                    SELECT n.* FROM nodes_fts
                    JOIN nodes n ON n.rowid = nodes_fts.rowid
                    WHERE nodes_fts MATCH ?
                      {rowid_clause}
                      AND n.embedding IS NOT NULL
                      AND n.superseded_by IS NULL
                      AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
                      AND (n.owner_id = ? OR n.owner_id IS NULL)
                    LIMIT ?
                """,
                tuple([fts_query] + rowid_clause_params + [owner_id, candidate_limit]),
            ).fetchall()
        else:
            rows = conn.execute(
                f"""
                    SELECT n.* FROM nodes_fts
                    JOIN nodes n ON n.rowid = nodes_fts.rowid
                    WHERE nodes_fts MATCH ?
                      {rowid_clause}
                      AND n.embedding IS NOT NULL
                      AND n.superseded_by IS NULL
                      AND (n.status IS NULL OR n.status IN ('approved', 'pending', 'active'))
                    LIMIT ?
                """,
                tuple([fts_query] + rowid_clause_params + [candidate_limit]),
            ).fetchall()
        telemetry["fts_candidates_returned"] += len(rows)
        if len(rows) >= candidate_limit:
            telemetry["fts_limit_hits"] += 1
        return [(row, None) for row in rows], telemetry
    except Exception:
        telemetry["fallback_scan_count"] += 1
        if owner_id:
            rows = conn.execute(
                f"SELECT * FROM nodes WHERE embedding IS NOT NULL{rowid_filter_sql} AND (owner_id = ? OR owner_id IS NULL) ORDER BY accessed_at DESC LIMIT 64",
                tuple(rowid_filter_params + [owner_id]),
            ).fetchall()
        else:
            rows = conn.execute(
                f"SELECT * FROM nodes WHERE embedding IS NOT NULL{rowid_filter_sql} ORDER BY accessed_at DESC LIMIT 64",
                tuple(rowid_filter_params),
            ).fetchall()
        telemetry["fallback_candidates_returned"] += len(rows)
        return [(row, None) for row in rows], telemetry
def _resolve_fact_subject_anchor(
    graph: "MemoryGraph",
    text: str,
    *,
    subject_entity_id: Optional[str] = None,
    subject_entity_name: Optional[str] = None,
) -> Optional["Node"]:
    """Resolve a subject anchor for a fact row from structured metadata only."""
    if subject_entity_id:
        try:
            node = graph.get_node(str(subject_entity_id).strip())
        except Exception:
            node = None
        if node and str(getattr(node, "type", "") or "").strip() in {
            "Person", "Place", "Pet", "Organization", "Concept"
        }:
            return node

    candidate = " ".join(str(subject_entity_name or "").split()).strip()
    if not candidate:
        return None

    for node_type in ("Person", "Place", "Pet", "Organization", "Concept"):
        try:
            node = graph.find_node_by_name(candidate, type=node_type)
        except Exception:
            node = None
        if node:
            return node
    return None


def _ensure_fact_subject_edge(
    graph: "MemoryGraph",
    *,
    fact_node: "Node",
    conn: sqlite3.Connection,
    subject_entity_id: Optional[str] = None,
    subject_entity_name: Optional[str] = None,
) -> Optional[str]:
    """Persist the generic subject -> fact link when the subject is resolvable."""
    if not fact_node or not getattr(fact_node, "id", None):
        return None
    if str(getattr(fact_node, "type", "") or "").strip().lower() != "fact":
        return None

    subject_node = _resolve_fact_subject_anchor(
        graph,
        str(getattr(fact_node, "name", "") or ""),
        subject_entity_id=subject_entity_id,
        subject_entity_name=subject_entity_name,
    )
    if not subject_node or not getattr(subject_node, "id", None):
        return None
    if str(subject_node.id) == str(fact_node.id):
        return None

    existing = conn.execute(
        "SELECT id FROM edges WHERE source_id = ? AND target_id = ? AND relation = 'has_fact' LIMIT 1",
        (subject_node.id, fact_node.id),
    ).fetchone()
    if existing:
        return str(existing[0] or "")

    edge = Edge.create(
        source_id=subject_node.id,
        target_id=fact_node.id,
        relation="has_fact",
        source_fact_id=fact_node.id,
    )
    conn.execute(
        """
        INSERT OR REPLACE INTO edges
        (id, source_id, target_id, relation, attributes, weight,
         valid_from, valid_until, created_at, source_fact_id,
         origin_package_id, origin_version_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            edge.id,
            edge.source_id,
            edge.target_id,
            edge.relation,
            json.dumps(edge.attributes),
            edge.weight,
            edge.valid_from,
            edge.valid_until,
            edge.created_at or _now_iso(),
            edge.source_fact_id,
            edge.origin_package_id,
            edge.origin_version_id,
        ),
    )
    return edge.id


def store(
    text: str,
    category: str = "fact",
    verified: bool = False,
    pinned: bool = False,
    confidence: float = 0.5,
    privacy: str = "shared",
    source: Optional[str] = None,
    source_id: Optional[str] = None,
    source_chunk_id: Optional[str] = None,
    owner_id: Optional[str] = None,
    session_id: Optional[str] = None,
    fact_type: str = "mutable",
    extraction_confidence: float = 0.5,
    dedup_threshold: float = 0.95,  # Catch near-identical duplicates (was 0.92, raised to avoid false positives on similar-but-different facts)
    update_if_dup: bool = True,
    skip_dedup: bool = False,  # If True, skip deduplication entirely
    speaker: Optional[str] = None,  # Who stated this fact
    status: Optional[str] = None,  # Override default status (pending for auto, approved for manual)
    knowledge_type: str = "fact",  # fact, belief, preference, experience
    keywords: Optional[str] = None,  # Space-separated derived search terms
    source_type: Optional[str] = None,  # user, assistant, subagent, tool, import
    target_datastore: Optional[str] = None,  # reserved routing seam (no-op in memorydb)
    domains: Optional[List[str]] = None,  # optional domain tags
    project: Optional[str] = None,  # project label for project-state facts
    source_channel: Optional[str] = None,  # conversation channel/source (telegram/discord/etc.)
    source_conversation_id: Optional[str] = None,  # stable thread/group identifier
    source_author_id: Optional[str] = None,  # external speaker/author identifier
    speaker_entity_id: Optional[str] = None,  # canonical speaker entity id
    conversation_id: Optional[str] = None,  # canonical conversation/thread identifier
    participant_entity_ids: Optional[List[str]] = None,  # canonical participants for this context
    visibility_scope: Optional[str] = None,  # private_subject/source_shared/global_shared/system
    sensitivity: Optional[str] = None,  # normal/restricted/secret
    provenance_confidence: Optional[float] = None,  # attribution confidence
    actor_id: Optional[str] = None,  # canonical actor entity id
    subject_entity_id: Optional[str] = None,  # canonical subject entity id
    subject_entity_name: Optional[str] = None,  # exact named entity this fact is about
    structural_anchor_kind: Optional[str] = None,  # exact-anchor preservation marker
    occurred_start: Optional[str] = None,  # When the fact/event happened (range start)
    occurred_end: Optional[str] = None,  # When the fact/event happened (range end)
    mentioned_at: Optional[str] = None,  # When Quaid learned/was told the fact
    created_at: Optional[str] = None,  # Override created_at timestamp (ISO format)
    accessed_at: Optional[str] = None,  # Override accessed_at timestamp (ISO format)
    _conn: Optional[sqlite3.Connection] = None,
    _dedup_rowid_min_exclusive: Optional[int] = None,
    _dedup_rowid_max: Optional[int] = None,
    _dedup_only: bool = False,
) -> Dict[str, Any]:
    """
    Store a new memory with deduplication.
    
    Args:
        text: The memory text to store
        category: preference, fact, decision, entity, other
        verified: Whether this is a verified fact
        pinned: Whether this memory is pinned (never decays)
        confidence: Confidence level 0.0-1.0
        privacy: private, shared, public
        source: Source of the memory (e.g., "telegram")
        source_id: Source message ID
        owner_id: Owner identifier for multi-user support
        dedup_threshold: Similarity threshold for duplicate detection (0.85 = very similar)
        update_if_dup: If duplicate found, update it instead of skipping
    
    Returns:
        Dict with: id, status ("created", "duplicate", "updated"), similarity (if dup)
    """
    # Circuit breaker guard — block writes if disabled
    try:
        from lib.circuit_breaker import check_write_allowed
        from lib.adapter import get_adapter
        breaker = check_write_allowed(get_adapter().data_dir())
        if not breaker.allows_writes():
            return {
                "id": None,
                "status": "blocked",
                "reason": f"circuit_breaker:{breaker.status}",
                "dedup_telemetry": {},
            }
    except Exception as exc:
        logger.warning("Memory write circuit-breaker check failed: %s", exc)
        if _is_fail_hard_mode():
            raise RuntimeError("Memory write circuit-breaker check failed") from exc

    # Input validation
    if not text or not text.strip():
        raise ValueError("Content cannot be empty")

    text = text.strip()
    word_count = len(text.split())
    if (
        word_count < 3
        and category not in _LOW_INFO_ENTITY_CATEGORIES
        and not _looks_like_compact_script_fact(text)
    ):
        raise ValueError(f"Facts must be at least 3 words (got {word_count}: '{text}'). A fact needs a subject, verb, and object (e.g., 'X is Y').")

    if not owner_id:
        try:
            owner_id = _get_memory_config().users.default_owner
        except Exception as exc:
            if _is_fail_hard_mode():
                raise RuntimeError("store failed to read default owner") from exc
            logger.warning(
                "store failed to read default owner; using 'default': %s",
                exc,
            )
            owner_id = "default"
    owner_id = str(owner_id).strip()
    if not owner_id:
        owner_id = "default"

    confidence = _validate_confidence_unit_interval(confidence, "confidence")
    extraction_confidence = _validate_confidence_unit_interval(
        extraction_confidence,
        "extraction_confidence",
    )
    if provenance_confidence is not None:
        provenance_confidence = _validate_confidence_unit_interval(
            provenance_confidence,
            "provenance_confidence",
        )
    # Normalize source_type aliases at storage boundary.
    if source_type is not None:
        source_type = str(source_type).strip().lower()
        if source_type == "agent":
            source_type = "assistant"
        if source_type not in {"user", "assistant", "subagent", "both", "tool", "import"}:
            source_type = None
    project = _normalize_project_tag(project)
    domains = _sanitize_domains_for_project(domains, project)

    # Default speaker attribution for assistant-originated facts when omitted.
    if (not speaker) and source_type == "assistant":
        speaker = "Assistant"
    if speaker_entity_id and not actor_id:
        actor_id = speaker_entity_id
    if conversation_id and not source_conversation_id:
        source_conversation_id = conversation_id
    if subject_entity_name is not None:
        subject_entity_name = " ".join(str(subject_entity_name).split()).strip() or None
    if structural_anchor_kind is not None:
        structural_anchor_kind = str(structural_anchor_kind).strip().lower() or None
    if source_chunk_id is not None:
        source_chunk_id = str(source_chunk_id).strip() or None
    
    # Map category to type
    type_map = {
        "preference": "Preference",
        "fact": "Fact",
        "decision": "Event",
        "entity": "Concept",
        "other": "Fact"
    }
    node_type = type_map.get(category.lower(), "Fact")

    graph = get_graph()
    dedup_telemetry: Dict[str, int] = {
        "hash_exact_hits": 0,
        "scanned_rows": 0,
        "gray_zone_rows": 0,
        "llm_checks": 0,
        "llm_same_hits": 0,
        "llm_accept_hits": 0,
        "llm_subsume_update_hits": 0,
        "llm_subsume_keep_hits": 0,
        "llm_different_hits": 0,
        "fallback_reject_hits": 0,
        "auto_reject_hits": 0,
        "vec_query_count": 0,
        "vec_candidates_returned": 0,
        "vec_candidate_limit": 0,
        "vec_limit_hits": 0,
        "fts_query_count": 0,
        "fts_candidates_returned": 0,
        "fts_candidate_limit": 0,
        "fts_limit_hits": 0,
        "fallback_scan_count": 0,
        "fallback_candidates_returned": 0,
        "token_prefilter_terms": 0,
        "token_prefilter_skips": 0,
        "temporal_variant_hits": 0,
    }

    def _with_dedup_telemetry(payload: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(payload or {})
        out["dedup_telemetry"] = dict(dedup_telemetry)
        return out

    def _merge_session_id(existing_value: Optional[str], new_value: Optional[str]) -> Optional[str]:
        if not new_value:
            return existing_value
        if not existing_value:
            return new_value
        if str(existing_value) == str(new_value):
            return existing_value
        existing_match = re.match(r"session-(\d+)$", str(existing_value))
        new_match = re.match(r"session-(\d+)$", str(new_value))
        if existing_match and new_match:
            return existing_value if int(existing_match.group(1)) <= int(new_match.group(1)) else new_value
        return new_value

    def _apply_metadata_flags(
        existing: Node,
        *,
        allow_structural_anchor_upgrade: bool = False,
    ) -> None:
        """Persist source/domain metadata on dedup-update paths."""
        if not (
            session_id
            or source_type
            or target_datastore
            or domains
            or project
            or source_channel
            or source_conversation_id
            or source_author_id
            or speaker_entity_id
            or conversation_id
            or participant_entity_ids
            or visibility_scope
            or sensitivity
            or provenance_confidence is not None
            or actor_id
            or subject_entity_id
            or subject_entity_name
            or structural_anchor_kind
            or occurred_start
            or occurred_end
            or mentioned_at
            or source_chunk_id
        ):
            return
        attrs = existing.attributes if isinstance(existing.attributes, dict) else (existing.attributes or {})
        merged_session_id = _merge_session_id(existing.session_id, session_id)
        if merged_session_id != existing.session_id:
            existing.session_id = merged_session_id
        source_type_rank = {
            "import": 0,
            "user": 1,
            "assistant": 2,
            "tool": 2,
            "both": 2,
            "subagent": 3,
        }
        existing_source_type = str(attrs.get("source_type") or "").strip().lower()
        source_type_upgrade = bool(
            source_type
            and (
                not existing_source_type
                or source_type_rank.get(str(source_type), 0) > source_type_rank.get(existing_source_type, 0)
            )
        )
        if source_type_upgrade:
            attrs["source_type"] = source_type
        if source and (source_type_upgrade or not existing.source):
            existing.source = source
        if source_id and (source_type_upgrade or not existing.source_id):
            existing.source_id = source_id
        if source_chunk_id and not existing.source_chunk_id:
            existing.source_chunk_id = source_chunk_id
        if source_chunk_id and not attrs.get("source_chunk_id"):
            attrs["source_chunk_id"] = source_chunk_id
        if target_datastore and not attrs.get("target_datastore"):
            attrs["target_datastore"] = target_datastore
        if speaker and not existing.speaker:
            existing.speaker = speaker
        if domains:
            attrs["domains"] = _normalize_domains((attrs.get("domains") or []) + domains)
        if project and not attrs.get("project"):
            attrs["project"] = project
        if source_channel and not attrs.get("source_channel"):
            attrs["source_channel"] = source_channel
        if source_conversation_id and not attrs.get("source_conversation_id"):
            attrs["source_conversation_id"] = source_conversation_id
        if source_author_id and not attrs.get("source_author_id"):
            attrs["source_author_id"] = source_author_id
        if speaker_entity_id and not attrs.get("speaker_entity_id"):
            attrs["speaker_entity_id"] = speaker_entity_id
        if conversation_id and not attrs.get("conversation_id"):
            attrs["conversation_id"] = conversation_id
        if participant_entity_ids and not attrs.get("participant_entity_ids"):
            attrs["participant_entity_ids"] = list(participant_entity_ids)
        if visibility_scope and not attrs.get("visibility_scope"):
            attrs["visibility_scope"] = visibility_scope
        if sensitivity and not attrs.get("sensitivity"):
            attrs["sensitivity"] = sensitivity
        if provenance_confidence is not None and attrs.get("provenance_confidence") is None:
            attrs["provenance_confidence"] = float(provenance_confidence)
        if actor_id and not attrs.get("actor_id"):
            attrs["actor_id"] = actor_id
        resolved_subject_id = str(attrs.get("subject_entity_id") or "").strip() or subject_entity_id
        if not resolved_subject_id and subject_entity_name:
            subject_anchor = _resolve_fact_subject_anchor(
                graph,
                existing.name,
                subject_entity_name=subject_entity_name,
            )
            if subject_anchor and getattr(subject_anchor, "id", None):
                resolved_subject_id = str(subject_anchor.id)
        if resolved_subject_id and not attrs.get("subject_entity_id"):
            attrs["subject_entity_id"] = resolved_subject_id
        if subject_entity_name and not attrs.get("subject_entity_name"):
            attrs["subject_entity_name"] = subject_entity_name
        if (
            allow_structural_anchor_upgrade
            and structural_anchor_kind
            and not attrs.get("structural_anchor_kind")
        ):
            attrs["structural_anchor_kind"] = structural_anchor_kind
        if occurred_start and not existing.occurred_start:
            existing.occurred_start = occurred_start
        if occurred_end and not existing.occurred_end:
            existing.occurred_end = occurred_end
        if mentioned_at and not existing.mentioned_at:
            existing.mentioned_at = mentioned_at
        if speaker_entity_id and not existing.speaker_entity_id:
            existing.speaker_entity_id = speaker_entity_id
        if conversation_id and not existing.conversation_id:
            existing.conversation_id = conversation_id
        if visibility_scope and not existing.visibility_scope:
            existing.visibility_scope = visibility_scope
        if sensitivity and not existing.sensitivity:
            existing.sensitivity = sensitivity
        if provenance_confidence is not None and existing.provenance_confidence is None:
            existing.provenance_confidence = float(provenance_confidence)
        existing.attributes = attrs
        if str(getattr(existing, "type", "") or "").strip().lower() == "fact":
            conn_cm = nullcontext(_conn) if _conn is not None else graph._get_conn()
            with conn_cm as conn:
                _ensure_fact_subject_edge(
                    graph,
                    fact_node=existing,
                    conn=conn,
                    subject_entity_id=resolved_subject_id,
                    subject_entity_name=subject_entity_name,
                )

    def _node_temporal_merge_fact(existing: Node) -> Dict[str, Any]:
        attrs = existing.attributes if isinstance(existing.attributes, dict) else (existing.attributes or {})
        return {
            "text": existing.name,
            "category": attrs.get("category") or existing.knowledge_type or existing.type,
            "_source_timestamp": existing.mentioned_at or existing.created_at,
            "occurred_start": existing.occurred_start,
            "occurred_end": existing.occurred_end,
            "mentioned_at": existing.mentioned_at,
            "extraction_confidence": existing.extraction_confidence,
            "source": existing.source,
            "_source_id": existing.source_id,
            "source_chunk_id": existing.source_chunk_id,
        }

    def _incoming_temporal_merge_fact() -> Dict[str, Any]:
        return {
            "text": text,
            "category": category,
            "_source_timestamp": mentioned_at or created_at,
            "occurred_start": occurred_start,
            "occurred_end": occurred_end,
            "mentioned_at": mentioned_at,
            "extraction_confidence": extraction_confidence,
            "source": source,
            "_source_id": source_id,
            "source_chunk_id": source_chunk_id,
        }

    def _apply_temporal_variant_update(
        existing: Node,
        *,
        incoming_embedding: Optional[List[float]] = None,
    ) -> None:
        merged_fact = _merge_extraction_duplicate_fact_entries(
            _node_temporal_merge_fact(existing),
            _incoming_temporal_merge_fact(),
        )
        merged_start = merged_fact.get("occurred_start")
        merged_end = merged_fact.get("occurred_end")
        merged_mentioned = merged_fact.get("mentioned_at")
        if merged_start:
            existing.occurred_start = merged_start
        if merged_end:
            existing.occurred_end = merged_end
        if merged_mentioned and not existing.mentioned_at:
            existing.mentioned_at = merged_mentioned
        merged_text = str(merged_fact.get("text") or "").strip()
        if incoming_embedding is not None and merged_text == text and existing.name != text:
            existing.name = text
            existing.embedding = incoming_embedding
            existing.content_hash = text_hash

    def _is_temporal_variant_of_existing(existing: Node) -> bool:
        return _facts_are_extraction_temporal_siblings(
            _node_temporal_merge_fact(existing),
            _incoming_temporal_merge_fact(),
        )

    rowid_filter_parts: List[str] = []
    rowid_filter_params: List[Any] = []
    rowid_min = None
    rowid_max = None
    if _dedup_rowid_min_exclusive is not None:
        try:
            rowid_min = int(_dedup_rowid_min_exclusive)
        except (TypeError, ValueError):
            rowid_min = None
        if rowid_min is not None and rowid_min >= 0:
            rowid_filter_parts.append(" AND rowid > ?")
            rowid_filter_params.append(rowid_min)
    if _dedup_rowid_max is not None:
        try:
            rowid_max = int(_dedup_rowid_max)
        except (TypeError, ValueError):
            rowid_max = None
        if rowid_max is not None and rowid_max >= 0:
            rowid_filter_parts.append(" AND rowid <= ?")
            rowid_filter_params.append(rowid_max)
    rowid_filter_sql = "".join(rowid_filter_parts)

    # Fast exact-dedup: content hash check (before embedding, saves API calls)
    text_hash = content_hash(text)
    if not skip_dedup:
        conn_cm = nullcontext(_conn) if _conn is not None else graph._get_conn()
        with conn_cm as conn:
            owner_clause = "AND (owner_id = ? OR owner_id IS NULL)" if owner_id else ""
            params = [text_hash] + rowid_filter_params + ([owner_id] if owner_id else [])
            existing_row = conn.execute(f"""
                SELECT * FROM nodes WHERE content_hash = ?
                  {rowid_filter_sql}
                  AND (status IS NULL OR status IN ('approved', 'pending', 'active', 'flagged'))
                  AND deleted_at IS NULL
                  {owner_clause}
                LIMIT 1
            """, params).fetchone()
            if existing_row:
                existing = graph._row_to_node(existing_row)
                dedup_telemetry["hash_exact_hits"] += 1
                log_dedup_decision(graph, text, existing.id, existing.name,
                                   1.0, "hash_exact", owner_id=owner_id, source=source, conn=_conn)
                # Confirmation boosting: re-extraction confirms this fact
                existing.confirmation_count += 1
                existing.last_confirmed_at = _now_iso()
                existing.confidence = min(existing.confidence + 0.02, 0.95)
                # Bjork: re-encoding strengthens storage (smaller than retrieval increment)
                existing.storage_strength = min(10.0, existing.storage_strength + 0.03)
                existing_had_occurred = bool(existing.occurred_start or existing.occurred_end)
                _apply_metadata_flags(existing, allow_structural_anchor_upgrade=True)
                if existing_had_occurred and _is_temporal_variant_of_existing(existing):
                    dedup_telemetry["temporal_variant_hits"] += 1
                    _apply_temporal_variant_update(existing)
                if update_if_dup and verified and not existing.verified:
                    existing.verified = True
                    existing.confidence = 0.9
                graph.update_node(existing, conn=_conn)
                if update_if_dup and verified:
                    return _with_dedup_telemetry({
                        "id": existing.id,
                        "status": "updated",
                        "similarity": 1.0,
                        "existing_text": existing.name,
                        "confirmation_count": existing.confirmation_count,
                    })
                return _with_dedup_telemetry({
                    "id": existing.id,
                    "status": "duplicate",
                    "similarity": 1.0,
                    "existing_text": existing.name,
                    "confirmation_count": existing.confirmation_count,
                })

    # Dedup check: three-zone logic with optional LLM verification
    embedding = graph.get_embedding(text, conn=_conn)
    if not embedding and _is_fail_hard_mode():
        raise RuntimeError(
            "Embedding generation failed while failHard is enabled; refusing to store memory without an embedding"
        )
    if not skip_dedup and embedding:
        # Load dedup thresholds from config (with fallbacks)
        if _HAS_CONFIG:
            cfg = _get_memory_config()
            auto_reject_thresh = cfg.janitor.dedup.auto_reject_threshold
            gray_zone_low = cfg.janitor.dedup.gray_zone_low
            llm_verify_enabled = cfg.janitor.dedup.llm_verify_enabled
        else:
            auto_reject_thresh = 0.98
            gray_zone_low = 0.88
            llm_verify_enabled = False

        # Search for high-similarity matches using FTS5 token pre-filter
        gray_zone_candidates: List[Tuple[Node, float]] = []
        conn_cm = nullcontext(_conn) if _conn is not None else graph._get_conn()
        with conn_cm as conn:
            candidate_rows: List[Tuple[sqlite3.Row, Optional[float]]] = []
            if _lib_has_vec():
                try:
                    candidate_rows, candidate_meta = _load_dedup_candidates_vec(
                        graph=graph,
                        conn=conn,
                        query_embedding=embedding,
                        owner_id=owner_id,
                        rowid_min=rowid_min,
                        rowid_max=rowid_max,
                    )
                    for key, value in candidate_meta.items():
                        dedup_telemetry[key] += int(value or 0)
                except Exception as exc:
                    if _is_fail_hard_mode():
                        raise RuntimeError(
                            "Vector dedup candidate search failed while fail-hard mode is enabled"
                        ) from exc
                    logger.warning("Vector dedup candidate search failed; falling back to FTS: %s", exc)
            if not candidate_rows:
                candidate_rows, candidate_meta = _load_dedup_candidates_fts(
                    conn=conn,
                    owner_id=owner_id,
                    rowid_filter_sql=rowid_filter_sql,
                    rowid_filter_params=rowid_filter_params,
                    rowid_min=rowid_min,
                    rowid_max=rowid_max,
                    text=text,
                )
                for key, value in candidate_meta.items():
                    dedup_telemetry[key] += int(value or 0)

            for row, candidate_similarity in candidate_rows:
                existing = graph._row_to_node(row)
                sim = candidate_similarity
                if sim is None:
                    if not existing.embedding:
                        continue
                    sim = graph.cosine_similarity(embedding, existing.embedding)
                dedup_telemetry["scanned_rows"] += 1

                if _is_temporal_variant_of_existing(existing):
                    dedup_telemetry["temporal_variant_hits"] += 1
                    log_dedup_decision(
                        graph,
                        text,
                        existing.id,
                        existing.name,
                        sim,
                        "temporal_variant",
                        owner_id=owner_id,
                        source=source,
                        conn=_conn,
                    )
                    existing.confirmation_count += 1
                    existing.last_confirmed_at = _now_iso()
                    existing.confidence = min(existing.confidence + 0.02, 0.95)
                    existing.storage_strength = min(10.0, existing.storage_strength + 0.03)
                    _apply_metadata_flags(existing, allow_structural_anchor_upgrade=True)
                    _apply_temporal_variant_update(existing, incoming_embedding=embedding)
                    if update_if_dup and verified and not existing.verified:
                        existing.verified = True
                        existing.confidence = 0.9
                    graph.update_node(existing, conn=_conn)
                    return _with_dedup_telemetry({
                        "id": existing.id,
                        "status": "duplicate",
                        "similarity": round(sim, 3),
                        "existing_text": existing.name,
                        "confirmation_count": existing.confirmation_count,
                    })

                if sim >= auto_reject_thresh and texts_are_near_identical(text, existing.name):
                    dedup_telemetry["auto_reject_hits"] += 1
                    # Zone 1: Auto-reject (high sim AND texts are near-identical strings)
                    log_dedup_decision(graph, text, existing.id, existing.name,
                                       sim, "auto_reject", owner_id=owner_id, source=source, conn=_conn)
                    # Confirmation boosting: re-extraction confirms this fact
                    existing.confirmation_count += 1
                    existing.last_confirmed_at = _now_iso()
                    existing.confidence = min(existing.confidence + 0.02, 0.95)
                    # Bjork: re-encoding strengthens storage (smaller than retrieval increment)
                    existing.storage_strength = min(10.0, existing.storage_strength + 0.03)
                    _apply_metadata_flags(existing, allow_structural_anchor_upgrade=True)
                    if update_if_dup and verified and not existing.verified:
                        existing.verified = True
                        existing.confidence = 0.9
                    graph.update_node(existing, conn=_conn)
                    if update_if_dup and verified:
                        return _with_dedup_telemetry({
                            "id": existing.id,
                            "status": "updated",
                            "similarity": round(sim, 3),
                            "existing_text": existing.name,
                            "confirmation_count": existing.confirmation_count,
                        })
                    return _with_dedup_telemetry({
                        "id": existing.id,
                        "status": "duplicate",
                        "similarity": round(sim, 3),
                        "existing_text": existing.name,
                        "confirmation_count": existing.confirmation_count,
                    })

                elif sim >= gray_zone_low:
                    dedup_telemetry["gray_zone_rows"] += 1
                    # Zone 2: Gray zone — LLM verification
                    if llm_verify_enabled:
                        gray_zone_candidates.append((existing, sim))
                        continue
                    else:
                        # LLM verification disabled — use similarity threshold
                        # But only reject if texts are near-identical strings
                        if sim >= dedup_threshold and texts_are_near_identical(text, existing.name):
                            dedup_telemetry["fallback_reject_hits"] += 1
                            log_dedup_decision(graph, text, existing.id, existing.name,
                                               sim, "fallback_reject",
                                               owner_id=owner_id, source=source, conn=_conn)
                            # Confirmation boosting: re-extraction confirms this fact
                            existing.confirmation_count += 1
                            existing.last_confirmed_at = _now_iso()
                            existing.confidence = min(existing.confidence + 0.02, 0.95)
                            # Bjork: re-encoding strengthens storage (smaller than retrieval increment)
                            existing.storage_strength = min(10.0, existing.storage_strength + 0.03)
                            _apply_metadata_flags(existing, allow_structural_anchor_upgrade=True)
                            if update_if_dup and verified and not existing.verified:
                                existing.verified = True
                                existing.confidence = 0.9
                            graph.update_node(existing, conn=_conn)
                            if update_if_dup and verified:
                                return _with_dedup_telemetry({
                                    "id": existing.id,
                                    "status": "updated",
                                    "similarity": round(sim, 3),
                                    "existing_text": existing.name,
                                    "confirmation_count": existing.confirmation_count,
                                })
                            return _with_dedup_telemetry({
                                "id": existing.id,
                                "status": "duplicate",
                                "similarity": round(sim, 3),
                                "existing_text": existing.name,
                                "confirmation_count": existing.confirmation_count,
                            })

                # Zone 3: sim < gray_zone_low — store normally (continue checking)

        if gray_zone_candidates and llm_verify_enabled:
            # Keep gray-zone dedup batches small enough that Haiku can return
            # stable JSON quickly; larger batches were truncating under load.
            batch_size = 4
            for offset in range(0, len(gray_zone_candidates), batch_size):
                batch = gray_zone_candidates[offset:offset + batch_size]
                dedup_telemetry["llm_checks"] += len(batch)
                llm_results = _llm_dedup_check_many(text, [existing.name for existing, _sim in batch])
                for idx, (existing, sim) in enumerate(batch, start=1):
                    llm_result = llm_results.get(idx) if llm_results else None
                    if llm_result is not None:
                        subsumes = llm_result.get("subsumes")
                        is_same = bool(llm_result.get("is_same"))

                        # Guard against over-eager duplicate rejections: if the LLM
                        # says "same" but omits subsumption direction, infer it when
                        # token-overlap clearly indicates subset/superset; otherwise
                        # treat as distinct unless strings are near-identical.
                        if is_same and subsumes is None:
                            if is_subset_overlap_candidate(text, existing.name):
                                text_tokens = _lib_extract_key_tokens(text)
                                existing_tokens = _lib_extract_key_tokens(existing.name)
                                if len(text_tokens) >= len(existing_tokens):
                                    subsumes = "a_subsumes_b"
                                else:
                                    subsumes = "b_subsumes_a"
                            elif not texts_are_near_identical(text, existing.name):
                                dedup_telemetry["llm_different_hits"] += 1
                                dedup_telemetry["llm_accept_hits"] += 1
                                log_dedup_decision(
                                    graph,
                                    text,
                                    existing.id,
                                    existing.name,
                                    sim,
                                    "llm_accept_guard",
                                    llm_reasoning=llm_result.get("reasoning"),
                                    owner_id=owner_id,
                                    source=source,
                                    conn=_conn,
                                )
                                continue

                        if is_same or subsumes is not None:
                            dedup_telemetry["llm_same_hits"] += 1
                            decision = "llm_reject"
                            if subsumes == "a_subsumes_b":
                                decision = "llm_subsume_update"
                                dedup_telemetry["llm_subsume_update_hits"] += 1
                            elif subsumes == "b_subsumes_a":
                                decision = "llm_subsume_keep"
                                dedup_telemetry["llm_subsume_keep_hits"] += 1
                            log_dedup_decision(graph, text, existing.id, existing.name,
                                               sim, decision,
                                               llm_reasoning=llm_result.get("reasoning"),
                                               owner_id=owner_id, source=source, conn=_conn)
                            existing.confirmation_count += 1
                            existing.last_confirmed_at = _now_iso()
                            existing.confidence = min(existing.confidence + 0.02, 0.95)
                            existing.storage_strength = min(10.0, existing.storage_strength + 0.03)
                            _apply_metadata_flags(existing)
                            if update_if_dup and verified and not existing.verified:
                                existing.verified = True
                                existing.confidence = 0.9
                            if subsumes == "a_subsumes_b":
                                existing.name = text
                                existing.embedding = None
                                existing.content_hash = None
                                attrs = existing.attributes if isinstance(existing.attributes, dict) else (existing.attributes or {})
                                if structural_anchor_kind and not attrs.get("structural_anchor_kind"):
                                    attrs["structural_anchor_kind"] = structural_anchor_kind
                                    existing.attributes = attrs
                                if _lib_has_vec():
                                    conn_cm = nullcontext(_conn) if _conn is not None else graph._get_conn()
                                    with conn_cm as conn:
                                        try:
                                            conn.execute("DELETE FROM vec_nodes WHERE node_id = ?", (existing.id,))
                                        except sqlite3.OperationalError as exc:
                                            if "no such table: vec_nodes" not in str(exc).lower():
                                                logger.warning(
                                                    "subsume update failed vec_nodes cleanup for %s: %s",
                                                    existing.id,
                                                    exc,
                                                )
                                                if _is_fail_hard_mode():
                                                    raise RuntimeError(
                                                        "Vector index cleanup failed during subsume update while fail-hard mode is enabled"
                                                    ) from exc
                                        except Exception as exc:
                                            logger.warning(
                                                "subsume update failed vec_nodes cleanup for %s: %s",
                                                existing.id,
                                                exc,
                                            )
                                            if _is_fail_hard_mode():
                                                raise RuntimeError(
                                                    "Vector index cleanup failed during subsume update while fail-hard mode is enabled"
                                                ) from exc
                            graph.update_node(existing, conn=_conn)
                            if (update_if_dup and verified) or subsumes == "a_subsumes_b":
                                return _with_dedup_telemetry({
                                    "id": existing.id,
                                    "status": "updated",
                                    "similarity": round(sim, 3),
                                    "existing_text": existing.name,
                                    "confirmation_count": existing.confirmation_count,
                                })
                            return _with_dedup_telemetry({
                                "id": existing.id,
                                "status": "duplicate",
                                "similarity": round(sim, 3),
                                "existing_text": existing.name,
                                "confirmation_count": existing.confirmation_count,
                            })
                        dedup_telemetry["llm_different_hits"] += 1
                        dedup_telemetry["llm_accept_hits"] += 1
                        log_dedup_decision(graph, text, existing.id, existing.name,
                                           sim, "llm_accept",
                                           llm_reasoning=llm_result.get("reasoning"),
                                           owner_id=owner_id, source=source, conn=_conn)
                        continue
                    if sim >= dedup_threshold and texts_are_near_identical(text, existing.name):
                        dedup_telemetry["fallback_reject_hits"] += 1
                        log_dedup_decision(graph, text, existing.id, existing.name,
                                           sim, "fallback_reject",
                                           owner_id=owner_id, source=source, conn=_conn)
                        existing.confirmation_count += 1
                        existing.last_confirmed_at = _now_iso()
                        existing.confidence = min(existing.confidence + 0.02, 0.95)
                        existing.storage_strength = min(10.0, existing.storage_strength + 0.03)
                        _apply_metadata_flags(existing, allow_structural_anchor_upgrade=True)
                        if update_if_dup and verified and not existing.verified:
                            existing.verified = True
                            existing.confidence = 0.9
                        graph.update_node(existing, conn=_conn)
                        if update_if_dup and verified:
                            return _with_dedup_telemetry({
                                "id": existing.id,
                                "status": "updated",
                                "similarity": round(sim, 3),
                                "existing_text": existing.name,
                                "confirmation_count": existing.confirmation_count,
                            })
                        return _with_dedup_telemetry({
                            "id": existing.id,
                            "status": "duplicate",
                            "similarity": round(sim, 3),
                            "existing_text": existing.name,
                            "confirmation_count": existing.confirmation_count,
                        })
    
    if _dedup_only:
        return _with_dedup_telemetry({"id": None, "status": "not_found"})

    # Confidence adjustment for assistant-inferred facts
    adjusted_confidence = confidence
    if source_type == "assistant":
        adjusted_confidence = round(confidence * 0.9, 3)
    elif source_type == "subagent":
        adjusted_confidence = round(confidence * 0.85, 3)

    # No duplicate found, create new node
    node = Node.create(
        type=node_type,
        name=text,
        verified=verified,
        pinned=pinned,
        privacy=privacy,
        source=source,
        source_id=source_id,
        confidence=adjusted_confidence,
        fact_type=fact_type,
        knowledge_type=knowledge_type,
        extraction_confidence=extraction_confidence,
        speaker=speaker
    )
    node.owner_id = owner_id
    node.session_id = session_id
    node.keywords = keywords
    node.occurred_start = occurred_start
    node.occurred_end = occurred_end
    node.mentioned_at = mentioned_at
    if created_at:
        node.created_at = created_at
    if accessed_at:
        node.accessed_at = accessed_at

    node.speaker_entity_id = speaker_entity_id or actor_id
    node.conversation_id = conversation_id or source_conversation_id
    node.visibility_scope = visibility_scope or ("private_subject" if owner_id else "source_shared")
    node.sensitivity = sensitivity or "normal"
    node.provenance_confidence = float(
        provenance_confidence if provenance_confidence is not None else extraction_confidence
    )
    if not subject_entity_id and subject_entity_name:
        subject_anchor = _resolve_fact_subject_anchor(
            graph,
            text,
            subject_entity_name=subject_entity_name,
        )
        if subject_anchor and getattr(subject_anchor, "id", None):
            subject_entity_id = str(subject_anchor.id)

    # Store metadata flags in attributes blob
    if (
        source_type
        or target_datastore
        or domains
        or project
        or source_channel
        or source_conversation_id
        or source_author_id
        or speaker_entity_id
        or conversation_id
        or participant_entity_ids
        or visibility_scope
        or sensitivity
        or provenance_confidence is not None
        or actor_id
        or subject_entity_id
        or subject_entity_name
        or structural_anchor_kind
        or source_chunk_id
    ):
        attrs = json.loads(node.attributes) if isinstance(node.attributes, str) else (node.attributes or {})
        if source_type:
            attrs["source_type"] = source_type
        if target_datastore:
            attrs["target_datastore"] = target_datastore
        if domains:
            attrs["domains"] = domains
        if project:
            attrs["project"] = project
        if source_channel:
            attrs["source_channel"] = source_channel
        if source_conversation_id:
            attrs["source_conversation_id"] = source_conversation_id
        if source_author_id:
            attrs["source_author_id"] = source_author_id
        if speaker_entity_id:
            attrs["speaker_entity_id"] = speaker_entity_id
        if conversation_id:
            attrs["conversation_id"] = conversation_id
        if participant_entity_ids:
            attrs["participant_entity_ids"] = list(participant_entity_ids)
        if visibility_scope:
            attrs["visibility_scope"] = visibility_scope
        if sensitivity:
            attrs["sensitivity"] = sensitivity
        if provenance_confidence is not None:
            attrs["provenance_confidence"] = float(provenance_confidence)
        if actor_id:
            attrs["actor_id"] = actor_id
        if subject_entity_id:
            attrs["subject_entity_id"] = subject_entity_id
        if subject_entity_name:
            attrs["subject_entity_name"] = subject_entity_name
        if structural_anchor_kind:
            attrs["structural_anchor_kind"] = structural_anchor_kind
        if source_chunk_id:
            attrs["source_chunk_id"] = source_chunk_id
        node.attributes = attrs

    injection_match = None
    if not status:
        injection_match = _check_injection_blocklist(text)
        if injection_match:
            node.status = "flagged"
            attrs = json.loads(node.attributes) if isinstance(node.attributes, str) else (node.attributes or {})
            attrs["flagged_pattern"] = injection_match
            node.attributes = attrs
        else:
            node.status = "pending"
    else:
        node.status = status
    node.embedding = embedding  # Reuse the embedding we already computed
    node.content_hash = text_hash  # Reuse the hash we already computed
    node.source_chunk_id = source_chunk_id
    try:
        node_id = graph.add_node(node, embed=False, conn=_conn)  # Don't re-embed
    except (ValueError, RuntimeError) as exc:
        raise ValueError(f"Failed to store memory due to domain validation: {exc}") from exc
    conn_cm = nullcontext(_conn) if _conn is not None else graph._get_conn()
    with conn_cm as conn:
        _ensure_fact_subject_edge(
            graph,
            fact_node=node,
            conn=conn,
            subject_entity_id=subject_entity_id,
            subject_entity_name=subject_entity_name,
        )

    result = {"id": node_id, "status": "created"}
    if node.status == "flagged":
        result["flagged"] = True
        result["flagged_pattern"] = injection_match
    return _with_dedup_telemetry(result)


def create_edge(
    subject_name: str,
    relation: str,
    object_name: str,
    source_fact_id: Optional[str] = None,
    create_missing_entities: bool = True,
    owner_id: Optional[str] = None,
    _conn: Optional[sqlite3.Connection] = None,
) -> Dict[str, Any]:
    """Create an edge between two named entities.

    Args:
        subject_name: Name of the source entity (e.g., "Carol Smith")
        relation: Relationship type (e.g., "parent_of")
        object_name: Name of the target entity (e.g., "Alice Smith")
        source_fact_id: Optional ID of the fact that created this edge
        create_missing_entities: If True, create Person nodes for missing entities
        owner_id: Owner ID for newly created entity nodes

    Returns:
        Dict with edge_id, status, and any created entity IDs
    """
    graph = get_graph()
    telemetry_enabled = str(
        os.environ.get("BENCHMARK_EDGE_TELEMETRY") or ""
    ).strip().lower() in {"1", "true", "yes", "on"}
    edge_t0 = time.perf_counter() if telemetry_enabled else 0.0
    phase_ms: Dict[str, float] = {}

    def _mark_phase(name: str, start_t: float) -> None:
        if telemetry_enabled:
            phase_ms[name] = round((time.perf_counter() - start_t) * 1000.0, 2)
    relation = (relation or "").strip().lower().replace(" ", "_")
    if not relation:
        return {"status": "error", "message": "Relation is required"}

    # Canonicalize common aliases so edge types stay queryable and deduplicated.
    relation_aliases = {
        "family_member": "family_of",
        "family_member_of": "family_of",
        "relative_of": "family_of",
        "partner_with": "partner_of",
        "partnered_with": "partner_of",
        "married_to": "spouse_of",
        "engaged_to": "partner_of",
    }
    relation = relation_aliases.get(relation, relation)

    owner_full = ""
    try:
        owner_node = resolve_owner_person(str(owner_id or "").strip()) if owner_id else None
        owner_full = str(getattr(owner_node, "name", "") or "").strip()
    except Exception:
        owner_full = ""
    subject_name = _canonicalize_owner_alias(subject_name, owner_full)
    object_name = _canonicalize_owner_alias(object_name, owner_full)
    if _is_placeholder_entity_name(subject_name, owner_full) or _is_placeholder_entity_name(object_name, owner_full):
        return {
            "status": "error",
            "message": "Placeholder entity label cannot be used for edge creation",
        }
    if _is_sentence_like_entity_name(subject_name) or _is_sentence_like_entity_name(object_name):
        return {
            "status": "error",
            "message": "Entity label looks like a full sentence; use the minimal entity name",
        }

    # Keep symmetric relations deterministic to avoid A->B and B->A duplicates.
    symmetric_relations = {
        "spouse_of",
        "partner_of",
        "sibling_of",
        "family_of",
        "friend_of",
        "neighbor_of",
        "colleague_of",
        "related_to",
        "knows",
    }
    if relation in symmetric_relations and subject_name.strip().lower() > object_name.strip().lower():
        subject_name, object_name = object_name, subject_name

    def _find_entity(conn: sqlite3.Connection, name: str) -> Optional[Node]:
        """Find entity by exact name, then fuzzy match using SQL patterns.

        Resolution order:
        1. Exact name match (any type)
        2. Case-insensitive exact match on Person/Place/Pet/Organization
        3. Prefix match: "Alice" → "Alice Smith" (shortest match wins)
        4. Suffix match: "Smith" → "Alice Smith" (shortest match wins)

        Note: SQL pattern matching used instead of embedding similarity because
        entity nodes (Person/Place/Pet) have short names where pattern matching
        is more reliable than vector similarity for name resolution.
        """
        row = conn.execute(
            "SELECT * FROM nodes WHERE name = ? LIMIT 1",
            (name,)
        ).fetchone()
        if row:
            return graph._row_to_node(row)
        # Case-insensitive exact match
        row = conn.execute(
            "SELECT * FROM nodes WHERE LOWER(name) = LOWER(?) AND type IN ('Person', 'Place', 'Pet', 'Organization') LIMIT 1",
            (name,)
        ).fetchone()
        if row:
            return graph._row_to_node(row)
        # Escape SQL LIKE wildcards in entity names to prevent unintended matches
        escaped = name.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        # Prefix match: "Alice" → "Alice Smith"
        row = conn.execute(
            "SELECT * FROM nodes WHERE name LIKE ? ESCAPE '\\' AND type IN ('Person', 'Place', 'Pet', 'Organization') ORDER BY LENGTH(name) LIMIT 1",
            (escaped + "%",)
        ).fetchone()
        if row:
            return graph._row_to_node(row)
        # Suffix match: "Smith" → "Alice Smith"
        row = conn.execute(
            "SELECT * FROM nodes WHERE name LIKE ? ESCAPE '\\' AND type IN ('Person', 'Place', 'Pet', 'Organization') ORDER BY LENGTH(name) LIMIT 1",
            ("%" + escaped,)
        ).fetchone()
        if row:
            return graph._row_to_node(row)
        return None

    def _insert_entity(conn: sqlite3.Connection, node: Node) -> None:
        # create_edge-created entities are structural graph anchors resolved by
        # exact name traversal; do not block edge writes on embedding latency.
        if not node.content_hash:
            node.content_hash = content_hash(node.name)
        now_iso = _now_iso()

        conn.execute("""
            INSERT OR REPLACE INTO nodes
            (id, type, name, attributes, embedding, verified, pinned, confidence,
             source, source_id, privacy, valid_from, valid_until,
             occurred_start, occurred_end, mentioned_at,
             created_at, updated_at, accessed_at, access_count, storage_strength, owner_id, session_id,
             fact_type, knowledge_type, extraction_confidence, status, speaker, speaker_entity_id,
             conversation_id, visibility_scope, sensitivity, provenance_confidence,
             content_hash, superseded_by, confirmation_count, last_confirmed_at, keywords)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            node.id, node.type, node.name,
            json.dumps(node.attributes),
            graph._pack_embedding(node.embedding) if node.embedding else None,
            1 if node.verified else 0,
            1 if node.pinned else 0,
            node.confidence,
            node.source, node.source_id,
            node.privacy,
            node.valid_from, node.valid_until,
            node.occurred_start, node.occurred_end, node.mentioned_at,
            node.created_at or now_iso,
            now_iso,
            node.accessed_at or now_iso,
            node.access_count,
            node.storage_strength,
            node.owner_id,
            node.session_id,
            node.fact_type,
            node.knowledge_type,
            node.extraction_confidence,
            node.status,
            node.speaker,
            node.speaker_entity_id,
            node.conversation_id,
            node.visibility_scope,
            node.sensitivity,
            node.provenance_confidence,
            node.content_hash,
            node.superseded_by,
            node.confirmation_count,
            node.last_confirmed_at,
            node.keywords,
        ))

    def _edge_exists(conn: sqlite3.Connection, source_id: str, target_id: str, rel: str) -> bool:
        row = conn.execute(
            "SELECT 1 FROM edges WHERE source_id = ? AND target_id = ? AND relation = ? LIMIT 1",
            (source_id, target_id, rel),
        ).fetchone()
        return row is not None

    def _insert_edge_row(
        conn: sqlite3.Connection,
        *,
        source_id: str,
        target_id: str,
        rel: str,
        src_fact_id: Optional[str],
    ) -> str:
        existing = conn.execute(
            "SELECT id FROM edges WHERE source_id = ? AND target_id = ? AND relation = ? LIMIT 1",
            (source_id, target_id, rel),
        ).fetchone()
        if existing:
            return str(existing["id"] or existing[0] or "")
        edge = Edge.create(
            source_id=source_id,
            target_id=target_id,
            relation=rel,
            source_fact_id=src_fact_id,
        )
        conn.execute(
            """
            INSERT INTO edges
            (id, source_id, target_id, relation, attributes, weight,
             valid_from, valid_until, created_at, source_fact_id)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                edge.id, edge.source_id, edge.target_id, edge.relation,
                json.dumps(edge.attributes),
                edge.weight,
                edge.valid_from, edge.valid_until,
                edge.created_at or _now_iso(),
                edge.source_fact_id,
            ),
        )
        return edge.id

    def _collect_partner_ids(conn: sqlite3.Connection, person_id: str) -> List[str]:
        rows = conn.execute(
            """
            SELECT
                CASE
                    WHEN source_id = ? THEN target_id
                    ELSE source_id
                END AS partner_id
            FROM edges
            WHERE relation IN ('spouse_of', 'partner_of')
              AND (source_id = ? OR target_id = ?)
            """,
            (person_id, person_id, person_id),
        ).fetchall()
        partner_ids: List[str] = []
        for row in rows:
            partner_id = str(row["partner_id"] or "").strip()
            if partner_id and partner_id not in partner_ids and partner_id != person_id:
                partner_ids.append(partner_id)
        return partner_ids

    def _collect_children_ids(conn: sqlite3.Connection, parent_id: str) -> List[str]:
        rows = conn.execute(
            "SELECT target_id FROM edges WHERE relation = 'parent_of' AND source_id = ?",
            (parent_id,),
        ).fetchall()
        child_ids: List[str] = []
        for row in rows:
            child_id = str(row["target_id"] or "").strip()
            if child_id and child_id not in child_ids and child_id != parent_id:
                child_ids.append(child_id)
        return child_ids

    conn_ctx = nullcontext(_conn) if _conn is not None else graph._get_conn()
    with conn_ctx as conn:
        # Find or create subject entity
        p0 = time.perf_counter() if telemetry_enabled else 0.0
        subject = _find_entity(conn, subject_name)
        _mark_phase("find_subject", p0)
        subject_created = False
        if not subject and create_missing_entities:
            p0 = time.perf_counter() if telemetry_enabled else 0.0
            inferred_type = _infer_edge_entity_type(subject_name, relation, is_subject=True)
            subject = Node.create(type=inferred_type, name=subject_name)
            subject.owner_id = owner_id
            subject.status = "active"  # Entity nodes are structural, not claims needing review
            _insert_entity(conn, subject)
            subject_created = True
            _mark_phase("create_subject", p0)
        elif not subject:
            return {"status": "error", "message": f"Subject entity '{subject_name}' not found"}

        # Find or create object entity
        p0 = time.perf_counter() if telemetry_enabled else 0.0
        obj = _find_entity(conn, object_name)
        _mark_phase("find_object", p0)
        object_created = False
        if not obj and create_missing_entities:
            p0 = time.perf_counter() if telemetry_enabled else 0.0
            inferred_type = _infer_edge_entity_type(object_name, relation, is_subject=False)
            obj = Node.create(type=inferred_type, name=object_name)
            obj.owner_id = owner_id
            obj.status = "active"  # Entity nodes are structural, not claims needing review
            _insert_entity(conn, obj)
            object_created = True
            _mark_phase("create_object", p0)
        elif not obj:
            return {"status": "error", "message": f"Object entity '{object_name}' not found"}

        # Create edge in same transaction as any new entities.
        p0 = time.perf_counter() if telemetry_enabled else 0.0
        edge_id = _insert_edge_row(
            conn,
            source_id=subject.id,
            target_id=obj.id,
            rel=relation,
            src_fact_id=source_fact_id,
        )
        _mark_phase("insert_edge", p0)

        inferred_edges_created = 0

        def _ensure_parent_edge(parent_id: str, child_id: str) -> None:
            nonlocal inferred_edges_created
            if not parent_id or not child_id or parent_id == child_id:
                return
            if _edge_exists(conn, parent_id, child_id, "parent_of"):
                return
            _insert_edge_row(
                conn,
                source_id=parent_id,
                target_id=child_id,
                rel="parent_of",
                src_fact_id=source_fact_id,
            )
            inferred_edges_created += 1

        p0 = time.perf_counter() if telemetry_enabled else 0.0
        if relation == "parent_of":
            for partner_id in _collect_partner_ids(conn, subject.id):
                _ensure_parent_edge(partner_id, obj.id)
        elif relation in {"spouse_of", "partner_of"}:
            for child_id in _collect_children_ids(conn, subject.id):
                _ensure_parent_edge(obj.id, child_id)
            for child_id in _collect_children_ids(conn, obj.id):
                _ensure_parent_edge(subject.id, child_id)
        _mark_phase("infer_coparent_edges", p0)

        result = {
            "edge_id": edge_id,
            "status": "created",
            "subject_id": subject.id,
            "object_id": obj.id,
            "subject_created": subject_created,
            "object_created": object_created,
        }
        if inferred_edges_created:
            result["inferred_edges_created"] = inferred_edges_created
        if telemetry_enabled:
            total_ms = round((time.perf_counter() - edge_t0) * 1000.0, 2)
            result["timing_ms"] = {"total": total_ms, **phase_ms}
            try:
                print(
                    f"[edge_telemetry] relation={relation} "
                    f"subject_created={subject_created} object_created={object_created} "
                    f"timing_ms={json.dumps(result['timing_ms'], sort_keys=True)}",
                    file=sys.stderr,
                )
            except Exception:
                pass
        return result


def delete_edges_by_source_fact(source_fact_id: str) -> int:
    """Delete all edges that were created from a specific fact.

    Args:
        source_fact_id: The ID of the source fact

    Returns:
        Number of edges deleted
    """
    graph = get_graph()
    with graph._get_conn() as conn:
        result = conn.execute(
            "DELETE FROM edges WHERE source_fact_id = ?",
            (source_fact_id,)
        )
        return result.rowcount


def forget(query: Optional[str] = None, node_id: Optional[str] = None) -> bool:
    """Delete a memory by query or ID."""
    graph = get_graph()

    if node_id:
        return graph.delete_node(node_id)

    if query:
        results = graph.search_hybrid(query, limit=1)
        if results:
            node, _ = results[0]
            return graph.delete_node(node.id)

    return False


def get_memory(node_id: str) -> Optional[Dict[str, Any]]:
    """Get a single memory by ID."""
    graph = get_graph()
    node = graph.get_node(node_id)
    if node:
        return {
            "id": node.id,
            "type": node.type,
            "name": node.name,
            "content": node.name,
            "verified": node.verified,
            "pinned": node.pinned,
            "confidence": node.confidence,
            "owner_id": node.owner_id,
            "source_chunk_id": node.source_chunk_id,
            "created_at": node.created_at,
            "updated_at": node.updated_at,
            "attributes": node.attributes
        }
    return None


def hard_delete_node(node_id: str, conn: Optional[sqlite3.Connection] = None) -> bool:
    """Hard delete a node and all related references from the database.

    Cleans up edges, contradictions, and decay_review_queue entries.
    dedup_log references are kept (audit trail).
    """
    graph = get_graph()

    def _delete_with_conn(active_conn: sqlite3.Connection) -> bool:
        active_conn.execute("DELETE FROM edges WHERE source_id = ? OR target_id = ?", (node_id, node_id))
        active_conn.execute("DELETE FROM contradictions WHERE node_a_id = ? OR node_b_id = ?", (node_id, node_id))
        active_conn.execute("DELETE FROM decay_review_queue WHERE node_id = ?", (node_id,))
        # Explicit cleanup for callers supplying connections with foreign_keys=OFF.
        active_conn.execute("DELETE FROM node_domains WHERE node_id = ?", (node_id,))
        active_conn.execute("UPDATE nodes SET superseded_by = NULL WHERE superseded_by = ?", (node_id,))
        # Clean up vec_nodes index (virtual table, no CASCADE)
        try:
            active_conn.execute("DELETE FROM vec_nodes WHERE node_id = ?", (node_id,))
        except sqlite3.OperationalError as exc:
            if "no such table: vec_nodes" not in str(exc).lower():
                logger.warning(
                    "hard_delete_node failed vec_nodes cleanup for %s: %s",
                    node_id,
                    exc,
                )
                if _is_fail_hard_mode():
                    raise RuntimeError(
                        "Vector index cleanup failed during hard delete while failHard is enabled"
                    ) from exc
        except Exception as exc:
            logger.warning(
                "hard_delete_node failed vec_nodes cleanup for %s: %s",
                node_id,
                exc,
            )
            if _is_fail_hard_mode():
                raise RuntimeError(
                    "Vector index cleanup failed during hard delete while failHard is enabled"
                ) from exc
        # dedup_log.existing_node_id uses ON DELETE SET NULL — audit trail preserved automatically
        result = active_conn.execute("DELETE FROM nodes WHERE id = ?", (node_id,))
        return result.rowcount > 0

    if conn is not None:
        return _delete_with_conn(conn)

    with graph._get_conn() as managed_conn:
        return _delete_with_conn(managed_conn)


def soft_delete(node_id: str, reason: str = "manual") -> bool:
    """Delete a memory and related references from the database."""
    return hard_delete_node(node_id)


def store_contradiction(node_a_id: str, node_b_id: str, explanation: str) -> Optional[str]:
    """Store a detected contradiction between two memory nodes."""
    graph = get_graph()
    contradiction_id = str(uuid.uuid4())
    # Normalize order so UNIQUE constraint works regardless of discovery direction
    a_id, b_id = sorted([node_a_id, node_b_id])
    try:
        with graph._get_conn() as conn:
            cursor = conn.execute("""
                INSERT OR IGNORE INTO contradictions (id, node_a_id, node_b_id, explanation, detected_at)
                VALUES (?, ?, ?, ?, ?)
            """, (contradiction_id, a_id, b_id, explanation, _now_iso()))
            if cursor.rowcount > 0:
                return contradiction_id
            existing = conn.execute(
                "SELECT id FROM contradictions WHERE node_a_id = ? AND node_b_id = ?",
                (a_id, b_id),
            ).fetchone()
            if existing:
                return str(existing["id"])
            return None
    except Exception as exc:
        try:
            from lib.fail_policy import is_fail_hard_enabled
            if is_fail_hard_enabled():
                raise RuntimeError(
                    f"Failed to store contradiction for {a_id} vs {b_id}"
                ) from exc
        except RuntimeError:
            raise
        except Exception:
            pass
        logger.warning(
            "store_contradiction failed for node_a=%s node_b=%s: %s",
            a_id,
            b_id,
            exc,
        )
        return None


def get_pending_contradictions(limit: int = 50) -> List[Dict[str, Any]]:
    """Get pending contradictions with full node context."""
    graph = get_graph()
    with graph._get_conn() as conn:
        rows = conn.execute("""
            SELECT c.id, c.node_a_id, c.node_b_id, c.explanation, c.detected_at,
                   a.name AS text_a, a.confidence AS conf_a, a.created_at AS created_a,
                   a.source AS source_a, a.speaker AS speaker_a, a.access_count AS access_a,
                   b.name AS text_b, b.confidence AS conf_b, b.created_at AS created_b,
                   b.source AS source_b, b.speaker AS speaker_b, b.access_count AS access_b
            FROM contradictions c
            JOIN nodes a ON c.node_a_id = a.id
            JOIN nodes b ON c.node_b_id = b.id
            WHERE c.status = 'pending'
              AND a.superseded_by IS NULL
              AND b.superseded_by IS NULL
            ORDER BY c.detected_at ASC
            LIMIT ?
        """, (limit,)).fetchall()
    return [dict(row) for row in rows]


def resolve_contradiction(contradiction_id: str, resolution: str, reason: str) -> bool:
    """Mark a contradiction as resolved."""
    graph = get_graph()
    now_iso = _now_iso()
    with graph._get_conn() as conn:
        result = conn.execute("""
            UPDATE contradictions
            SET status = 'resolved', resolution = ?, resolution_reason = ?,
                resolved_at = ?
            WHERE id = ?
        """, (resolution, reason, now_iso, contradiction_id))
        return result.rowcount > 0


def mark_contradiction_false_positive(contradiction_id: str, reason: str) -> bool:
    """Mark a contradiction as a false positive."""
    graph = get_graph()
    now_iso = _now_iso()
    with graph._get_conn() as conn:
        result = conn.execute("""
            UPDATE contradictions
            SET status = 'false_positive', resolution = 'keep_both',
                resolution_reason = ?, resolved_at = ?
            WHERE id = ?
        """, (reason, now_iso, contradiction_id))
        return result.rowcount > 0


# ==========================================================================
# Dedup Logging & LLM Verification
# ==========================================================================

def log_dedup_decision(
    graph: MemoryGraph,
    new_text: str,
    existing_node_id: str,
    existing_text: str,
    similarity: float,
    decision: str,
    llm_reasoning: Optional[str] = None,
    owner_id: Optional[str] = None,
    source: Optional[str] = None,
    conn: Optional[sqlite3.Connection] = None,
) -> str:
    """Log a dedup decision to dedup_log table. Returns log entry ID."""
    log_id = str(uuid.uuid4())

    def _insert(active_conn: sqlite3.Connection, existing_id: Optional[str]) -> None:
        active_conn.execute("""
            INSERT INTO dedup_log
            (id, new_text, existing_node_id, existing_text, similarity,
             decision, llm_reasoning, owner_id, source, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (log_id, new_text, existing_id, existing_text,
              similarity, decision, llm_reasoning, owner_id, source, _now_iso()))

    conn_cm = nullcontext(conn) if conn is not None else graph._get_conn()
    with conn_cm as active_conn:
        try:
            _insert(active_conn, existing_node_id)
        except sqlite3.IntegrityError:
            # FK constraint can fail if the candidate node was hard-deleted between
            # the FTS search and this insert (WAL snapshot mismatch). Fall back to
            # NULL existing_node_id — the audit trail is preserved without the link.
            print(f"[dedup_log] WARNING: FK constraint for node {existing_node_id}, inserting with NULL reference", file=sys.stderr)
            _insert(active_conn, None)
    return log_id


def _llm_dedup_check(new_text: str, existing_text: str) -> Optional[Dict[str, Any]]:
    """Ask the fast-reasoning LLM whether two texts represent the same fact.

    Returns {"is_same": bool, "reasoning": str} or None on failure.
    """
    results = _llm_dedup_check_many(new_text, [existing_text])
    if not results:
        return None
    return results.get(1)


def _llm_dedup_check_many(new_text: str, existing_texts: List[str]) -> Optional[Dict[int, Dict[str, Any]]]:
    """Ask the fast-reasoning LLM whether multiple texts duplicate one new fact.

    Returns {pair_index: {"is_same": bool, "subsumes": str|None, "reasoning": str}}
    using 1-based pair indexes, or None on failure.
    """
    if not _HAS_LLM_CLIENTS:
        return None
    candidates = [str(text or "").strip() for text in (existing_texts or []) if str(text or "").strip()]
    if not candidates:
        return None
    if len(candidates) == 1:
        prompt = (
            "Are these two statements the same fact (just reworded), or does one "
            "SUBSUME the other (contains all the same info plus additional detail)?\n\n"
            "IMPORTANT RULES:\n"
            "- Negation flips meaning: 'likes coffee' vs 'doesn't like coffee' are DIFFERENT.\n"
            "- If Statement A includes ALL info from Statement B plus more detail, "
            "A subsumes B. Example: 'The user has a dog named Scout' subsumes 'The user has a dog'.\n"
            "- If they convey the same info in different words, they are the SAME.\n"
            "- Only mark as different if they contain genuinely distinct information.\n\n"
            f'Statement A (new): "{new_text}"\n'
            f'Statement B (existing): "{candidates[0]}"\n\n'
            'Respond with JSON only: {"is_same": true/false, "subsumes": "a_subsumes_b" | "b_subsumes_a" | null, "reasoning": "brief reason"}'
        )

        try:
            response, _duration = call_fast_reasoning(prompt, max_tokens=1500, timeout=120.0)
        except Exception as _llm_exc:
            logger.warning("_llm_dedup_check_many LLM error (single pair), skipping dedup: %s", _llm_exc)
            return None
        if not response:
            return None
        parsed = parse_json_response(response)
        if isinstance(parsed, dict) and "is_same" in parsed:
            subsumes = parsed.get("subsumes")
            if subsumes not in ("a_subsumes_b", "b_subsumes_a"):
                subsumes = None
            return {
                1: {
                    "is_same": bool(parsed["is_same"]) or subsumes is not None,
                    "subsumes": subsumes,
                    "reasoning": str(parsed.get("reasoning", "")),
                }
            }
        return None

    pair_lines = "\n".join(
        f'{idx}. "{existing}"'
        for idx, existing in enumerate(candidates, start=1)
    )
    prompt = (
        "Compare Statement A against each candidate statement below.\n\n"
        "IMPORTANT RULES:\n"
        "- Negation flips meaning: 'likes coffee' vs 'doesn't like coffee' are DIFFERENT.\n"
        "- If Statement A includes ALL info from Statement B plus more detail, "
        "A subsumes B. Example: 'The user has a dog named Scout' subsumes 'The user has a dog'.\n"
        "- If they convey the same info in different words, they are the SAME.\n"
        "- Only mark as different if they contain genuinely distinct information.\n\n"
        f'Statement A (new): "{new_text}"\n\n'
        f"Candidates:\n{pair_lines}\n\n"
        "Respond with JSON only as an array of objects:\n"
        '[{"pair": 1, "is_same": true/false, "subsumes": "a_subsumes_b" | "b_subsumes_a" | null, "reasoning": "brief reason"}]'
    )

    max_tokens = min(2000, max(1500, 120 * len(candidates)))
    try:
        response, _duration = call_fast_reasoning(prompt, max_tokens=max_tokens, timeout=120.0)
    except Exception as _llm_exc:
        logger.warning("_llm_dedup_check_many LLM error (multi pair), skipping dedup: %s", _llm_exc)
        return None
    if not response:
        return None

    parsed = parse_json_response(response)
    if not isinstance(parsed, list):
        return None
    results: Dict[int, Dict[str, Any]] = {}
    for item in parsed:
        if not isinstance(item, dict):
            continue
        try:
            pair_idx = int(item.get("pair", 0))
        except Exception:
            continue
        if pair_idx < 1 or pair_idx > len(candidates):
            continue
        subsumes = item.get("subsumes")
        if subsumes not in ("a_subsumes_b", "b_subsumes_a"):
            subsumes = None
        is_same_raw = item.get("is_same")
        if not isinstance(is_same_raw, bool):
            if isinstance(is_same_raw, str):
                is_same = is_same_raw.lower() in ("true", "yes", "1")
            else:
                is_same = bool(is_same_raw)
        else:
            is_same = is_same_raw
        results[pair_idx] = {
            "is_same": bool(is_same) or subsumes is not None,
            "subsumes": subsumes,
            "reasoning": str(item.get("reasoning", "")),
        }
    return results or None




def _resolve_node_identifier(graph: "MemoryGraph", identifier: str) -> Optional[Node]:
    value = str(identifier or "").strip()
    if not value:
        return None
    node = graph.get_node(value)
    if node:
        return node
    with graph._get_conn() as conn:
        row = conn.execute(
            "SELECT * FROM nodes WHERE LOWER(name) = LOWER(?) ORDER BY CASE WHEN status = 'active' THEN 0 ELSE 1 END, LENGTH(name) ASC LIMIT 1",
            (value,),
        ).fetchone()
        if row:
            return graph._row_to_node(row)
        alias_row = conn.execute(
            "SELECT canonical_node_id, canonical_name FROM entity_aliases WHERE LOWER(alias) = LOWER(?) ORDER BY CASE WHEN canonical_node_id IS NULL OR canonical_node_id = '' THEN 1 ELSE 0 END LIMIT 1",
            (value,),
        ).fetchone()
        if alias_row:
            canonical_node_id = str(alias_row["canonical_node_id"] or "").strip()
            if canonical_node_id:
                row = conn.execute("SELECT * FROM nodes WHERE id = ? LIMIT 1", (canonical_node_id,)).fetchone()
                if row:
                    return graph._row_to_node(row)
            canonical_name = str(alias_row["canonical_name"] or "").strip()
            if canonical_name:
                row = conn.execute(
                    "SELECT * FROM nodes WHERE LOWER(name) = LOWER(?) ORDER BY CASE WHEN status = 'active' THEN 0 ELSE 1 END, LENGTH(name) ASC LIMIT 1",
                    (canonical_name,),
                ).fetchone()
                if row:
                    return graph._row_to_node(row)
    return None

def get_recent_dedup_rejections(hours: int = 24, limit: int = 50) -> List[Dict[str, Any]]:
    """Get recent dedup rejections for nightly review."""
    graph = get_graph()
    cutoff = (_now() - timedelta(hours=hours)).isoformat()
    with graph._get_conn() as conn:
        rows = conn.execute("""
            SELECT * FROM dedup_log
            WHERE review_status = 'unreviewed'
              AND created_at > ?
              AND decision != 'hash_exact'
            ORDER BY created_at DESC
            LIMIT ?
        """, (cutoff, limit)).fetchall()
    return [dict(row) for row in rows]


def resolve_dedup_review(log_id: str, status: str, resolution: Optional[str] = None) -> bool:
    """Mark a dedup log entry as reviewed. status: 'confirmed' or 'reversed'."""
    graph = get_graph()
    now_iso = _now_iso()
    with graph._get_conn() as conn:
        result = conn.execute("""
            UPDATE dedup_log
            SET review_status = ?, review_resolution = ?,
                reviewed_at = ?
            WHERE id = ?
        """, (status, resolution, now_iso, log_id))
        return result.rowcount > 0


# ==========================================================================
# Decay Review Queue
# ==========================================================================

def queue_for_decay_review(mem: Dict[str, Any]) -> str:
    """Queue a memory for decay review instead of silent deletion. Returns queue ID."""
    graph = get_graph()
    queue_id = str(uuid.uuid4())
    now_iso = _now_iso()
    with graph._get_conn() as conn:
        # queued_for_decay intentionally leaves normal recall/search status
        # filters until a reviewer EXTENDs/PINs the memory or deletes it.
        # Skip if this node is already queued (prevents duplicate entries on re-runs)
        existing = conn.execute(
            "SELECT id FROM decay_review_queue WHERE node_id = ? AND status = 'pending'",
            (mem["id"],)
        ).fetchone()
        if existing:
            conn.execute(
                """
                UPDATE nodes
                SET status = 'queued_for_decay', updated_at = ?
                WHERE id = ?
                  AND (status IS NULL OR status IN ('approved', 'active', 'queued_for_decay'))
                """,
                (now_iso, mem["id"]),
            )
            return existing["id"]
        conn.execute("""
            INSERT INTO decay_review_queue
            (id, node_id, node_text, node_type, confidence_at_queue,
             access_count, last_accessed, verified, created_at_node, queued_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            queue_id,
            mem["id"],
            mem["text"],
            mem.get("type"),
            mem["confidence"],
            mem.get("access_count", 0),
            mem.get("last_accessed"),
            1 if mem.get("verified") else 0,
            mem.get("created_at"),
            now_iso,
        ))
        conn.execute(
            """
            UPDATE nodes
            SET status = 'queued_for_decay', updated_at = ?
            WHERE id = ?
              AND (status IS NULL OR status IN ('approved', 'active', 'queued_for_decay'))
            """,
            (now_iso, mem["id"]),
        )
    return queue_id


def get_pending_decay_reviews(limit: int = 50) -> List[Dict[str, Any]]:
    """Get pending decay review queue items."""
    graph = get_graph()
    with graph._get_conn() as conn:
        rows = conn.execute("""
            SELECT q.*, n.speaker AS node_speaker, n.source AS node_source, n.attributes AS node_attributes
            FROM decay_review_queue q
            LEFT JOIN nodes n ON n.id = q.node_id
            WHERE q.status = 'pending'
            ORDER BY queued_at ASC
            LIMIT ?
        """, (limit,)).fetchall()
    return [dict(row) for row in rows]


def resolve_decay_review(
    queue_id: str, decision: str, reason: str, conn: Optional[sqlite3.Connection] = None
) -> bool:
    """Mark a decay review item as reviewed. decision: 'delete', 'extend', 'pin'."""
    graph = get_graph()

    def _resolve_with_conn(active_conn: sqlite3.Connection) -> bool:
        now_iso = _now_iso()
        result = active_conn.execute("""
            UPDATE decay_review_queue
            SET decision = ?, decision_reason = ?, status = 'reviewed',
                reviewed_at = ?
            WHERE id = ?
        """, (decision, reason, now_iso, queue_id))
        return result.rowcount > 0

    if conn is not None:
        return _resolve_with_conn(conn)

    with graph._get_conn() as managed_conn:
        return _resolve_with_conn(managed_conn)


def decay_memories() -> Dict[str, Any]:
    """Apply confidence decay to memories.

    Aligned with janitor semantics:
    - Subtractive decay (confidence - 0.10) instead of multiplicative
    - Only decays memories not accessed in 30+ days
    - Respects pinned flag
    """
    graph = get_graph()

    now = _now()
    now_iso = now.isoformat()
    cutoff = (now - timedelta(days=30)).isoformat()

    with graph._get_conn() as conn:
        result = conn.execute("""
            UPDATE nodes
            SET confidence = MAX(confidence - 0.10, 0.1),
                updated_at = ?
            WHERE pinned = 0
              AND verified = 0
              AND confidence > 0.1
              AND superseded_by IS NULL
              AND (status IS NULL OR status IN ('approved', 'active'))
              AND accessed_at < ?
        """, (now_iso, cutoff))

        return {"decayed_count": result.rowcount}


def get_entity_summary(node_id: str) -> Optional[str]:
    """Get the stored summary for an entity node, or None if not summarized."""
    graph = get_graph()
    node = graph.get_node(node_id)
    if not node:
        return None
    return node.attributes.get("summary")


def generate_entity_summary(node_id: str, use_llm: bool = True) -> Optional[str]:
    """Generate a summary paragraph for a Person/Place/Concept node from connected facts.

    Args:
        node_id: The entity node ID to summarize
        use_llm: If True, use LLM to generate natural summary. If False, concatenate facts.

    Returns:
        The generated summary text, or None if the node doesn't exist or has no facts.
    """
    graph = get_graph()
    node = graph.get_node(node_id)
    if not node:
        return None
    if node.type not in ("Person", "Place", "Concept"):
        return None

    # Gather all connected facts via edges
    related = graph.get_related_bidirectional(node_id, depth=1, max_results=50)
    facts = []
    for rel_node, relation, direction, depth, path in related:
        if rel_node.type in ("Fact", "Preference", "Event"):
            facts.append(rel_node.name)

    # Also search for facts that mention the entity name
    with graph._get_conn() as conn:
        name_pattern = f"%{_escape_like_pattern(node.name)}%"
        rows = conn.execute(
            "SELECT name FROM nodes WHERE type IN ('Fact', 'Preference') AND name LIKE ? ESCAPE '\\' AND id != ? LIMIT 30",
            (name_pattern, node_id)
        ).fetchall()
        for row in rows:
            if row['name'] not in facts:
                facts.append(row['name'])

    if not facts:
        return None

    if use_llm and _HAS_LLM_CLIENTS:
        # Use LLM to generate natural summary
        facts_text = "\n".join(f"- {f}" for f in facts[:20])  # Cap at 20 to save tokens
        prompt = f"""Generate a brief summary paragraph (2-4 sentences) about "{node.name}" based on these known facts:

{facts_text}

Write a natural, flowing paragraph. Only include information from the facts above — do not add anything new. Be concise."""

        try:
            response, _ = call_fast_reasoning(
                prompt,
                system_prompt="Write plain prose only. Do not use JSON, bullets, or markdown.",
            )
            if response:
                summary = response.strip()
                # Store in node attributes
                node.attributes["summary"] = summary
                node.attributes["summary_updated_at"] = _now_iso()
                node.attributes["summary_fact_count"] = len(facts)
                graph.update_node(node)
                return summary
        except Exception as exc:
            logger.warning("LLM summary failed for %s: %s", node.name, exc)
            if _is_fail_hard_mode():
                raise

    # Fallback: simple concatenation
    summary = f"{node.name}: " + ". ".join(facts[:10])
    if len(facts) > 10:
        summary += f" (and {len(facts) - 10} more facts)"

    node.attributes["summary"] = summary
    node.attributes["summary_updated_at"] = _now_iso()
    node.attributes["summary_fact_count"] = len(facts)
    graph.update_node(node)
    return summary


def summarize_all_entities(owner_id: str = None, use_llm: bool = True, entity_types: List[str] = None) -> Dict[str, Any]:
    """Generate summaries for all Person/Place/Concept nodes.

    Args:
        owner_id: Optional owner ID to filter entities.
        use_llm: If True, use LLM to generate natural summaries.
        entity_types: List of node types to summarize (default: Person, Place, Concept).

    Returns:
        Dict with counts of summaries generated, skipped, and failed.
    """
    if entity_types is None:
        entity_types = ["Person", "Place", "Concept"]

    graph = get_graph()
    stats = {"generated": 0, "skipped": 0, "failed": 0, "total": 0}

    with graph._get_conn() as conn:
        query = f"SELECT id, name, type, attributes FROM nodes WHERE type IN ({','.join('?' for _ in entity_types)})"
        params: list = list(entity_types)
        if owner_id:
            query += " AND owner_id = ?"
            params.append(owner_id)
        rows = conn.execute(query, params).fetchall()

    stats["total"] = len(rows)

    for row in rows:
        # Skip if already has a recent summary and not using LLM (quick mode)
        attrs_raw = row['attributes']
        try:
            attrs = json.loads(attrs_raw) if attrs_raw else {}
        except (TypeError, ValueError) as exc:
            logger.warning(
                "[memory_graph] malformed node attributes JSON for summary node_id=%s; using empty attributes: %s",
                row['id'],
                exc,
            )
            attrs = {}
        if attrs.get("summary") and not use_llm:
            stats["skipped"] += 1
            continue

        summary = generate_entity_summary(row['id'], use_llm=use_llm)
        if summary:
            stats["generated"] += 1
        else:
            stats["skipped"] += 1

    return stats


def initialize_db() -> None:
    """Initialize the database - just ensure schema exists."""
    graph = get_graph()  # This calls _init_db() internally
    # The initialization is already done in the constructor


def warm_embedding_cache(
    texts: List[str],
    *,
    max_workers: Optional[int] = None,
    pool_name: str = "embeddings",
    task_name: str = "embedding_cache",
    timeout_s: Optional[float] = None,
) -> Dict[str, int]:
    """Precompute embeddings for a batch of texts into the shared cache."""
    return get_graph().warm_embedding_cache(
        texts,
        max_workers=max_workers,
        pool_name=pool_name,
        task_name=task_name,
        timeout_s=timeout_s,
    )


if __name__ == "__main__":
    import argparse
    import sys

    def main():
        parser = argparse.ArgumentParser(
            prog="memory_graph.py",
            description="Local Graph Memory System CLI",
        )
        subparsers = parser.add_subparsers(dest="command", help="Command")

        # --- init ---
        subparsers.add_parser("init", help="Initialize the database")

        # --- plan-tool-hint ---
        pth_p = subparsers.add_parser("plan-tool-hint", help="Return a tool hint for the given query, or nothing")
        pth_p.add_argument("query", help="User query to classify")
        pth_p.add_argument("--timeout-ms", type=int, default=None, help="LLM timeout in ms")

        # --- stats ---
        subparsers.add_parser("stats", help="Show database statistics")
        subparsers.add_parser("health", help="Show KB health metrics (detailed)")
        backfill_p = subparsers.add_parser("backfill-hashes", help="Backfill content_hash for nodes with NULL hash")
        backfill_p.add_argument("--dry-run", action="store_true", help="Preview what would be updated without making changes")

        # --- store ---
        store_p = subparsers.add_parser("store", help="Store a new memory")
        store_p.add_argument("text", help="Text of the memory to store")
        store_p.add_argument("--owner", default=None, help="Owner ID")
        store_p.add_argument("--category", default="fact", help="Category (default: fact)")
        store_p.add_argument("--source", default=None, help="Source of the memory")
        store_p.add_argument("--verified", action="store_true", help="Mark as verified")
        store_p.add_argument("--pinned", action="store_true", help="Mark as pinned")
        store_p.add_argument("--confidence", type=float, default=0.5, help="Confidence score (default: 0.5)")
        store_p.add_argument("--extraction-confidence", type=float, default=0.5, help="Extraction confidence (default: 0.5)")
        store_p.add_argument("--status", default=None, help="Initial status")
        store_p.add_argument("--privacy", default="shared", help="Privacy level (default: shared)")
        store_p.add_argument("--session-id", default=None, help="Session ID")
        store_p.add_argument("--speaker", default=None, help="Speaker name")
        store_p.add_argument("--skip-dedup", action="store_true", help="Skip deduplication check")
        store_p.add_argument("--knowledge-type", default="fact", choices=["fact", "belief", "preference", "experience"], help="Knowledge type (default: fact)")
        store_p.add_argument("--source-type", default=None, choices=["user", "assistant", "agent", "both", "tool", "import"], help="Source type (user, assistant|agent, both, tool, import)")
        store_p.add_argument("--keywords", default=None, help="Space-separated derived search keywords")
        store_p.add_argument("--created-at", default=None, help="Override created_at timestamp (ISO format)")
        store_p.add_argument("--accessed-at", default=None, help="Override accessed_at timestamp (ISO format)")
        store_p.add_argument("--structural-anchor-kind", default=None, help="Structural anchor kind to preserve on the stored fact")
        store_p.add_argument("--project", default=None, help="Project name this fact belongs to (stored in attributes)")
        store_p.add_argument("--domains", default="", help='Comma-separated domain tags (e.g., "technical,research")')
        store_p.add_argument("--sensitivity", default=None, help="Sensitivity tag (private_health, financial, relationship_conflict, family_trauma, emotional_vulnerability)")
        store_p.add_argument("--sensitivity-handling", default=None, help="Handling guidance for sensitive facts")

        # --- forget ---
        forget_p = subparsers.add_parser("forget", help="Permanently delete a memory by ID or query")
        forget_p.add_argument("query", nargs="*", help="Search query to find memory to forget")
        forget_p.add_argument("--id", dest="node_id", default=None, help="Node ID to forget directly")

        # --- delete ---
        delete_p = subparsers.add_parser("delete", help="Soft-delete a memory")
        delete_p.add_argument("id", help="Node ID to delete")
        delete_p.add_argument("--reason", default="manual", help="Deletion reason (default: manual)")

        # --- get-node ---
        get_node_p = subparsers.add_parser("get-node", help="Get a memory node by ID")
        get_node_p.add_argument("id", help="Node ID")

        # --- get-edges ---
        get_edges_p = subparsers.add_parser("get-edges", help="Get edges for a node")
        get_edges_p.add_argument("id", help="Node ID")

        # --- create-edge ---
        create_edge_p = subparsers.add_parser("create-edge", help="Create a graph edge")
        create_edge_p.add_argument("subject", help="Subject node name")
        create_edge_p.add_argument("relation", help="Relation type")
        create_edge_p.add_argument("object", help="Object node name")
        create_edge_p.add_argument("--owner", default=None, help="Owner ID")
        create_edge_p.add_argument("--source-fact-id", default=None, help="Source fact ID to link edge to")
        create_edge_p.add_argument("--create-missing", action="store_true",
                                   help="Create Person nodes for missing entities")
        create_edge_p.add_argument("--json", action="store_true", help="JSON output")

        # --- delete-edges-by-fact ---
        del_edges_p = subparsers.add_parser("delete-edges-by-fact", help="Delete edges linked to a source fact")
        del_edges_p.add_argument("fact_id", help="Source fact ID")

        # --- fact-history ---
        history_p = subparsers.add_parser("fact-history", help="Show fact evolution history (supersedes chain)")
        history_p.add_argument("id", help="Node ID")

        # --- recall ---
        # Config JSON schema (all fields optional):
        # {
        #   "stores": ["vector","graph","docs"] | {"vector": {...}, "graph": {...}, "docs": {"project":"quaid","limit":5}},
        #   "limit": 5,
        #   "min_similarity": 0.60,
        #   "domain_filter": {"all": true},
        #   "domain_boost": ["technical","project"],
        #   "project": "quaid",
        #   "fast": false,
        #   "depth": 1,
        #   "date_from": "YYYY-MM-DD",
        #   "date_to": "YYYY-MM-DD",
        #   "dateFrom": "YYYY-MM-DD",
        #   "dateTo": "YYYY-MM-DD",
        #   "after": "YYYY-MM-DD",
        #   "before": "YYYY-MM-DD",
        #   "as_of": "YYYY-MM-DD",
        #   "asOf": "YYYY-MM-DD",
        #   "temporal_dimension": "auto|occurred|mentioned|record",
        #   "include_chunks": false,
        #   "max_chunk_tokens": 512,
        #   "max_total_chunk_tokens": 2048,
        #   "session_id": null,
        #   "current_session_id": null,
        #   "compaction_time": null,
        #   "archive": false,
        #   "candidate_pool": null,
        #   "owner": null
        # }
        recall_p = subparsers.add_parser("recall", help="Recall memories (unified recall surface)")
        recall_p.add_argument("query", nargs="+", help="Search query (last token parsed as JSON config if it starts with '{')")
        recall_p.add_argument("--json", action="store_true", help="JSON output")
        recall_p.add_argument("--debug", action="store_true", help="Show scoring breakdown per result")
        recall_p.add_argument("--date-from", "--date_from", dest="date_from", default=None, help="Only return memories from this date onward (YYYY-MM-DD)")
        recall_p.add_argument("--date-to", "--date_to", dest="date_to", default=None, help="Only return memories up to this date (YYYY-MM-DD)")
        recall_p.add_argument("--after", "--since", dest="date_after", help="Alias for --date-from using occurred/event time")
        recall_p.add_argument("--before", "--until", "--as-of", "--as_of", "--asOf", dest="date_to", help="Alias for --date-to")
        recall_p.add_argument("--temporal-dimension", "--temporal_dimension", choices=["auto", "occurred", "mentioned", "record", "created_at"], default=None, help="Date axis for date filters")
        recall_p.add_argument("--include-chunks", "--include_chunks", action="store_true", help="Include bounded session chunk evidence for linked facts")
        recall_p.add_argument("--max-chunk-tokens", "--max_chunk_tokens", type=int, default=None, help="Max tokens per included session chunk")
        recall_p.add_argument("--max-total-chunk-tokens", "--max_total_chunk_tokens", type=int, default=None, help="Aggregate token cap for all included session chunks")

        recall_docs_request_p = subparsers.add_parser("recall-docs-request", help=argparse.SUPPRESS)
        recall_docs_request_p.add_argument("query", help="Internal docs recall request query")
        recall_docs_request_p.add_argument("options_json", help="Internal docs recall request options JSON")

        recall_memory_request_p = subparsers.add_parser("recall-memory-request", help=argparse.SUPPRESS)
        recall_memory_request_p.add_argument("query", help="Internal memory recall request query")
        recall_memory_request_p.add_argument("options_json", help="Internal memory recall request options JSON")

        recall_fast_p = subparsers.add_parser("recall-fast", help="Fast pre-injection recall with HyDE fanout")
        recall_fast_p.add_argument("query", nargs="+", help="Search query")
        recall_fast_p.add_argument("--owner", default=None, help="Owner ID")
        recall_fast_p.add_argument("--limit", type=int, default=10, help="Max results (default: 10)")
        recall_fast_p.add_argument("--min-similarity", type=float, default=0.60, help="Min similarity threshold (default: 0.60)")
        recall_fast_p.add_argument("--date-from", default=None, help="Only return memories from this date onward (YYYY-MM-DD)")
        recall_fast_p.add_argument("--date-to", default=None, help="Only return memories up to this date (YYYY-MM-DD)")
        recall_fast_p.add_argument("--temporal-dimension", "--temporal_dimension", choices=["auto", "occurred", "mentioned", "record", "created_at"], default=None, help="Date axis for date filters")
        recall_fast_p.add_argument("--domain-filter", default='{"all": true}', help='Domain filter JSON, e.g. {"all":true} or {"technical":true}')
        recall_fast_p.add_argument("--domain-boost", default="[]", help='Domain boost JSON array, e.g. ["technical","project"]')
        recall_fast_p.add_argument("--project", default=None, help="Filter by project/domain label")
        recall_fast_p.add_argument("--timeout-ms", type=int, default=None, help="Override overall fast-recall timeout budget")
        recall_fast_p.add_argument("--planner-profile", choices=["off", "fast", "aggressive"], default="fast",
                                   help="Planner fanout profile for fast recall (default: fast)")
        recall_fast_p.add_argument("--include-chunks", "--include_chunks", action="store_true", help="Include bounded session chunk evidence for linked facts")
        recall_fast_p.add_argument("--max-chunk-tokens", "--max_chunk_tokens", type=int, default=None, help="Max tokens per included session chunk")
        recall_fast_p.add_argument("--max-total-chunk-tokens", "--max_total_chunk_tokens", type=int, default=None, help="Aggregate token cap for all included session chunks")
        recall_fast_p.add_argument("--json", action="store_true", help="JSON output including recall metadata")
        recall_fast_p.add_argument("--debug", action="store_true", help="Show scoring breakdown for each result")

        # --- decay ---
        subparsers.add_parser("decay", help="Run memory decay")

        # --- edge-keywords ---
        ek_p = subparsers.add_parser("edge-keywords", help="Edge keywords management")
        ek_sub = ek_p.add_subparsers(dest="subcmd", help="Subcommand")

        ek_sub.add_parser("list", help="List all edge keywords")
        ek_sub.add_parser("seed", help="Seed keywords from existing edge relations")

        ek_check_p = ek_sub.add_parser("check", help="Check if a query would trigger graph expansion")
        ek_check_p.add_argument("query", nargs="+", help="Query to check")

        ek_add_p = ek_sub.add_parser("add", help="Add keywords for a relation")
        ek_add_p.add_argument("relation", help="Relation name")
        ek_add_p.add_argument("keywords", help="Comma-separated keywords")

        ek_gen_p = ek_sub.add_parser("generate", help="Generate keywords for a relation using LLM")
        ek_gen_p.add_argument("relation", help="Relation name")

        relation_types_p = subparsers.add_parser("relation-types", help="List active graph relation types")
        relation_types_p.add_argument("--json", action="store_true", help="JSON output")

        system_context_p = subparsers.add_parser(
            "system-context-metadata",
            help="Render aggregated runtime metadata for system prompt builders",
        )
        system_context_p.add_argument("--json", action="store_true", help="JSON output")

        # --- add-alias ---
        add_alias_p = subparsers.add_parser("add-alias", help="Add an entity alias")
        add_alias_p.add_argument("alias", help="The alias name (e.g., 'Sol')")
        add_alias_p.add_argument("canonical", help="The canonical name (e.g., 'Alice Smith')")
        add_alias_p.add_argument("--node-id", default=None, help="Optional canonical node ID")
        add_alias_p.add_argument("--owner", default=None, help="Owner ID")

        # --- list-aliases ---
        list_aliases_p = subparsers.add_parser("list-aliases", help="List entity aliases")
        list_aliases_p.add_argument("--owner", default=None, help="Filter by owner")

        # --- delete-alias ---
        delete_alias_p = subparsers.add_parser("delete-alias", help="Delete an entity alias by ID")
        delete_alias_p.add_argument("alias_id", help="Alias ID to delete")

        # --- summarize-entity ---
        sum_entity_p = subparsers.add_parser("summarize-entity", help="Generate summary for an entity node")
        sum_entity_p.add_argument("node_id", help="Entity node ID to summarize")
        sum_entity_p.add_argument("--no-llm", action="store_true", help="Skip LLM, use simple concatenation")

        # --- recall-stats ---
        recall_stats_p = subparsers.add_parser("recall-stats", help="Show recall observability stats")
        recall_stats_p.add_argument("--days", type=int, default=7, help="Number of days to analyze (default: 7)")

        # --- health-trend ---
        health_trend_p = subparsers.add_parser("health-trend", help="Show health snapshots over time")
        health_trend_p.add_argument("--limit", type=int, default=10, help="Max snapshots to show (default: 10)")

        # --- dedup-audit ---
        subparsers.add_parser("dedup-audit", help="Audit dedup_log for accuracy metrics")

        # --- flagged ---
        flagged_p = subparsers.add_parser("flagged", help="List/manage facts flagged by injection blocklist")
        flagged_p.add_argument("--approve", metavar="NODE_ID", help="Move flagged fact to pending status")
        flagged_p.add_argument("--reject", metavar="NODE_ID", help="Hard-delete a flagged fact")

        # --- summarize-all ---
        sum_all_p = subparsers.add_parser("summarize-all", help="Generate summaries for all entity nodes")
        sum_all_p.add_argument("--owner", default=None, help="Owner ID to filter entities")
        sum_all_p.add_argument("--no-llm", action="store_true", help="Skip LLM, use simple concatenation")
        sum_all_p.add_argument("--types", default=None, help="Comma-separated entity types (default: Person,Place,Concept)")

        # --- detect-provider ---
        subparsers.add_parser("detect-provider", help="Show current LLM and embeddings provider status")

        # Parse args
        args = parser.parse_args()
        if args.command in {"recall", "recall-fast"} and bool(getattr(args, "json", False)):
            os.environ["QUAID_QUIET"] = "1"

        if not args.command:
            graph = get_graph()
            print("Local Graph Memory System")
            print(json.dumps(graph.get_stats(), indent=2))
            return

        # --- Command handlers ---

        if args.command == "init":
            initialize_db()
            print("Database initialized")

        elif args.command == "stats":
            graph = get_graph()
            print(json.dumps(graph.get_stats(), indent=2))

        elif args.command == "health":
            created = _ensure_visible_identity_stubs()
            if created:
                logger.info("Auto-created missing visible identity stubs: %s", ", ".join(created))
            graph = get_graph()
            print(json.dumps(graph.get_health_metrics(), indent=2))

        elif args.command == "backfill-hashes":
            graph = get_graph()
            with graph._get_conn() as conn:
                rows = conn.execute(
                    "SELECT id, name FROM nodes WHERE content_hash IS NULL"
                ).fetchall()
            if args.dry_run:
                print(f"Would backfill {len(rows)} content hashes:")
                for row in rows:
                    h = content_hash(row["name"])
                    print(f"  ID {row['id']}: {row['name'][:60]}... -> {h[:16]}...")
                print(f"\nTotal: {len(rows)} (dry run, no changes made)")
            else:
                count = 0
                with graph._get_conn() as conn:
                    for row in rows:
                        h = content_hash(row["name"])
                        conn.execute(
                            "UPDATE nodes SET content_hash = ? WHERE id = ?",
                            (h, row["id"])
                        )
                        count += 1
                print(f"Backfilled {count} content hashes")

        elif args.command == "plan-tool-hint":
            timeout_s = (args.timeout_ms / 1000.0) if args.timeout_ms else None
            hint = plan_tool_hint(args.query, timeout_s=timeout_s)
            if hint:
                print(hint)

        elif args.command == "store":
            try:
                owner = args.owner or _get_memory_config().users.default_owner
                parsed_domains = [
                    d.strip() for d in str(getattr(args, "domains", "") or "").split(",")
                    if d.strip()
                ]
                project_tag = _normalize_project_tag(getattr(args, 'project', None))
                parsed_domains = _sanitize_domains_for_project(parsed_domains, project_tag)
                result = store(
                    args.text,
                    category=args.category,
                    verified=args.verified,
                    pinned=args.pinned,
                    confidence=args.confidence,
                    privacy=args.privacy,
                    extraction_confidence=args.extraction_confidence,
                    source=args.source,
                    owner_id=owner,
                    session_id=args.session_id,
                    skip_dedup=args.skip_dedup,
                    speaker=args.speaker,
                    status=args.status,
                    knowledge_type=args.knowledge_type,
                    keywords=args.keywords,
                    source_type=args.source_type,
                    domains=parsed_domains,
                    project=project_tag,
                    created_at=getattr(args, 'created_at', None),
                    accessed_at=getattr(args, 'accessed_at', None),
                    structural_anchor_kind=getattr(args, 'structural_anchor_kind', None),
                )
                # Add project tagging to attributes if specified.
                # Apply on ALL statuses (created, duplicate, updated) — dedup
                # returns existing node ID, and we still want to tag it.
                tag_node_id = result.get("id") or result.get("existing_id")
                if tag_node_id and (project_tag or parsed_domains or args.sensitivity):
                    graph = get_graph()
                    node = graph.get_node(tag_node_id)
                    if node:
                        attrs = node.attributes if isinstance(node.attributes, dict) else {}
                        if project_tag:
                            attrs["project"] = project_tag
                        if parsed_domains:
                            attrs["domains"] = _sanitize_domains_for_project(
                                (attrs.get("domains") or []) + parsed_domains,
                                project_tag,
                            )
                        if args.sensitivity:
                            attrs["sensitivity"] = args.sensitivity
                        if args.sensitivity_handling:
                            attrs["sensitivity_handling"] = args.sensitivity_handling
                        node.attributes = attrs
                        graph.update_node(node)
                if result["status"] == "created":
                    print(f"Stored: {result['id']}")
                elif result["status"] == "duplicate":
                    print(f"Duplicate (similarity: {result['similarity']}) [{result['id']}]: {result['existing_text'][:80]}")
                elif result["status"] == "updated":
                    print(f"Updated existing: {result['id']}")
            except (ValueError, RuntimeError) as e:
                print(f"Error: {e}", file=sys.stderr)
                sys.exit(1)

        elif args.command == "get-node":
            node_id = args.id
            result = get_memory(node_id)
            if result:
                print(json.dumps(result, indent=2))
            else:
                print("Memory not found", file=sys.stderr)
                sys.exit(1)

        elif args.command == "delete":
            if soft_delete(args.id, args.reason):
                print(f"Deleted memory: {args.id}")
            else:
                print(f"Memory not found: {args.id}")  # Print to stdout, don't error

        elif args.command == "forget":
            if args.node_id:
                if forget(node_id=args.node_id):
                    print(f"Permanently deleted: {args.node_id}")
                else:
                    print("Memory not found", file=sys.stderr)
                    sys.exit(1)
            elif args.query:
                query = " ".join(args.query)
                if forget(query=query):
                    print(f"Deleted memory matching: {query}")
                else:
                    print("No matching memory found", file=sys.stderr)
                    sys.exit(1)
            else:
                print("Error: provide --id <id> or a search query", file=sys.stderr)
                sys.exit(1)

        elif args.command == "edge-keywords":
            subcmd = args.subcmd or "list"

            if subcmd == "list":
                keywords = get_edge_keywords()
                if not keywords:
                    print("No edge keywords stored yet. Run 'edge-keywords seed' to generate.")
                else:
                    print(f"Edge keywords ({len(keywords)} relations):\n")
                    for relation, kws in sorted(keywords.items()):
                        print(f"  {relation}: {', '.join(kws)}")

            elif subcmd == "seed":
                print("Seeding keywords for existing edge relations...")
                count = seed_edge_keywords_from_db()
                print(f"Generated keywords for {count} relations")

            elif subcmd == "check":
                test_query = " ".join(args.query)
                result = should_expand_graph(test_query)
                print(f"Query: \"{test_query}\"")
                print(f"Should expand graph: {result}")

            elif subcmd == "add":
                keywords = [k.strip().lower() for k in args.keywords.split(",")]
                if store_edge_keywords(args.relation, keywords):
                    print(f"Stored keywords for '{args.relation}': {keywords}")
                else:
                    print(f"Failed to store keywords for '{args.relation}'")
                    sys.exit(1)

            elif subcmd == "generate":
                print(f"Generating keywords for '{args.relation}'...")
                keywords = generate_keywords_for_relation(args.relation)
                if keywords:
                    store_edge_keywords(args.relation, keywords)
                    print(f"Generated and stored: {keywords}")
                else:
                    print("Failed to generate keywords")
                    sys.exit(1)

        elif args.command == "relation-types":
            relation_types = list_relation_types()
            if args.json:
                print(json.dumps(relation_types))
            elif relation_types:
                for relation in relation_types:
                    print(relation)
            else:
                print("No active relation types found")

        elif args.command == "system-context-metadata":
            from core.runtime.system_context import build_system_context_block, collect_system_context_metadata

            if args.json:
                print(json.dumps(collect_system_context_metadata(), indent=2, sort_keys=True))
            else:
                print(build_system_context_block())

        elif args.command == "decay":
            result = decay_memories()
            print(f"Decayed {result['decayed_count']} memories")

        elif args.command == "create-edge":
            create_missing = getattr(args, 'create_missing', False)
            result = create_edge(args.subject, args.relation, args.object, source_fact_id=args.source_fact_id, create_missing_entities=create_missing, owner_id=args.owner)

            if args.json:
                print(json.dumps(result))
            else:
                if result["status"] == "created":
                    print(f"Created edge: {args.subject} --{args.relation}--> {args.object}")
                    print(f"Edge ID: {result['edge_id']}")
                else:
                    print(f"Error: {result.get('message', 'Unknown error')}", file=sys.stderr)
                    sys.exit(1)

        elif args.command == "delete-edges-by-fact":
            count = delete_edges_by_source_fact(args.fact_id)
            print(f"Deleted {count} edges linked to fact {args.fact_id}")

        elif args.command == "get-edges":
            graph = get_graph()
            node = _resolve_node_identifier(graph, args.id)
            if node is None:
                print(f"Node not found: {args.id}", file=sys.stderr)
                sys.exit(1)
            edges = graph.get_edges(node.id)
            if edges:
                print(json.dumps([asdict(e) for e in edges], indent=2))
            else:
                print("No edges found for node", file=sys.stderr)

        elif args.command == "fact-history":
            graph = get_graph()
            history = graph.get_fact_history(args.id)
            if history:
                for i, node in enumerate(history):
                    marker = " (current)" if node.superseded_by is None else f" → superseded by {node.superseded_by[:8]}"
                    print(f"  {i+1}. [{node.created_at}] {node.name} [C:{node.confidence:.1f}]{marker}")
            else:
                print("No history found for node", file=sys.stderr)

        elif args.command == "recall":
            # Parse query and optional JSON config from positional args.
            # The last token is treated as config if it starts with '{'.
            raw_tokens = args.query
            cfg: dict = {}
            if raw_tokens and raw_tokens[-1].strip().startswith("{"):
                try:
                    cfg = json.loads(raw_tokens[-1])
                    raw_tokens = raw_tokens[:-1]
                except json.JSONDecodeError as _e:
                    print(f"recall: invalid config JSON: {_e}", file=sys.stderr)
                    sys.exit(1)
            query = " ".join(raw_tokens)
            if not query:
                if args.json:
                    print("[]")
                sys.exit(0)

            # Resolve stores config.
            # stores can be a list ["vector","graph","docs"] or a dict {"vector":{...},"docs":{...}}
            stores_explicit = "stores" in cfg
            store_names, store_opts = _resolve_recall_store_request(cfg)

            want_docs = "docs" in store_names
            want_memory = bool([s for s in store_names if s != "docs"]) or not store_names

            # Top-level config with per-store overrides
            limit       = cfg.get("limit", 5)
            owner       = _resolve_cli_recall_owner(cfg)
            use_json    = args.json
            use_debug   = args.debug

            # Memory-store config (top-level, overridable per store)
            mem_opts    = store_opts.get("vector", store_opts.get("graph", {}))
            domain_filter   = mem_opts.get("domain_filter", cfg.get("domain_filter", {"all": True}))
            domain_boost    = mem_opts.get("domain_boost", cfg.get("domain_boost", []))
            project         = mem_opts.get("project", cfg.get("project"))
            min_similarity  = mem_opts.get("min_similarity", cfg.get("min_similarity", 0.60))
            use_fast        = cfg.get("fast", False)
            graph_depth     = cfg.get("depth", store_opts.get("graph", {}).get("depth", 1))
            session_id      = cfg.get("session_id")
            current_session_id = cfg.get("current_session_id")
            compaction_time = cfg.get("compaction_time")
            date_from, date_to = _resolve_recall_command_date_bounds(
                cfg,
                cli_date_from=getattr(args, "date_from", None) or getattr(args, "date_after", None),
                cli_date_to=getattr(args, "date_to", None),
            )
            temporal_dimension = _resolve_recall_command_temporal_dimension(
                cfg,
                cli_temporal_dimension=getattr(args, "temporal_dimension", None),
                cli_after=getattr(args, "date_after", None),
            )
            archive         = cfg.get("archive", False)
            candidate_pool  = cfg.get("candidate_pool")
            planner_profile = cfg.get("planner_profile", "full")
            timeout_ms      = cfg.get("timeout_ms")
            include_chunks  = bool(getattr(args, "include_chunks", False) or cfg.get("include_chunks", False))
            max_chunk_tokens = cfg.get("max_chunk_tokens", getattr(args, "max_chunk_tokens", None))
            max_total_chunk_tokens = cfg.get("max_total_chunk_tokens", getattr(args, "max_total_chunk_tokens", None))
            planned_queries = None
            planned_meta = None

            if not stores_explicit and want_memory and not archive and not session_id:
                planned = _plan_fanout_queries(
                    query,
                    max_queries=5,
                    timeout_s=_recall_planner_timeout_s(timeout_ms, fast_mode=bool(use_fast)),
                    return_meta=True,
                    planner_profile="fast" if use_fast else planner_profile,
                    max_retries=0 if use_fast else 1,
                )
                if isinstance(planned, tuple) and len(planned) == 2:
                    planned_queries, planned_meta = planned
                if isinstance(planned_meta, dict):
                    planned_stores = _planner_store_plan(planned_meta.get("planned_stores")) or ["vector"]
                    store_names = planned_stores
                    want_docs = "docs" in store_names
                    want_memory = bool([s for s in store_names if s != "docs"]) or not store_names
                    planned_project = planned_meta.get("planned_project")
                    if planned_project and not project:
                        project = planned_project

            json_payload = None
            text_memory_results = None

            if want_memory and archive:
                from datastore.memorydb.archive_store import search_archive as _search_archive
                archive_results = _search_archive(query, limit=limit)
                if use_json:
                    out = []
                    for r in archive_results:
                        out.append({
                            "text": r.get("name", ""),
                            "category": r.get("type", "?"),
                            "similarity": 1.0,
                            "id": r.get("id", ""),
                            "created_at": r.get("archived_at", ""),
                            "valid_from": "",
                            "valid_until": "",
                            "privacy": r.get("privacy", "shared"),
                            "owner_id": r.get("owner_id", ""),
                            "source_type": r.get("source_type", "archive"),
                            "via": "archive",
                            "archive_reason": r.get("archive_reason", ""),
                        })
                    json_payload = _build_recall_json_payload(out)
                else:
                    for r in archive_results:
                        print(f"[archive] [{r.get('type', '?')}] {r.get('name', '')} |ID:{r.get('id', '')}|archived:{r.get('archived_at', '')}|reason:{r.get('archive_reason', '')}")
                    if not archive_results:
                        print("No archived memories found")
            elif want_memory and session_id:
                # Session-filtered search: return facts from a specific session
                mg = MemoryGraph()
                with mg._get_conn() as conn:
                    rows = conn.execute(
                        "SELECT id, type, name, extraction_confidence, created_at, privacy, owner_id, session_id "
                        "FROM nodes WHERE session_id = ? AND owner_id = ? AND status IN ('active', 'approved', 'pending') "
                        "ORDER BY created_at DESC LIMIT ?",
                        (session_id, owner, int(limit))
                    ).fetchall()
                out = []
                for r in rows:
                    out.append({
                        "text": r["name"],
                        "category": r["type"],
                        "similarity": 1.0,
                        "id": r["id"],
                        "created_at": r["created_at"] or "",
                        "extraction_confidence": r["extraction_confidence"],
                        "valid_from": "",
                        "valid_until": "",
                        "privacy": r["privacy"] or "shared",
                        "owner_id": r["owner_id"] or "",
                        "source_type": "",
                    })
                if use_json:
                    json_payload = _build_recall_json_payload(out)
                else:
                    for r in out:
                        conf_raw = r.get('extraction_confidence')
                        conf = conf_raw if conf_raw is not None else 0.5
                        created = r.get('created_at', '') or ''
                        date_str = f"({created.split('T')[0]})" if created else ""
                        print(f"[1.00] [{r['category']}]{date_str}[C:{conf:.1f}] {r['text']} |ID:{r['id']}|T:{created}|VF:|VU:|P:{r['privacy'] or 'shared'}|O:{r['owner_id'] or ''}")
                    if not out:
                        print("No facts found for this session")
            elif want_memory:
                common_kwargs = dict(
                    privacy="shared",
                    current_session_id=current_session_id,
                    compaction_time=compaction_time,
                    date_from=date_from,
                    date_to=date_to,
                    temporal_dimension=temporal_dimension,
                    debug=use_debug,
                    domain=domain_filter,
                    domain_boost=domain_boost,
                    project=project,
                    timeout_ms=timeout_ms,
                    candidate_pool=candidate_pool,
                    max_chunk_tokens=max_chunk_tokens,
                    max_total_chunk_tokens=max_total_chunk_tokens,
                )
                if _should_run_recall_store_plan(store_names, use_fast=bool(use_fast)):
                    explicit_session_chunks_requested = _session_chunks_explicitly_requested(
                        stores_explicit,
                        store_names,
                    )
                    results, meta, docs_bundle = _run_recall_store_plan(
                        query,
                        stores=store_names,
                        limit=limit,
                        owner_id=owner,
                        min_similarity=min_similarity,
                        planner_profile="fast" if use_fast else planner_profile,
                        planned_queries=planned_queries,
                        planner_meta=planned_meta,
                        fast_mode=bool(use_fast),
                        graph_depth=graph_depth,
                        common_kwargs=common_kwargs,
                    )
                    if use_json:
                        results, meta = _prepare_recall_output_rows(
                            results,
                            meta,
                            include_chunks=include_chunks,
                            suppress_session_chunk_rows=not explicit_session_chunks_requested,
                            respect_auto_session_chunk_meta=not explicit_session_chunks_requested,
                            max_chunk_tokens=max_chunk_tokens,
                            max_total_chunk_tokens=max_total_chunk_tokens,
                        )
                        json_payload = _build_recall_json_payload(results, meta=meta, docs=docs_bundle)
                    else:
                        results, meta = _prepare_recall_output_rows(
                            results,
                            meta,
                            include_chunks=include_chunks,
                            suppress_session_chunk_rows=not explicit_session_chunks_requested,
                            respect_auto_session_chunk_meta=not explicit_session_chunks_requested,
                            max_chunk_tokens=max_chunk_tokens,
                            max_total_chunk_tokens=max_total_chunk_tokens,
                        )
                        text_memory_results = results
                        _print_recall_results(text_memory_results)
                        if docs_bundle:
                            _print_docs_bundle(docs_bundle)
                    want_docs = False
                else:
                    # Vector-only recall
                    recall_kwargs = _build_cli_vector_recall_kwargs(
                        limit=limit,
                        owner=owner,
                        min_similarity=min_similarity,
                        current_session_id=current_session_id,
                        compaction_time=compaction_time,
                        date_from=date_from,
                        date_to=date_to,
                        temporal_dimension=temporal_dimension,
                        use_debug=use_debug,
                        domain_filter=domain_filter,
                        domain_boost=domain_boost,
                        project=project,
                        timeout_ms=timeout_ms,
                        include_chunks=include_chunks,
                        max_chunk_tokens=max_chunk_tokens,
                        max_total_chunk_tokens=max_total_chunk_tokens,
                        use_fast=use_fast,
                        planner_profile=planner_profile,
                        planned_queries=planned_queries,
                        planned_meta=planned_meta,
                    )
                    json_payload, text_memory_results = _run_cli_vector_recall_branch(
                        query,
                        recall_kwargs,
                        use_json=use_json,
                        stores_explicit=stores_explicit,
                        store_names=store_names,
                        archive=archive,
                        session_id=session_id,
                    )
                    if not use_json and text_memory_results is not None:
                        _print_recall_results(text_memory_results)

            # docs store
            if want_docs:
                try:
                    docs_options = _build_cli_docs_recall_options(
                        cfg,
                        store_opts,
                        limit=limit,
                        want_memory=want_memory,
                        date_from=date_from,
                        date_to=date_to,
                    )
                    if not want_memory:
                        docs_response = _request_cli_docs_recall_via_broker(query, docs_options)
                    else:
                        # M4: mixed docs+vector recall stays on the existing path;
                        # broker dispatch for mixed store plans is a later slice.
                        docs_response = _run_cli_docs_recall_request(query, docs_options)
                    doc_results = docs_response["docs"]
                    doc_limit = int(docs_response["limit"])
                    if use_json:
                        if json_payload is None:
                            json_payload = _build_docs_only_recall_json_payload(
                                doc_results,
                                limit=doc_limit,
                            )
                        else:
                            json_payload["docs"] = _validate_docs_bundle(doc_results)
                        if _recall_telemetry_enabled():
                            if json_payload.get("meta") is None or not isinstance(json_payload.get("meta"), dict):
                                json_payload["meta"] = {}
                            json_payload["meta"]["docs"] = docs_response.get("meta") or {}
                    else:
                        _print_docs_bundle(doc_results)
                except Exception as _docs_err:
                    if _is_fail_hard_mode():
                        raise
                    print(f"[docs] warning: {_docs_err}", file=sys.stderr)

            if use_json and json_payload is not None:
                print(json.dumps(json_payload, indent=2))

        elif args.command == "recall-docs-request":
            try:
                request_options = json.loads(args.options_json)
            except json.JSONDecodeError as exc:
                print(f"recall-docs-request: invalid options JSON: {exc}", file=sys.stderr)
                sys.exit(1)
            if not isinstance(request_options, dict):
                print("recall-docs-request: options JSON must be an object", file=sys.stderr)
                sys.exit(1)
            docs_response = _request_cli_docs_recall_via_broker(args.query, request_options)
            print(json.dumps(docs_response, indent=2))

        elif args.command == "recall-memory-request":
            try:
                request_options = json.loads(args.options_json)
            except json.JSONDecodeError as exc:
                print(f"recall-memory-request: invalid options JSON: {exc}", file=sys.stderr)
                sys.exit(1)
            if not isinstance(request_options, dict):
                print("recall-memory-request: options JSON must be an object", file=sys.stderr)
                sys.exit(1)
            selector = str(request_options.get("selector") or "").strip().lower().replace("-", "_")
            handler_store = str(request_options.get("store") or "").strip().lower().replace("-", "_")
            recall_kwargs = _build_cli_memory_recall_request_kwargs(request_options)
            memory_response = _request_cli_vector_recall_via_broker(
                args.query,
                recall_kwargs,
                selector=selector,
                store=handler_store,
            )
            print(json.dumps(memory_response, indent=2))

        elif args.command == "recall-fast":
            query = " ".join(args.query)
            domain_filter = json.loads(getattr(args, "domain_filter", '{"all": true}') or '{"all": true}')
            domain_boost = json.loads(getattr(args, "domain_boost", "[]") or "[]")
            timeout_ms = _resolve_cli_recall_fast_timeout_ms(getattr(args, "timeout_ms", None))
            results, meta = recall_fast(
                query,
                limit=args.limit,
                owner_id=args.owner,
                min_similarity=args.min_similarity,
                date_from=getattr(args, "date_from", None),
                date_to=getattr(args, "date_to", None),
                temporal_dimension=getattr(args, "temporal_dimension", None),
                debug=getattr(args, "debug", False),
                domain=domain_filter,
                domain_boost=domain_boost,
                project=getattr(args, "project", None),
                timeout_ms=timeout_ms,
                planner_profile=getattr(args, "planner_profile", "fast"),
                include_chunks=getattr(args, "include_chunks", False),
                max_chunk_tokens=getattr(args, "max_chunk_tokens", None),
                max_total_chunk_tokens=getattr(args, "max_total_chunk_tokens", None),
                return_meta=True,
            )
            if args.json:
                print(json.dumps({"results": _strip_recall_transport_meta_from_output_rows(results), "meta": meta}))
            else:
                _print_recall_results(results)

        elif args.command == "add-alias":
            graph = get_graph()
            alias_id = graph.add_alias(args.alias, args.canonical, canonical_node_id=args.node_id, owner_id=args.owner)
            print(f"Added alias: '{args.alias}' -> '{args.canonical}' (ID: {alias_id})")

        elif args.command == "list-aliases":
            graph = get_graph()
            aliases = graph.get_aliases(owner_id=args.owner)
            if aliases:
                for a in aliases:
                    node_str = f" [node:{a['canonical_node_id']}]" if a['canonical_node_id'] else ""
                    owner_str = f" (owner:{a['owner_id']})" if a['owner_id'] else ""
                    print(f"  {a['alias']} -> {a['canonical_name']}{node_str}{owner_str} |ID:{a['id']}")
            else:
                print("No aliases found")

        elif args.command == "delete-alias":
            graph = get_graph()
            if graph.delete_alias(args.alias_id):
                print(f"Deleted alias: {args.alias_id}")
            else:
                print(f"Alias not found: {args.alias_id}", file=sys.stderr)
                sys.exit(1)

        elif args.command == "recall-stats":
            graph = get_graph()
            days = args.days
            with graph._get_conn() as conn:
                cutoff = (_now() - timedelta(days=days)).isoformat()
                rows = conn.execute("""
                    SELECT COUNT(*) as total,
                           ROUND(AVG(results_count), 1) as avg_results,
                           ROUND(AVG(avg_similarity), 3) as avg_sim,
                           ROUND(AVG(top_similarity), 3) as avg_top_sim,
                           ROUND(AVG(latency_ms), 0) as avg_latency_ms,
                           SUM(multi_pass_triggered) as multi_pass_count,
                           SUM(fts_fallback_used) as fts_fallback_count,
                           SUM(reranker_used) as reranker_count,
                           ROUND(AVG(CASE WHEN reranker_used THEN reranker_changes END), 1) as avg_reranker_changes,
                           SUM(CASE WHEN reranker_used THEN reranker_top1_changed ELSE 0 END) as top1_changed_count,
                           ROUND(AVG(CASE WHEN reranker_used THEN reranker_avg_displacement END), 2) as avg_displacement,
                           SUM(graph_discoveries) as total_graph_discoveries
                    FROM recall_log WHERE created_at >= ?
                """, (cutoff,)).fetchone()

                if not rows or rows["total"] == 0:
                    print(f"No recall logs in the last {days} days")
                else:
                    total = rows["total"]
                    reranker_count = rows['reranker_count'] or 0
                    print(f"Recall Stats (last {days} days)")
                    print(f"{'='*50}")
                    print(f"Total recalls:           {total}")
                    print(f"Avg results/recall:      {rows['avg_results']}")
                    print(f"Avg similarity:          {rows['avg_sim']}")
                    print(f"Avg top similarity:      {rows['avg_top_sim']}")
                    print(f"Avg latency:             {int(rows['avg_latency_ms'] or 0)}ms")
                    print(f"Multi-pass triggered:    {rows['multi_pass_count']}/{total} ({rows['multi_pass_count']*100//total}%)")
                    print(f"FTS fallback used:       {rows['fts_fallback_count']}/{total} ({rows['fts_fallback_count']*100//total}%)")
                    print(f"Reranker used:           {reranker_count}/{total} ({reranker_count*100//total}%)")
                    print(f"Avg reranker changes:    {rows['avg_reranker_changes'] or 0}")
                    if reranker_count > 0:
                        top1_count = rows['top1_changed_count'] or 0
                        print(f"Reranker top-1 changed:  {top1_count}/{reranker_count} ({top1_count*100//reranker_count}%)")
                        print(f"Avg rank displacement:   {rows['avg_displacement'] or 0}")
                    print(f"Graph discoveries:       {rows['total_graph_discoveries']}")

                    # Intent breakdown
                    intent_rows = conn.execute("""
                        SELECT intent, COUNT(*) as cnt FROM recall_log
                        WHERE created_at >= ? AND intent IS NOT NULL
                        GROUP BY intent ORDER BY cnt DESC
                    """, (cutoff,)).fetchall()
                    if intent_rows:
                        print(f"\nIntent distribution:")
                        for row in intent_rows:
                            print(f"  {row['intent']}: {row['cnt']}")

                    # Per-intent reranker breakdown
                    if reranker_count > 0:
                        reranker_by_intent = conn.execute("""
                            SELECT intent,
                                   COUNT(*) as cnt,
                                   SUM(reranker_top1_changed) as top1_changed,
                                   ROUND(AVG(reranker_avg_displacement), 1) as avg_disp
                            FROM recall_log
                            WHERE created_at >= ? AND reranker_used = 1 AND intent IS NOT NULL
                            GROUP BY intent ORDER BY cnt DESC
                        """, (cutoff,)).fetchall()
                        if reranker_by_intent:
                            print(f"\nReranker by intent:")
                            for row in reranker_by_intent:
                                t1 = row['top1_changed'] or 0
                                disp = row['avg_disp'] or 0
                                print(f"  {row['intent']:15s} {t1}/{row['cnt']} top-1 changed, avg displacement {disp}")

        elif args.command == "health-trend":
            graph = get_graph()
            with graph._get_conn() as conn:
                rows = conn.execute("""
                    SELECT * FROM health_snapshots
                    ORDER BY created_at DESC LIMIT ?
                """, (args.limit,)).fetchall()

                if not rows:
                    print("No health snapshots yet. Run janitor to generate.")
                else:
                    print(f"Health Trend (last {len(rows)} snapshots)")
                    print(f"{'='*70}")
                    for row in reversed(rows):  # Oldest first
                        print(f"\n[{row['created_at']}]")
                        print(f"  Nodes: {row['total_nodes']}  Edges: {row['total_edges']}  Avg conf: {row['avg_confidence']:.3f}")
                        print(f"  Orphans: {row['orphan_count']}  Embedding coverage: {row['embedding_coverage']:.1f}%")
                        if row['nodes_by_status']:
                            print(f"  Status: {row['nodes_by_status']}")
                        if row['confidence_distribution']:
                            print(f"  Confidence: {row['confidence_distribution']}")
                        if row['staleness_distribution']:
                            print(f"  Staleness: {row['staleness_distribution']}")

        elif args.command == "dedup-audit":
            graph = get_graph()
            with graph._get_conn() as conn:
                # Decision distribution
                decisions = conn.execute("""
                    SELECT decision, COUNT(*) as cnt FROM dedup_log
                    GROUP BY decision ORDER BY cnt DESC
                """).fetchall()

                total_dedup = sum(r["cnt"] for r in decisions)
                if not total_dedup:
                    print("No dedup log entries found")
                else:
                    print(f"Dedup Audit ({total_dedup} total entries)")
                    print(f"{'='*50}")
                    print(f"\nDecision distribution:")
                    for row in decisions:
                        pct = row["cnt"] * 100 // total_dedup
                        print(f"  {row['decision']}: {row['cnt']} ({pct}%)")

                    # Review status
                    reviews = conn.execute("""
                        SELECT review_status, COUNT(*) as cnt FROM dedup_log
                        GROUP BY review_status ORDER BY cnt DESC
                    """).fetchall()
                    print(f"\nReview status:")
                    for row in reviews:
                        print(f"  {row['review_status']}: {row['cnt']}")

                    reversed_count = sum(r["cnt"] for r in reviews if r["review_status"] == "reversed")
                    reviewed_count = sum(r["cnt"] for r in reviews if r["review_status"] != "unreviewed")
                    if reviewed_count > 0:
                        print(f"\nReversal rate: {reversed_count}/{reviewed_count} ({reversed_count*100//reviewed_count}%)")

                    # Gray zone analysis (0.88-0.95 similarity)
                    gray_zone = conn.execute("""
                        SELECT COUNT(*) as cnt,
                               ROUND(AVG(similarity), 3) as avg_sim,
                               decision,
                               COUNT(CASE WHEN review_status = 'reversed' THEN 1 END) as reversals
                        FROM dedup_log
                        WHERE similarity BETWEEN 0.88 AND 0.95
                        GROUP BY decision
                    """).fetchall()
                    if gray_zone:
                        total_gray = sum(r["cnt"] for r in gray_zone)
                        print(f"\nGray zone (0.88-0.95 similarity): {total_gray} entries")
                        for row in gray_zone:
                            print(f"  {row['decision']}: {row['cnt']} (avg sim: {row['avg_sim']}, reversals: {row['reversals']})")

                    # Sample LLM reasoning
                    samples = conn.execute("""
                        SELECT new_text, existing_text, similarity, decision, llm_reasoning
                        FROM dedup_log
                        WHERE llm_reasoning IS NOT NULL
                        ORDER BY created_at DESC LIMIT 5
                    """).fetchall()
                    if samples:
                        print(f"\nRecent LLM reasoning samples:")
                        for s in samples:
                            print(f"\n  [{s['decision']}] sim={s['similarity']:.3f}")
                            print(f"  New:      {s['new_text'][:80]}")
                            print(f"  Existing: {s['existing_text'][:80]}")
                            print(f"  Reason:   {s['llm_reasoning'][:120]}")

        elif args.command == "summarize-entity":
            summary = generate_entity_summary(args.node_id, use_llm=not args.no_llm)
            if summary:
                node = get_graph().get_node(args.node_id)
                node_name = node.name if node else args.node_id
                print(f"Summary for {node_name}:")
                print(summary)
            else:
                print(f"Could not generate summary for node {args.node_id}", file=sys.stderr)
                print("Node may not exist, may not be a Person/Place/Concept, or may have no connected facts.", file=sys.stderr)
                sys.exit(1)

        elif args.command == "summarize-all":
            entity_types = None
            if args.types:
                entity_types = [t.strip() for t in args.types.split(",")]
            stats = summarize_all_entities(
                owner_id=args.owner,
                use_llm=not args.no_llm,
                entity_types=entity_types
            )
            print(json.dumps(stats, indent=2))

        elif args.command == "flagged":
            graph = get_graph()
            if args.approve:
                node = graph.get_node(args.approve)
                if not node:
                    print(f"Node not found: {args.approve}", file=sys.stderr)
                    sys.exit(1)
                if node.status != "flagged":
                    print(f"Node {args.approve} is not flagged (status: {node.status})", file=sys.stderr)
                    sys.exit(1)
                node.status = "pending"
                graph.update_node(node)
                print(f"Approved: {args.approve} -> pending")
            elif args.reject:
                node = graph.get_node(args.reject)
                if not node:
                    print(f"Node not found: {args.reject}", file=sys.stderr)
                    sys.exit(1)
                if node.status != "flagged":
                    print(f"Node {args.reject} is not flagged (status: {node.status})", file=sys.stderr)
                    sys.exit(1)
                graph.hard_delete_node(args.reject)
                print(f"Rejected and deleted: {args.reject}")
            else:
                with graph._get_conn() as conn:
                    rows = conn.execute("""
                        SELECT id, name, attributes, created_at
                        FROM nodes WHERE status = 'flagged'
                        ORDER BY created_at DESC
                    """).fetchall()
                if not rows:
                    print("No flagged facts")
                else:
                    print(f"Flagged facts ({len(rows)}):")
                    for row in rows:
                        attrs = json.loads(row["attributes"]) if row["attributes"] else {}
                        pattern = attrs.get("flagged_pattern", "?")
                        print(f"  [{row['created_at']}] {row['name'][:80]}")
                        print(f"    ID: {row['id']}  Pattern: {pattern}")

        elif args.command == "detect-provider":
            from lib.embeddings import get_embeddings_provider
            adapter = get_adapter_instance()
            adapter_name = type(adapter).__name__
            try:
                llm = adapter.get_llm_provider()
                llm_name = type(llm).__name__
                profiles = llm.get_profiles()
            except Exception as e:
                llm_name = f"ERROR: {e}"
                profiles = {}
            embed = get_embeddings_provider()
            print("LLM:")
            print(f"  Adapter:    {adapter_name}")
            print(f"  Provider:   {llm_name}")
            deep_profile = profiles.get("deep") or profiles.get("high")
            fast_profile = profiles.get("fast") or profiles.get("low")
            if isinstance(deep_profile, dict):
                print(f"  Deep:       {deep_profile.get('model', '?')}")
            if isinstance(fast_profile, dict):
                print(f"  Fast:       {fast_profile.get('model', '?')}")
            print()
            print("Embeddings:")
            print(f"  Provider:   {type(embed).__name__}")
            print(f"  Model:      {embed.model_name} ({embed.dimension()}-dim)")

    try:
        main()
    except Exception as e:
        import traceback
        print(f"Error: {e}", file=sys.stderr)
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)
